_STRUCTURED_PARSE_CACHE = _BoundedTTLCache()


def _parse_query_structured(query: str) -> dict:
    """Parse query into structured facets using LLM (deterministic JSON output).

    Returns dict with keys: statutes, doctrine, leading_bge, synonyms, domain.
    Returns empty dict on failure/timeout/disabled.
    """
    if not LLM_EXPANSION_ENABLED or not ANTHROPIC_API_KEY:
        return {}

    query = _llm_input_excerpt(query)
    cache_key = _BoundedTTLCache.key_for(query)
    if (cached := _STRUCTURED_PARSE_CACHE.get(cache_key)) is not None:
        return cached

    try:
        import httpx
    except ImportError:
        return {}

    try:
        with httpx.Client(timeout=LLM_EXPANSION_TIMEOUT + 1.0) as client:
            resp = client.post(
                "https://api.anthropic.com/v1/messages",
                headers={
                    "x-api-key": ANTHROPIC_API_KEY,
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                },
                json={
                    "model": "claude-haiku-4-5-20251001",
                    "max_tokens": 300,
                    # DO NOT add prompt caching here. Tried and reverted
                    # 2026-08-24, measured in production: 12 consecutive
                    # calls, zero cache reads.
                    #
                    # The minimum cacheable prefix is MODEL-DEPENDENT and
                    # NOT monotonic across generations: 512 tokens on the
                    # newest models, 1024 on Sonnet 4.6/5, but **4096 on
                    # Haiku 4.5**. STRUCTURED_PARSE_PROMPT is ~1050 tokens,
                    # so a cache_control marker here is silently ignored —
                    # no error, just cache_creation_input_tokens: 0.
                    # Caching would need either a 4x longer prompt (absurd)
                    # or a different model (defeats the point of Haiku).
                    "system": STRUCTURED_PARSE_PROMPT,
                    "messages": [{"role": "user", "content": query}],
                },
            )
            resp.raise_for_status()
            _resp_json = resp.json()
            _llm_usage_log(model="claude-haiku-4-5-20251001",
                            feature="query_parse", response_json=_resp_json)
            text = _resp_json["content"][0]["text"].strip()
            # Strip markdown fences if present
            if text.startswith("```"):
                text = text.split("\n", 1)[-1].rsplit("```", 1)[0].strip()
            import json as _json
            parsed = _json.loads(text)
            # Validate structure
            result = {
                "statutes": list(parsed.get("statutes") or []),
                "doctrine": str(parsed.get("doctrine") or ""),
                "doctrine_fr": str(parsed.get("doctrine_fr") or ""),
                "doctrine_it": str(parsed.get("doctrine_it") or ""),
                "leading_bge": list(parsed.get("leading_bge") or []),
                "synonyms": list(parsed.get("synonyms") or []),
                "domain": str(parsed.get("domain") or ""),
            }
            _STRUCTURED_PARSE_CACHE.set(cache_key, result)
            logger.debug("Structured parse for query(len=%d): %s", len(query or ""), result)
            return result
    except Exception as e:
        logger.debug("Structured parse failed for query(len=%d): %s", len(query or ""), e)
        return {}


