# ── LLM query expansion function ─────────────────────────────


def _expand_query_with_llm(query: str) -> list[str]:
    """Expand a search query using Claude Haiku for legal synonym/cross-lingual terms.

    Returns additional search terms, or empty list on failure/timeout/disabled.
    Results are cached in-memory for the lifetime of the process.
    Called from search_fts5 which runs in asyncio.to_thread, so sync HTTP is fine.
    """
    if not LLM_EXPANSION_ENABLED or not ANTHROPIC_API_KEY:
        return []

    # Excerpt BEFORE caching so the key basis equals what the LLM sees.
    query = _llm_input_excerpt(query)
    cache_key = _BoundedTTLCache.key_for(query)
    if (cached := _LLM_EXPANSION_CACHE.get(cache_key)) is not None:
        return cached

    try:
        import httpx
    except ImportError:
        logger.debug("httpx not installed, skipping LLM expansion")
        return []

    try:
        with httpx.Client(timeout=LLM_EXPANSION_TIMEOUT) as client:
            resp = client.post(
                "https://api.anthropic.com/v1/messages",
                headers={
                    "x-api-key": ANTHROPIC_API_KEY,
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                },
                json={
                    "model": "claude-haiku-4-5-20251001",
                    "max_tokens": 150,
                    "system": EXPANSION_SYSTEM_PROMPT,
                    "messages": [{"role": "user", "content": query}],
                },
            )
            resp.raise_for_status()
            _resp_json = resp.json()
            _llm_usage_log(model="claude-haiku-4-5-20251001",
                            feature="query_expansion", response_json=_resp_json)
            text = _resp_json["content"][0]["text"]
            terms = [t.strip() for t in text.strip().split("\n") if t.strip()]
            terms = terms[:6]
            _LLM_EXPANSION_CACHE.set(cache_key, terms)
            logger.debug("LLM expansion for query(len=%d): %s", len(query or ""), terms)
            return terms
    except Exception as e:
        logger.debug("LLM expansion failed for query(len=%d): %s", len(query or ""), e)
        return []


# ── Database ──────────────────────────────────────────────────

# db_generation cache-invalidation tracking. See docs/db_contract.md.
# Module-level: each worker process maintains its own last-seen generation.
# Updated in get_db() whenever a fresh connection reports a different
# PRAGMA user_version than we last saw — triggers _cache_clear() so stale
# aggregation results (list_courts, get_statistics) don't outlive a swap.
_last_seen_db_generation: int = 0


def get_db() -> sqlite3.Connection:
    """Get a read-only connection to the local SQLite database.

    Raises FileNotFoundError if the database hasn't been built yet,
    prompting the user to run the 'update_database' tool.
    """
    if not DB_PATH.exists():
        raise FileNotFoundError(
            f"Database not found at {DB_PATH}. "
            f"Run the 'update_database' tool to download and build the search index. "
            f"This requires ~65 GB free disk space and takes 30-60 minutes."
        )
    last_error = None
    for _ in range(3):
        try:
            conn = sqlite3.connect(
                f"file:{DB_PATH}?immutable=1",
                uri=True,
                check_same_thread=False,
                timeout=1.0,
            )
            conn.row_factory = sqlite3.Row
            conn.execute("PRAGMA query_only = ON")  # read-only for safety

            # Cache-invalidation check: a writer (build_fts5 / quick_publish)
            # sets PRAGMA user_version after each durable write. If we see
            # a value different from what we cached last, the on-disk DB
            # has been swapped under us — clear _query_cache so aggregation
            # results don't outlive the swap. Bare try/except so a failed
            # PRAGMA never breaks request serving.
            global _last_seen_db_generation
            try:
                gen = conn.execute("PRAGMA user_version").fetchone()[0]
                if gen != _last_seen_db_generation:
                    logger.info(
                        "db_generation transitioned %d → %d (clearing _query_cache)",
                        _last_seen_db_generation, gen,
                    )
                    _cache_clear()
                    _last_seen_db_generation = gen
            except Exception as _gen_err:
                logger.warning("db_generation check failed: %s", _gen_err)

            return conn
        except sqlite3.OperationalError as e:
            last_error = e
            time.sleep(0.2)

    raise sqlite3.OperationalError(
        f"Unable to open SQLite database at {DB_PATH}: {last_error}"
    )


def get_db_generation() -> int:
    """Return the last-seen db_generation as recorded by get_db().

    Used by /health and operator diagnostics. Returns 0 if no get_db()
    call has occurred yet (worker just started).
    """
    return _last_seen_db_generation


def get_db_stats() -> dict:
    """Get database statistics."""
    key = ("get_db_stats",)
    cached = _cache_get(key)
    if cached is not None:
        return cached

    try:
        conn = get_db()
        total = conn.execute("SELECT COUNT(*) FROM decisions").fetchone()[0]
        courts = conn.execute(
            "SELECT court, COUNT(*) as n FROM decisions GROUP BY court ORDER BY n DESC"
        ).fetchall()
        date_range = conn.execute(
            "SELECT MIN(decision_date), MAX(decision_date) FROM decisions"
        ).fetchone()
        conn.close()
        return _cache_set(key, {
            "total_decisions": total,
            "courts": {r["court"]: r["n"] for r in courts},
            "earliest_date": date_range[0],
            "latest_date": date_range[1],
            "db_path": str(DB_PATH),
            "db_size_mb": round(DB_PATH.stat().st_size / 1024 / 1024, 1),
        })
    except FileNotFoundError:
        return {"error": "Database not found. Run 'update_database' first."}


# ── Query cache (cleared on DB rebuild) ──────────────────────
# Caches expensive aggregation queries (list_courts, get_statistics, get_db_stats).
# Keyed by (function_name, args_tuple). Invalidated when DB is rebuilt.
_query_cache: dict[tuple, object] = {}


def _cache_get(key: tuple):
    return _query_cache.get(key)


def _cache_set(key: tuple, value):
    _query_cache[key] = value
    return value


def _cache_clear():
    _query_cache.clear()
    # LLM-derived caches ride the same DB-generation swap hook: expansion
    # terms and parsed facets can reference decisions that no longer exist
    # after a rebuild.
    _LLM_EXPANSION_CACHE.clear()
    _STRUCTURED_PARSE_CACHE.clear()
    # Result payloads embed snippets and totals from the pre-swap corpus.
    _SEARCH_RESULT_CACHE.clear()
    logger.info("Query cache cleared")


# ── Metrics ──────────────────────────────────────────────────
# Lightweight in-process counters. Thread-safe via GIL for simple increments.
import collections

_metrics = {
    "tool_calls": collections.Counter(),       # tool_name → count
    "tool_latency_ms": collections.defaultdict(list),  # tool_name → [ms, ms, ...]
    "tool_errors": collections.Counter(),       # tool_name → error count
    "haiku_rerank_fired": 0,
    "haiku_rerank_skipped": 0,
    "haiku_rerank_changed_top": 0,
    "zero_results": [],                        # recent zero-result queries
    "recent_queries": [],                      # last 200 search queries (text only)
    "search_followups": 0,                     # searches followed by get_decision/case_brief
    "search_total": 0,                         # total searches (for followup rate)
    "last_tool_was_search": False,             # tracks if previous call was search
    "clients": collections.Counter(),          # client type → call count
    "sessions": 0,
    # tool_name → Counter({"substantive": n, "empty": n}). Call counts alone
    # cannot answer "did we actually answer?": an empty search, a cite that
    # resolves to exists=false and a get_law miss are all HTTP 200 and land
    # in tool_calls indistinguishable from a hit. See _classify_outcome.
    "tool_outcomes": collections.defaultdict(collections.Counter),
    # How each REST outcome was determined ('declared' by the route vs
    # 'status' inferred from the HTTP code) and, when empty, why. Without
    # the first, an answered rate cannot be read honestly: a status-only
    # label scores an empty 200 as answered.
    "outcome_sources": collections.defaultdict(collections.Counter),
    "empty_reasons": collections.defaultdict(collections.Counter),
    "search_result_cache_hits": 0,
    "search_result_cache_misses": 0,
    "startup_time": datetime.now(timezone.utc).isoformat(),
}

# ── Per-request context (ASGI → handle_call_tool) ──
_ctx_client_ip = contextvars.ContextVar("client_ip", default="")
# LLM-call provenance: mcp | rest | internal (default). Set by the MCP
# dispatch and the REST LLM endpoints; anything else (batch scripts,
# maintenance sessions) inherits "internal" — which is precisely the
# attribution that was missing on 2026-08-18/20.
_ctx_llm_source = contextvars.ContextVar("llm_source", default="internal")

# Quota for the MCP dispatch gate. The REST layer does its own import
# inside the app factory; the dispatch runs outside that scope, so it
# needs a module-level binding — referencing the factory's names raised
# NameError at runtime (caught in review before deploy, 2026-08-23).
try:
    from web_api import ocl_quota as _mcp_quota
    _MCP_QUOTA_AVAILABLE = True
except Exception as _mcp_quota_err:                     # noqa: BLE001
    _mcp_quota = None
    _MCP_QUOTA_AVAILABLE = False
_ctx_client_ua = contextvars.ContextVar("client_ua", default="")
_ctx_session_id = contextvars.ContextVar("session_id", default="")

# One opaque id per live MCP connection, minted on first use.
#
# The ASGI layer can read a session id off the wire (`session_id=` in the
# SSE POST query string, `Mcp-Session-Id` for Streamable HTTP) but cannot
# usefully publish it: both transports run the MCP protocol loop in a
# long-lived task created at connect, and later POSTs feed messages into
# it from *different* tasks. A contextvar set in the POST never reaches
# the tool handler, which is why every captured record carried sid=None
# and the impression->fetch join produced nothing at all.
#
# Deriving it from the SDK's own per-request session object instead works
# for both transports and needs one call site. Keyed weakly so the id
# dies with the connection, which is what /datenschutz/ describes: "eine
# Sitzungskennung ... die Kennung wechselt mit jeder Verbindung". Not
# id(), whose values are recycled after garbage collection and would
# silently fuse two unrelated sessions.
_session_ids: "weakref.WeakKeyDictionary" = weakref.WeakKeyDictionary()


def _derive_session_id(sess) -> str:
    """Stable opaque id for the connection `sess` belongs to, or ''."""
    if sess is None:
        return ""
    try:
        sid = _session_ids.get(sess)
        if sid is None:
            sid = "s_" + secrets.token_hex(8)
            _session_ids[sess] = sid
        return sid
    except TypeError:
        # Not weak-referenceable — no session linkage rather than a crash.
        return ""


def _client_class(ua: str | None, x_client: str | None = None) -> str:
    """Coarse client class from a User-Agent — the label that may be
    logged durably. Mirrors the middleware's metrics buckets; returns a
    class, never the UA string itself.

    The Word add-in runs in an Office webview and sends whatever
    User-Agent that webview carries, so it is indistinguishable from any
    other browser by UA alone and was landing in "other". It identifies
    itself with an X-Client header instead — which the REST metrics
    already read — so the header wins where it is present. Without this
    the one paying, non-agent client is unsegmentable in the dev-data
    corpus, which is precisely the population worth analysing on its own.
    """
    if (x_client or "").strip().lower() == "word-addin":
        return "word_addin"
    u = (ua or "").lower()
    if not u:
        return "-"
    if "claude-user" in u:
        return "claude.ai"
    if "claude-code" in u or "claude-vscode" in u:
        return "claude-code"
    if "undici" in u or "chatgpt" in u or "openai" in u:
        return "chatgpt"
    if "gemini" in u or "google" in u:
        return "gemini"
    if "bot" in u or "crawler" in u:
        return "bot"
    return "other"


def _trusted_client_ip(req) -> str:
    """Client IP behind a single trusted nginx hop — spoofing-resistant.

    nginx sets ``X-Real-IP`` to the real ``$remote_addr`` and appends it as the
    LAST ``X-Forwarded-For`` hop, so those are the only trustworthy values.
    Earlier XFF hops are entirely client-controlled; trusting the FIRST hop (the
    historical bug) let a caller rotate a forged header to defeat the per-IP LLM
    quota. Order: X-Real-IP → last XFF hop → socket peer.
    """
    xri = req.headers.get("x-real-ip", "")
    if xri and xri.strip():
        return xri.strip()
    xff = req.headers.get("x-forwarded-for", "")
    if xff:
        hops = [h.strip() for h in xff.split(",") if h.strip()]
        if hops:
            return hops[-1]  # nginx-appended real peer; never the spoofable first hop
    return req.client.host if getattr(req, "client", None) else "0.0.0.0"

# ── Session → client mapping (for integrator detection) ──
_session_clients: dict[str, dict] = {}  # session_id → {ip, ua, first_seen, tools: []}
_SESSION_LOG_MAX = 2000  # cap to prevent memory growth


def _record_tool_call(name: str, duration_ms: float, *, error: bool = False):
    """Record a tool invocation for metrics."""
    _metrics["tool_calls"][name] += 1
    # Store individual latencies for percentile calc (cap at 500 per tool)
    lat_list = _metrics["tool_latency_ms"][name]
    lat_list.append(duration_ms)
    if len(lat_list) > 500:
        _metrics["tool_latency_ms"][name] = lat_list[-500:]
    if error:
        _metrics["tool_errors"][name] += 1
    # Track search → followup pattern
    if name in ("search_decisions",):
        _metrics["search_total"] += 1
        _metrics["last_tool_was_search"] = True
    elif name in ("get_decision", "get_case_brief", "find_citations", "get_doctrine"):
        if _metrics["last_tool_was_search"]:
            _metrics["search_followups"] += 1
        _metrics["last_tool_was_search"] = False
    else:
        _metrics["last_tool_was_search"] = False


# ── Outcome labelling ────────────────────────────────────────
# A tool that ran without raising still may not have answered. These
# markers are the no-result paths the handlers actually emit (grepped from
# this file, not invented): "No results found." / "No data found." /
# "No decisions found matching your query" / "No articles found." /
# "No outgoing|incoming citations found." / "No sufficiently similar
# decisions found." / "No leading cases found" / "No commentaries found" /
# "No law found with" / "No suitable case found" / "<X> not found: ...".
_EMPTY_TEXT_MARKERS = (
    "no results found",
    "no data found",
    "no data available",
    "no decisions found",
    "no articles found",
    "no outgoing citations found",
    "no incoming citations found",
    "no sufficiently similar decisions found",
    "no leading cases found",
    "no commentaries found",
    "no law found with",
    "no suitable case found",
    "not found:",
    "unknown tool:",
)
# Marker matching applies only to short responses. A 200k-char decision is
# never "empty" no matter what phrases its text happens to contain, and this
# single guard removes essentially every false positive without needing the
# markers to be anchored.
_EMPTY_MAX_CHARS = 4000
# A payload carrying nothing but a note/hint is a no-answer dressed politely.
_NON_ANSWER_KEYS = {"note", "_note", "hint", "_hint", "query", "queried",
                    "tool", "message",
                    # A never-empty fallback that found nothing to fall back
                    # on is still an empty answer: the flag, the identifiers
                    # it echoes and the corpus label carry no law.
                    "no_commentary", "no_materialien", "filters_relaxed",
                    "found",
                    "law", "law_code", "article", "sr_number", "source",
                    "corpus", "language_filter", "year_filter"}


def _is_miss_payload(payload) -> bool:
    """True when a helper's dict answer is a miss: an `error`, or a
    never-empty fallback that says so with `found: false` (get_commentary /
    get_materialien drop `error` on a miss because the payload is an answer
    — what the corpus holds instead — not a failure). Internal callers that
    build on another tool's answer test this, never `error` alone, so a
    fallback payload is never mistaken for the thing asked for."""
    if not isinstance(payload, dict) or not payload:
        return True
    if payload.get("error"):
        return True
    return payload.get("found") is False


def _response_text(result) -> str:
    """Flatten a dispatch result to text. Handles the deep-research
    (content, structuredContent) tuple and the ordinary TextContent list."""
    if isinstance(result, tuple):
        result = result[0] if result else []
    if isinstance(result, str):
        return result
    if not isinstance(result, (list, tuple)):
        return ""
    return "\n".join(
        getattr(item, "text", "") or "" for item in result
    )


def _classify_outcome(result) -> str:
    """Return "substantive" or "empty" for a successful tool result.

    Errors are not judged here — they are already counted separately from
    the raised exception, which is the only reliable signal of a server
    fault. A handled "not found" is deliberately "empty", not "error": the
    caller asked and we had nothing, which is a coverage question rather
    than a failure.
    """
    text = _response_text(result).strip()
    if not text:
        return "empty"

    # Structural signals first — JSON payloads say so explicitly.
    if text[0] in "{[":
        try:
            payload = json.loads(text)
        except (ValueError, TypeError):
            payload = None
        if isinstance(payload, list):
            return "substantive" if payload else "empty"
        if isinstance(payload, dict):
            if payload.get("error"):
                return "empty"
            if payload.get("exists") is False:
                return "empty"
            informative = {k for k, v in payload.items()
                           if v not in (None, "", [], {}, False)}
            if informative and informative <= _NON_ANSWER_KEYS:
                return "empty"
            if not informative:
                return "empty"
            return "substantive"

    if len(text) <= _EMPTY_MAX_CHARS:
        low = text.lower()
        if any(marker in low for marker in _EMPTY_TEXT_MARKERS):
            return "empty"
    return "substantive"


def _record_tool_outcome(name: str, outcome: str) -> None:
    """Count one labelled outcome. Never raises: telemetry must not be able
    to fail a request that already produced a good answer."""
    try:
        _metrics["tool_outcomes"][name][outcome] += 1
    except Exception:                                   # pragma: no cover
        pass


def _record_outcome_source(name: str, source: str) -> None:
    """Where a REST outcome came from: 'declared' (the route said so) or
    'status' (inferred from the HTTP code, which cannot see an empty 200).

    Published so a reader can tell how much of an answered rate is
    measured and how much is assumed.
    """
    try:
        _metrics["outcome_sources"][name][source] += 1
    except Exception:                                   # pragma: no cover
        pass


def _record_empty_reason(name: str, reason: str) -> None:
    """Why a call answered nothing — no_fts_match, filters_excluded_all,
    id_not_found, corpus_not_built, out_of_range, http_404 …

    Call counts say a tool ran; the answered rate says it found something;
    only the reason says what to fix.
    """
    try:
        _metrics["empty_reasons"][name][reason[:48]] += 1
    except Exception:                                   # pragma: no cover
        pass


def _mark_outcome(response, outcome: str, reason: str | None = None):
    """Declare a REST route's outcome for the metrics middleware.

    Routes know their payload; the middleware cannot see it without
    buffering the stream. Usage:

        return _mark_outcome(JSONResponse(payload), "empty", "no_fts_match")
    """
    try:
        response.headers["X-OCL-Outcome"] = outcome
        if reason:
            response.headers["X-OCL-Empty-Reason"] = reason[:48]
    except Exception:                                   # pragma: no cover
        pass
    return response


# Keys under which a REST payload carries its answer. A payload whose
# every present key here is an empty list answered nothing, whatever the
# HTTP status says.
_RESULT_KEYS = ("results", "articles", "commentaries", "cases",
                "leading_cases", "publications", "documents", "sources",
                "botschaft_documents", "amendment_refs",
                "parliamentary_modifications", "laws",
                "catalog", "by_source")

# Several helpers report a miss as a 200 carrying {"error": "..."}. The
# three kinds are not the same finding and must not share a counter: a
# missing database is an operations problem, a caught exception is a
# fault the 5xx-only error rate cannot see, and a malformed request is
# the caller's.
#
# The corpus test names the two things that can be absent rather than
# matching "not available" loosely: "Historical version not available
# for SR 210 as of 2020-01-01" is a version that does not exist, not a
# database that was never deployed, and must not be filed as one.
_ERR_NO_CORPUS = ("database not available", "graph not available",
                  "not built", "deploy ")
_ERR_BACKEND = ("database error", "lookup failed", "search failed",
                "query failed")
_ERR_BAD_REQUEST = ("provide ", "at least one of", "is required")

# Statuses that mean "ran, returned no law" when a route has not declared
# its own outcome. 400/422 belong here: a rejected request produced no
# legal content, and the route raised before it could say so itself.
_EMPTY_STATUSES = frozenset({204, 400, 404, 410, 422})


def _payload_outcome(payload) -> tuple[str, str | None] | None:
    """Classify a REST payload as substantive or empty — or decline.

    Returns (outcome, reason) where reason is None if the caller should
    name it, or None outright when the shape is unrecognised. Declining
    is the safe answer: an unlabelled route falls back to the status
    heuristic and is counted as assumed, which beats a confident wrong
    label. Nothing here may guess.
    """
    if not isinstance(payload, dict):
        return None
    err = payload.get("error")
    if isinstance(err, str) and err.strip():
        # A miss that still offers real alternatives is a different result
        # from a dead end, and counting them together would hide whether
        # the candidate fallback actually helps anyone.
        if payload.get("candidates"):
            return "empty", "id_not_found_with_candidates"
        low = err.lower()
        if any(s in low for s in _ERR_NO_CORPUS):
            return "empty", "corpus_not_built"
        if any(s in low for s in _ERR_BACKEND):
            return "empty", "backend_error"
        if any(s in low for s in _ERR_BAD_REQUEST):
            return "empty", "bad_request"
        return "empty", "id_not_found"
    present = [k for k in _RESULT_KEYS if isinstance(payload.get(k), list)]
    if present:
        if any(payload[k] for k in present):
            return "substantive", None
        return "empty", None            # caller names it
    total = payload.get("total")
    if isinstance(total, int):
        return ("substantive", None) if total else ("empty", None)
    return None


def _declare_outcome(response, payload, empty_reason: str | None = None):
    """Label a dict payload's outcome on the way out, and return it.

        return _declare_outcome(response, resp, "no_fts_match")

    `empty_reason` names the miss only where the payload cannot: a
    payload that already says WHY it is empty (no corpus, backend fault,
    bad request) keeps its own, more specific reason.
    """
    verdict = _payload_outcome(payload)
    if verdict:
        outcome, reason = verdict
        _mark_outcome(response, outcome,
                      (reason or empty_reason or "no_match")
                      if outcome == "empty" else None)
    return payload


# ── Full-capture mode (time-boxed evaluation period) ─────────────────
# Policy 2026-08-19: for a first period, gather every data point the
# server sees, then prune by measured usefulness. OFF by default; turns
# on via SWISS_CASELAW_FULL_CAPTURE=1 in .env.mcp ONLY after the amended
# /datenschutz/ is live — the notice precedes the collection, never the
# reverse. Records go to research_logs/capture_YYYY-MM-DD.jsonl and are
# collected into the private data repo behind the same amendment marker
# as the traces.
#
# Two carve-outs, deliberate and not env-controlled:
#   * attest / verify-claim / draft document BODIES are never captured —
#     they are client work product, and the Word add-in's own policy
#     states document text is not stored on our server.
#   * no IP addresses — the session id carries the sequence analytics; a
#     session is a pseudonymous connection, not a person.
_FULL_CAPTURE = os.environ.get("SWISS_CASELAW_FULL_CAPTURE", "") == "1"
# Free-text fields that are document content rather than a query, plus
# credentials. Stripped from captured arguments; length recorded instead.
_CAPTURE_BODY_FIELDS = {"response_text", "document_text", "text", "claim",
                        "facts", "content", "body", "draft_text",
                        "redacted_text", "statement", "paragraph_text",
                        "selected_text"}
_CAPTURE_SECRET_FIELDS = {"license_key", "license", "token", "api_key",
                          "authorization", "password"}


def _new_result_set_id() -> str:
    """An opaque, ephemeral token identifying one search's result list.

    Echoed in the search response and stamped into the impression record,
    so a later fetch can be joined back to the exact ranked list it came
    from — the impression/click pair that unbiased learning-to-rank needs
    and that a raw fetch event, shorn of its position, cannot provide.

    Random, tied to no person, meaningless after the day's records are
    pruned. Correlating two requests by it is the within-session linkage
    the /datenschutz/ evaluation-period notice discloses.
    """
    return "rs_" + secrets.token_hex(8)


def _traffic_class(client: str | None, src: str, tool: str | None,
                   has_session: bool) -> str:
    """crawler | agent | direct — the segment a record belongs to.

    Most raw volume is crawler traffic (export_decision bots); the
    signal-bearing sessions are a minority, and a dataset that does not
    separate them trains on noise. Coarse and deterministic:
      * crawler — a known bot UA, or a bulk export fetch
      * agent   — an MCP session running several tools (real research)
      * direct  — a stateless one-shot API call
    """
    if client == "bot":
        return "crawler"
    if src == "mcp" and has_session:
        return "agent"
    # A bulk export with no session is the classic crawler shape; the
    # SAME tool inside a session is an agent reading a result it found,
    # which the interaction join counts as engagement — so the session,
    # not the tool alone, decides. (The join's _FETCH_TOOLS and this
    # classifier must not disagree about export_decision.)
    if tool in ("export_decision", "get_decisions") and not has_session:
        return "crawler"
    return "direct"


def _capture_event(record: dict) -> None:
    """Append one full-capture record. Never raises; never blocks."""
    if not _FULL_CAPTURE:
        return
    try:
        day = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        path = _RESEARCH_LOG_DIR / f"capture_{day}.jsonl"
        _RESEARCH_LOG_DIR.mkdir(parents=True, exist_ok=True)
        with _research_log_lock:
            with open(path, "a", encoding="utf-8") as fh:
                fh.write(json.dumps(record, ensure_ascii=False,
                                    default=str) + "\n")
    except Exception:                                   # pragma: no cover
        pass


# A body can arrive under a name nobody thought to list. attest_response
# calls its document `draft_text`, which was not in the set above, so 166
# drafted legal opinions reached disk before anyone noticed — among them a
# named taxpayer with her canton and employer, and successive revisions of
# a criminal defence, which is data on criminal proceedings and therefore
# besonders schützenswert under nFADP Art. 5(c).
#
# The lesson is that a denylist of names cannot be trusted on its own, so
# length is the backstop: no legitimate search query is this long (the
# longest observed in a day of live traffic was 214 characters), while a
# document always is. Anything past the threshold is stored as its length
# whatever it is called, so the next unlisted parameter fails safe.
_CAPTURE_MAX_ARG_CHARS = 600


def _capture_args(arguments: dict) -> dict:
    """Arguments as received, minus document bodies and credentials.

    Bodies are replaced by their length so volume stays measurable
    without the content ever landing on disk.
    """
    out = {}
    for k, v in (arguments or {}).items():
        kl = k.lower()
        if kl in _CAPTURE_SECRET_FIELDS:
            out[k] = "<redacted>"
        elif isinstance(v, str) and (kl in _CAPTURE_BODY_FIELDS
                                     or len(v) > _CAPTURE_MAX_ARG_CHARS):
            out[f"{k}_len"] = len(v)
        else:
            out[k] = v
    return out


def _record_query(query: str):
    """No-op (privacy contract: query content is never logged).

    Previously appended the query string to an in-memory buffer that was
    then persisted to metrics.db.daily_queries and emitted via the live
    metrics endpoint's ``top_queries`` field. That contradicted the
    /datenschutz/ promise that "Search query content is never logged at
    any tier." Aggregate search totals still flow through
    daily_summary.search_total without retaining the strings.

    Kept as a signature-compatible stub so existing call sites work
    untouched; safe to remove the call sites in a follow-up cleanup."""
    return


# ── Research telemetry (JSON lines, no PII) ──────────────────
# Appends one JSON line per search to a daily log file.
# Purpose: scientific evaluation of search pipeline components.
import threading

_RESEARCH_LOG_DIR = Path(os.environ.get("SWISS_CASELAW_DIR", str(Path.home() / ".swiss-caselaw"))) / "research_logs"
_research_log_lock = threading.Lock()
_METRICS_HISTORY = _RESEARCH_LOG_DIR / "daily_metrics.jsonl"

# ── Trace retention (/datenschutz/ commitment) ────────────────
# search_traces_*.jsonl carry the rerank records' query[:200] text; before
# 2026-07 retention was UNBOUNDED (564 MB / 123 daily files accumulated
# since April). The page now promises deletion after 30 days — this prune
# is what makes that promise true. Strict filename regex: the date comes
# from the NAME, never mtime (backups/rsync touch mtimes), and
# daily_metrics.jsonl is structurally unreachable.
_RESEARCH_TRACE_RETENTION_DAYS = int(os.environ.get("RESEARCH_TRACE_RETENTION_DAYS", "30"))
_TRACE_FILE_RE = re.compile(r"^search_traces_(\d{4}-\d{2}-\d{2})\.jsonl$")

# capture_*.jsonl is the evaluation-phase corpus: full tool arguments,
# query text and a session id, i.e. session-linked raw data. The page
# sets no fixed deadline for it — retention is the developer's call,
# bounded by the stated purposes — so the default here keeps everything
# and the window is set by choosing a value, which is what exercising
# that discretion looks like in practice. Kept separate from the 30-day
# trace window either way: the point of the period is a corpus long
# enough to learn from, and traces carry no session reference.
#
# The prune below globbed search_traces_* only, so capture files had no
# deletion path at all; setting this now actually does something.
_CAPTURE_RETENTION_DAYS = int(os.environ.get("CAPTURE_RETENTION_DAYS", "0"))
_CAPTURE_FILE_RE = re.compile(r"^capture_(\d{4}-\d{2}-\d{2})\.jsonl$")
_last_trace_prune_day: str | None = None


def _prune_search_traces(today: str) -> None:
    """Delete trace files older than the retention window. Once per day per
    process (module-global guard, GIL-safe); unlink(missing_ok=True) makes
    the 8 workers' concurrent prunes race-free. Never raises."""
    global _last_trace_prune_day
    if _last_trace_prune_day == today:
        return
    _last_trace_prune_day = today
    for pattern, regex, days in (
        ("search_traces_*.jsonl", _TRACE_FILE_RE,
         _RESEARCH_TRACE_RETENTION_DAYS),
        ("capture_*.jsonl", _CAPTURE_FILE_RE, _CAPTURE_RETENTION_DAYS),
    ):
        if days <= 0:
            continue  # retention disabled → keep everything, prune nothing
        try:
            cutoff = (
                datetime.strptime(today, "%Y-%m-%d") - timedelta(days=days)
            ).strftime("%Y-%m-%d")
            for f in _RESEARCH_LOG_DIR.glob(pattern):
                mt = regex.match(f.name)
                if mt and mt.group(1) < cutoff:
                    f.unlink(missing_ok=True)
        except Exception:
            pass  # retention must never break search

# ── Persistent metrics (SQLite) ──────────────────────────────
# Stores true deltas per day so lifetime totals survive restarts.
_METRICS_DB_PATH = Path(os.environ.get("SWISS_CASELAW_DIR", str(Path.home() / ".swiss-caselaw"))) / "metrics.db"
_metrics_db_lock = threading.Lock()

# Track last-flushed state to compute deltas
_last_flushed: dict = {
    "tool_calls": collections.Counter(),
    "tool_errors": collections.Counter(),
    "clients": collections.Counter(),
    "sessions": 0,
    "haiku_rerank_fired": 0,
    "haiku_rerank_skipped": 0,
    "haiku_rerank_changed_top": 0,
    "search_total": 0,
    "search_followups": 0,
}


def _classify_rest_metric(path: str, status: int) -> tuple[str | None, bool]:
    """Map a REST request (path, HTTP status) to (tool_name, is_error) for metrics.

    Path-depth-aware so crawler 4xx on per-decision sub-resources
    (/api/decisions/{id}/export.*, /api/decisions/{id}) and fabricated
    /api/laws/{abbr}/{canton} URLs are NOT charged to the parent tool's error rate.
    Only genuine 5xx server faults count as errors — a 404 on a missing decision or a
    422 on a bad URL is an expected client/crawler condition, not a tool failure.
    Returns (None, False) for non-/api or unclassified paths.
    """
    p = (path or "").strip("/")
    if not p.startswith("api/"):
        return None, False
    parts = p.split("/")
    if len(parts) < 2:
        return None, False
    endpoint = parts[1]
    if endpoint == "decisions":
        if len(parts) >= 4 and parts[3].startswith("export"):
            tool = "export_decision"
        elif len(parts) >= 3:
            tool = "get_decision"
        else:
            tool = "search_decisions"
    elif endpoint == "decision":
        tool = "get_decision"
    elif endpoint in ("docs", "openapi.json", "redoc"):
        tool = None
    else:
        tool = endpoint
    return tool, (status >= 500)


# Crawler policy. The corpus is CC0 and every /entscheid/ decision page carries
# Schema.org markup, so all HTML content + the sitemaps stay fully crawlable.
# We disallow the per-decision API subtree (/api/decisions/...): its export
# renderers (.pdf/.docx via reportlab/python-docx on the shared
# asyncio.to_thread pool) were the bulk crawler load that starved search + MCP,
# and the JSON variants are redundant reformats of the crawlable /entscheid/
# HTML page. A plain prefix (no wildcard) so every crawler honours it.
# /metrics and /dev stay operational-only. NB: a crawler obeys ONLY its
# most-specific User-agent group, so the disallows must be repeated in every
# named group, otherwise the AI bots (each with its own group) would ignore them.
_ROBOTS_AGENTS = (
    "*", "GPTBot", "ChatGPT-User", "OAI-SearchBot", "ClaudeBot", "anthropic-ai",
    "Claude-Web", "Google-Extended", "GoogleOther", "PerplexityBot",
    "Perplexity-User", "CCBot", "cohere-ai", "Meta-ExternalAgent", "Bytespider",
    "Applebot", "Applebot-Extended",
)
_ROBOTS_DISALLOW = (
    "Disallow: /api/decisions/\n"
    "Disallow: /metrics\n"
    "Disallow: /dev\n"
)


def _build_robots_txt(base_url: str) -> str:
    """Render robots.txt: HTML pages + sitemaps open to all crawlers, the
    per-decision /api/decisions/ subtree disallowed in EVERY User-agent group."""
    # Disallow lines come BEFORE "Allow: /": longest-match crawlers (Google,
    # Bing) are order-independent, but first-match parsers (urllib, simpler
    # bots) return the first matching rule, so a leading "Allow: /" would
    # nullify the disallows. This order is correct for both.
    groups = "\n".join(
        "User-agent: %s\n%sAllow: /\n" % (ua, _ROBOTS_DISALLOW)
        for ua in _ROBOTS_AGENTS
    )
    return (
        "# OpenCaseLaw crawl policy (CC0 corpus). HTML content and sitemaps are\n"
        "# open to every crawler; per-decision export renderers under /api/ are\n"
        "# disallowed (redundant reformats; expensive to render for bots).\n\n"
        + groups
        + "\nSitemap: %s/sitemap.xml\n" % base_url
    )


def _init_metrics_db():
    """Create persistent metrics tables if they don't exist."""
    try:
        conn = sqlite3.connect(str(_METRICS_DB_PATH), timeout=5)
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA busy_timeout=3000")
        conn.executescript("""
            CREATE TABLE IF NOT EXISTS daily_tools (
                date TEXT NOT NULL,
                tool TEXT NOT NULL,
                calls INTEGER NOT NULL DEFAULT 0,
                errors INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (date, tool)
            );
            CREATE TABLE IF NOT EXISTS daily_clients (
                date TEXT NOT NULL,
                client TEXT NOT NULL,
                sessions INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (date, client)
            );
            CREATE TABLE IF NOT EXISTS daily_summary (
                date TEXT PRIMARY KEY,
                sessions INTEGER NOT NULL DEFAULT 0,
                haiku_fired INTEGER NOT NULL DEFAULT 0,
                haiku_skipped INTEGER NOT NULL DEFAULT 0,
                haiku_changed_top INTEGER NOT NULL DEFAULT 0,
                search_total INTEGER NOT NULL DEFAULT 0,
                search_followups INTEGER NOT NULL DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS daily_queries (
                date TEXT NOT NULL,
                query TEXT NOT NULL,
                count INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (date, query)
            );
        """)
        conn.close()
    except Exception as e:
        logger.warning("metrics db init failed: %s", e)


def _flush_metrics_to_disk():
    """Compute deltas since last flush and write to SQLite + JSONL."""
    global _last_flushed
    try:
        _RESEARCH_LOG_DIR.mkdir(parents=True, exist_ok=True)
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")

        # ── Compute deltas ──
        delta_tools = {}
        for tool, count in _metrics["tool_calls"].items():
            prev = _last_flushed["tool_calls"].get(tool, 0)
            d_calls = count - prev
            d_errors = _metrics["tool_errors"].get(tool, 0) - _last_flushed["tool_errors"].get(tool, 0)
            if d_calls > 0 or d_errors > 0:
                delta_tools[tool] = {"calls": max(d_calls, 0), "errors": max(d_errors, 0)}

        delta_clients = {}
        for client, count in _metrics["clients"].items():
            prev = _last_flushed["clients"].get(client, 0)
            d = count - prev
            if d > 0:
                delta_clients[client] = d

        d_sessions = _metrics["sessions"] - _last_flushed["sessions"]
        d_haiku_fired = _metrics["haiku_rerank_fired"] - _last_flushed["haiku_rerank_fired"]
        d_haiku_skipped = _metrics["haiku_rerank_skipped"] - _last_flushed["haiku_rerank_skipped"]
        d_haiku_changed = _metrics["haiku_rerank_changed_top"] - _last_flushed["haiku_rerank_changed_top"]
        d_search_total = _metrics["search_total"] - _last_flushed["search_total"]
        d_search_followups = _metrics["search_followups"] - _last_flushed["search_followups"]

        # ── Update last_flushed to current state ──
        _last_flushed = {
            "tool_calls": collections.Counter(_metrics["tool_calls"]),
            "tool_errors": collections.Counter(_metrics["tool_errors"]),
            "clients": collections.Counter(_metrics["clients"]),
            "sessions": _metrics["sessions"],
            "haiku_rerank_fired": _metrics["haiku_rerank_fired"],
            "haiku_rerank_skipped": _metrics["haiku_rerank_skipped"],
            "haiku_rerank_changed_top": _metrics["haiku_rerank_changed_top"],
            "search_total": _metrics["search_total"],
            "search_followups": _metrics["search_followups"],
        }

        # ── Write deltas to SQLite ──
        with _metrics_db_lock:
            conn = sqlite3.connect(str(_METRICS_DB_PATH), timeout=5)
            conn.execute("PRAGMA busy_timeout=3000")
            try:
                for tool, stats in delta_tools.items():
                    conn.execute(
                        "INSERT INTO daily_tools (date, tool, calls, errors) VALUES (?, ?, ?, ?) "
                        "ON CONFLICT(date, tool) DO UPDATE SET calls = calls + ?, errors = errors + ?",
                        (today, tool, stats["calls"], stats["errors"], stats["calls"], stats["errors"]),
                    )
                for client, count in delta_clients.items():
                    conn.execute(
                        "INSERT INTO daily_clients (date, client, sessions) VALUES (?, ?, ?) "
                        "ON CONFLICT(date, client) DO UPDATE SET sessions = sessions + ?",
                        (today, client, count, count),
                    )
                if d_sessions > 0 or d_haiku_fired > 0:
                    conn.execute(
                        "INSERT INTO daily_summary (date, sessions, haiku_fired, haiku_skipped, haiku_changed_top, search_total, search_followups) "
                        "VALUES (?, ?, ?, ?, ?, ?, ?) "
                        "ON CONFLICT(date) DO UPDATE SET "
                        "sessions = sessions + ?, haiku_fired = haiku_fired + ?, "
                        "haiku_skipped = haiku_skipped + ?, haiku_changed_top = haiku_changed_top + ?, "
                        "search_total = search_total + ?, search_followups = search_followups + ?",
                        (today, max(d_sessions, 0), max(d_haiku_fired, 0), max(d_haiku_skipped, 0),
                         max(d_haiku_changed, 0), max(d_search_total, 0), max(d_search_followups, 0),
                         max(d_sessions, 0), max(d_haiku_fired, 0), max(d_haiku_skipped, 0),
                         max(d_haiku_changed, 0), max(d_search_total, 0), max(d_search_followups, 0)),
                    )
                # No-op: query content is never persisted (privacy
                # contract). The previous block wrote the top-50
                # cleartext queries into daily_queries on every flush;
                # that table is being phased out and is wiped on the
                # next deploy. Aggregate "how many searches today" is
                # already in daily_summary.search_total above.
                conn.commit()
            finally:
                conn.close()

        # ── Also append to JSONL for backward compat ──
        snapshot = _get_metrics()
        snapshot["flushed_at"] = datetime.now(timezone.utc).isoformat()
        snapshot["type"] = "periodic_flush"
        with _research_log_lock:
            with open(_METRICS_HISTORY, "a") as f:
                f.write(json.dumps(snapshot, ensure_ascii=False) + "\n")
    except Exception as e:
        logger.warning("metrics flush failed: %s", e)


def _get_lifetime_metrics(range_param: str = "all") -> dict:
    """Read lifetime metrics from SQLite. Accurate across restarts."""
    try:
        if not _METRICS_DB_PATH.exists():
            return {"error": "No persistent metrics yet"}

        now = datetime.now(timezone.utc)
        cutoffs = {
            "1d": 1, "7d": 7, "30d": 30, "90d": 90, "365d": 365, "all": 0,
        }
        days = cutoffs.get(range_param, 0)
        if days:
            cutoff_date = (now - timedelta(days=days)).strftime("%Y-%m-%d")
            date_clause = "WHERE date >= ?"
            date_params: tuple = (cutoff_date,)
        else:
            date_clause = ""
            date_params = ()

        conn = sqlite3.connect(f"file:{_METRICS_DB_PATH}?mode=ro", uri=True)
        conn.row_factory = sqlite3.Row

        # Tool stats
        tools = {}
        for row in conn.execute(
            f"SELECT tool, SUM(calls) as calls, SUM(errors) as errors "
            f"FROM daily_tools {date_clause} GROUP BY tool ORDER BY SUM(calls) DESC", date_params
        ):
            tools[row["tool"]] = {"calls": row["calls"], "errors": row["errors"], "avg_ms": 0}

        # Client stats
        clients = {}
        for row in conn.execute(
            f"SELECT client, SUM(sessions) as sessions FROM daily_clients {date_clause} GROUP BY client ORDER BY SUM(sessions) DESC", date_params
        ):
            clients[row["client"]] = row["sessions"]

        # Summary
        summary = conn.execute(
            f"SELECT SUM(sessions) as sessions, SUM(haiku_fired) as hf, SUM(haiku_skipped) as hs, "
            f"SUM(haiku_changed_top) as hc, SUM(search_total) as st, SUM(search_followups) as sf "
            f"FROM daily_summary {date_clause}", date_params
        ).fetchone()

        sessions = summary["sessions"] or 0
        total_calls = sum(t["calls"] for t in tools.values())
        st = summary["st"] or 0
        sf = summary["sf"] or 0

        # Date range
        date_range = conn.execute(
            f"SELECT MIN(date) as first, MAX(date) as last, COUNT(DISTINCT date) as days FROM daily_summary {date_clause}", date_params
        ).fetchone()

        # Top queries: never surfaced — privacy contract forbids logging
        # query content. The daily_queries table is phased out (wiped at
        # the same deploy that landed this change). Returning [] keeps
        # downstream consumers (admin dashboard) rendering an empty
        # panel rather than erroring on a missing key.
        top_queries = []

        # Daily breakdown
        daily = []
        for row in conn.execute(
            f"SELECT date, sessions, haiku_fired, search_total FROM daily_summary {date_clause} ORDER BY date", date_params
        ):
            daily.append({"date": row["date"], "sessions": row["sessions"],
                          "searches": row["search_total"], "haiku_fired": row["haiku_fired"]})

        conn.close()

        return {
            "period": {
                "from": date_range["first"] or "",
                "to": date_range["last"] or "",
                "days": date_range["days"] or 0,
                "range": range_param,
            },
            "sessions": sessions,
            "total_tool_calls": total_calls,
            "calls_per_session": round(total_calls / max(sessions, 1), 1),
            "followup_rate": round(sf / max(st, 1) * 100),
            "clients": clients,
            "tools": tools,
            "haiku_rerank": {
                "fired": summary["hf"] or 0,
                "skipped": summary["hs"] or 0,
                "changed_top": summary["hc"] or 0,
            },
            "top_queries": top_queries,
            "daily": daily,
        }
    except Exception as e:
        return {"error": str(e)}


def _start_metrics_flusher():
    """Start background thread that flushes metrics every 10 minutes."""
    _init_metrics_db()
    def _flusher():
        while True:
            time.sleep(600)  # 10 min
            _flush_metrics_to_disk()
    t = threading.Thread(target=_flusher, daemon=True)
    t.start()


def _log_search_trace(trace: dict):
    """Append a search trace to the daily research log (non-blocking)."""
    try:
        _RESEARCH_LOG_DIR.mkdir(parents=True, exist_ok=True)
        day = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        _prune_search_traces(day)
        path = _RESEARCH_LOG_DIR / f"search_traces_{day}.jsonl"
        line = json.dumps(trace, ensure_ascii=False, default=str) + "\n"
        with _research_log_lock:
            with open(path, "a") as f:
                f.write(line)
    except Exception:
        pass  # never break search for logging


def _record_zero_result(tool: str, query: str):
    """No-op (privacy contract: query content is never logged).

    Previously stored the failing query string in an in-memory buffer
    and surfaced it via the live metrics endpoint's
    ``zero_result_queries`` field — useful for quality work but
    inconsistent with the no-query-content guarantee at /datenschutz/.
    The aggregate "how many calls returned zero results" can be
    reconstructed from daily_tool_calls error/return counts if needed.

    Kept as a signature-compatible stub so existing call sites work
    untouched; safe to remove the call sites in a follow-up cleanup."""
    return


def _get_metrics() -> dict:
    """Return current metrics snapshot."""
    tool_stats = {}
    for name, count in _metrics["tool_calls"].most_common():
        lats = sorted(_metrics["tool_latency_ms"].get(name, []))
        n = len(lats)
        outcomes = _metrics["tool_outcomes"].get(name) or {}
        tool_stats[name] = {
            "calls": count,
            "avg_ms": round(sum(lats) / n, 1) if n else 0,
            "p50_ms": round(lats[n // 2], 0) if n else 0,
            "p95_ms": round(lats[int(n * 0.95)], 0) if n else 0,
            "errors": _metrics["tool_errors"].get(name, 0),
            # Cumulative since boot, same semantics as calls/errors, so the
            # existing delta reconstruction in scripts/metrics_report.py
            # handles them without a special case. labelled = the two summed;
            # calls - labelled is the share no outcome could be attached to.
            "substantive": outcomes.get("substantive", 0),
            "empty": outcomes.get("empty", 0),
            # Provenance of those labels. 'status' means inferred from the
            # HTTP code, which cannot see a 200 carrying an empty list, so
            # a tool whose outcomes are mostly status-derived has an
            # optimistic answered rate. 'declared' means the route said so.
            "outcome_declared": (_metrics["outcome_sources"].get(name)
                                 or {}).get("declared", 0),
            "outcome_from_status": (_metrics["outcome_sources"].get(name)
                                    or {}).get("status", 0),
            # Top reasons a call answered nothing — the actionable field.
            "empty_reasons": dict(
                (_metrics["empty_reasons"].get(name)
                 or collections.Counter()).most_common(5)),
        }

    # Query content never surfaced (privacy contract — see
    # _record_query / _record_zero_result above). recent_queries +
    # zero_results buffers are no-op stubs; both lists are empty and
    # exist only to keep downstream code that references them happy.
    top_queries: list = []
    zero_agg: collections.Counter = collections.Counter()

    sessions = max(_metrics["sessions"], 1)
    total_calls = sum(s["calls"] for s in tool_stats.values())

    followup_rate = round(_metrics["search_followups"] / max(_metrics["search_total"], 1) * 100)

    return {
        "uptime_since": _metrics["startup_time"],
        "sessions": _metrics["sessions"],
        "calls_per_session": round(total_calls / sessions, 1),
        "followup_rate": followup_rate,
        "clients": dict(_metrics["clients"].most_common()),
        "top_queries": top_queries,
        "tools": tool_stats,
        "haiku_rerank": {
            "fired": _metrics["haiku_rerank_fired"],
            "skipped": _metrics["haiku_rerank_skipped"],
            "changed_top": _metrics["haiku_rerank_changed_top"],
        },
        "search_result_cache": {
            "hits": _metrics["search_result_cache_hits"],
            "misses": _metrics["search_result_cache_misses"],
            "entries": len(_SEARCH_RESULT_CACHE),
        },
        "zero_result_queries": [
            {"query": q, "count": n}
            for q, n in zero_agg.most_common(30)
        ],
    }


# ── Search functions ──────────────────────────────────────────

def _sanitize_fts5(query: str) -> str:
    """Sanitize a query for FTS5 — remove characters that cause syntax errors."""
    q = query.strip()
    # Phrase preservation (issue #42): pull out balanced "double-quoted" phrases
    # BEFORE the destructive transforms + operator handling below, so an
    # intentional phrase search ("Treu und Glauben") isn't silently decomposed
    # into an AND query (which for that phrase is ~92% false positives). Only
    # engages when quotes are balanced (even count); unbalanced or empty quotes
    # fall through to the legacy strip, which still prevents the "" empty-phrase
    # FTS5 crash. Each phrase's interior is reduced to tokenizable text
    # (punctuation -> space) so the phrase itself can't trigger an FTS5 syntax
    # error, and operators inside it stay literal (as phrase semantics require).
    _phrases: list[str] = []
    if q.count('"') >= 2 and q.count('"') % 2 == 0:
        _PH_STRIP = re.compile(r"[\"'\u2019.\-\u2013\u2014/\\(){}\[\]^~:]")

        def _stash_phrase(m: "re.Match") -> str:
            inner = re.sub(r"\s+", " ", _PH_STRIP.sub(" ", m.group(1))).strip()
            if not inner:
                return " "  # empty phrase -> dropped (FTS5 "" crash guard)
            _phrases.append(inner)
            return f" \ue000{len(_phrases) - 1}\ue000 "

        q = re.sub(r'"([^"]*)"', _stash_phrase, q)
    # FTS3/4-style proximity "a NEAR/5 b" \u2192 FTS5 "NEAR(a b, 5)" (#78).
    # Users porting queries from other engines type the slash form; FTS5
    # rejects it and the error surfaced as a silent no-match. Chains
    # (a NEAR/3 b NEAR/7 c) collapse into ONE group with the largest
    # distance \u2014 nested NEAR is not valid FTS5. The construct is stashed
    # as a placeholder (like phrases) because the transforms below strip
    # its parens and slash; terms are mini-cleaned here, multi-token terms
    # become quoted phrases inside the group. Runs after phrase-stashing,
    # so a quoted operand arrives as a placeholder and stays a phrase.
    _nears: list[str] = []

    def _fold_near_chain(m: "re.Match") -> str:
        parts = re.split(r"\s+NEAR/(\d+)\s+", m.group(0), flags=re.IGNORECASE)
        terms: list[str] = []
        for raw_term in parts[0::2]:
            cleaned = re.sub(r"[^\w\s\ue000]", " ", raw_term)
            toks = cleaned.split()
            if not toks:
                continue
            terms.append(" ".join(toks) if len(toks) == 1
                         else f'"{" ".join(toks)}"')
        if len(terms) < 2:
            return " ".join(terms) + " "     # degenerate \u2014 plain terms
        dist = min(max(int(d) for d in parts[1::2]), 999)
        _nears.append(f"NEAR({' '.join(terms)}, {dist})")
        return f" \ue001{len(_nears) - 1}\ue001 "

    q = re.sub(r"\S+(?:\s+NEAR/\d+\s+\S+)+", _fold_near_chain, q,
               flags=re.IGNORECASE)
    # Replace apostrophes (French: l'obligation)
    q = q.replace("\u2019", " ").replace("'", " ")
    # Replace ALL dots with spaces — FTS5 query parser rejects bare
    # punctuation, AND treats in-token dots as syntax errors in some
    # contexts (e.g. "10.21257/sg.288" → "fts5: syntax error near \".\""
    # reported 2026-05-27). Since the unicode61 tokenizer treats dots as
    # token separators anyway, replacing them preserves semantic meaning:
    # "Art.172" indexes as ["art", "172"] either way.
    q = q.replace('.', ' ')
    # Strip double quotes — LLM-generated queries use them sporadically and
    # "" (empty phrase) triggers FTS5 "syntax error near \"\"". Rare legit
    # use of "phrase" search is outweighed by reliability gain here.
    q = q.replace('"', ' ')
    # Hyphens: FTS5 parses "X-Y" as column-filter (column=X, term=Y) →
    # "no such column: X" errors. Real production trigger today (2026-04-20):
    # German compound "öffentlich-rechtliche" broke search_commentaries.
    # Replace with spaces; the FTS5 tokenizer also treats hyphen as a word
    # boundary, so "X-Y" and "X Y" index the same way. Semantic loss: nil.
    q = q.replace('-', ' ').replace('\u2013', ' ').replace('\u2014', ' ')
    # Colons: same family of bug ("col:term" column-filter syntax). Preserve
    # only when the prefix token is an actual FTS5 column name — that's the
    # only legitimate use of ":" inside a user query.
    _FTS5_COLUMN_NAMES = (
        "full_text", "regeste", "title", "docket", "docket_number",
        "abstract_de", "abstract_fr", "abstract_it", "chamber", "court",
        "abbr", "article_num", "authors", "article", "sr_number", "snippet",
    )
    def _colon_replacer(m: "re.Match") -> str:
        prefix = m.group(1)
        if prefix.lower() in _FTS5_COLUMN_NAMES:
            return f"{prefix}:"
        return f"{prefix} "
    q = re.sub(r"(\w+):", _colon_replacer, q)
    # Strip any "orphan" colons (not preceded by a word char) — e.g. ":foo",
    # " : bar", "::". Colons preceded by a word char are kept only if the
    # preceding token was whitelisted above.
    q = re.sub(r"(?<!\w):", " ", q)
    # Remove other FTS5 problematic characters. The slash "/" is treated
    # by FTS5's syntax parser like punctuation in some positions
    # (DOI "10.21257/sg.288" → "syntax error near \"/\""), so we strip
    # it to spaces. unicode61 tokenizer treats it as a word separator
    # anyway, so semantic meaning is preserved.
    q = q.replace("(", " ").replace(")", " ").replace("{", " ").replace("}", " ")
    q = q.replace("[", " ").replace("]", " ").replace("^", " ").replace("~", " ")
    q = q.replace("/", " ").replace("\\", " ")
    # Characters with no FTS5 meaning that its parser rejects outright.
    # Measured in production 2026-08-26: search_scholarship logged 176
    # "fts5: syntax error" in TWO HOURS — 131 on ",", 30 on "%", 15 on the
    # backtick, 2 on "=" — because these reached the engine raw. A query as
    # ordinary as "Haftung, Vertrag" returned a database error to the user.
    # search_decisions was insulated only because the Haiku query-parse
    # normalises text first; search_scholarship goes straight to FTS5.
    #
    # Safe at this point in the pipeline: stashed phrases (\ue000) and folded
    # NEAR groups (\ue001) are re-inserted AFTER the operator loop below, so
    # the comma inside NEAR(a b, 5) and every phrase interior are untouched.
    # "*" (prefix) and ":" (column filter) are deliberately NOT in this class.
    q = re.sub(r"[,%`=;!?&|<>@#$]", " ", q)
    # Collapse multiple spaces
    q = re.sub(r'\s+', ' ', q).strip()
    if not q:
        return ""
    # FTS5 treats uppercase AND / OR / NOT / NEAR as reserved operators, but
    # "OR" is ALSO the Swiss statute abbreviation for Obligationenrecht and
    # gets used as a literal far more often than as a boolean. So:
    #   - "OR" is ALWAYS quoted (force literal match on the word "OR").
    #   - AND / NOT / NEAR keep operator semantics when they have operands on
    #     both sides; otherwise they're stripped so bare-operator queries
    #     don't fault FTS5.
    FTS5_RESERVED = {"AND", "NOT", "NEAR"}
    tokens = q.split()
    bare_content = [t for t in tokens if t.upper() not in (FTS5_RESERVED | {"OR"})]
    if not bare_content:
        return ""
    out_tokens: list[str] = []
    for i, t in enumerate(tokens):
        tu = t.upper()
        if tu == "OR":
            out_tokens.append('"OR"')
        elif tu in FTS5_RESERVED:
            has_left = i > 0 and tokens[i - 1].upper() not in (FTS5_RESERVED | {"OR"})
            has_right = any(
                nt.upper() not in (FTS5_RESERVED | {"OR"})
                for nt in tokens[i + 1:]
            )
            if has_left and has_right:
                out_tokens.append(tu)       # keep as boolean operator
            # else: drop bare operator
        else:
            out_tokens.append(t)
    result = " ".join(out_tokens)
    # Re-insert translated NEAR groups (#78) FIRST — a group can carry a
    # stashed-phrase marker as an operand, and the phrase loop below is
    # what resolves it to its quoted form. (Both run after the operator
    # loop so interiors can't be mistaken for boolean operators.)
    for _i, _ng in enumerate(_nears):
        result = result.replace(f"\ue001{_i}\ue001", _ng)
    # Re-insert the preserved phrases as FTS5 quoted phrases (issue #42).
    for _i, _ph in enumerate(_phrases):
        result = result.replace(f"\ue000{_i}\ue000", f'"{_ph}"')
    return result


# A query that is exactly one balanced double-quoted phrase (e.g. `"Treu und
# Glauben"`). Such a query must stay a phrase MATCH: the OR/expansion strategies
# would turn it into a term-alternation ("Glauben" alone matches) with ~92% false
# positives (issue #42). re.DOTALL is irrelevant \u2014 phrases are single-line.
_PURE_PHRASE_RE = re.compile(r'^"[^"]+"$')


def _is_pure_phrase_query(fts_query: str) -> bool:
    """True if the sanitized query is a single quoted phrase and nothing else."""
    return bool(_PURE_PHRASE_RE.match((fts_query or "").strip()))


_FTS5_OR_MAX_TERMS = 12

# Function words that must never become an OR term: on decisions_fts a
# single "in" / "und" / "der" / "de" / "che" matches most of the ~1M rows,
# and a ranked OR over such a term is a BM25 pass over the whole table.
# NL_STOPWORDS (query-parse list) plus the common de/fr/it/en function
# words it leaves out; legal vocabulary is deliberately absent.
_FTS5_OR_STOPWORDS: frozenset[str] = frozenset(NL_STOPWORDS) | frozenset({
    # de
    "es", "er", "sie", "ist", "hat", "wird", "dass", "bei", "nach", "aus",
    "vom", "vor", "durch", "sich", "auch", "nur", "noch", "wie", "wenn",
    "sind", "war", "werden", "wurde", "sein", "seine", "seiner", "ihre",
    "ihrer", "dieser", "diese", "dieses", "gegen", "bzw", "sowie", "kann",
    "muss", "hier", "dort", "so", "ob", "ab", "je",
    # fr
    "est", "sont", "que", "qui", "il", "elle", "ils", "elles", "ne", "pas",
    "par", "en", "se", "ce", "ces", "cette", "cet", "son", "sa", "ses",
    "leur", "leurs", "on", "où", "ou", "mais", "donc", "car", "si", "été",
    "être", "avoir", "fait", "plus", "très", "tout", "tous", "toute",
    "toutes", "aussi", "comme", "lors", "selon", "vers", "chez", "entre",
    # it
    "che", "non", "sono", "da", "come", "ha", "hanno", "era", "essere",
    "sua", "suo", "suoi", "sue", "loro", "questo", "questa", "questi",
    "queste", "anche", "più", "già", "tra", "fra", "dal", "dallo", "dalla",
    "dai", "dagli", "dalle", "nello", "negli", "nelle", "sullo", "sugli",
    "sulle", "alla", "allo", "alle", "dello", "degli", "dell", "nell",
    "all", "sull", "dall", "col", "coi", "lo", "gli", "le", "il",
    # en
    "is", "are", "was", "were", "be", "been", "by", "at", "as", "it",
    "its", "this", "that", "these", "those", "from", "into", "than", "then",
    "not", "no", "yes", "but", "if", "so", "any", "all", "can", "may",
    "does", "do", "did", "has", "have", "had",
})

# Ceiling on the rows a relaxed OR may score on decisions_fts. BM25 needs
# every matched row scored before ORDER BY rank can pick the top of the
# list, so an OR of common legal words ("Vertrag" OR "Schaden") over the
# whole table is unbounded; the relaxed query scores the first N matches
# (court/date filters applied, so a filtered page is not blind) and ranks
# within them. 20,000 rows is ~50-100 ms of scoring; the strict path's own
# pool is 5,000.
_OR_RELAX_SCAN_CAP = 20_000
# Ceiling on the statute-ranked candidates the OR re-rank scores. Each
# candidate is one rowid-keyed MATCH (a doclist seek per term, ~1 ms),
# so the head of the statute ranking is re-ordered and the tail keeps its
# order. find_leading_cases over-fetches limit×3, so this is only reached
# at limit > 33.
_OR_RERANK_MAX_CANDIDATES = 100


def _fts5_or_query(query: str) -> str:
    """The ranked-OR relaxation of a free-text query, or "" when there is
    nothing to relax.

    FTS5 ANDs bare terms, so a query of four terms answers nothing as soon
    as one of them is absent from every candidate — measured over 30 days:
    find_leading_cases empty on 31% of MCP calls, search_botschaft on 57%.
    The relaxed form ORs the distinct word tokens and lets BM25 rank the
    rows that carry most of them. It is only ever run AFTER the strict form
    answered nothing, and the caller flags the result (`filters_relaxed`),
    so a relaxed page is never mistaken for a strict one. A single-term
    query cannot be relaxed (OR of one term is the term) and returns "".

    Function words (_FTS5_OR_STOPWORDS) are dropped first: a query of only
    stop words returns "" and never relaxes, and "Haftung des Tierhalters"
    relaxes to "Haftung" OR "Tierhalters", not to a term that matches the
    whole corpus.

    Invariant #3 exemption: this is the one FTS5 entry point that does not
    pass through _sanitize_fts5, because the sanitiser quotes the OR
    operator ('"Art" OR "41"' -> '"Art" "OR" "41"'). It is safe by
    construction — tokens come from re.findall(r"\\w+") (letters, digits,
    underscore only), every token is wrapped in double quotes and the FTS5
    operator words are dropped — so no operator, punctuation or column
    filter from the input can reach the MATCH expression. Tested against
    hostile input in tests/test_never_empty_fallbacks.py.
    """
    toks: list[str] = []
    seen: set[str] = set()
    for t in re.findall(r"\w+", query or ""):
        tl = t.lower()
        if (len(tl) < 2 or tl in seen or tl in ("and", "or", "not", "near")
                or tl in _FTS5_OR_STOPWORDS):
            continue
        seen.add(tl)
        toks.append(t)
        if len(toks) >= _FTS5_OR_MAX_TERMS:
            break
    if len(toks) < 2:
        return ""
    return " OR ".join(f'"{t}"' for t in toks)


# Exact match-count for the `total` field on text searches. The reranked path
# returns a bounded candidate POOL, so its size is not the true number of
# matching decisions: it scales with `limit` and caps at MAX_RERANK_CANDIDATES.
# This computes the real count of decisions matching the sanitized FTS query
# (+ the same filters), so `total` is honest and pagination is meaningful — the
# results themselves (and their ranking) are unchanged. Cached per
# (db_generation, query, filters); db_generation is part of the key, so a
# nightly atomic swap invalidates stale counts automatically.
_FTS_TOTAL_CACHE: dict = {}
_FTS_TOTAL_CACHE_MAX = 2048
# An unbounded FTS5 COUNT walks the whole doclist — 10-15s for a 300k-match word
# like "Verfahren". So the count is BOUNDED via a LIMIT subquery (the LIMIT
# short-circuits the FTS scan): exact up to the cap, reported as the cap (a
# floor) beyond it. The reranked text path only returns ~MAX_RERANK_CANDIDATES
# anyway, and structural filters (court/canton/date) give exact totals + full
# enumeration well past this — so the cap costs nothing real.
#
# Set to MAX_LIMIT (2026-07-09): the count is EXACT up to the most results a text
# search can return, reported as "MAX_LIMIT+" beyond. Aligning the cap with
# MAX_LIMIT means the displayed total never under-reports within the retrievable
# range, so a client paginating a text+filter result set is never told to stop
# early — no loss of the enumerate-all guarantee. The real CPU fix for the hot
# _exact_fts_total path (py-spy: one worker at 827%) was the CROSS JOIN below
# that forces FTS-driven counting; with that in place the cap value costs nothing
# (a broad language-filtered count is ~0ms at 1000 or 2000). Was briefly 1000;
# restored to full retrievable precision once CROSS JOIN removed the cost.
_FTS_TOTAL_CAP = MAX_LIMIT


def _exact_fts_total(conn, fts_query: str, where: str, params: list):
    """Return `(total, is_capped)` for decisions matching `fts_query` + filters,
    or None on any error (caller then falls back to the candidate-pool size).
    Bounded by _FTS_TOTAL_CAP — exact up to the cap, the cap as a floor beyond it
    — so a broad term cannot make COUNT walk the whole doclist. `is_capped` is
    True when the true count exceeds the cap, i.e. `total` is a lower bound (#53).
    Unfiltered queries count the FTS index directly (no table join) for speed."""
    if not fts_query or not fts_query.strip():
        return None
    try:
        gen = conn.execute("PRAGMA user_version").fetchone()[0]
    except Exception:
        gen = 0
    key = (gen, fts_query, where, tuple(params))
    hit = _FTS_TOTAL_CACHE.get(key)
    if hit is not None:
        return hit
    cap1 = _FTS_TOTAL_CAP + 1  # LIMIT short-circuits the FTS scan → bounded latency
    try:
        if where:
            # CROSS JOIN forces SQLite to drive the count from the FTS MATCH
            # (bounded by LIMIT), not from the filter index. With a plain JOIN the
            # planner drove off idx_decisions_language for the very common
            # language filter — scanning ~600k 'de' rows and probing FTS for each,
            # ~5s per count on the hot search path (py-spy showed _exact_fts_total
            # at 98% of worker CPU, 2026-07-09). CROSS JOIN keeps the count EXACT
            # (same semantics as before) but makes the common case ~5s -> ~0s; the
            # only cost is a selective filter + very broad term (rare) at ~1s.
            row = conn.execute(
                "SELECT count(*) FROM (SELECT 1 FROM decisions_fts "
                "CROSS JOIN decisions d ON d.rowid = decisions_fts.rowid "
                f"WHERE decisions_fts MATCH ?{where} LIMIT ?)",
                [fts_query] + list(params) + [cap1],
            ).fetchone()
        else:
            row = conn.execute(
                "SELECT count(*) FROM (SELECT 1 FROM decisions_fts "
                "WHERE decisions_fts MATCH ? LIMIT ?)",
                [fts_query, cap1],
            ).fetchone()
        raw = int(row[0]) if row and row[0] is not None else 0
        # raw is at most cap+1 (the subquery LIMIT); raw > cap means the count
        # was clipped -> the reported total is a lower bound, not exact (#53).
        total = min(raw, _FTS_TOTAL_CAP)
        is_capped = raw > _FTS_TOTAL_CAP
    except Exception:
        return None
    if len(_FTS_TOTAL_CACHE) >= _FTS_TOTAL_CACHE_MAX:
        # Evict the oldest ~1/8 instead of clearing the whole cache. A full
        # clear() (the previous behaviour) periodically dumped every entry, so
        # on the hot _exact_fts_total path a burst of misses had to recompute
        # doclist walks all at once — a recompute storm right when load is
        # highest. dict preserves insertion order, so the leading keys are the
        # oldest; popping a fraction keeps hot counts resident (2026-07-09).
        for _old_key in list(_FTS_TOTAL_CACHE.keys())[:_FTS_TOTAL_CACHE_MAX // 8]:
            _FTS_TOTAL_CACHE.pop(_old_key, None)
    _FTS_TOTAL_CACHE[key] = (total, is_capped)
    return (total, is_capped)


# ── Search-result cache ──────────────────────────────────────
# Devdata 2026-08: ~30% of search queries are byte-identical repeats
# (one integrator loop alone at ~8,900×/wk), each re-paying the full
# FTS5 + hybrid + Haiku-rerank pipeline. Keyed on the sha256 of ALL
# search args serialized verbatim: FTS5 operators are case-sensitive
# ('Mietzins OR Pachtzins' ≠ 'mietzins or pachtzins', see c975ea1a),
# so no strip/lower/truncation — a folded key would serve one query's
# results for the other. Same privacy posture as the LLM caches: no
# raw query text retained as a key, memory-only, cleared on DB swap
# via _cache_clear() and by the nightly worker recycle. TTL is
# belt-and-braces on top of the generation hook and bounds how long a
# silently degraded entry (e.g. rerank timeout) can live.
# maxsize raised 256 -> 1024 (2026-08-24). Replaying three days of captured
# traffic showed 1024 saturates the hit rate (2048/4096 are identical) with an
# observed peak of ~1,513 entries per shard. Rows carry no full_text and
# snippets are capped at MAX_SNIPPET_LEN, so this is ~42KB/entry, ~43MB per
# worker, ~350MB across the 8 — acceptable.
#
# TTL deliberately LEFT AT 1h. Raising it to 6-24h would buy more, but the
# probe that would benefit most is quality/smoke.py's own canary, which uses a
# real German query specifically so it reaches _rerank_rows — "precisely the
# code that broke" on 2026-08-22. A longer TTL turns that canary into a cache
# hit and pushes rerank-breakage detection from minutes to hours. Cheaper and
# safer to stop paying for our own monitoring at source: the ops-dashboard
# probe fires every 60s (~1,323 pipeline runs/day). If the TTL is ever raised,
# make smoke.py vary its query first.
_SEARCH_RESULT_CACHE = _BoundedTTLCache(maxsize=1024, ttl_s=3600.0)
# Bulk/export calls (REST allows limit up to 2000) are rare, huge, and
# not the repeat traffic — don't let one evict 50 real entries' worth
# of memory.
_SEARCH_RESULT_CACHE_LIMIT_GATE = 100


def _search_result_cache_key(args: tuple) -> str:
    payload = json.dumps(args, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8", "replace")).hexdigest()


def search_fts5(
    query: str,
    court: str | None = None,
    canton: str | None = None,
    language: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
    chamber: str | None = None,
    decision_type: str | None = None,
    legal_area: str | None = None,
    marked_for_publication: bool | None = None,
    limit: int = DEFAULT_LIMIT,
    offset: int = 0,
    sort: str | None = None,
    meta: dict | None = None,
) -> tuple[list[dict], int]:
    """
    Full-text search using SQLite FTS5 with BM25 ranking.

    Returns (results, total_count) where total_count is the approximate
    total number of matching decisions (exact for filter-only queries).

    Pass `meta={}` to receive out-of-band `meta["total_is_lower_bound"]` — True
    when total_count is a capped floor rather than an exact count (#53). Kept as
    an out-param so the 6 callers that discard total stay unchanged.

    Results are served from _SEARCH_RESULT_CACHE for byte-identical repeat
    calls (limit ≤ _SEARCH_RESULT_CACHE_LIMIT_GATE). Hits and misses are
    deep-copied in both directions: callers mutate returned rows (the REST
    `fields` stripping, handler annotations), and a shared reference would
    poison the cache.

    The FTS5 query supports:
    - Simple words: verfassungsrecht
    - Phrases: "Treu und Glauben"
    - Boolean: arbeitsrecht AND kündigung
    - Prefix: verfassung*
    - Column filters: full_text:miete AND regeste:kündigung
    """
    # get_db() BEFORE the cache lookup: its db_generation check clears the
    # cache on a corpus swap, so a hit can never outlive the DB it came from.
    conn = get_db()
    try:
        cache_key = None
        if limit <= _SEARCH_RESULT_CACHE_LIMIT_GATE:
            cache_key = _search_result_cache_key((
                query, court, canton, language, date_from, date_to,
                chamber, decision_type, legal_area, marked_for_publication,
                limit, offset, sort,
            ))
            cached = _SEARCH_RESULT_CACHE.get(cache_key)
            if cached is not None:
                _metrics["search_result_cache_hits"] += 1
                results, total, cached_meta = copy.deepcopy(cached)
                if meta is not None:
                    meta.update(cached_meta)
                return results, total
            _metrics["search_result_cache_misses"] += 1

        # Always give the inner search a real dict, even when the caller
        # passed None: cache entries must be meta-complete, or a later
        # caller that DOES want meta would replay a hit with no flags.
        inner_meta: dict = {}
        results, total = _search_fts5_inner(
            conn, query, court, canton, language,
            date_from, date_to, chamber, decision_type, legal_area,
            limit, offset, sort=sort,
            marked_for_publication=marked_for_publication,
            meta=inner_meta,
        )
        # Surface the BGE-bound flag on each result (BGer Neuheiten "*" =
        # "für die Publikation vorgesehen"). Single guarded lookup — the column
        # exists only after a post-schema-change rebuild; pre-rebuild → omitted.
        if results and _sqlite_has_column(conn, "decisions", "marked_for_publication"):
            ids = [r.get("decision_id") for r in results if r.get("decision_id")]
            if ids:
                ph = ",".join("?" * len(ids))
                flags = {
                    row[0]: row[1]
                    for row in conn.execute(
                        f"SELECT decision_id, marked_for_publication "
                        f"FROM decisions WHERE decision_id IN ({ph})",
                        ids,
                    )
                }
                for r in results:
                    v = flags.get(r.get("decision_id"))
                    if v is not None:
                        r["marked_for_publication"] = bool(v)
        if meta is not None:
            meta.update(inner_meta)
        # A deadline-partial pool is a degraded result the next identical
        # call may well beat — never pin it for the TTL.
        if cache_key is not None and not inner_meta.get("deadline_partial"):
            _SEARCH_RESULT_CACHE.set(
                cache_key, copy.deepcopy((results, total, inner_meta))
            )
        return results, total
    finally:
        conn.close()


def _parse_date_param(val: str | None) -> str | None:
    """Normalize a date filter to ISO 8601 (YYYY-MM-DD), or None if unparseable.

    date_from/date_to are compared lexicographically by SQLite against ISO
    decision_date strings, so a non-ISO value silently corrupts the filter:
    Swiss 'DD.MM.YYYY' is always < 'YYYY-MM-DD' (filter no-ops -> unfiltered),
    US 'MM/DD/YYYY' can be always-false (0 results). Rather than compare
    garbage, accept ISO pass-through + Swiss DD.MM.YYYY (the standard CH format,
    with calendar validation) and return None for anything else so the caller
    drops the filter instead of silently mis-filtering (issue #45).
    """
    if not val or not isinstance(val, str) or not val.strip():
        return None
    s = val.strip()
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
        try:
            datetime.strptime(s, "%Y-%m-%d")  # reject '2024-99-99' / '2023-02-29'
        except ValueError:
            return None
        return s
    m = re.fullmatch(r"(\d{1,2})\.(\d{1,2})\.(\d{4})", s)
    if m:
        d, mo, y = (int(x) for x in m.groups())
        try:
            datetime(y, mo, d)  # reject impossible dates (32.13.2024)
        except ValueError:
            return None
        return f"{y:04d}-{mo:02d}-{d:02d}"
    return None


def _query_length_error(query: str | None) -> str | None:
    """Refusal message for a query beyond QUERY_MAX_CHARS, else None.

    The text must teach the calling agent HOW to retry — Copilot-style
    clients read tool errors and re-call. A generic 'too long' produces a
    generic retry; naming the extraction step produces a usable one.
    (Below the hard cap, long queries are auto-condensed instead — see
    QUERY_CONDENSE_THRESHOLD.)"""
    n = len(query or "")
    if n <= QUERY_MAX_CHARS:
        return None
    return (
        f"Query too long: {n:,} characters (max {QUERY_MAX_CHARS:,}). Do not "
        "paste entire documents or letters. Extract the legal issue and retry "
        "with 3-8 precise search terms, e.g. 'missbräuchliche Kündigung "
        "Art. 336 OR Sperrfrist'. One search per distinct legal issue. "
        "Statute citations (Art. 336 OR) may be included verbatim in the query."
    )


def _date_arg_error(date_from: str | None, date_to: str | None) -> str | None:
    """Return an error message if a NON-EMPTY date filter can't be parsed, else
    None. Used to reject an unrecognized date explicitly instead of silently
    dropping the filter and returning broader results (issue #45, Codex review)."""
    bad = [f"{lbl}={v!r}" for lbl, v in (("date_from", date_from), ("date_to", date_to))
           if v and v.strip() and _parse_date_param(v) is None]
    if bad:
        return ("Unrecognized date filter (" + ", ".join(bad) +
                "). Use ISO YYYY-MM-DD or Swiss DD.MM.YYYY. The filter was NOT "
                "applied — re-issue with a valid date rather than trusting these results.")
    return None


def _search_fts5_inner(
    conn: sqlite3.Connection,
    query: str,
    court: str | None,
    canton: str | None,
    language: str | None,
    date_from: str | None,
    date_to: str | None,
    chamber: str | None,
    decision_type: str | None,
    legal_area: str | None,
    limit: int,
    offset: int = 0,
    sort: str | None = None,
    marked_for_publication: bool | None = None,
    meta: dict | None = None,
) -> tuple[list[dict], int]:
    """Inner search logic. Returns (results, total_count). Caller closes conn.

    When `meta` is a dict, sets `meta["total_is_lower_bound"]` — default False;
    only the reranked FTS path sets it True (capped count or count failure).
    Filter-only and docket totals are exact, so they leave the default (#53)."""
    if meta is not None:
        meta["total_is_lower_bound"] = False
    _trace_t0 = time.monotonic()
    _deadline = (_trace_t0 + SEARCH_DEADLINE_MS / 1000.0) if SEARCH_DEADLINE_MS > 0 else None
    _trace = {
        # Privacy contract (/datenschutz/): search query CONTENT is never
        # persisted. Search traces are kept for latency/strategy analysis, so we
        # store only the non-content length, never the query text itself. Codex
        # review P0.2. (Legal-domain queries can carry client names, allegations,
        # privileged strategy — these must not land in research_logs.)
        "query_len": len(query or ""),
        "language_filter": language,
        "court_filter": court,
    }
    # Auto-condense pasted documents after an integration evaluation found that
    # document-length input could time out. One choke point serves MCP, REST
    # and every internal search_fts5 caller. Citation refs survive verbatim;
    # the rest is distilled to the most informative terms. Disclosed via
    # meta['query_condensed'] so callers can tell the user what was searched.
    _condensed_info = None
    if QUERY_CONDENSE_THRESHOLD > 0 and len(query or "") > QUERY_CONDENSE_THRESHOLD:
        query, _condensed_info = _condense_query(query)
        if _condensed_info:
            _trace["condensed"] = True
            if meta is not None:
                meta["query_condensed"] = True
                meta["condensed_terms"] = _condensed_info["refs"] + _condensed_info["terms"]
                meta["original_query_chars"] = _condensed_info["original_chars"]
                # Internal: callers reuse the condensed text for pinpoint
                # enrichment instead of re-feeding the whole document.
                meta["condensed_query"] = query
    is_filter_only = not query.strip()
    effective_max = FILTER_MAX_LIMIT if is_filter_only else MAX_LIMIT
    limit = max(1, min(limit, effective_max))
    offset = max(0, offset)

    # Normalize date filters to ISO so the lexicographic SQLite comparison is
    # correct (issue #45); Swiss DD.MM.YYYY now works, unparseable -> dropped.
    date_from = _parse_date_param(date_from)
    date_to = _parse_date_param(date_to)

    fts_query = _sanitize_fts5(query)
    if not fts_query.strip():
        # No search query — return recent decisions with filters
        return _list_recent(conn, court, canton, language, date_from, date_to, chamber, decision_type, limit, offset, sort=sort, marked_for_publication=marked_for_publication)

    # Build WHERE clause for filters (applied to main table via JOIN)
    filters = []
    params: list = []

    if court:
        filters.append("d.court = ?")
        params.append(court.lower())
    if canton:
        filters.append("d.canton = ?")
        params.append(canton.upper())
    if language:
        filters.append("d.language = ?")
        params.append(language.lower())
    if date_from:
        filters.append("d.decision_date >= ?")
        params.append(date_from)
    if date_to:
        filters.append("d.decision_date <= ?")
        params.append(date_to)
    if chamber:
        filters.append("d.chamber LIKE ?")
        params.append(f"%{chamber}%")
    if decision_type:
        filters.append("d.decision_type LIKE ?")
        params.append(f"%{decision_type}%")
    # BGE-bound filter: only when requested AND the column exists (post-rebuild),
    # so the query never references the column on a pre-rebuild served DB.
    if marked_for_publication and _sqlite_has_column(conn, "decisions", "marked_for_publication"):
        filters.append("d.marked_for_publication = 1")
    # legal_area is NOT a WHERE filter — too many decisions lack this field.
    # Instead it's used as a reranking boost (see _rerank_rows).

    where = (" AND " + " AND ".join(filters)) if filters else ""

    is_docket_query = _looks_like_docket_query(fts_query)
    # Explicit-syntax detection runs on the ORIGINAL query: the sanitizer
    # rewrites 'Art. 335 OR' into 'Art 335 "OR"', which defeated the statute
    # mask AND tripped the quote-count branch, cutting every statute-citing
    # query off from the vector rescue below. A condensed document is natural
    # language by construction — never operator syntax.
    has_explicit_syntax = False if _condensed_info else _has_explicit_fts_syntax(query)
    inline_docket_candidates = _extract_inline_docket_candidates(fts_query)
    # Try collapsing space-separated queries into docket form
    collapsed = _collapse_spaced_docket(fts_query)
    if collapsed and collapsed not in inline_docket_candidates:
        inline_docket_candidates.insert(0, collapsed)
    inline_docket_results: list[dict] = []
    query_preferred_courts = _detect_query_preferred_courts(fts_query)

    # Docket-style lookups should prioritize exact/near-exact docket matches.
    if is_docket_query:
        # Extract just the docket portion from mixed queries like "BGer 4A_291/2017"
        docket_search_query = inline_docket_candidates[0] if inline_docket_candidates else fts_query
        try:
            docket_results = _search_by_docket(
                conn, docket_search_query, where, params, offset + limit,
                preferred_courts=query_preferred_courts,
            )
            if docket_results:
                if sort in ("date_desc", "date_asc"):
                    reverse = sort == "date_desc"
                    docket_results.sort(
                        key=lambda r: r.get("decision_date") or "", reverse=reverse,
                    )
                total = len(docket_results)
                return docket_results[offset:offset + limit], total
        except sqlite3.OperationalError as e:
            logger.debug("Docket-first query failed, falling back to FTS: %s", e)
    if inline_docket_candidates:
        per_docket_limit = max(4, min(limit, 10))
        for candidate in inline_docket_candidates[:3]:
            try:
                inline_docket_results.extend(
                    _search_by_docket(
                        conn, candidate, where, params, per_docket_limit,
                        preferred_courts=query_preferred_courts,
                    )
                )
            except sqlite3.OperationalError as e:
                logger.debug("Inline docket lookup failed for %s: %s", candidate, e)
                continue
        inline_docket_results = _dedupe_results_by_decision_id(inline_docket_results)

    _bm25_weights = ", ".join(
        str(SCORING_CONFIG[k]) for k in [
            "bm25_decision_id", "bm25_court", "bm25_canton", "bm25_docket_number",
            "bm25_language", "bm25_title", "bm25_regeste", "bm25_full_text",
        ]
    )
    sql = f"""
        SELECT
            d.decision_id,
            d.court,
            d.canton,
            d.chamber,
            d.docket_number,
            d.decision_date,
            d.language,
            d.title,
            d.regeste,
            d.full_text AS full_text_raw,
            snippet(decisions_fts, 7, '<mark>', '</mark>', '...', 40) as snippet,
            d.source_url,
            d.pdf_url,
            bm25(decisions_fts, {_bm25_weights}) as bm25_score
        FROM decisions_fts
        JOIN decisions d ON d.rowid = decisions_fts.rowid
        WHERE decisions_fts MATCH ?{where}
        ORDER BY bm25_score ASC
        LIMIT ?
    """

    had_success = False
    candidate_meta: dict[str, dict] = {}

    # ── Query analysis: expansion + structured parse run CONCURRENTLY (~2s saved,
    #    identical results to the prior sequential path) ──
    _trace["parse_start_ms"] = round((time.monotonic() - _trace_t0) * 1000)
    strategies, llm_terms, structured_parse, _parse_outcome = _analyze_query(
        fts_query, is_docket_query, original_query=query,
        force_natural_language=bool(_condensed_info))
    _trace["parse_ms"] = round((time.monotonic() - _trace_t0) * 1000) - _trace.get("parse_start_ms", 0)
    # ok | empty | skipped | failed | timeout — a parse failure was
    # indistinguishable from a query that never warranted a parse, so the
    # failure rate was unknowable (audit 2026-08-19).
    _trace["parse_outcome"] = _parse_outcome
    if structured_parse:
        # The FULL parse, not a five-field excerpt: this record is the
        # training set for a small query parser that could replace the
        # Haiku call (query-parse dominates search p50). Every field is
        # model-derived legal vocabulary — the same class of content the
        # excerpt already carried, no raw query text.
        _trace["structured_parse"] = dict(structured_parse)
        # The expansion terms actually used downstream were never traced
        # at all; a parser trained without them learns half the job. Only
        # the ADDED terms are kept: expansion frequently echoes the
        # query's own tokens, and the type-A record stores query_len
        # precisely so that no query text rides along — a term whose
        # every token already appears in the query is an echo, not an
        # expansion, and is dropped. (The delta is also the better
        # dataset: it is the part a parser has to learn.)
        _qtoks = {t.lower() for t in re.findall(r"\w+", query or "")}
        _trace["llm_terms"] = [
            t for t in (llm_terms or [])
            if not {w.lower() for w in re.findall(r"\w+", t)} <= _qtoks
        ][:12]
        # Inject doctrine + synonyms as FTS strategy
        if structured_parse:
            doctrine = (structured_parse.get("doctrine") or "").strip()
            # Detect concept translation: doctrine terms not in original query
            query_tokens = {t.lower() for t in re.findall(r'\w+', fts_query)}
            doctrine_tokens = {t.lower() for t in re.findall(r'\w+', doctrine)}
            is_concept_translation = bool(
                doctrine_tokens and not doctrine_tokens.issubset(query_tokens)
            )
            # Higher weight for concept translations (Hundebiss → Tierhalterhaftung)
            doctrine_weight = SCORING_CONFIG["doctrine_concept_translation_weight"] if is_concept_translation else SCORING_CONFIG["doctrine_direct_weight"]

            sp_parts: list[str] = []
            doctrine_fts: str = ""
            if doctrine:
                words = doctrine.split()
                if len(words) >= 2:
                    doctrine_fts = f'"{" ".join(words)}"'
                elif words:
                    doctrine_fts = words[0]
                sp_parts.append(doctrine_fts)
            syns = list(structured_parse.get("synonyms") or [])[:6]
            # Deterministic trilingual bridge (user report 2026-07-04: IT
            # decisions under-surfaced because Haiku drops Italian synonyms
            # inconsistently). Add the DE/FR/IT equivalents of any known
            # Swiss legal concept in the query or synonyms — additive OR
            # terms, so IT (and FR/DE) forms are always searched. Capped so
            # a broad query can't explode the FTS strategy.
            try:
                from search_stack.legal_glossary import trilingual_equivalents
                gloss = trilingual_equivalents([query, doctrine] + syns)[:8]
            except Exception:
                gloss = []
            for syn in syns + gloss:
                words = syn.strip().split()
                if len(words) >= 2:
                    sp_parts.append(f'"{" ".join(words)}"')
                elif words:
                    sp_parts.append(words[0])
            if sp_parts:
                sp_query = " OR ".join(sp_parts)
                strategies.append({
                    "name": "structured_doctrine",
                    "query": sp_query,
                    "weight": doctrine_weight,
                })
            # For concept translations, also add regeste/title-focused doctrine strategies.
            # Insert AFTER standard strategies (nl_and, regeste_focus, title_focus)
            # to avoid displacing them from early slots.
            if is_concept_translation and doctrine_fts:
                doctrine_norm = _normalize_token_for_fts(doctrine) if len(doctrine.split()) == 1 else doctrine_fts
                # Find insertion point: after title_focus or regeste_focus
                insert_pos = 0
                for si, s in enumerate(strategies):
                    if s.get("name") in {"title_focus", "regeste_focus"}:
                        insert_pos = si + 1
                strategies.insert(insert_pos, {
                    "name": "doctrine_regeste",
                    "query": f"regeste:{doctrine_norm}",
                    "weight": SCORING_CONFIG["doctrine_regeste_weight"],
                })
                strategies.insert(insert_pos + 1, {
                    "name": "doctrine_title",
                    "query": f"title:{doctrine_norm}",
                    "weight": SCORING_CONFIG["doctrine_title_weight"],
                })
        # Cross-lingual doctrine strategies (FR/IT equivalents)
        if structured_parse:
            for lang_key, lang_label in [("doctrine_fr", "fr"), ("doctrine_it", "it")]:
                cross_doc = (structured_parse.get(lang_key) or "").strip()
                if cross_doc and len(cross_doc) > 2:
                    words = cross_doc.split()
                    if len(words) >= 2:
                        cross_fts = f'"{" ".join(words)}"'
                    else:
                        cross_fts = words[0]
                    strategies.append({
                        "name": f"doctrine_{lang_label}",
                        "query": cross_fts,
                        "weight": SCORING_CONFIG["doctrine_cross_lingual_weight"],
                    })

    _trace["strategies_planned"] = len(strategies)
    target_pool = _target_candidate_pool(
        limit=limit,
        offset=offset,
        is_docket=is_docket_query,
        has_explicit_syntax=has_explicit_syntax,
    )
    query_has_expandable_terms = _query_has_expandable_terms(fts_query)

    _hard_interrupted = False
    for idx, strategy in enumerate(strategies):
        # Soft-deadline: stop launching more FTS strategies once the budget is
        # spent (always run the first, the primary strategy), so a broad query
        # degrades to fewer-strategy BM25 instead of a >50s pile-up.
        if idx > 0 and _past_deadline(_deadline):
            _trace["deadline_hit_strategy"] = idx
            if meta is not None:
                # Fewer strategies ran than planned: the ranking is degraded,
                # and callers paging or scripting on it deserve to know.
                meta["deadline_partial"] = True
            break
        match_query = strategy["query"]
        strategy_name = strategy.get("name", "")
        strategy_weight = float(strategy.get("weight", 1.0))
        expensive_strategy = strategy_name in {"nl_or", "nl_or_expanded"}
        cross_lingual = strategy_name.startswith("doctrine_fr") or strategy_name.startswith("doctrine_it")
        effective_need = offset + limit
        early_enough = max(effective_need * 2, 20)
        if expensive_strategy and not cross_lingual and len(candidate_meta) >= early_enough:
            break
        if strategy_name == "nl_or_expanded" and not query_has_expandable_terms:
            continue
        if expensive_strategy and _query_has_numeric_terms(fts_query):
            continue
        try:
            candidate_limit = min(max(target_pool, effective_need * 2), MAX_RERANK_CANDIDATES)
            if strategy_name in {"regeste_focus", "title_focus"}:
                candidate_limit = min(
                    MAX_RERANK_CANDIDATES,
                    max(candidate_limit, target_pool * 4),
                )
            with _deadline_abort(conn, _deadline):
                rows = conn.execute(
                    sql,
                    [match_query] + params + [candidate_limit],
                ).fetchall()
            had_success = True
        except sqlite3.OperationalError as e:
            if _past_deadline(_deadline) and "interrupt" in str(e).lower():
                # The progress handler aborted an in-flight MATCH — record it;
                # the cooperative check above ends the loop next iteration and
                # whatever candidates exist are returned with a partial note.
                _hard_interrupted = True
                _trace["deadline_interrupted"] = True
                if meta is not None:
                    meta["deadline_partial"] = True
            logger.debug(
                "FTS query failed, trying next strategy: %s (%s)",
                _truncate(match_query, 120),
                e,
            )
            continue

        for rank, row in enumerate(rows, start=1):
            decision_id = row["decision_id"]
            current = candidate_meta.get(decision_id)
            if current is None:
                current = {
                    "row": row,
                    "best_bm25": _to_float(row["bm25_score"]),
                    "rrf_score": 0.0,
                    "strategy_hits": 0,
                }
                candidate_meta[decision_id] = current

            bm25 = _to_float(row["bm25_score"])
            if bm25 < float(current["best_bm25"]):
                current["best_bm25"] = bm25
                current["row"] = row

            current["rrf_score"] = float(current["rrf_score"]) + (
                strategy_weight / (RRF_RANK_CONSTANT + rank)
            )
            current["strategy_hits"] = int(current["strategy_hits"]) + 1

        if len(candidate_meta) >= target_pool:
            break
        if idx == 0 and has_explicit_syntax and len(candidate_meta) >= effective_need:
            break

    # ── Vector search (parallel candidate source) ──
    # Augment vector query with LLM expansion terms for better semantic recall
    vector_scores: dict[str, float] = {}
    sparse_scores: dict[str, float] = {}
    if not is_docket_query and not has_explicit_syntax and not _past_deadline(_deadline):
        vector_query = fts_query
        if llm_terms:
            vector_query = f"{fts_query} {' '.join(llm_terms)}"
        vector_scores = _search_vectors(
            query=vector_query,
            language=language,
        )
        # Merge chunk-level vector results (re-check the deadline: the dense
        # vector search above may have crossed the budget mid-block).
        if not _past_deadline(_deadline):
            chunk_scores = _search_vectors_chunks(
                query=vector_query,
                language=language,
            )
            if chunk_scores:
                for did, dist in chunk_scores.items():
                    if did not in vector_scores or dist < vector_scores[did]:
                        vector_scores[did] = dist

        # Sparse search (re-check the deadline before this sub-source too).
        if not _past_deadline(_deadline):
            sparse_scores = _search_sparse(query=fts_query)

        # Add vector-only candidates to the pool (only when VECTOR_WEIGHT > 0)
        if vector_scores:
            vec_only_ids = (
                set(vector_scores.keys()) - set(candidate_meta.keys())
                if VECTOR_WEIGHT > 0
                else set()
            )
            if vec_only_ids:
                ph = ",".join("?" for _ in vec_only_ids)
                # Apply the SAME user filters as the FTS pass ({where}+params);
                # otherwise vector-only candidates bypass court/canton/date/
                # chamber/type/language filters (mirrors sg_rows/bge_rows).
                vec_rows = conn.execute(
                    f"""SELECT d.decision_id, d.court, d.canton, d.chamber,
                           d.docket_number, d.decision_date, d.language,
                           d.title, d.regeste, d.full_text AS full_text_raw,
                           '' as snippet, d.source_url, d.pdf_url,
                           0.0 as bm25_score
                    FROM decisions d WHERE d.decision_id IN ({ph}){where}""",
                    list(vec_only_ids) + params,
                ).fetchall()
                for row in vec_rows:
                    did = row["decision_id"]
                    candidate_meta[did] = {
                        "row": row,
                        "best_bm25": 0.0,
                        "rrf_score": 0.0,
                        "strategy_hits": 0,
                    }
            for rank, (did, _dist) in enumerate(
                sorted(vector_scores.items(), key=lambda x: x[1]), start=1
            ):
                if did in candidate_meta:
                    cm = candidate_meta[did]
                    cm["rrf_score"] = float(cm["rrf_score"]) + (
                        VECTOR_WEIGHT / (RRF_RANK_CONSTANT + rank)
                    )
                    cm["strategy_hits"] = int(cm["strategy_hits"]) + 1

        # Add sparse-only candidates to the pool
        if sparse_scores:
            sparse_only_ids = set(sparse_scores.keys()) - set(candidate_meta.keys())
            if sparse_only_ids:
                ph = ",".join("?" for _ in sparse_only_ids)
                # Same user filters as the FTS pass (incl. language, which sparse
                # retrieval is otherwise blind to).
                sp_rows = conn.execute(
                    f"""SELECT d.decision_id, d.court, d.canton, d.chamber,
                           d.docket_number, d.decision_date, d.language,
                           d.title, d.regeste, d.full_text AS full_text_raw,
                           '' as snippet, d.source_url, d.pdf_url,
                           0.0 as bm25_score
                    FROM decisions d WHERE d.decision_id IN ({ph}){where}""",
                    list(sparse_only_ids) + params,
                ).fetchall()
                for row in sp_rows:
                    did = row["decision_id"]
                    candidate_meta[did] = {
                        "row": row,
                        "best_bm25": 0.0,
                        "rrf_score": 0.0,
                        "strategy_hits": 0,
                    }
            for rank, (did, _score) in enumerate(
                sorted(sparse_scores.items(), key=lambda x: -x[1]), start=1
            ):
                if did in candidate_meta:
                    cm = candidate_meta[did]
                    cm["rrf_score"] = float(cm["rrf_score"]) + (
                        SPARSE_RRF_WEIGHT / (RRF_RANK_CONSTANT + rank)
                    )
                    cm["strategy_hits"] = int(cm["strategy_hits"]) + 1

    # ── Statute-graph retrieval (citation graph candidate source) ──
    # Use both regex extraction AND structured parse for maximum coverage
    STATUTE_GRAPH_RRF_WEIGHT = SCORING_CONFIG["statute_graph_rrf_weight"]
    has_structured_statutes = False
    # NOTE: statute-graph MUST run even for a quoted statute ref like "Art. 8 BV"
    # — that is the advertised article-search syntax, and it reaches ~2x more
    # decisions (cross-lingual "art. 8 Cst.", pinpoints) than a literal phrase
    # MATCH. A quoted DOCTRINE phrase ("Treu und Glauben") extracts no statute
    # ref, so this block is a no-op for it — the #42 exactness comes from the
    # strategy short-circuit + skipped doctrine/vector, not from gating here.
    if not is_docket_query:
        query_statutes = _extract_query_statute_refs(fts_query)
        if llm_terms:
            for t in llm_terms:
                query_statutes |= _extract_query_statute_refs(t)
        # Structured parse statutes (deterministic, not regex-dependent)
        if structured_parse.get("statutes"):
            for sref in structured_parse["statutes"]:
                parts = sref.strip().split()
                if len(parts) >= 2:
                    law = parts[0].upper()
                    art = parts[1].lower().replace(".", "")
                    query_statutes.add(f"ART.{art}.{law}")
            has_structured_statutes = True
        # Adjust weight based on query context:
        # - Pure statute queries ("Art. 41 OR"): high weight, statute-graph is primary signal
        # - Mixed queries ("Art. 41 OR Haftpflicht Schadenersatz"): lower weight,
        #   FTS keyword matches are more relevant for ranking
        query_tokens = set(re.findall(r'[a-zäöü]+', fts_query.lower()))
        non_statute_tokens = query_tokens - _STATUTE_REFERENCE_NOISE
        has_keyword_context = len(non_statute_tokens) >= 2
        if has_structured_statutes:
            sg_weight = SCORING_CONFIG["sg_weight_with_keywords"] if has_keyword_context else SCORING_CONFIG["sg_weight_pure_statute"]
        else:
            sg_weight = SCORING_CONFIG["sg_weight_unstructured_with_keywords"] if has_keyword_context else STATUTE_GRAPH_RRF_WEIGHT
        statute_graph_results = [] if _past_deadline(_deadline) else _search_statute_graph(query_statutes, limit=50 if has_structured_statutes else 30)
        if statute_graph_results:
            sg_only_ids = [
                did for did, _sc in statute_graph_results
                if did not in candidate_meta
            ]
            if sg_only_ids:
                ph = ",".join("?" for _ in sg_only_ids)
                sg_rows = conn.execute(
                    f"""SELECT d.decision_id, d.court, d.canton, d.chamber,
                           d.docket_number, d.decision_date, d.language,
                           d.title, d.regeste, d.full_text AS full_text_raw,
                           '' as snippet, d.source_url, d.pdf_url,
                           0.0 as bm25_score
                    FROM decisions d WHERE d.decision_id IN ({ph}){where}""",
                    sg_only_ids + params,
                ).fetchall()
                for row in sg_rows:
                    did = row["decision_id"]
                    candidate_meta[did] = {
                        "row": row,
                        "best_bm25": 0.0,
                        "rrf_score": 0.0,
                        "strategy_hits": 0,
                    }
            for rank, (did, _score) in enumerate(statute_graph_results, start=1):
                if did in candidate_meta:
                    cm = candidate_meta[did]
                    cm["rrf_score"] = float(cm["rrf_score"]) + (
                        sg_weight / (RRF_RANK_CONSTANT + rank)
                    )
                    cm["strategy_hits"] = int(cm["strategy_hits"]) + 1

    # ── BGE direct-lookup (structured parse + LLM free-text) ──
    # Structured parse provides deterministic BGE refs; LLM free-text is fallback.
    LLM_BGE_RRF_WEIGHT = SCORING_CONFIG["llm_bge_rrf_weight"]
    STRUCTURED_BGE_RRF_WEIGHT = SCORING_CONFIG["structured_bge_rrf_weight"]
    if not is_docket_query:
        bge_pattern = re.compile(r"BGE\s+(\d{1,3})\s+([IVX]{1,4})\s+(\d{1,4})", re.IGNORECASE)
        llm_bge_ids: list[str] = []
        structured_bge_ids: list[str] = []
        # From structured parse (deterministic)
        for bge_ref in (structured_parse.get("leading_bge") or []):
            m = bge_pattern.search(bge_ref)
            if m:
                candidate_id = f"bge_BGE_{m.group(1)}_{m.group(2).upper()}_{m.group(3)}"
                structured_bge_ids.append(candidate_id)
        # From LLM free-text expansion (stochastic, fallback)
        if llm_terms:
            for term in llm_terms:
                for m in bge_pattern.finditer(term):
                    candidate_id = f"bge_BGE_{m.group(1)}_{m.group(2).upper()}_{m.group(3)}"
                    if candidate_id not in structured_bge_ids:
                        llm_bge_ids.append(candidate_id)
        all_bge_ids = structured_bge_ids + llm_bge_ids
        if all_bge_ids:
            # Fetch rows for BGE IDs not already in pool
            new_bge_ids = [did for did in all_bge_ids if did not in candidate_meta]
            if new_bge_ids:
                ph = ",".join("?" for _ in new_bge_ids)
                bge_rows = conn.execute(
                    f"""SELECT d.decision_id, d.court, d.canton, d.chamber,
                           d.docket_number, d.decision_date, d.language,
                           d.title, d.regeste, d.full_text AS full_text_raw,
                           '' as snippet, d.source_url, d.pdf_url,
                           0.0 as bm25_score
                    FROM decisions d WHERE d.decision_id IN ({ph}){where}""",
                    new_bge_ids + params,
                ).fetchall()
                for row in bge_rows:
                    did = row["decision_id"]
                    candidate_meta[did] = {
                        "row": row,
                        "best_bm25": 0.0,
                        "rrf_score": 0.0,
                        "strategy_hits": 0,
                    }
            # Structured BGE refs get higher weight (deterministic)
            structured_set = set(structured_bge_ids)
            for rank, did in enumerate(all_bge_ids, start=1):
                if did in candidate_meta:
                    weight = STRUCTURED_BGE_RRF_WEIGHT if did in structured_set else LLM_BGE_RRF_WEIGHT
                    cm = candidate_meta[did]
                    cm["rrf_score"] = float(cm["rrf_score"]) + (
                        weight / (RRF_RANK_CONSTANT + rank)
                    )
                    cm["strategy_hits"] = int(cm["strategy_hits"]) + 1

    if candidate_meta:
        rows_for_rerank = [m["row"] for m in candidate_meta.values()]
        fusion_scores = {
            did: {
                "rrf_score": float(meta["rrf_score"]),
                "strategy_hits": int(meta["strategy_hits"]),
            }
            for did, meta in candidate_meta.items()
        }
        total_candidates = len(candidate_meta)
        if inline_docket_results:
            # When merging with docket results, get enough from reranker
            # (offset+limit) and let merge handle final pagination.
            reranked = _rerank_rows(
                rows_for_rerank,
                fts_query,
                offset + limit,
                fusion_scores=fusion_scores,
                vector_scores=vector_scores,
                sparse_scores=sparse_scores,
                offset=0,
                sort=sort,
                is_docket_query=is_docket_query,
                deadline=_deadline,
            )
            merged = _merge_priority_results(
                primary=inline_docket_results,
                secondary=reranked,
                limit=limit,
                offset=offset,
            )
            # Total after dedup
            all_ids = {r["decision_id"] for r in inline_docket_results}
            all_ids.update(candidate_meta.keys())
            return merged, len(all_ids)
        _signal_sink: dict = {}
        reranked = _rerank_rows(
            rows_for_rerank,
            fts_query,
            limit,
            fusion_scores=fusion_scores,
            vector_scores=vector_scores,
            sparse_scores=sparse_scores,
            offset=offset,
            sort=sort,
            is_docket_query=is_docket_query,
            deadline=_deadline,
            signal_sink=_signal_sink,
        )
        reranked = _dedupe_results_by_decision_id(reranked)
        # Per-signal contributions for what actually surfaced. Only the
        # top 10 — the full pool is hundreds of rows and the tuning
        # question is about the head, not the tail.
        _trace["signals_weights_v"] = _SCORING_V
        _trace["signals_top"] = {
            r["decision_id"]: _signal_sink[r["decision_id"]]
            for r in reranked[:10] if r.get("decision_id") in _signal_sink
        }
        # Soft boost: if legal_area filter given, promote matching results
        if legal_area and reranked:
            la_lower = legal_area.lower()
            if la_lower == "anwaltsrecht":
                # Use Anwaltsrecht tags DB for hard filtering
                aw_conn = _get_anwaltsrecht_conn()
                if aw_conn:
                    try:
                        tagged_ids = {
                            row[0] for row in aw_conn.execute(
                                "SELECT DISTINCT decision_id FROM anwaltsrecht_tags"
                            ).fetchall()
                        }
                        matching = [r for r in reranked if r.get("decision_id") in tagged_ids]
                        others = [r for r in reranked if r.get("decision_id") not in tagged_ids]
                        reranked = matching + others
                    finally:
                        aw_conn.close()
                else:
                    # Fallback to text-based matching
                    matching = [r for r in reranked if la_lower in (r.get("legal_area") or "").lower()]
                    others = [r for r in reranked if la_lower not in (r.get("legal_area") or "").lower()]
                    reranked = matching + others
            else:
                matching = [r for r in reranked if la_lower in (r.get("legal_area") or "").lower()]
                others = [r for r in reranked if la_lower not in (r.get("legal_area") or "").lower()]
                reranked = matching + others

        # Cross-lingual interleaving: ensure FR/IT results appear in top results
        # when the query language differs from result language.
        # Reserve ~20% of slots for cross-lingual results if available.
        if reranked and not language:  # only when no language filter is set
            query_lang = _detect_query_languages(fts_query)
            primary_lang = query_lang[0] if query_lang else "de"
            cross = [r for r in reranked if r.get("language", "") != primary_lang]
            if cross and len(cross) >= 2:
                same = [r for r in reranked if r.get("language", "") == primary_lang]
                # Interleave: insert cross-lingual results at positions 5, 10, 15...
                # Top 4 slots always go to best-matching (usually primary language)
                merged = list(same[:4])
                ci = 0
                for i, r in enumerate(same[4:], start=4):
                    if (i) % 5 == 0 and ci < len(cross):
                        merged.append(cross[ci])
                        ci += 1
                    merged.append(r)
                # Append remaining cross-lingual
                merged.extend(cross[ci:])
                reranked = merged[:len(reranked)]

        # Result-set id: the join key between this impression and any
        # later fetch. Minted once, carried into the trace, the response
        # (via meta) and the impression capture record below.
        _result_set_id = _new_result_set_id()
        if meta is not None:
            meta["result_set_id"] = _result_set_id

        # Emit research trace
        _trace["result_set_id"] = _result_set_id
        _trace["total_candidates"] = total_candidates
        _trace["result_count"] = len(reranked)
        _trace["total_ms"] = round((time.monotonic() - _trace_t0) * 1000)
        _trace["is_docket"] = is_docket_query
        _trace["result_ids"] = [r.get("decision_id", "") for r in reranked[:20]]
        _trace["result_langs"] = [r.get("language", "") for r in reranked[:20]]
        _trace["result_courts"] = [r.get("court", "") for r in reranked[:20]]
        # Cross-lingual analysis
        query_langs = _detect_query_languages(query)
        primary = query_langs[0] if query_langs else "de"
        cross = [i+1 for i, r in enumerate(reranked[:20]) if r.get("language", "") != primary]
        _trace["query_language"] = primary
        _trace["cross_lingual_positions"] = cross
        _trace["timestamp"] = datetime.now(timezone.utc).isoformat()
        _log_search_trace(_trace)

        # Impression: the ranked list as shown, in the capture stream
        # (which carries the session id) so a later fetch in the same
        # session joins to it offline. This is the half of every LTR
        # training pair — the displayed positions — that a fetch event
        # cannot reconstruct after the fact. Ids and ranks; the query
        # itself rides the tool-call capture record, not this one.
        if _FULL_CAPTURE:
            _sid = _ctx_session_id.get("")
            _capture_event({
                "src": "impression",
                "ts": datetime.now(timezone.utc).isoformat(),
                "sid": _sid[:16] if _sid else None,
                "result_set_id": _result_set_id,
                "query_len": len(query or ""),
                # Ranked ids + positions. Position is the load-bearing LTR
                # signal; the per-candidate scores already live in the
                # trace's signals_top, cross-referenced by result_set_id,
                # so they are not duplicated here.
                "ranked": [{"id": r.get("decision_id", ""), "rank": i}
                           for i, r in enumerate(reranked[:30])
                           if r.get("decision_id")],
            })

        # Honest `total`: exact count of decisions matching the query + filters,
        # not the reranked candidate-pool size. max() keeps total >= what is
        # returned when query-expansion surfaces candidates beyond the base match.
        _exact_info = _exact_fts_total(conn, fts_query, where, params)
        if _exact_info is None:
            # Count failed → we report the candidate-pool size, which is not an
            # exact match count; flag it as a lower bound (#53).
            total_out = total_candidates
            _lower_bound = True
        else:
            _exact_total, _exact_capped = _exact_info
            total_out = max(_exact_total, total_candidates)
            # When the pool wins the max(), `total` is a candidate-pool size —
            # and _target_candidate_pool scales with offset+limit, so rendering
            # it unmarked made `total` a function of the caller's page size
            # (60 -> 400 -> 2000 for one query, #56). The pool is a lower bound
            # on the expanded result set, never an exact count; say so.
            #
            # #75: that predicate is false whenever _exact_total already
            # exceeds the un-enlarged pool floor (MIN_CANDIDATE_POOL = 60), so
            # at limit <= 15 the strict-FTS count rendered as exact while the
            # same query at a larger limit or offset served 30x more rows. The
            # population, not the page size, decides: whenever more than the
            # strict query ran, the retrievable set is a superset of the exact
            # count and `total` is a lower bound. A single-strategy run (the
            # phrase path) keeps its exact, unmarked total.
            _expanded = len(strategies) > 1
            _lower_bound = (
                _exact_capped or total_candidates > _exact_total or _expanded)
        if meta is not None:
            meta["total_is_lower_bound"] = _lower_bound
        return reranked, total_out

    if had_success:
        if inline_docket_results:
            total = len(inline_docket_results)
            return inline_docket_results[offset:offset + limit], total
        return [], 0
    if inline_docket_results:
        total = len(inline_docket_results)
        return inline_docket_results[offset:offset + limit], total
    return [], 0


def _search_by_docket(
    conn: sqlite3.Connection,
    raw_query: str,
    where: str,
    params: list,
    limit: int,
    *,
    preferred_courts: set[str] | None = None,
) -> list[dict]:
    """Docket-first retrieval for docket-like queries."""
    variants = _build_docket_variants(raw_query)
    if not variants:
        return []
    if preferred_courts is None:
        preferred_courts = _detect_query_preferred_courts(raw_query)

    exact_variants = sorted(variants)
    exact_placeholders = ",".join("?" for _ in exact_variants)
    rank_expr = f"CASE WHEN d.docket_number IN ({exact_placeholders}) THEN 0 ELSE 1 END"

    sql = f"""
        SELECT
            d.decision_id,
            d.court,
            d.canton,
            d.chamber,
            d.docket_number,
            d.decision_date,
            d.language,
            d.title,
            d.regeste,
            NULL as snippet,
            d.source_url,
            d.pdf_url,
            ({rank_expr}) AS docket_rank
        FROM decisions d
        WHERE d.docket_number IN ({exact_placeholders}){where}
        ORDER BY docket_rank ASC,
                 d.decision_date DESC
        LIMIT ?
    """
    sql_limit = max(limit * 4, limit)
    rows = conn.execute(
        sql,
        [
            *exact_variants,
            *exact_variants,
            *params,
            sql_limit,
        ],
    ).fetchall()
    results = []
    for r in rows:
        results.append({
            "decision_id": r["decision_id"],
            "court": r["court"],
            "canton": r["canton"],
            "chamber": r["chamber"],
            "docket_number": r["docket_number"],
            "decision_date": r["decision_date"],
            "language": r["language"],
            "title": r["title"],
            "regeste": _truncate(r["regeste"], MAX_SNIPPET_LEN) if r["regeste"] else None,
            "snippet": r["snippet"],
            "source_url": r["source_url"],
            "pdf_url": r["pdf_url"],
            "relevance_score": round(100.0 - float(r["docket_rank"]), 4),
        })
    if preferred_courts:
        results.sort(
            key=lambda r: (
                0 if (r.get("court") or "").lower() in preferred_courts else 1,
                -_date_sort_key(str(r.get("decision_date") or "")),
                str(r.get("decision_id") or ""),
            ),
        )
    if len(results) < limit:
        primary_court = (results[0].get("court") or "").lower() if results else None
        related = _search_related_docket_family(
            conn,
            raw_query=raw_query,
            where=where,
            params=params,
            preferred_courts=preferred_courts,
            primary_court=primary_court,
            existing_ids={r["decision_id"] for r in results if r.get("decision_id")},
            limit=max(limit * 3, 20),
        )
        if related:
            results = _dedupe_results_by_decision_id(results + related)
    return results[:limit]


def _search_related_docket_family(
    conn: sqlite3.Connection,
    *,
    raw_query: str,
    where: str,
    params: list,
    preferred_courts: set[str],
    primary_court: str | None,
    existing_ids: set[str],
    limit: int,
) -> list[dict]:
    family = _parse_docket_family(raw_query)
    if family is None:
        return []

    prefix, serial, year = family
    candidates = _build_docket_family_candidates(prefix=prefix, serial=serial, year=year)
    if not candidates:
        return []
    candidate_placeholders = ",".join("?" for _ in candidates)
    family_filters = [f"d.docket_number IN ({candidate_placeholders})"]
    family_params: list = [*candidates]

    sql = f"""
        SELECT
            d.decision_id,
            d.court,
            d.canton,
            d.chamber,
            d.docket_number,
            d.decision_date,
            d.language,
            d.title,
            d.regeste,
            NULL as snippet,
            d.source_url,
            d.pdf_url
        FROM decisions d
        WHERE {" AND ".join(family_filters)}{where}
        LIMIT ?
    """
    query_limit = max(limit * 12, 240)
    rows = conn.execute(
        sql,
        [*family_params, *params, query_limit],
    ).fetchall()
    if not rows:
        return []

    preferred_rank_courts = set(preferred_courts or ())
    if primary_court:
        preferred_rank_courts.add(primary_court)

    ranked_rows: list[tuple[tuple, sqlite3.Row]] = []
    for row in rows:
        decision_id = row["decision_id"]
        if not decision_id or decision_id in existing_ids:
            continue
        row_docket = row["docket_number"] or ""
        row_serial = _extract_docket_serial(row_docket, prefix=prefix, year=year)
        distance = abs(row_serial - serial) if row_serial is not None else 10_000_000
        preferred_rank = 0 if (row["court"] or "").lower() in preferred_rank_courts else 1
        ranked_rows.append(
            (
                (
                    preferred_rank,
                    distance,
                    -_date_sort_key(str(row["decision_date"] or "")),
                    str(decision_id),
                ),
                row,
            )
        )
    ranked_rows.sort(key=lambda item: item[0])

    out: list[dict] = []
    for _key, r in ranked_rows:
        out.append({
            "decision_id": r["decision_id"],
            "court": r["court"],
            "canton": r["canton"],
            "chamber": r["chamber"],
            "docket_number": r["docket_number"],
            "decision_date": r["decision_date"],
            "language": r["language"],
            "title": r["title"],
            "regeste": _truncate(r["regeste"], MAX_SNIPPET_LEN) if r["regeste"] else None,
            "snippet": r["snippet"],
            "source_url": r["source_url"],
            "pdf_url": r["pdf_url"],
            "relevance_score": 96.0,
        })
        if len(out) >= limit:
            break
    return out


def _build_docket_family_candidates(*, prefix: str, serial: int, year: str) -> list[str]:
    if serial <= 0 or not prefix or not year:
        return []
    serial_window = 40
    lo = max(1, serial - serial_window)
    hi = serial + serial_window
    variants: list[str] = []
    seen: set[str] = set()
    for n in range(lo, hi + 1):
        for sep1 in (".", "_", "-"):
            for sep2 in ("/", "_"):
                candidate = f"{prefix}{sep1}{n}{sep2}{year}"
                if candidate in seen:
                    continue
                seen.add(candidate)
                variants.append(candidate)
    return variants


def _parse_docket_family(raw_query: str) -> tuple[str, int, str] | None:
    text = re.sub(r"\s+", "", (raw_query or "")).upper()
    m = re.fullmatch(
        r"(?P<prefix>[A-Z0-9]{1,4})[._-](?P<serial>\d{1,6})[/_](?P<year>\d{4})",
        text,
    )
    if not m:
        return None
    try:
        serial = int(m.group("serial"))
    except Exception:
        return None
    return m.group("prefix"), serial, m.group("year")


def _extract_docket_serial(docket: str, *, prefix: str, year: str) -> int | None:
    m = re.search(
        rf"{re.escape(prefix)}[._-](?P<serial>\d{{1,6}})[/_]{re.escape(year)}$",
        (docket or "").upper(),
    )
    if not m:
        return None
    try:
        return int(m.group("serial"))
    except Exception:
        return None


def _build_docket_variants(raw_query: str) -> set[str]:
    q = re.sub(r"\s+", "", (raw_query or ""))
    if not q:
        return set()
    variants = {
        q,
        q.upper(),
        q.replace("_", "/"),
        q.replace("-", "/"),
        q.replace(".", "/"),
        q.replace("/", "_"),
        q.replace("-", "_"),
        q.replace(".", "_"),
        q.replace("/", "-"),
        q.replace("_", "-"),
        q.replace(".", "-"),
    }
    # BVGE references: "BVGE 2013/10" stored with space in docket_number
    bvge_match = QUERY_BVGE_PATTERN.search(raw_query or "")
    if bvge_match:
        bvge_text = re.sub(r"\s+", " ", bvge_match.group(0).strip().upper())
        # Normalize slash spacing: "BVGE 2013 / 10" → "BVGE 2013/10"
        bvge_text = re.sub(r"\s*/\s*", "/", bvge_text)
        variants.add(bvge_text)  # "BVGE 2013/10"
        variants.add(bvge_text.replace("/", "_"))  # "BVGE 2013_10"
        variants.add(bvge_text.replace("/", " "))  # "BVGE 2013 10"
    clean: set[str] = set()
    for v in variants:
        v = re.sub(r"[/_.-]{2,}", lambda m: m.group(0)[0], v).strip("/_.-")
        if v:
            clean.add(v)
    return clean


def _detect_query_preferred_courts(query: str) -> set[str]:
    text = _normalize_text_for_match(query)
    if not text:
        return set()
    preferred: set[str] = set()
    for court, hints in COURT_QUERY_HINTS.items():
        for hint in hints:
            norm_hint = _normalize_text_for_match(hint)
            if norm_hint and norm_hint in text:
                preferred.add(court)
                preferred.update(COURT_QUERY_EXPANSIONS.get(court, ()))
                break
    return preferred


def _extract_inline_docket_candidates(query: str) -> list[str]:
    matches_with_pos: list[tuple[int, str]] = []
    seen: set[str] = set()
    for pattern in QUERY_DOCKET_PATTERNS:
        for match in pattern.finditer(query or ""):
            raw = (match.group(0) or "").strip()
            norm = _normalize_docket_ref(raw)
            if not raw or len(norm) < 5 or norm in seen:
                continue
            seen.add(norm)
            matches_with_pos.append((match.start(), raw))
    matches_with_pos.sort(key=lambda x: x[0])
    return [raw for _, raw in matches_with_pos[:5]]


def _make_canonical_key(court: str, docket: str, date: str | None = None) -> str:
    """Compute a canonical key for dedup (aggressive normalization)."""
    docket_norm = re.sub(r"[^A-Z0-9]", "", (docket or "").upper())
    date_compact = (date or "").replace("-", "")[:8]
    return f"{court}|{docket_norm}|{date_compact}"


def _dedupe_results_by_decision_id(rows: list[dict]) -> list[dict]:
    """Deduplicate search results by decision_id and canonical_key.

    Computes a canonical key from court+docket+date to collapse formatting
    variants of the same case (first/highest-ranked wins).
    """
    out: list[dict] = []
    seen_ids: set[str] = set()
    seen_canonical: set[str] = set()
    for row in rows:
        did = row.get("decision_id")
        if not did or did in seen_ids:
            continue
        ckey = _make_canonical_key(
            row.get("court", ""), row.get("docket_number", ""), row.get("decision_date"),
        )
        # Skip canonical dedup for empty-docket keys (format: court||date)
        if ckey and "||" not in ckey and ckey in seen_canonical:
            continue
        seen_ids.add(did)
        if ckey and "||" not in ckey:
            seen_canonical.add(ckey)
        out.append(row)
    return out


def _merge_priority_results(
    *,
    primary: list[dict],
    secondary: list[dict],
    limit: int,
    offset: int = 0,
) -> list[dict]:
    merged = _dedupe_results_by_decision_id((primary or []) + (secondary or []))
    return merged[offset:offset + max(1, limit)]


def _extract_query_statute_refs(query: str) -> set[str]:
    refs: set[str] = set()
    for match in QUERY_STATUTE_PATTERN.finditer(query or ""):
        article = re.sub(r"\s+", "", (match.group("article") or "").lower())
        if not article:
            continue
        paragraph_raw = match.group("paragraph") or ""
        paragraph = re.sub(r"\s+", "", paragraph_raw.lower()) or None
        law = (match.group("law") or "").upper()
        if not law or law in QUERY_STATUTE_INVALID_LAWS:
            continue
        refs.add(f"ART.{article}.{law}")
        if paragraph:
            refs.add(f"ART.{article}.ABS.{paragraph}.{law}")
    return refs


def _extract_query_citation_refs(query: str) -> set[str]:
    refs: set[str] = set()
    q = query or ""

    for match in QUERY_BGE_PATTERN.finditer(q):
        text = re.sub(r"\s+", " ", match.group(0).strip().upper())
        refs.add(text)

    for pattern in QUERY_DOCKET_PATTERNS:
        for match in pattern.finditer(q):
            normalized = _normalize_docket_ref(match.group(0))
            if normalized:
                refs.add(normalized)

    if _looks_like_docket_query(q):
        normalized = _normalize_docket_ref(q)
        if normalized:
            refs.add(normalized)

    return refs


def _normalize_docket_ref(value: str) -> str:
    text = (value or "").strip().upper()
    if not text:
        return ""
    text = text.replace("-", "_").replace(".", "_").replace("/", "_")
    text = re.sub(r"_+", "_", text)
    return text.strip("_")


_graph_warned = False
_vec_warned = False
_statutes_warned = False
_cantonal_warned = False
_ok_warned = False


def _get_graph_conn() -> sqlite3.Connection | None:
    """Open a read-only connection to the reference graph DB, or None if unavailable."""
    global _graph_warned
    if not GRAPH_DB_PATH.exists():
        if not _graph_warned:
            logger.warning("Reference graph DB not found at %s — citation features disabled", GRAPH_DB_PATH)
            _graph_warned = True
        return None
    try:
        conn = sqlite3.connect(f"file:{GRAPH_DB_PATH}?immutable=1", uri=True, timeout=0.5)
        conn.row_factory = sqlite3.Row
        return conn
    except sqlite3.Error as e:
        logger.warning("Failed to open graph DB: %s", e)
        return None


_canonical_warned = False


def _get_canonical_conn() -> sqlite3.Connection | None:
    """Open a read-only connection to the canonical_identity sidecar, or None."""
    global _canonical_warned
    if not CANONICAL_DB_PATH.exists():
        if not _canonical_warned:
            logger.info("canonical_identity sidecar not found at %s — date/dedup enrichment disabled", CANONICAL_DB_PATH)
            _canonical_warned = True
        return None
    try:
        conn = sqlite3.connect(f"file:{CANONICAL_DB_PATH}?immutable=1", uri=True, timeout=0.5)
        conn.row_factory = sqlite3.Row
        return conn
    except sqlite3.Error as e:
        logger.warning("Failed to open canonical_identity sidecar: %s", e)
        return None


def _canonical_for(decision_id: str | None) -> dict | None:
    """Sidecar enrichment for one decision_id (corrected date, provenance, ecli,
    canonical_key), or None. Tolerant of the sidecar being absent."""
    if not decision_id:
        return None
    conn = _get_canonical_conn()
    if conn is None:
        return None
    try:
        row = conn.execute(
            "SELECT * FROM canonical_identity WHERE decision_id = ?", (decision_id,)
        ).fetchone()
        return dict(row) if row else None
    except sqlite3.Error:
        return None
    finally:
        conn.close()


_manifest_warned = False


def _get_manifest_conn() -> sqlite3.Connection | None:
    """Open a read-only connection to the representation manifest, or None.

    The manifest (scripts/build_representation_manifest.py, rebuilt nightly
    via tmp+rename) maps duplicate representations — the same decision
    published under two identifiers (GE procedure/decision numbers, VD dual
    scrapes, SH twin courts; ~140k rows) — onto one canonical decision_id.
    This is Phase-4 consumption per the 2026-07-15 design doc §7: link-only,
    additive, reversible. No row is ever hidden or dropped here.
    """
    global _manifest_warned
    if not REPRESENTATION_MANIFEST_DB_PATH.exists():
        if not _manifest_warned:
            logger.info(
                "representation manifest not found at %s — representation links disabled",
                REPRESENTATION_MANIFEST_DB_PATH)
            _manifest_warned = True
        return None
    try:
        conn = sqlite3.connect(
            f"file:{REPRESENTATION_MANIFEST_DB_PATH}?immutable=1",
            uri=True, timeout=0.5)
        conn.row_factory = sqlite3.Row
        return conn
    except sqlite3.Error as e:
        logger.warning("Failed to open representation manifest: %s", e)
        return None


def _representation_info(decision_id: str | None) -> dict | None:
    """Representation links for one decision_id, or None when unlinked.

    {"canonical_decision_id", "is_canonical", "members": [...]} — members are
    the OTHER non-canonical representations (self-links excluded; the
    canonical is named by its own field, not listed as a member). Additive
    metadata only: the caller still serves whichever row was asked for.
    Tolerant of the manifest being absent; never raises.
    """
    if not decision_id:
        return None
    conn = _get_manifest_conn()
    if conn is None:
        return None
    try:
        canonical = decision_id
        row = conn.execute(
            "SELECT canonical_decision_id FROM decision_representations "
            "WHERE member_decision_id = ? "
            "AND canonical_decision_id != member_decision_id",
            (decision_id,),
        ).fetchone()
        if row:
            canonical = row["canonical_decision_id"]
        members = [
            {"decision_id": r["member_decision_id"],
             "relation_type": r["relation_type"],
             "evidence_method": r["evidence_method"],
             "confidence": r["confidence"]}
            for r in conn.execute(
                "SELECT member_decision_id, relation_type, evidence_method, "
                "confidence FROM decision_representations "
                "WHERE canonical_decision_id = ? "
                "AND member_decision_id != canonical_decision_id "
                "AND member_decision_id != ?",
                (canonical, decision_id),
            )
        ]
        if canonical == decision_id and not members:
            return None
        return {
            "canonical_decision_id": canonical,
            "is_canonical": canonical == decision_id,
            "members": members,
        }
    except sqlite3.Error:
        return None
    finally:
        conn.close()


def _canonical_links_for(decision_ids) -> dict[str, str] | None:
    """member decision_id -> canonical decision_id for every id the manifest
    links, in one indexed IN-lookup (idx_repr_member). None when the manifest
    is not loaded, so callers can tell "no manifest" from "no link"; ids the
    manifest does not know are simply absent from the mapping. Never raises."""
    ids = [d for d in dict.fromkeys(decision_ids) if isinstance(d, str) and d]
    conn = _get_manifest_conn()
    if conn is None:
        return None
    links: dict[str, str] = {}
    try:
        for i in range(0, len(ids), 500):
            chunk = ids[i:i + 500]
            for r in conn.execute(
                "SELECT member_decision_id, canonical_decision_id "
                f"FROM decision_representations "
                f"WHERE member_decision_id IN ({','.join('?' * len(chunk))})",
                chunk,
            ):
                if r[1]:
                    links[r[0]] = r[1]
        return links
    except sqlite3.Error:
        return None
    finally:
        conn.close()


def _attach_canonical_ids(rows) -> None:
    """Add canonical_decision_id + is_canonical to decision dicts in place.

    Duplicate representations (the same ruling stored under two ids) are
    linked by the representation manifest; a client that sees the canonical
    id on every row can collapse them without a second request. One batched
    lookup per call, so a search page costs one indexed query. No-op without
    the manifest (the fields are then absent, not false); additive: no row is
    dropped, reordered or renamed, and decision_id is never changed.
    """
    try:
        links = _canonical_links_for(
            [r.get("decision_id") for r in rows if isinstance(r, dict)])
    except Exception:
        return
    if links is None:
        return
    for r in rows:
        did = r.get("decision_id") if isinstance(r, dict) else None
        if not did:
            continue
        canonical = links.get(did) or did
        r["canonical_decision_id"] = canonical
        r["is_canonical"] = canonical == did


