# Major laws by abbreviation. Only a resolution shortcut — statutes.db is the
# authority and is consulted for anything not listed here.
_MATERIALIEN_SR_MAP = {
    "BV": "101", "ZGB": "210", "OR": "220", "ZPO": "272",
    "STGB": "311.0", "STPO": "312.0", "SCHKG": "281.1",
    "VWVG": "172.021", "BGFA": "935.61", "BGG": "173.110",
    "AVIG": "837.0", "IVG": "831.20", "AHVG": "831.10",
    "KVG": "832.10", "UVG": "832.20", "DSG": "235.1",
    "SVG": "741.01", "ATSG": "830.1", "EOG": "834.1",
    "ARBG": "822.11", "MWSTG": "641.20", "DBG": "642.11",
}


def _resolve_materialien_sr(conn, law: str) -> str:
    """law_code ('OR') -> SR number ('220'). Map first, then the curated
    table's own sr_number, then statutes.db by abbreviation."""
    sr = _MATERIALIEN_SR_MAP.get(law, "")
    if sr:
        return sr
    try:
        r0 = conn.execute(
            "SELECT sr_number FROM materialien WHERE law_code = ? AND sr_number IS NOT NULL LIMIT 1",
            (law,),
        ).fetchone()
        if r0 and r0["sr_number"]:
            return r0["sr_number"]
    except sqlite3.Error:
        pass
    try:
        st_conn = sqlite3.connect(f"file:{STATUTES_DB_PATH}?mode=ro", uri=True, timeout=0.5)
        st_conn.row_factory = sqlite3.Row
        try:
            r0 = st_conn.execute(
                "SELECT sr_number FROM laws WHERE UPPER(abbr_de) = ? LIMIT 1", (law,),
            ).fetchone()
            return r0["sr_number"] if r0 else ""
        finally:
            st_conn.close()
    except Exception:
        return ""


# A Botschaft's opening paragraph carries its own header, very regularly:
#   16.077 / Botschaft / zur Änderung des Obligationenrechts (Aktienrecht) /
#   vom 23. November 2016
# botschaft_documents.title and .publication_date are empty for all 6,154 rows,
# so this is where the human-readable title comes from. Measured on 400 linked
# documents: 69% match. The remainder are recent messages whose first
# paragraph is the Übersicht itself (no header paragraph at all — scanning
# further paragraphs does not help, verified); those fall back to an excerpt,
# which brings the combined coverage to 100%.
_BOTSCHAFT_HEAD_RE = re.compile(
    r"^\s*(?:\d{2}\.\d{3,4}\s*\n+)?"
    r"(?P<kind>Botschaft|Message|Messaggio|Bericht|Rapport)\s*\n+"
    r"(?P<title>.{3,400}?)\s*\n+"
    r"(?:vom|du|del|dell')\s+(?P<date>\d{1,2}\.?\s*\w+\s+\d{4})",
    re.IGNORECASE | re.DOTALL,
)


def _botschaft_header(text: str) -> tuple[str | None, str | None]:
    """(title, date) from a Botschaft's opening paragraph, or (None, None)."""
    m = _BOTSCHAFT_HEAD_RE.match(text or "")
    if not m:
        return None, None
    return (f"{m.group('kind')} {' '.join(m.group('title').split())}".strip(),
            m.group("date").strip())


def _linked_botschaft_documents(conn, sr: str, article: str | None,
                                limit: int = 20) -> list[dict]:
    """The Federal Council messages linked to an article.

    The curated `materialien` digest covers two laws (BV, BGFA — 167 rows),
    so for every other statute this is what the tool actually has to offer:
    19,809 article->Botschaft links across 620 SR numbers and 6,154 documents,
    all sitting in the same DB. Before this, get_materialien answered
    "No Materialien found" for OR, ZGB, StGB and everything else, which was
    false — the material was there, just not the digest.

    The link relation is 'considered' for all 19,809 rows (they are derived
    from the statute's AS/BBl amendment footnotes), so this says "this message
    concerns that article", never "this is the enacting message".
    """
    if not sr:
        return []
    sql = """SELECT d.bbl_citation, d.source_url, d.eli_uri, d.language,
                    d.bbl_year, d.bbl_page, l.article, l.relation,
                    p.text AS head_text
               FROM article_botschaft_links l
               JOIN botschaft_documents d ON d.botschaft_id = l.botschaft_id
               LEFT JOIN botschaft_paragraphs p
                      ON p.botschaft_id = d.botschaft_id AND p.para_order = 1
              WHERE l.sr_number = ?"""
    params: list = [sr]
    if article:
        sql += " AND l.article = ?"
        params.append(article)
    # publication_date is empty for every row; bbl_year is the real ordering.
    # Fetch extra: one message exists once per language (BBl 2022 2743 and
    # FF 2022 2743 are the same document), and those are grouped below, so a
    # bare LIMIT would return half as many distinct messages as asked for.
    sql += " ORDER BY d.bbl_year DESC, d.bbl_page DESC LIMIT ?"
    params.append(limit * 3)
    grouped: dict[tuple, dict] = {}
    try:
        rows = list(conn.execute(sql, params))
    except sqlite3.Error:
        return []
    for r in rows:
        # One entry per MESSAGE, not per (message, article): a law-level
        # query otherwise lists the same Botschaft twenty times, once for
        # each article it touches. The articles it covers go in a list.
        key = (r["bbl_year"], r["bbl_page"])
        item = grouped.get(key)
        if item is None:
            if len(grouped) >= limit:
                continue
            title, date = _botschaft_header(r["head_text"] or "")
            item = {
                "bbl_citation": r["bbl_citation"],
                "title": title,
                "date": date,
                "year": r["bbl_year"],
                "url": r["source_url"],
                "eli_uri": r["eli_uri"],
                "language": r["language"],
                "articles": [r["article"]],
                "relation": r["relation"],
                "other_languages": [],
            }
            if not title:
                # No header paragraph (recent messages open with the
                # Übersicht). Give the opening lines verbatim rather than an
                # untitled citation — labelled as an excerpt so it is never
                # mistaken for the document's own title.
                item["excerpt"] = _truncate(
                    " ".join((r["head_text"] or "").split()), 200) or None
            grouped[key] = item
            continue
        # Same message: either another article it covers, or another
        # language edition of it.
        if r["article"] not in item["articles"]:
            item["articles"].append(r["article"])
        if r["language"] != item["language"] and not any(
                o["language"] == r["language"] for o in item["other_languages"]):
            item["other_languages"].append({
                "language": r["language"], "bbl_citation": r["bbl_citation"],
                "url": r["source_url"],
            })
        if not item["title"]:
            t2, d2 = _botschaft_header(r["head_text"] or "")
            if t2:
                item["title"], item["date"] = t2, d2
                item.pop("excerpt", None)
    return list(grouped.values())


def get_materialien(law_code: str, article: str | None = None) -> dict:
    """Fetch preparatory materials (Botschaften, parliamentary data) for a law article.

    Returns legislative intent, key arguments, design choices, rejected
    alternatives, and parliamentary modifications from the Federal Council's
    Botschaft and subsequent parliamentary debates.
    """
    conn = _get_materialien_conn()
    if conn is None:
        return {"error": "Materialien database not available."}

    try:
        law = (law_code or "").upper()
        if not law:
            return {"error": "Provide law_code (e.g., BV, OR, StGB, BGFA)."}

        if article:
            rows = conn.execute(
                """SELECT * FROM materialien
                   WHERE law_code = ? AND article = ?
                   ORDER BY bbl_ref""",
                (law, article),
            ).fetchall()
        else:
            rows = conn.execute(
                """SELECT * FROM materialien
                   WHERE law_code = ?
                   ORDER BY CAST(article AS INTEGER), article, bbl_ref""",
                (law,),
            ).fetchall()

        sources = []
        for r in rows:
            sources.append({
                "law_code": r["law_code"],
                "article": r["article"],
                "bbl_ref": r["bbl_ref"],
                "bbl_page_refs": json.loads(r["bbl_page_refs"]) if r["bbl_page_refs"] else [],
                "legislative_intent": r["legislative_intent"],
                "key_arguments": r["key_arguments"],
                "design_choices": r["design_choices"],
                "rejected_alternatives": r["rejected_alternatives"],
                "general_context": r["general_context"],
            })

        # Parliamentary modifications (law-level)
        mods = conn.execute(
            "SELECT * FROM parliamentary_modifications WHERE law_code = ? ORDER BY date",
            (law,),
        ).fetchall()
        modifications = [
            {"council": m["council"], "date": m["date"], "text": m["text"]}
            for m in mods
        ]

        # Fedlex amendment references (AS/BBl from statute footnotes).
        # The amendment_refs table uses sr_number, not law_code — resolve
        # via the abbreviation lookup in statutes.db or the known SR map.
        sr = _resolve_materialien_sr(conn, law)
        # The Botschaft documents linked to this article. For every law
        # outside the two-law curated digest this is the substance of the
        # answer, so it is fetched whether or not a digest exists.
        botschaft_docs = _linked_botschaft_documents(conn, sr, article)

        amendment_refs = []
        try:
            if sr:
                ref_sql = "SELECT * FROM amendment_refs WHERE sr_number = ?"
                ref_params: list = [sr]
                if article:
                    ref_sql += " AND article = ?"
                    ref_params.append(article)
                ref_sql += " ORDER BY year DESC, page DESC LIMIT 50"
                try:
                    for r in conn.execute(ref_sql, ref_params):
                        amendment_refs.append({
                            "ref_type": r["ref_type"],
                            "year": r["year"],
                            "page": r["page"],
                            "citation": f"{r['ref_type']} {r['year']} {r['page']}",
                            "fedlex_url": r["fedlex_url"],
                            "context": r["context"],
                        })
                except sqlite3.OperationalError:
                    pass  # amendment_refs table may not exist in older DBs
        except Exception:
            pass

        if not sources and not amendment_refs and not botschaft_docs:
            # Nothing keyed to the provision in either Materialien corpus
            # (~4,100 misses a month, 30 days to 2026-09-08). Keep the
            # success shape, flag the miss, and hand over what the corpus
            # does hold on the provision — all of it from existing handlers.
            where = f"{law}" + (f" Art. {article}" if article else "")
            ctx = _statute_fallback_context(
                law_code=law, sr_number=sr or None, article=article)
            held = [name for name, key in (
                ("the statute text and doctrine excerpt (get_doctrine)", "doctrine"),
                ("the leading cases (find_leading_cases)", "leading_cases"),
                ("the scholarship citing it (find_scholarship_citing_statute)",
                 "scholarship_citing_statute"),
            ) if ctx.get(key)]
            return {
                "law_code": law,
                "sr_number": sr or None,
                "article": article,
                # Machine-readable miss signal (see _is_miss_payload).
                "found": False,
                "no_materialien": True,
                "sources": [],
                "botschaft_documents": [],
                "amendment_refs": [],
                "parliamentary_modifications": modifications,
                "doctrine": ctx["doctrine"],
                "leading_cases": ctx["leading_cases"],
                "scholarship_citing_statute": ctx["scholarship_citing_statute"],
                "note": (
                    f"No Materialien are keyed to {where}: no digest entry, no "
                    "linked Federal Council message and no AS/BBl amendment "
                    "reference. search_botschaft runs full-text over all "
                    "Federal Council messages and is the tool for a provision "
                    "without a link. "
                    + (("Listed instead is what the corpus holds on the "
                        "provision: " + ", ".join(held) + ". None of it is "
                        "legislative history; quote only verbatim from "
                        "get_article_purpose / search_botschaft.")
                       if held else "")
                ).strip(),
            }

        out = {
            "law_code": law,
            "sr_number": sr or None,
            "article": article,
            "sources": sources,
            "botschaft_documents": botschaft_docs,
            "amendment_refs": amendment_refs,
            "parliamentary_modifications": modifications,
        }
        # Say plainly which of the two corpora answered, so a caller never
        # mistakes "no digest" for "no preparatory materials".
        if not sources:
            where = f"{law}" + (f" Art. {article}" if article else "")
            if botschaft_docs:
                out["note"] = (
                    f"No curated digest exists for {where} (the digest corpus "
                    "covers BV and BGFA only). Listed instead are the Federal "
                    "Council messages that concern this article, from the "
                    "statute's AS/BBl footnotes. Use search_botschaft to search "
                    "their full text; quote only verbatim."
                )
            else:
                out["note"] = (
                    f"No digest and no linked Federal Council message for {where}"
                    + (" — only the AS/BBl amendment references below."
                       if amendment_refs else ".")
                    + " search_botschaft runs full-text over all 6,154 messages "
                      "and is the better tool when an article has no link."
                )
        return out
    except sqlite3.Error as e:
        return {"error": f"Materialien lookup failed: {e}"}
    finally:
        conn.close()


def search_materialien(
    query: str, law_code: str | None = None, limit: int = 10,
) -> dict:
    """Full-text search across all preparatory materials.

    Searches legislative intent, key arguments, design choices, and
    general context of Federal Council Botschaften.
    """
    conn = _get_materialien_conn()
    if conn is None:
        return {"error": "Materialien database not available."}

    try:
        raw_query = query
        query = _sanitize_fts5(query)
        if not query:
            return {"error": "Provide a search query."}
        limit = min(max(1, limit), 50)

        params: list = [query]
        where = ["materialien_fts MATCH ?"]
        if law_code:
            where.append("m.law_code = ?")
            params.append(law_code.upper())
        where_sql = " AND ".join(where)
        params.append(limit)

        _sql = f"""SELECT m.law_code, m.article, m.bbl_ref, m.legislative_intent,
                       snippet(materialien_fts, 3, '>>>', '<<<', '...', 40) AS snippet
                FROM materialien_fts f
                JOIN materialien m ON m.id = f.rowid
                WHERE {where_sql}
                ORDER BY f.rank
                LIMIT ?"""
        rows = conn.execute(_sql, params).fetchall()
        relaxed = False
        _or_q = _fts5_or_query(raw_query)
        if not rows and _or_q and _or_q != query:
            # Strict AND over a 167-entry digest is empty for nearly every
            # multi-term question; rank the digests carrying any term.
            rows = conn.execute(_sql, [_or_q, *params[1:]]).fetchall()
            relaxed = bool(rows)
        debate_query = _or_q if relaxed else query

        results = [
            {
                "law_code": r["law_code"],
                "article": r["article"],
                "bbl_ref": r["bbl_ref"],
                "legislative_intent": (r["legislative_intent"] or "")[:300],
                "snippet": _render_fts_snippet(r["snippet"]),
            }
            for r in rows
        ]

        # Also search debate transcripts (Amtliches Bulletin)
        debate_results = []
        try:
            debate_rows = conn.execute(
                """SELECT d.law_code, d.council, d.page_num,
                          snippet(debate_fts, 2, '>>>', '<<<', '...', 40) AS snippet
                   FROM debate_fts f
                   JOIN debate_pages d ON d.id = f.rowid
                   WHERE debate_fts MATCH ?
                   ORDER BY f.rank
                   LIMIT 5""",
                (debate_query,),
            ).fetchall()
            if not debate_rows and not relaxed and _or_q and _or_q != query:
                debate_rows = conn.execute(
                    """SELECT d.law_code, d.council, d.page_num,
                              snippet(debate_fts, 2, '>>>', '<<<', '...', 40) AS snippet
                       FROM debate_fts f
                       JOIN debate_pages d ON d.id = f.rowid
                       WHERE debate_fts MATCH ?
                       ORDER BY f.rank
                       LIMIT 5""",
                    (_or_q,),
                ).fetchall()
                if debate_rows and not results:
                    relaxed = True
            for r in debate_rows:
                debate_results.append({
                    "law_code": r["law_code"],
                    "council": r["council"],
                    "page": r["page_num"],
                    "snippet": _render_fts_snippet(r["snippet"]),
                    "source": "Amtliches Bulletin",
                })
        except sqlite3.OperationalError:
            pass  # debate_fts may not exist in older DBs

        out = {
            "query": query,
            "count": len(results),
            "results": results,
            "debate_results": debate_results,
            # State the corpus size up front. This index is the curated
            # digest — 167 entries covering BV and BGFA — not the 6,154
            # Federal Council messages. A bare count:0 read as "Switzerland
            # has no preparatory materials on this", which is false and the
            # opposite of useful.
            "corpus": ("curated digest of legislative intent: BV and BGFA only "
                       "(167 article digests, 748 debate pages)"),
        }
        if relaxed:
            out["filters_relaxed"] = True
            out["note"] = (
                f"No digest entry contains every term of \"{raw_query}\"; listed "
                "instead are the entries matching any of the terms, best matches "
                "first (filters_relaxed, ranked OR). The digest covers BV and BGFA "
                "only; search_botschaft runs full-text over all Federal Council "
                "messages."
            )
        elif not results and not debate_results:
            out["note"] = (
                "No hit in the curated digest, which covers only BV and BGFA. "
                "This is a coverage limit, not an absence of materials: use "
                "search_botschaft for full-text search across all 6,154 Federal "
                "Council messages (421,489 indexed paragraphs), or "
                "get_materialien(law_code) for the messages linked to a "
                "specific statute."
            )
        return out
    except sqlite3.Error as e:
        return {"error": f"Materialien search failed: {e}"}
    finally:
        conn.close()


_SR_NUMBER_MAP = {  # law abbreviation (UPPER) -> SR number
    "BV": "101", "ZGB": "210", "OR": "220", "ZPO": "272",
    "STGB": "311.0", "STPO": "312.0", "SCHKG": "281.1",
    "VWVG": "172.021", "BGFA": "935.61", "BGG": "173.110",
    "AVIG": "837.0", "IVG": "831.20", "AHVG": "831.10",
    "KVG": "832.10", "UVG": "832.20", "DSG": "235.1",
    "SVG": "741.01", "ATSG": "830.1", "EOG": "834.1",
    "ARBG": "822.11", "MWSTG": "641.20", "DBG": "642.11",
}


def _resolve_sr_for_law(conn: sqlite3.Connection, law_code: str) -> str:
    """Resolve a law abbreviation to its SR number: static map -> materialien
    digest row -> statutes.db abbreviation lookup. Returns '' if unresolved."""
    sr = _SR_NUMBER_MAP.get(law_code.upper(), "")
    if sr:
        return sr
    try:
        r = conn.execute(
            "SELECT sr_number FROM materialien "
            "WHERE law_code = ? AND sr_number IS NOT NULL LIMIT 1",
            (law_code.upper(),),
        ).fetchone()
        if r and r["sr_number"]:
            return r["sr_number"]
    except sqlite3.Error:
        pass
    try:
        st = sqlite3.connect(
            f"file:{STATUTES_DB_PATH}?mode=ro", uri=True, timeout=0.5,
        )
        st.row_factory = sqlite3.Row
        r = st.execute(
            "SELECT sr_number FROM laws WHERE UPPER(abbr_de) = ? LIMIT 1",
            (law_code.upper(),),
        ).fetchone()
        st.close()
        if r and r["sr_number"]:
            return r["sr_number"]
    except Exception:
        pass
    return ""


def _verbatim_botschaft_pointer(
    conn: sqlite3.Connection, sr: str, article: str,
) -> dict | None:
    """Bridge the digest/doctrine path to the VERBATIM Botschaft corpus.

    Looks up article_botschaft_links -> botschaft_documents for (sr, article)
    and returns a lean pointer telling the caller to fetch quotable text via
    get_article_purpose (R2/R4). Returns None if the article isn't linked or
    the Phase-2 tables aren't present.
    """
    if not sr or not article:
        return None
    try:
        rows = conn.execute(
            """SELECT DISTINCT d.bbl_citation, d.eli_uri
               FROM article_botschaft_links abl
               JOIN botschaft_documents d ON d.botschaft_id = abl.botschaft_id
               WHERE abl.sr_number = ? AND abl.article = ?
               LIMIT 5""",
            (sr, article),
        ).fetchall()
    except sqlite3.OperationalError:
        return None
    if not rows:
        return None
    return {
        "available": True,
        "tool": "get_article_purpose",
        "call": f'get_article_purpose(sr_number="{sr}", article="{article}")',
        "bbl_citations": [r["bbl_citation"] for r in rows if r["bbl_citation"]],
        "eli_uris": [r["eli_uri"] for r in rows if r["eli_uri"]],
        "note": (
            "Verbatim Botschaft paragraphs for this article are available — "
            "call get_article_purpose for quotable text (R2/R4). Any digest "
            "fields above are paraphrase, not verbatim."
        ),
    }


def _get_materialien_for_doctrine(law_code: str, article: str) -> dict | None:
    """Fetch a compact Materialien excerpt for get_doctrine / get_law enrichment.

    Richness ladder: openlegalcommentary digest (BV/BGFA only, PARAPHRASE) ->
    Fedlex amendment refs (publication locators) -> ALWAYS a pointer to the
    verbatim Botschaft corpus (get_article_purpose) whenever article_botschaft_links
    has a row, so the statute path bridges to quotable text instead of returning
    "no materials".
    """
    conn = _get_materialien_conn()
    if conn is None:
        return None
    try:
        sr = _resolve_sr_for_law(conn, law_code)
        verbatim = _verbatim_botschaft_pointer(conn, sr, article) if sr else None

        # 1. openlegalcommentary digest (richest prose, but PARAPHRASE)
        row = None
        try:
            row = conn.execute(
                """SELECT legislative_intent, key_arguments, bbl_ref
                   FROM materialien
                   WHERE law_code = ? AND article = ?
                   ORDER BY bbl_ref LIMIT 1""",
                (law_code.upper(), article),
            ).fetchone()
        except sqlite3.OperationalError:
            pass
        if row:
            out = {
                "bbl_ref": row["bbl_ref"],
                "legislative_intent": (row["legislative_intent"] or "")[:500],
                "key_arguments": (row["key_arguments"] or "")[:500],
                "source": "openlegalcommentary.ch (CC BY-SA 4.0) — PARAPHRASE, not verbatim",
            }
            if verbatim:
                out["verbatim_botschaft"] = verbatim
            return out

        # 2. Fedlex amendment refs (publication locators)
        if sr:
            try:
                refs = conn.execute(
                    """SELECT ref_type, year, page, fedlex_url, context
                       FROM amendment_refs
                       WHERE sr_number = ? AND article = ?
                         AND ref_type IN ('BBl', 'FF')
                       ORDER BY year DESC LIMIT 3""",
                    (sr, article),
                ).fetchall()
            except sqlite3.OperationalError:
                refs = []
            if refs:
                bbl_citations = [f"{r['ref_type']} {r['year']} {r['page']}" for r in refs]
                out = {
                    "bbl_ref": bbl_citations[0],
                    "bbl_citations": bbl_citations,
                    "fedlex_urls": [r["fedlex_url"] for r in refs if r["fedlex_url"]],
                    "context": (refs[0]["context"] or "")[:300],
                    "source": "Fedlex (automatic extraction from statute footnotes)",
                }
                if verbatim:
                    out["verbatim_botschaft"] = verbatim
                return out

        # 3. Verbatim pointer alone — the article is linked to a Botschaft even
        #    though no digest/refs exist; surface the quotable bridge anyway.
        if verbatim:
            return {
                "verbatim_botschaft": verbatim,
                "source": "Fedlex Botschaft corpus (verbatim, via article_botschaft_links)",
            }
        return None
    except sqlite3.Error:
        return None
    finally:
        conn.close()


def _materials_for_decision(decision_id: str, max_items: int = 6) -> list[dict] | None:
    """Preparatory Botschaft materials for the statute articles a decision cites,
    most-cited first. Lean pointers to get_article_purpose — NO verbatim text in
    the decision payload (R1-R3 clean). Returns None when the graph/materials DBs
    are unavailable, [] when the decision cites nothing with a Botschaft link.
    """
    if not decision_id:
        return None
    gconn = _get_graph_conn()
    if gconn is None:
        return None
    try:
        if not _sqlite_has_table(gconn, "decision_statutes"):
            return None
        rows = gconn.execute(
            """SELECT s.law_code AS law_code, s.article AS article,
                      SUM(ds.mention_count) AS mc
               FROM decision_statutes ds
               JOIN statutes s ON s.statute_id = ds.statute_id
               WHERE ds.decision_id = ?
                 AND s.article IS NOT NULL AND s.article != ''
               GROUP BY s.law_code, s.article
               ORDER BY mc DESC LIMIT 25""",
            (decision_id,),
        ).fetchall()
    except sqlite3.Error:
        return None
    finally:
        gconn.close()
    if not rows:
        return []
    mconn = _get_materialien_conn()
    if mconn is None:
        return None
    out: list[dict] = []
    seen: set = set()
    sr_cache: dict = {}
    try:
        for r in rows:
            if len(out) >= max_items:
                break
            law_code = r["law_code"]
            article = r["article"]
            if not law_code or not article:
                continue
            if law_code not in sr_cache:
                sr_cache[law_code] = _resolve_sr_for_law(mconn, law_code)
            sr = sr_cache[law_code]
            if not sr or (sr, article) in seen:
                continue
            ptr = _verbatim_botschaft_pointer(mconn, sr, article)
            if not ptr:
                continue
            seen.add((sr, article))
            out.append({
                "law": law_code,
                "article": article,
                "sr_number": sr,
                "bbl_citations": ptr["bbl_citations"],
                "tool": "get_article_purpose",
                "call": ptr["call"],
            })
    finally:
        mconn.close()
    return out


def _format_materials_section_md(mats: list[dict]) -> str:
    """Render _materials_for_decision output as a compact Markdown section for
    the text-mode get_decision response."""
    if not mats:
        return ""
    parts = [
        "\n## Preparatory materials (Botschaft) for cited articles\n",
        "_Federal Council Botschaft for the provisions this decision applies — "
        "for statutory interpretation (R4) call `get_article_purpose` for "
        "verbatim text:_\n",
    ]
    for m in mats:
        cites = ", ".join(m.get("bbl_citations") or []) or "—"
        parts.append(f"- **Art. {m['article']} {m['law']}** → {cites} — `{m['call']}`\n")
    return "".join(parts)


def _get_vector_model():
    """Lazy-load embedding model for vector search. Returns None if unavailable."""
    global _VECTOR_MODEL, _VECTOR_MODEL_FAILED
    if VECTOR_SEARCH_ENABLED in {"0", "false", "no"}:
        return None
    if _VECTOR_MODEL is not None:
        return _VECTOR_MODEL
    if _VECTOR_MODEL_FAILED:
        return None
    if not VECTOR_DB_PATH.exists():
        return None
    model_id = "BAAI/bge-m3"
    # Prefer FlagEmbedding — same library used to build the vectors DB
    try:
        from FlagEmbedding import BGEM3FlagModel  # type: ignore[import-untyped]
        _VECTOR_MODEL = BGEM3FlagModel(model_id, use_fp16=False)
        logger.info("Loaded %s with FlagEmbedding for vector search", model_id)
        return _VECTOR_MODEL
    except Exception as e:
        logger.debug("FlagEmbedding load failed, trying SentenceTransformer: %s", e)
    # Fall back to SentenceTransformer with PyTorch (skip ONNX — incompatible output format)
    try:
        from sentence_transformers import SentenceTransformer
        _VECTOR_MODEL = SentenceTransformer(model_id)
        logger.info("Loaded %s with SentenceTransformer (PyTorch) for vector search", model_id)
        return _VECTOR_MODEL
    except Exception as e:
        logger.warning("Vector model load failed: %s", e)
        _VECTOR_MODEL_FAILED = True
        return None


def _encode_query(model, query: str) -> bytes | None:
    """Encode a query string into packed float32 bytes for sqlite-vec.

    Handles FlagEmbedding models (any version: BGEM3FlagModel / M3Embedder)
    and SentenceTransformer. Detects model type by output shape, not class name.
    Returns None on encoding failure.
    """
    import struct as _struct

    import numpy as np

    try:
        # FlagEmbedding API (v1 BGEM3FlagModel and v2 M3Embedder)
        output = model.encode(
            [query],
            batch_size=1,
            max_length=256,
            return_dense=True,
            return_sparse=False,
            return_colbert_vecs=False,
        )
        if isinstance(output, dict) and "dense_vecs" in output:
            embedding = np.asarray(output["dense_vecs"][0], dtype=np.float32)
        else:
            # SentenceTransformer returns ndarray directly
            embedding = np.asarray(output[0], dtype=np.float32)
        return _struct.pack(f"{len(embedding)}f", *embedding.tolist())
    except Exception as e:
        logger.debug("Query encoding failed: %s", e)
        return None


def _search_vectors(
    query: str,
    language: str | None = None,
    k: int | None = None,
) -> dict[str, float]:
    """Run vector KNN search. Returns {decision_id: cosine_distance} or empty dict."""
    model = _get_vector_model()
    if model is None:
        return {}
    vec_conn = _get_vec_conn()
    if vec_conn is None:
        return {}
    k = k or VECTOR_K
    try:
        query_bytes = _encode_query(model, query)
        if query_bytes is None:
            return {}

        if language:
            rows = vec_conn.execute(
                "SELECT decision_id, distance FROM vec_decisions "
                "WHERE embedding MATCH ? AND k = ? AND language = ? "
                "ORDER BY distance",
                (query_bytes, k, language),
            ).fetchall()
        else:
            rows = vec_conn.execute(
                "SELECT decision_id, distance FROM vec_decisions "
                "WHERE embedding MATCH ? AND k = ? "
                "ORDER BY distance",
                (query_bytes, k),
            ).fetchall()
        return {row[0]: row[1] for row in rows}
    except Exception as e:
        logger.debug("Vector search failed: %s", e)
        return {}
    finally:
        vec_conn.close()


def _search_vectors_chunks(
    query: str,
    language: str | None = None,
    k: int | None = None,
) -> dict[str, float]:
    """KNN search at chunk level, aggregated to decision level (min distance).

    Falls back silently to empty dict if vec_chunks table doesn't exist.
    """
    model = _get_vector_model()
    if model is None:
        return {}
    vec_conn = _get_vec_conn()
    if vec_conn is None:
        return {}
    k = k or VECTOR_K * 3  # more results since multiple chunks per decision

    try:
        if not _sqlite_has_table(vec_conn, "vec_chunks"):
            return {}

        query_bytes = _encode_query(model, query)
        if query_bytes is None:
            return {}

        if language:
            rows = vec_conn.execute(
                "SELECT chunk_id, distance FROM vec_chunks "
                "WHERE embedding MATCH ? AND k = ? AND language = ? "
                "ORDER BY distance",
                (query_bytes, k, language),
            ).fetchall()
        else:
            rows = vec_conn.execute(
                "SELECT chunk_id, distance FROM vec_chunks "
                "WHERE embedding MATCH ? AND k = ? "
                "ORDER BY distance",
                (query_bytes, k),
            ).fetchall()

        # Aggregate: best (min distance) chunk per decision
        decision_scores: dict[str, float] = {}
        for chunk_id, distance in rows:
            decision_id = chunk_id.rsplit("__chunk_", 1)[0]
            if decision_id not in decision_scores or distance < decision_scores[decision_id]:
                decision_scores[decision_id] = distance

        return decision_scores
    except Exception as e:
        logger.debug("Chunk vector search failed: %s", e)
        return {}
    finally:
        vec_conn.close()


def _search_sparse(
    query: str,
    k: int | None = None,
) -> dict[str, float]:
    """Sparse retrieval using learned lexical weights from BGE-M3.

    Tokenizes the query, looks up the inverted index, and sums matching
    token weights per document. Returns {decision_id: score} or empty dict.
    """
    if SPARSE_SEARCH_ENABLED in {"0", "false", "no"}:
        return {}
    vec_conn = _get_vec_conn()
    if vec_conn is None:
        return {}
    k = k or SPARSE_K

    try:
        if not _sqlite_has_table(vec_conn, "sparse_terms"):
            return {}

        # Tokenize query using the model's tokenizer
        model = _get_vector_model()
        if model is None:
            return {}

        # Get tokenizer from model (SentenceTransformer or BGEM3FlagModel)
        tokenizer = getattr(model, "tokenizer", None)
        if tokenizer is None:
            # SentenceTransformer: try model[0].tokenizer (Transformer module)
            try:
                tokenizer = model[0].tokenizer
            except (IndexError, TypeError, AttributeError):
                pass
        if tokenizer is None:
            logger.debug("Cannot access tokenizer for sparse search")
            return {}

        tokens = tokenizer(query, return_tensors="pt")["input_ids"][0]
        # Skip special tokens (CLS=101, SEP=102, PAD=0)
        token_ids = [int(t) for t in tokens if int(t) not in (0, 1, 2, 101, 102)]

        if not token_ids:
            return {}

        placeholders = ",".join("?" * len(token_ids))
        rows = vec_conn.execute(
            f"SELECT decision_id, SUM(weight) as score FROM sparse_terms "
            f"WHERE token_id IN ({placeholders}) "
            f"GROUP BY decision_id ORDER BY score DESC LIMIT ?",
            (*token_ids, k),
        ).fetchall()
        return {row[0]: row[1] for row in rows}
    except Exception as e:
        logger.debug("Sparse search failed: %s", e)
        return {}
    finally:
        vec_conn.close()


def _sqlite_has_table(conn: sqlite3.Connection, table: str) -> bool:
    row = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
        (table,),
    ).fetchone()
    return row is not None


_SAFE_IDENT_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def _sqlite_has_column(conn: sqlite3.Connection, table: str, column: str) -> bool:
    """Defence-in-depth: PRAGMA cannot use ?-binding, so the table
    name is interpolated. All current callers pass internal constants,
    but reject any input that does not match a strict identifier
    pattern so a future caller cannot accidentally introduce SQL
    injection."""
    if not _SAFE_IDENT_RE.match(table or ""):
        return False
    try:
        rows = conn.execute(f"PRAGMA table_info({table})").fetchall()
    except sqlite3.Error:
        return False
    return any(str(r[1]).lower() == column.lower() for r in rows)


def _load_graph_signal_map(
    decision_ids: list[str],
    *,
    query_statutes: set[str],
    query_citations: set[str],
) -> dict[str, dict[str, float]]:
    if not GRAPH_SIGNALS_ENABLED or not decision_ids:
        return {}

    unique_ids = list(dict.fromkeys([did for did in decision_ids if did]))
    if not unique_ids:
        return {}

    signal_map: dict[str, dict[str, float]] = {
        did: {
            "statute_mentions": 0.0,
            "query_citation_hits": 0.0,
            "incoming_citations": 0.0,
        }
        for did in unique_ids
    }

    conn = _get_graph_conn()
    if conn is None:
        return {}
    try:
        has_citation_targets = _sqlite_has_table(conn, "citation_targets")
        has_legacy_target_column = _sqlite_has_column(
            conn, "decision_citations", "target_decision_id"
        )
        has_confidence_score = (
            has_citation_targets
            and _sqlite_has_column(conn, "citation_targets", "confidence_score")
        )

        placeholders = ",".join("?" for _ in unique_ids)
        if query_statutes:
            statute_refs = sorted(query_statutes)
            statute_placeholders = ",".join("?" for _ in statute_refs)
            rows = conn.execute(
                f"""
                SELECT decision_id, SUM(mention_count) AS n
                FROM decision_statutes
                WHERE decision_id IN ({placeholders})
                  AND statute_id IN ({statute_placeholders})
                GROUP BY decision_id
                """,
                tuple(unique_ids) + tuple(statute_refs),
            ).fetchall()
            for row in rows:
                signal_map[row["decision_id"]]["statute_mentions"] = float(row["n"] or 0.0)

        if query_citations:
            citation_refs = sorted(query_citations)
            citation_placeholders = ",".join("?" for _ in citation_refs)
            rows = conn.execute(
                f"""
                SELECT source_decision_id AS decision_id, SUM(mention_count) AS n
                FROM decision_citations
                WHERE source_decision_id IN ({placeholders})
                  AND target_ref IN ({citation_placeholders})
                GROUP BY source_decision_id
                """,
                tuple(unique_ids) + tuple(citation_refs),
            ).fetchall()
            for row in rows:
                signal_map[row["decision_id"]]["query_citation_hits"] = float(row["n"] or 0.0)

        if has_citation_targets:
            if has_confidence_score:
                rows = conn.execute(
                    f"""
                    SELECT
                        ct.target_decision_id AS decision_id,
                        SUM(dc.mention_count * COALESCE(ct.confidence_score, 1.0)) AS n
                    FROM citation_targets ct
                    JOIN decision_citations dc
                      ON dc.source_decision_id = ct.source_decision_id
                     AND dc.target_ref = ct.target_ref
                    WHERE ct.target_decision_id IN ({placeholders})
                    GROUP BY ct.target_decision_id
                    """,
                    tuple(unique_ids),
                ).fetchall()
            else:
                rows = conn.execute(
                    f"""
                    SELECT ct.target_decision_id AS decision_id, SUM(dc.mention_count) AS n
                    FROM citation_targets ct
                    JOIN decision_citations dc
                      ON dc.source_decision_id = ct.source_decision_id
                     AND dc.target_ref = ct.target_ref
                    WHERE ct.target_decision_id IN ({placeholders})
                    GROUP BY ct.target_decision_id
                    """,
                    tuple(unique_ids),
                ).fetchall()
        elif has_legacy_target_column:
            rows = conn.execute(
                f"""
                SELECT target_decision_id AS decision_id, SUM(mention_count) AS n
                FROM decision_citations
                WHERE target_decision_id IN ({placeholders})
                GROUP BY target_decision_id
                """,
                tuple(unique_ids),
            ).fetchall()
        else:
            rows = []
        for row in rows:
            signal_map[row["decision_id"]]["incoming_citations"] = max(
                0.0,
                float(row["n"] or 0.0),
            )
        # ── In-pool citation signal ──
        # Count how many OTHER candidates cite each candidate.
        # This is a topical relevance signal: if many search results
        # cite decision X, then X is likely a leading case for this query.
        if has_citation_targets and len(unique_ids) >= 3:
            try:
                rows = conn.execute(
                    f"""
                    SELECT ct.target_decision_id AS target_id,
                           COUNT(DISTINCT ct.source_decision_id) AS pool_cites
                    FROM citation_targets ct
                    WHERE ct.source_decision_id IN ({placeholders})
                      AND ct.target_decision_id IN ({placeholders})
                      AND ct.source_decision_id != ct.target_decision_id
                    GROUP BY ct.target_decision_id
                    """,
                    tuple(unique_ids) + tuple(unique_ids),
                ).fetchall()
                for row in rows:
                    tid = row["target_id"]
                    if tid in signal_map:
                        signal_map[tid]["in_pool_citations"] = float(row["pool_cites"])
            except sqlite3.Error:
                pass  # non-critical signal

    except sqlite3.Error as e:
        logger.debug("Graph-signal lookup failed: %s", e)
        return {}
    finally:
        conn.close()

    return signal_map


def _search_statute_graph(
    statute_refs: set[str],
    *,
    limit: int = 20,
) -> list[tuple[str, float]]:
    """Query citation graph for top decisions citing given statutes, ranked by authority.

    Returns list of (decision_id, authority_score) tuples sorted by authority desc.
    """
    if not statute_refs:
        return []

    conn = _get_graph_conn()
    if conn is None:
        return []

    try:
        has_citation_targets = _sqlite_has_table(conn, "citation_targets")
        refs = sorted(statute_refs)
        ph = ",".join("?" for _ in refs)

        # Two-path retrieval: top by mentions + top by authority
        # Path 1: Top 300 by statute mention count (catches frequently-discussing decisions)
        citing_rows = conn.execute(
            f"""
            SELECT decision_id, SUM(mention_count) AS total_mentions
            FROM decision_statutes
            WHERE statute_id IN ({ph})
            GROUP BY decision_id
            ORDER BY total_mentions DESC
            LIMIT 300
            """,
            tuple(refs),
        ).fetchall()

        if not citing_rows:
            return []

        mention_by_id = {r["decision_id"]: float(r["total_mentions"]) for r in citing_rows}
        all_ids: set[str] = {r["decision_id"] for r in citing_rows}

        # Path 2: Top 200 by incoming citations among ALL statute-citing decisions
        # This catches authoritative decisions that mention the statute only once
        if has_citation_targets:
            auth_top_rows = conn.execute(
                f"""
                SELECT ds.decision_id,
                       SUM(ds.mention_count) AS total_mentions,
                       COUNT(DISTINCT ct.source_decision_id) AS auth_count
                FROM decision_statutes ds
                JOIN citation_targets ct ON ct.target_decision_id = ds.decision_id
                WHERE ds.statute_id IN ({ph})
                GROUP BY ds.decision_id
                ORDER BY auth_count DESC
                LIMIT 200
                """,
                tuple(refs),
            ).fetchall()
            for r in auth_top_rows:
                did = r["decision_id"]
                if did not in mention_by_id:
                    mention_by_id[did] = float(r["total_mentions"])
                all_ids.add(did)

        citing_ids = list(all_ids)

        # Get incoming citation counts for ALL candidate decisions
        cid_ph = ",".join("?" for _ in citing_ids)
        if has_citation_targets:
            auth_rows = conn.execute(
                f"""
                SELECT ct.target_decision_id AS decision_id,
                       COUNT(DISTINCT ct.source_decision_id) AS n
                FROM citation_targets ct
                WHERE ct.target_decision_id IN ({cid_ph})
                GROUP BY ct.target_decision_id
                """,
                tuple(citing_ids),
            ).fetchall()
        else:
            auth_rows = []

        auth_by_id = {r["decision_id"]: float(r["n"] or 0.0) for r in auth_rows}

        # Score: balanced authority + mentions (both matter for statute queries)
        scored = []
        for did in citing_ids:
            authority = auth_by_id.get(did, 0.0)
            mentions = mention_by_id.get(did, 0.0)
            score = 0.7 * math.log1p(authority) + 0.7 * math.log1p(mentions)
            scored.append((did, score))

        scored.sort(key=lambda x: -x[1])
        return scored[:limit]

    except sqlite3.Error as e:
        logger.debug("Statute-graph search failed: %s", e)
        return []
    finally:
        conn.close()


def _bge_ref_candidates(ref: str) -> list[str]:
    """Canonical decision_id candidates for a BGE/ATF/DTF reference, by EXACT
    (vol, part, page) tuple — so '131 III 12' resolves to bge_BGE_131_III_12 and
    never prefix-matches the different ruling '131 III 121' (bug C-1). The
    trailing anchor keeps the page exact. Case-insensitive (issue #43) and
    tolerant of a trailing pinpoint suffix (', E. 2.3', ' consid. 2') so the
    tool's own citation round-trips — resolution is decision-level; the pinpoint
    is ignored here (get_erwaegung consumes it)."""
    r = (ref or "").strip()
    # Drop a trailing pinpoint suffix before the exact-tuple match.
    r = re.sub(r"\s*,?\s+(?:E|Erw|consid|cons)\.?\s+\S.*$", "", r, flags=re.IGNORECASE)
    # Accept the stored decision_id shapes as input, not only the human
    # reference form. attest_response builds "bge_BGE_76_II_346" from the
    # citation text and hands the resolver that id rather than the reference,
    # so this helper saw a string its tuple regex could not parse and returned
    # nothing — and a decision stored only as "bge_76_II_346" was reported as
    # absent from the corpus (GitHub #83). Underscores become spaces so the
    # regex below sees a reference. Non-BGE ids ("bger_4A_231_2014",
    # "mkg_MKGE_16_Nr_1") still fail that regex and yield [] exactly as before,
    # and the expansion stays keyed on the exact (vol, division, page) tuple,
    # so widening the input cannot resolve to a different decision.
    r = re.sub(r"^bge_(?:BGE_)?", "", r, flags=re.IGNORECASE).replace("_", " ")
    # Division = roman numeral + optional 'a'/'b' suffix (BGE 116 Ia 28). Roman
    # part upper-cased, suffix lower-cased, to match the stored 'Ia'/'III' form.
    m = re.match(r"(?:(?:BGE|ATF|DTF)\s+)?(\d+)\s+([IVX]+)([ab]?)\s+(\d+)\s*$",
                 r, flags=re.IGNORECASE)
    if not m:
        return []
    vol = m.group(1)
    div = m.group(2).upper() + m.group(3).lower()
    page = m.group(4)
    return [f"bge_BGE_{vol}_{div}_{page}", f"bge_{vol}_{div}_{page}", f"bge_{vol} {div} {page}"]


def _docket_is_prefix_of_longer(inp: str, docket: str | None) -> bool:
    """True if `docket` is the input followed by extra digit(s) — '131 III 12' vs
    '131 III 121'. Such a LIKE '%inp%' hit is a DIFFERENT decision and must be
    rejected (silently returning the wrong authority is the worst failure mode)."""
    inp = (inp or "").strip()
    d = (docket or "").strip()
    if not d or d == inp or not d.startswith(inp):
        return False
    rest = d[len(inp):]
    return bool(rest) and rest[0].isdigit()


def _extract_single_docket(text: str) -> str | None:
    """If `text` contains exactly ONE distinct BGer-style docket, return it in
    the stored space form ('6B 1518/2021'); otherwise None.

    Lets get_decision resolve a DECORATED form of its own printed citation —
    "BGer 6B 1518/2021 vom 31. Januar 2022", or stray leading/trailing space —
    by pulling out the docket and retrying the exact lookup (issue #44). The
    match is boundary-anchored (docket_aliases._DOCKET_IN_TEXT_RE), so a trailing
    digit ('6B 1518/20210') yields no match, and a second docket makes it
    ambiguous -> None: it never silently resolves to the wrong decision.
    """
    if not text:
        return None
    seen: dict[str, str] = {}
    for m in docket_aliases._DOCKET_IN_TEXT_RE.finditer(text):
        key = f"{m.group(1).upper()}_{m.group(2)}/{m.group(3)}"
        seen[key] = f"{m.group(1).upper()} {m.group(2)}/{m.group(3)}"  # stored space form
    if len(seen) != 1:
        return None
    return next(iter(seen.values()))


def _input_is_docket_like(s: str) -> bool:
    """Gate for the LIKE '%s%' docket scan: only fire when `s` plausibly holds a
    docket fragment — a digit-letter-or-slash run, not bare words/symbols/wildcards.
    Blocks bare words, single chars, symbols, and LIKE-wildcard-shaped garbage
    ('1 %', '6B %/2021') from false-matching decision IDs/titles — e.g.
    get_decision('INVALID') must NOT return a decision about 'Invalidenrente'
    (issue #44)."""
    s = (s or "").strip()
    if not s or "%" in s:
        return False
    # Require a docket-shaped fragment: 1-2 digits, optional letters, a
    # separator, then a digit (e.g. '6B 1518', '18/2021'). Bare words, single
    # chars, symbols, '1 %', '123' don't match.
    return bool(re.search(r"\d{1,2}[A-Za-z]{0,3}[.\s/_]\d", s))


def _like_escape(s: str) -> str:
    """Escape LIKE wildcards so user input can't inject '%'/'_' semantics into
    a `LIKE '%s%' ESCAPE '\\'` scan (issue #44). Backslash escaped first."""
    return s.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


def _lookup_docket_alias(conn: sqlite3.Connection, reference: str | None) -> list[str]:
    """Resolve a joined/secondary docket to canonical decision_id(s) (issue #41).

    Consolidated federal proceedings ("vereinigte Verfahren") are stored under
    only the lead docket; decision_docket_aliases maps every secondary docket to
    that lead. Returns 0, 1, or (ambiguous) >1 canonical ids. Guarded: returns
    [] when the table is absent (a server running against a pre-rebuild DB or a
    minimal test fixture), so this can never raise.
    """
    key = docket_aliases.normalize_docket_key(reference)
    if not key:
        return []
    try:
        rows = conn.execute(
            "SELECT DISTINCT canonical_decision_id FROM decision_docket_aliases "
            "WHERE alias_docket_norm = ?",
            (key,),
        ).fetchall()
    except sqlite3.OperationalError:
        return []  # alias table not present yet
    return [r[0] for r in rows]


def _joined_dockets_for(conn: sqlite3.Connection, decision_id: str | None) -> list[str]:
    """Every secondary (joined) docket stored for a consolidated decision (#41),
    in the alias table's normalised form ('1B_243/2022'), sorted; [] when there
    are none or the alias table is absent (never raises). The inverse of
    _lookup_docket_alias: it lets a record announce ALL its dockets, so a
    client holding only a joined docket can recognise the lead decision."""
    if not decision_id:
        return []
    try:
        rows = conn.execute(
            "SELECT DISTINCT alias_docket FROM decision_docket_aliases "
            "WHERE canonical_decision_id = ? ORDER BY alias_docket",
            (decision_id,),
        ).fetchall()
    except sqlite3.OperationalError:
        return []  # alias table not present yet
    return [r[0] for r in rows if r[0]]


def _lookup_ecthr_appno(conn: sqlite3.Connection, reference: str | None) -> list[str]:
    """Resolve a bare ECtHR application number to its judgment(s).

    ECtHR dockets carry the judgment date ("47358/20_20220830") because 158
    application numbers in the corpus name more than one judgment — merits,
    then just satisfaction or revision, years apart. A practitioner types the
    bare number, which after the re-keying no longer matches docket_number
    exactly, and would otherwise fall through to the `LIKE '%x%'` full scan.

    Uses a range predicate rather than LIKE so it stays on
    idx_decisions_docket: SQLite disables its prefix-LIKE optimisation as soon
    as ESCAPE is used, and the underscore has to be escaped to be literal.
    '_' is 0x5F and '`' is 0x60, so ["47358/20_", "47358/20`") is exactly the
    set of dockets beginning "47358/20_".

    Returns every match, earliest first. Callers resolve only when there is
    exactly one — an ambiguous application number is left to fall through
    rather than silently picking a judgment.
    """
    ref = (reference or "").strip()
    if not _ECTHR_APP_NO.match(ref):
        return []
    try:
        rows = conn.execute(
            "SELECT decision_id FROM decisions "
            "WHERE docket_number >= ? AND docket_number < ? "
            "ORDER BY decision_date ASC",
            (ref + "_", ref + "`"),
        ).fetchall()
    except sqlite3.OperationalError:
        return []
    return [r[0] for r in rows]


def _lookup_ref_candidates(conn: sqlite3.Connection, reference: str | None) -> str | None:
    """Resolve a typed identifier through decision_ref.resolve_decision_ref:
    the docket grammar names the court(s) and the id each scraper would have
    minted, and every candidate is tried as a PRIMARY-KEY lookup, in order.
    Bare cantonal dockets ('UH220412', 'ACPR/635/2024', 'VB.2025.0683'),
    dotted pre-2007 and EVG federal forms ('1A.235/2000', 'I 123/04'), BVGer /
    BStGer / BPatGer files, percent-encoded ids, the ZH Verwaltungsgericht
    double underscore and the space form of our own BGer citation strings
    (#76) all land here instead of in the ~2 s LIKE scan. Returns the first
    stored id, or None. Never raises (a fixture without the table yields None).
    """
    for cid in decision_ref.resolve_decision_ref(reference):
        try:
            row = conn.execute(
                "SELECT decision_id FROM decisions WHERE decision_id = ?", (cid,)
            ).fetchone()
        except sqlite3.OperationalError:
            return None
        if row:
            return row[0]
    return None


def _lookup_appno_in_prose(conn: sqlite3.Connection, reference: str | None) -> str | None:
    """An ECtHR application number written inside a reference ('CourEDH X c.
    Suisse, n° 22060/20') -> the unique judgment carrying it, via the indexed
    range lookup; None when the reference names no number or it is ambiguous."""
    appno = decision_ref.application_number(reference)
    if not appno or appno == (reference or "").strip():
        return None
    ids = _lookup_ecthr_appno(conn, appno)
    return ids[0] if len(ids) == 1 else None


def _decision_exists(decision_id: str | None) -> bool:
    """Indexed PK check — no full-text fetch, no LIKE."""
    if not decision_id:
        return False
    conn = get_db()
    try:
        return conn.execute(
            "SELECT 1 FROM decisions WHERE decision_id = ?", (decision_id,)
        ).fetchone() is not None
    except sqlite3.OperationalError:
        return False
    finally:
        conn.close()


def _resolve_decision_id(decision_id: str) -> str:
    """Resolve a user-supplied decision_id to the actual stored decision_id.

    Uses the FTS5 DB lookup (exact match → docket match → joined-docket alias →
    partial match), same logic as get_decision_by_id. Returns the input
    unchanged if no match.
    """
    decision_id = (decision_id or "").strip()  # trim so a padded id/docket resolves (#44)
    # Generate ID candidates for lookup. Delegate BGE-reference expansion to
    # _bge_ref_candidates so ATF (FR) and DTF (IT) forms resolve too — not just
    # BGE (issue #43). It is also anchored (\s*$), so '131 III 12' can't
    # prefix-match '131 III 121'.
    candidates = [decision_id]
    candidates.extend(_bge_ref_candidates(decision_id))

    conn = get_db()
    try:
        # Try exact ID match for all candidates
        for cid in candidates:
            row = conn.execute(
                "SELECT decision_id FROM decisions WHERE decision_id = ?", (cid,)
            ).fetchone()
            if row:
                return row[0]
        # Fallback: exact docket — always tried.
        row = conn.execute(
            "SELECT decision_id FROM decisions WHERE docket_number = ? "
            "ORDER BY decision_date DESC LIMIT 1",
            (decision_id,),
        ).fetchone()
        if row:
            return row[0]
        # Robustness (#44): resolve a DECORATED citation form ("BGer 6B 1518/2021
        # vom ...", stray whitespace) by extracting the single docket and
        # retrying the exact lookup.
        _ext = _extract_single_docket(decision_id)
        if _ext and _ext != decision_id:
            row = conn.execute(
                "SELECT decision_id FROM decisions WHERE docket_number = ? "
                "ORDER BY decision_date DESC LIMIT 1", (_ext,),
            ).fetchone()
            if row:
                return row[0]
        # The reference as a lawyer writes it (shared parser with the research
        # CLI): the label written first, tried in every stored separator; a
        # BGE label with a page or a trailing pinpoint; a cantonal docket inside
        # the service's own long-form string. A docket mentioned later in the
        # reference is a cross-reference and is never resolved to.
        parsed_hit = _resolve_parsed_reference(conn, decision_id)
        if parsed_hit:
            return parsed_hit
        # Bare ECtHR application number -> the judgment carrying it. Indexed,
        # and unique-only for the same reason as the alias step below.
        _appno_ids = _lookup_ecthr_appno(conn, decision_id)
        if len(_appno_ids) == 1:
            return _appno_ids[0]
        # Joined-docket alias (#41): a secondary docket of a consolidated
        # decision. Only a UNIQUE alias resolves; an ambiguous one falls through.
        alias_ids = _lookup_docket_alias(conn, decision_id)
        if len(alias_ids) == 1:
            return alias_ids[0]
        # Typed identifiers: docket grammar -> candidate ids, PK lookups only
        # (decision_ref). Before the LIKE scan so a bare cantonal docket or a
        # dotted federal one never pays for the table scan it used to miss on.
        _ref_hit = _lookup_ref_candidates(conn, decision_id) or _lookup_appno_in_prose(conn, decision_id)
        if _ref_hit:
            return _ref_hit
        # Last resort: LIKE %x% — full table scan ~2 s on 1M rows.
        # Skip when input clearly looks like a canonical decision_id
        # (it would have hit step 1 if it existed) or isn't docket-like at all
        # (bare words/chars/symbols would false-match — #44).
        if (not _CANONICAL_ID_PREFIX_RE.match(decision_id or "")
                and _input_is_docket_like(decision_id)):
            for cand in conn.execute(
                "SELECT decision_id, docket_number FROM decisions "
                "WHERE docket_number LIKE ? ESCAPE '\\' "
                "ORDER BY decision_date DESC LIMIT 8",
                (f"%{_like_escape(decision_id)}%",),
            ).fetchall():
                # never resolve to a longer docket that merely contains the input
                # as a numeric prefix (131 III 12 -> 131 III 121); see bug C-1.
                if not _docket_is_prefix_of_longer(decision_id, cand["docket_number"]):
                    return cand["decision_id"]
    finally:
        conn.close()
    return decision_id


def _resolve_parsed_reference(conn, reference: str) -> str | None:
    """Exact-label resolution of a written reference via reference_parser.

    Returns a decision_id only when a stored decision carries the label the
    reference writes first (BGE tuple, or a docket in one of its stored
    separators); several carriers are disambiguated by the court or canton the
    reference names, and stay unresolved when the reference names none."""
    try:
        parsed = reference_parser.parse_reference(reference)
    except Exception:  # noqa: BLE001 — a parser fault must not break resolution
        return None
    if parsed.bge_label and parsed.bge_label != reference.strip():
        for cid in _bge_ref_candidates(parsed.bge_label):
            row = conn.execute("SELECT decision_id FROM decisions WHERE decision_id = ?", (cid,)).fetchone()
            if row:
                return row[0]
    primary = parsed.primary_docket
    if not primary or (parsed.bge_label and parsed.bge_first):
        return None
    for variant in reference_parser.docket_variants(primary):
        rows = conn.execute(
            "SELECT decision_id, court, canton FROM decisions WHERE docket_number = ? "
            "ORDER BY decision_date DESC LIMIT 8", (variant,),
        ).fetchall()
        if not rows:
            continue
        records = [dict(zip(("decision_id", "court", "canton"), tuple(r))) for r in rows]
        scoped = [r for r in records if parsed.in_scope(r)]
        if parsed.courts or parsed.canton:
            if len({r["decision_id"] for r in scoped}) >= 1:
                return scoped[0]["decision_id"]
            continue
        return records[0]["decision_id"]
    alias_ids = _lookup_docket_alias(conn, primary)
    if len(alias_ids) == 1:
        return alias_ids[0]
    return None


def _decision_id_variants(decision_id: str) -> list[str]:
    """Generate ID variants for graph DB lookups.

    The FTS5 DB and graph DB may store the same decision under different ID
    formats. For BGE decisions, the direct scraper uses 'bge_138 III 374'
    while entscheidsuche uses 'bge_BGE_138_III_374'. This function generates
    all plausible variants so IN-clause lookups can match either.
    """
    variants = {decision_id}
    # Split court prefix from the rest
    parts = decision_id.split("_", 1)
    if len(parts) == 2:
        court, rest = parts
        # Variant: underscores in rest → spaces
        variants.add(f"{court}_{rest.replace('_', ' ')}")
        # Variant: spaces in rest → underscores
        variants.add(f"{court}_{rest.replace(' ', '_')}")

        # BGE-specific: handle FTS5/graph ID format mismatches.
        # FTS5 uses "bge_BGE_138_III_374"; graph uses "bge_138 III 374".
        if court in ("bge", "bge_historical"):
            stripped = re.sub(r"^(?:CH[_ ])?(?:BGE|ATF|DTF)[_ ]?", "", rest)
            core = stripped if stripped != rest else rest
            core_under = core.replace(" ", "_")
            core_space = core.replace("_", " ")
            # All plausible bge_* variants
            variants.update([
                f"bge_{core_under}",
                f"bge_{core_space}",
                f"bge_BGE_{core_under}",
            ])
    return list(variants)


def _count_citations(decision_id: str) -> tuple[int, int]:
    """Return (incoming_count, outgoing_count) for a decision from the graph DB.

    Uses all ID variants (FTS5 vs graph format) so format mismatches are handled.
    Returns (0, 0) if graph DB unavailable or decision not found.
    """
    conn = _get_graph_conn()
    if conn is None:
        return (0, 0)
    try:
        variants = _decision_id_variants(decision_id)
        placeholders = ",".join("?" for _ in variants)

        incoming = 0
        if _sqlite_has_table(conn, "citation_targets"):
            row = conn.execute(
                f"SELECT COUNT(*) AS n FROM citation_targets WHERE target_decision_id IN ({placeholders})",
                variants,
            ).fetchone()
            incoming = int(row["n"]) if row else 0

        row = conn.execute(
            f"SELECT COUNT(*) AS n FROM decision_citations WHERE source_decision_id IN ({placeholders})",
            variants,
        ).fetchone()
        outgoing = int(row["n"]) if row else 0

        return (incoming, outgoing)
    except sqlite3.Error as e:
        logger.debug("Citation count failed: %s", e)
        return (0, 0)
    finally:
        conn.close()


def _find_outgoing_citations(
    decision_id: str, *, min_confidence: float = 0.3, limit: int = 50, offset: int = 0
) -> list[dict]:
    """Find citations made by this decision (what it cites)."""
    conn = _get_graph_conn()
    if conn is None:
        return []
    try:
        # Try ID variants (space vs underscore) since FTS5 DB and graph DB
        # may store the same decision under different ID formats.
        variants = _decision_id_variants(decision_id)
        placeholders = ",".join(["?"] * len(variants))
        rows = conn.execute(
            f"""
            SELECT dc.target_ref, dc.target_type, dc.mention_count,
                   ct.target_decision_id, ct.confidence_score,
                   d.docket_number, d.court, d.decision_date
            FROM decision_citations dc
            LEFT JOIN citation_targets ct
              ON ct.source_decision_id = dc.source_decision_id
             AND ct.target_ref = dc.target_ref
            LEFT JOIN decisions d
              ON d.decision_id = ct.target_decision_id
            WHERE dc.source_decision_id IN ({placeholders})
              AND (ct.confidence_score IS NULL OR ct.confidence_score >= ?)
            ORDER BY dc.mention_count DESC, ct.confidence_score DESC,
                     dc.target_ref, ct.target_decision_id, dc.source_decision_id
            LIMIT ? OFFSET ?
            """,
            (*variants, min_confidence, limit, offset),
        ).fetchall()
        return [dict(r) for r in rows]
    except sqlite3.Error as e:
        logger.debug("Outgoing citations lookup failed: %s", e)
        return []
    finally:
        conn.close()


def _count_citations_filtered(
    decision_id: str, *, min_confidence: float = 0.3
) -> tuple[int, int]:
    """Return (incoming_total, outgoing_total) mirroring the exact WHERE clauses of
    _find_incoming_citations / _find_outgoing_citations, so truncation flags on the
    fetched pages are accurate (the plain _count_citations ignores min_confidence)."""
    conn = _get_graph_conn()
    if conn is None:
        return (0, 0)
    try:
        variants = _decision_id_variants(decision_id)
        ph = ",".join(["?"] * len(variants))
        out_row = conn.execute(
            f"""
            SELECT COUNT(*) AS n
            FROM decision_citations dc
            LEFT JOIN citation_targets ct
              ON ct.source_decision_id = dc.source_decision_id
             AND ct.target_ref = dc.target_ref
            WHERE dc.source_decision_id IN ({ph})
              AND (ct.confidence_score IS NULL OR ct.confidence_score >= ?)
            """,
            (*variants, min_confidence),
        ).fetchone()
        outgoing = int(out_row["n"]) if out_row else 0
        in_row = conn.execute(
            f"""
            SELECT COUNT(*) AS n
            FROM citation_targets ct
            JOIN decision_citations dc
              ON dc.source_decision_id = ct.source_decision_id
             AND dc.target_ref = ct.target_ref
            JOIN decisions d
              ON d.decision_id = ct.source_decision_id
            WHERE ct.target_decision_id IN ({ph})
              AND ct.confidence_score >= ?
            """,
            (*variants, min_confidence),
        ).fetchone()
        incoming = int(in_row["n"]) if in_row else 0
        return (incoming, outgoing)
    except sqlite3.Error as e:
        logger.debug("Filtered citation count failed: %s", e)
        return (0, 0)
    finally:
        conn.close()


def _find_incoming_citations(
    decision_id: str, *, min_confidence: float = 0.3, limit: int = 50, offset: int = 0
) -> list[dict]:
    """Find decisions that cite this decision."""
    conn = _get_graph_conn()
    if conn is None:
        return []
    try:
        # Try ID variants (space vs underscore) since FTS5 DB and graph DB
        # may store the same decision under different ID formats.
        variants = _decision_id_variants(decision_id)
        placeholders = ",".join(["?"] * len(variants))
        rows = conn.execute(
            f"""
            SELECT ct.source_decision_id, ct.confidence_score, ct.target_ref,
                   dc.mention_count,
                   d.docket_number, d.court, d.decision_date
            FROM citation_targets ct
            JOIN decision_citations dc
              ON dc.source_decision_id = ct.source_decision_id
             AND dc.target_ref = ct.target_ref
            JOIN decisions d
              ON d.decision_id = ct.source_decision_id
            WHERE ct.target_decision_id IN ({placeholders})
              AND ct.confidence_score >= ?
            ORDER BY d.decision_date DESC, ct.confidence_score DESC,
                     ct.source_decision_id, ct.target_ref, ct.target_decision_id
            LIMIT ? OFFSET ?
            """,
            (*variants, min_confidence, limit, offset),
        ).fetchall()
        return [dict(r) for r in rows]
    except sqlite3.Error as e:
        logger.debug("Incoming citations lookup failed: %s", e)
        return []
    finally:
        conn.close()


def _find_appeal_chain(
    decision_id: str, *, min_confidence: float = 0.3
) -> dict:
    """Traverse the appeal chain for a decision (prior and subsequent instances).

    Uses the is_prior_instance flag on decision_citations to distinguish
    procedural links (appeal chain) from doctrinal citations.
    """
    # Resolve user-supplied ID to actual stored ID (handles format differences)
    decision_id = _resolve_decision_id(decision_id)

    conn = _get_graph_conn()
    if conn is None:
        return {"decision_id": decision_id, "error": "Reference graph not available."}

    try:
        # Check if is_prior_instance column exists (backward compat)
        cols = [
            r[1] for r in conn.execute("PRAGMA table_info(decision_citations)").fetchall()
        ]
        if "is_prior_instance" not in cols:
            return {
                "decision_id": decision_id,
                "error": "Appeal chain data not available. Rebuild reference graph to enable.",
            }

        result: dict = {"decision_id": decision_id, "chain": []}

        # Get info about the queried decision
        src = conn.execute(
            "SELECT docket_number, court, canton, decision_date FROM decisions WHERE decision_id = ?",
            (decision_id,),
        ).fetchone()
        if src:
            result["docket_number"] = src["docket_number"]
            result["court"] = src["court"]
            result["decision_date"] = src["decision_date"]

        # Use separate visited sets per direction so nodes found walking
        # down (prior instances) are not excluded from the upward walk.
        # The root decision_id is NOT pre-added — _walk_chain queries it
        # at depth=0, then adds discovered children to visited to prevent cycles.
        visited_down: set[str] = set()
        visited_up: set[str] = set()

        # Walk DOWN: find prior instances (what this decision appealed)
        _walk_chain(conn, decision_id, "down", result["chain"], min_confidence, visited=visited_down)

        # For BGE decisions: the prior-instance info is usually on the
        # corresponding bger record (the non-BGE version of the same case,
        # which has the formulaic "Beschwerde gegen ..." header).  Look up
        # the bger record by matching the BGE's docket_number_2 field
        # (e.g. "4C_215/2005") to a bger decision's docket_number.
        if (src and (src["court"] or "").startswith("bge") and
                not result["chain"]):
            # Try to find the bger counterpart via docket_number_2
            fts_conn = get_db()
            try:
                bge_row = fts_conn.execute(
                    "SELECT docket_number_2 FROM decisions WHERE decision_id = ?",
                    (decision_id,),
                ).fetchone()
                bger_docket = None
                if bge_row:
                    try:
                        bger_docket = bge_row["docket_number_2"]
                    except (KeyError, IndexError):
                        pass
                if bger_docket:
                    bger_row = fts_conn.execute(
                        "SELECT decision_id FROM decisions WHERE court = 'bger' AND docket_number = ? LIMIT 1",
                        (bger_docket,),
                    ).fetchone()
                    if bger_row:
                        bger_id = bger_row["decision_id"]
                        _walk_chain(conn, bger_id, "down", result["chain"], min_confidence, visited=visited_down)
            except sqlite3.Error:
                pass
            finally:
                fts_conn.close()

        # Walk UP: find subsequent instances (decisions that appealed this one)
        _walk_chain(conn, decision_id, "up", result["chain"], min_confidence, visited=visited_up)

        # Sort chain by date
        result["chain"].sort(key=lambda x: x.get("decision_date") or "")

        return result
    except sqlite3.Error as e:
        logger.debug("Appeal chain lookup failed: %s", e)
        return {"decision_id": decision_id, "error": str(e)}
    finally:
        conn.close()


def _walk_chain(
    conn: sqlite3.Connection,
    decision_id: str,
    direction: str,
    chain: list[dict],
    min_confidence: float,
    visited: set[str],
    depth: int = 0,
) -> None:
    """Recursively walk the appeal chain in one direction."""
    if depth > 5:  # safety limit
        return
    if decision_id in visited:
        return
    visited.add(decision_id)  # mark before querying to prevent cycles

    if direction == "down":
        # Find prior instances: decisions this one appealed
        rows = conn.execute(
            """
            SELECT ct.target_decision_id, MAX(ct.confidence_score) AS confidence_score,
                   d.docket_number, d.court, d.canton, d.decision_date
            FROM decision_citations dc
            JOIN citation_targets ct
              ON ct.source_decision_id = dc.source_decision_id
             AND ct.target_ref = dc.target_ref
            JOIN decisions d
              ON d.decision_id = ct.target_decision_id
            WHERE dc.source_decision_id = ?
              AND dc.is_prior_instance = 1
              AND ct.confidence_score >= ?
            GROUP BY ct.target_decision_id
            ORDER BY confidence_score DESC
            LIMIT 5
            """,
            (decision_id, min_confidence),
        ).fetchall()

        for row in rows:
            target_id = row["target_decision_id"]
            if target_id in visited:
                continue
            chain.append({
                "decision_id": target_id,
                "docket_number": row["docket_number"],
                "court": row["court"],
                "canton": row["canton"],
                "decision_date": row["decision_date"],
                "confidence": round(float(row["confidence_score"]), 3),
                "relation": "prior_instance",
                "appealed_by": decision_id,
            })
            # Recurse down
            _walk_chain(conn, target_id, "down", chain, min_confidence, visited, depth + 1)

    elif direction == "up":
        # Find subsequent instances: decisions that appealed this one
        rows = conn.execute(
            """
            SELECT dc.source_decision_id, MAX(ct.confidence_score) AS confidence_score,
                   d.docket_number, d.court, d.canton, d.decision_date
            FROM decision_citations dc
            JOIN citation_targets ct
              ON ct.source_decision_id = dc.source_decision_id
             AND ct.target_ref = dc.target_ref
            JOIN decisions d
              ON d.decision_id = dc.source_decision_id
            WHERE ct.target_decision_id = ?
              AND dc.is_prior_instance = 1
              AND ct.confidence_score >= ?
            GROUP BY dc.source_decision_id
            ORDER BY d.decision_date ASC
            LIMIT 5
            """,
            (decision_id, min_confidence),
        ).fetchall()

        for row in rows:
            source_id = row["source_decision_id"]
            if source_id in visited:
                continue
            chain.append({
                "decision_id": source_id,
                "docket_number": row["docket_number"],
                "court": row["court"],
                "canton": row["canton"],
                "decision_date": row["decision_date"],
                "confidence": round(float(row["confidence_score"]), 3),
                "relation": "subsequent_instance",
                "appeals": decision_id,
            })
            # Recurse up
            _walk_chain(conn, source_id, "up", chain, min_confidence, visited, depth + 1)


def _text_matches_any_statute_hint(text: str, statutes: set[str]) -> bool:
    for ref in statutes:
        article, paragraph, law = _parse_statute_ref(ref)
        if not article or not law:
            continue
        hints = [
            f"art {article} {law.lower()}",
            f"{article} {law.lower()}",
        ]
        if paragraph:
            hints.extend(
                [
                    f"abs {paragraph}",
                    f"al {paragraph}",
                    f"cpv {paragraph}",
                    f"co {paragraph}",
                    f"alin {paragraph}",
                ]
            )
        if any(hint in text for hint in hints):
            return True
    return False


def _parse_statute_ref(ref: str) -> tuple[str | None, str | None, str | None]:
    m = re.match(
        (
            r"^ART\."
            r"(?P<article>\d+(?:bis|ter|quater|quinquies|sexies|[a-z])?)"
            r"(?:\.ABS\.(?P<paragraph>\d+(?:bis|ter|quater|quinquies|sexies|[a-z])?))?"
            r"\.(?P<law>[A-Z0-9/]+)$"
        ),
        ref,
    )
    if not m:
        return None, None, None
    return m.group("article"), m.group("paragraph"), m.group("law")


def _text_matches_any_citation_hint(text: str, citations: set[str]) -> bool:
    for ref in citations:
        ref_text = ref.lower().replace("_", " ")
        if ref_text and ref_text in text:
            return True
    return False


def _rerank_rows(
    rows: list[sqlite3.Row],
    raw_query: str,
    limit: int,
    *,
    fusion_scores: dict[str, dict] | None = None,
    vector_scores: dict[str, float] | None = None,
    sparse_scores: dict[str, float] | None = None,
    offset: int = 0,
    sort: str | None = None,
    is_docket_query: bool = False,
    deadline: float | None = None,
    signal_sink: dict | None = None,
) -> list[dict]:
    """
    Re-rank lexical FTS candidates with lightweight query-intent signals.

    The FTS index provides robust candidate retrieval; this stage improves top-k
    quality for practitioner-style natural-language and docket-centric queries.

    `signal_sink`, when given, receives {decision_id: {signal: weighted
    contribution}} for every scored candidate. Until 2026-08-19 the ~20
    per-row signals were collapsed to one scalar and discarded, so the
    hand-set SCORING_CONFIG weights could not be tuned against evidence —
    there was no record of which signal fired on which query.
    """
    if not rows:
        return []

    fusion_scores = fusion_scores or {}
    rank_terms = _extract_rank_terms(raw_query)
    expanded_rank_terms = _expand_rank_terms_for_match(rank_terms)
    all_rank_terms = set(rank_terms) | set(expanded_rank_terms)
    query_has_asyl_signal = any(t in ASYL_QUERY_TERMS for t in rank_terms)
    query_has_decision_intent = any(t in DECISION_INTENT_TERMS for t in rank_terms)
    query_has_accelerated_signal = any(
        t in ACCELERATED_PROCEDURE_TERMS or t.startswith("beschleunig")
        for t in all_rank_terms
    )
    query_languages = set(_detect_query_languages(raw_query))
    cleaned_phrase = _normalize_text_for_match(_clean_for_phrase(raw_query))
    query_norm = _normalize_docket(raw_query)
    query_statutes = _extract_query_statute_refs(raw_query)
    query_citations = _extract_query_citation_refs(raw_query)
    graph_signals = _load_graph_signal_map(
        [r["decision_id"] for r in rows],
        query_statutes=query_statutes,
        query_citations=query_citations,
    )

    scored: list[tuple[float, float, int, sqlite3.Row]] = []
    for idx, row in enumerate(rows):
        decision_id = row["decision_id"]
        bm25_score = _to_float(row["bm25_score"])
        bm25_component = -bm25_score

        title_text = _normalize_text_for_match(row["title"])
        regeste_text = _normalize_text_for_match(row["regeste"])
        snippet_text = _normalize_text_for_match(row["snippet"])
        docket_text = (row["docket_number"] or "").lower()
        docket_norm = _normalize_docket(docket_text)

        if rank_terms:
            title_cov = _term_coverage(rank_terms, title_text)
            regeste_cov = _term_coverage(rank_terms, regeste_text)
            snippet_cov = _term_coverage(rank_terms, snippet_text)
        else:
            title_cov = regeste_cov = snippet_cov = 0.0
        if expanded_rank_terms:
            expanded_title_cov = _term_coverage(expanded_rank_terms, title_text)
            expanded_regeste_cov = _term_coverage(expanded_rank_terms, regeste_text)
        else:
            expanded_title_cov = expanded_regeste_cov = 0.0

        phrase_hit = 0.0
        if cleaned_phrase:
            if cleaned_phrase in title_text or cleaned_phrase in regeste_text:
                phrase_hit += 1.0
            if cleaned_phrase in snippet_text:
                phrase_hit += 0.5

        docket_exact = 1.0 if query_norm and docket_norm and query_norm == docket_norm else 0.0
        docket_partial = 0.0
        if query_norm and docket_norm and not docket_exact:
            if len(query_norm) >= 5 and query_norm in docket_norm:
                docket_partial = 1.0

        fusion = fusion_scores.get(decision_id, {})
        rrf_score = float(fusion.get("rrf_score", 0.0))
        strategy_hits = int(fusion.get("strategy_hits", 0))

        graph = graph_signals.get(decision_id, {})
        statute_mentions = float(graph.get("statute_mentions", 0.0))
        query_citation_hits = float(graph.get("query_citation_hits", 0.0))
        incoming_citations = float(graph.get("incoming_citations", 0.0))

        statute_signal = 0.0
        citation_signal = 0.0
        authority_signal = 0.0
        if query_statutes and statute_mentions > 0:
            statute_signal = SCORING_CONFIG["statute_signal_base"] + min(
                SCORING_CONFIG["statute_signal_cap"],
                SCORING_CONFIG["statute_signal_per_mention"] * statute_mentions,
            )
        if query_citations and query_citation_hits > 0:
            citation_signal = SCORING_CONFIG["citation_signal_base"] + min(
                SCORING_CONFIG["citation_signal_cap"],
                SCORING_CONFIG["citation_signal_per_hit"] * query_citation_hits,
            )
        if incoming_citations > 0:
            authority_signal = min(
                SCORING_CONFIG["authority_signal_cap"],
                incoming_citations * SCORING_CONFIG["authority_signal_per_citation"],
            )
        in_pool_citations = float(graph.get("in_pool_citations", 0.0))
        in_pool_signal = 0.0
        if in_pool_citations >= SCORING_CONFIG["in_pool_min_citations"]:
            in_pool_signal = min(
                SCORING_CONFIG["in_pool_signal_cap"],
                SCORING_CONFIG["in_pool_signal_multiplier"] * math.log2(in_pool_citations),
            )

        local_ref_signal = 0.0
        local_text = f"{title_text} {regeste_text} {snippet_text}"
        if query_statutes and _text_matches_any_statute_hint(local_text, query_statutes):
            local_ref_signal += SCORING_CONFIG["local_statute_match_signal"]
        if query_citations and _text_matches_any_citation_hint(local_text, query_citations):
            local_ref_signal += SCORING_CONFIG["local_citation_match_signal"]

        court_prior_signal = 0.0
        if query_has_asyl_signal:
            court = (row["court"] or "").lower()
            docket = (row["docket_number"] or "")
            if court == "bvger":
                court_prior_signal += SCORING_CONFIG["asylum_bvger_boost"]
            if court == "bger":
                court_prior_signal += SCORING_CONFIG["asylum_bger_penalty"]
            if docket.upper().startswith("E-"):
                court_prior_signal += SCORING_CONFIG["asylum_e_docket_boost"]

        court_intent_signal = 0.0
        if query_has_decision_intent:
            court = (row["court"] or "").lower()
            if court in HIGH_COURTS:
                court_intent_signal += SCORING_CONFIG["decision_intent_boost"]

        procedure_signal = 0.0
        if query_has_asyl_signal and query_has_accelerated_signal:
            if any(term in local_text for term in ACCELERATED_PROCEDURE_TERMS):
                procedure_signal += SCORING_CONFIG["accelerated_procedure_signal"]

        language_signal = 0.0
        row_language = (row["language"] or "").lower()
        if query_languages and row_language in query_languages:
            language_signal += SCORING_CONFIG["language_match_signal"]

        # BGE/BGer authority boost — disabled, log-authority already handles this
        court_authority_boost = 0.0

        # Vector similarity signal
        vector_signal = 0.0
        if vector_scores:
            vec_dist = vector_scores.get(decision_id)
            if vec_dist is not None:
                vector_signal = VECTOR_SIGNAL_WEIGHT * max(0.0, 1.0 - vec_dist)

        # Sparse (learned lexical) signal
        sparse_signal = 0.0
        if sparse_scores:
            sp_score = sparse_scores.get(decision_id)
            if sp_score is not None:
                # Normalize: cap at reasonable max and scale
                max_sparse = max(sparse_scores.values()) if sparse_scores else 1.0
                sparse_signal = SPARSE_SIGNAL_WEIGHT * min(1.0, sp_score / max(max_sparse, 0.01))

        signal = (
            SCORING_CONFIG["w_docket_exact"] * docket_exact
            + SCORING_CONFIG["w_docket_partial"] * docket_partial
            + SCORING_CONFIG["w_title_cov"] * title_cov
            + SCORING_CONFIG["w_regeste_cov"] * regeste_cov
            + SCORING_CONFIG["w_snippet_cov"] * snippet_cov
            + SCORING_CONFIG["w_expanded_regeste_cov"] * expanded_regeste_cov
            + SCORING_CONFIG["w_expanded_title_cov"] * expanded_title_cov
            + SCORING_CONFIG["w_phrase_hit"] * phrase_hit
            + SCORING_CONFIG["w_rrf_score"] * rrf_score
            + SCORING_CONFIG["w_strategy_hits"] * min(strategy_hits, int(SCORING_CONFIG["strategy_hits_cap"]))
            + statute_signal
            + citation_signal
            + authority_signal
            + in_pool_signal
            + local_ref_signal
            + court_prior_signal
            + court_intent_signal
            + court_authority_boost
            + procedure_signal
            + language_signal
            + vector_signal
            + sparse_signal
        )
        final_score = bm25_component + signal

        if signal_sink is not None:
            # The weighted CONTRIBUTIONS, not the raw features: what the
            # tuner needs is how much each term actually moved this row
            # under the current weights. ~20 floats per candidate; the
            # caller keeps only the top-k after ranking.
            signal_sink[decision_id] = {
                "bm25": round(bm25_component, 4),
                "docket_exact": round(SCORING_CONFIG["w_docket_exact"] * docket_exact, 4),
                "docket_partial": round(SCORING_CONFIG["w_docket_partial"] * docket_partial, 4),
                "title_cov": round(SCORING_CONFIG["w_title_cov"] * title_cov, 4),
                "regeste_cov": round(SCORING_CONFIG["w_regeste_cov"] * regeste_cov, 4),
                "snippet_cov": round(SCORING_CONFIG["w_snippet_cov"] * snippet_cov, 4),
                "expanded_regeste_cov": round(SCORING_CONFIG["w_expanded_regeste_cov"] * expanded_regeste_cov, 4),
                "expanded_title_cov": round(SCORING_CONFIG["w_expanded_title_cov"] * expanded_title_cov, 4),
                "phrase_hit": round(SCORING_CONFIG["w_phrase_hit"] * phrase_hit, 4),
                "rrf": round(SCORING_CONFIG["w_rrf_score"] * rrf_score, 4),
                "strategy_hits": round(SCORING_CONFIG["w_strategy_hits"] * min(strategy_hits, int(SCORING_CONFIG["strategy_hits_cap"])), 4),
                "statute": round(statute_signal, 4),
                "citation": round(citation_signal, 4),
                "authority": round(authority_signal, 4),
                "in_pool": round(in_pool_signal, 4),
                "local_ref": round(local_ref_signal, 4),
                "court_prior": round(court_prior_signal, 4),
                "court_intent": round(court_intent_signal, 4),
                "court_authority": round(court_authority_boost, 4),
                "procedure": round(procedure_signal, 4),
                "language": round(language_signal, 4),
                "vector": round(vector_signal, 4),
                "sparse": round(sparse_signal, 4),
                "final": round(final_score, 4),
            }

        scored.append((final_score, bm25_score, idx, row))

    # Both rerank passes exist to refine RELEVANCE order. Under an explicit
    # date sort their entire output is overwritten by the re-sort below, so a
    # date-sorted search was paying a ~3 s synchronous Haiku round-trip for a
    # score boost that was provably discarded (integration evaluation latency audit).
    if sort not in ("date_desc", "date_asc"):
        scored = _apply_cross_encoder_boosts(scored, raw_query, deadline=deadline)
        scored = _apply_llm_rerank(scored, raw_query, is_docket_query=is_docket_query, deadline=deadline)
    scored.sort(key=lambda x: (-x[0], x[1], x[2]))

    # Apply user-requested sort order (overrides relevance ranking)
    if sort in ("date_desc", "date_asc"):
        reverse = sort == "date_desc"
        scored.sort(key=lambda x: (x[3]["decision_date"] or ""), reverse=reverse)

    # ── Enrich results with graph + metadata ──
    # Deduplicate BEFORE paginating (#77). The caller ran
    # _dedupe_results_by_decision_id on the already-sliced page, so canonical
    # twins were removed from the page instead of from the ranking: limit=50
    # delivered 49 rows, limit=200 delivered 192, while thousands of further
    # candidates waited behind the cut. That also broke the documented
    # completeness contract (`showing < limit` => "all results returned"),
    # because a short page is indistinguishable from exhaustion. Collapsing
    # the ranking first makes offset address a stable, duplicate-free list and
    # restores exactly min(limit, remaining) rows.
    # Three collapse rules apply downstream, so all three must apply HERE or
    # the page shrinks again after it is cut: decision_id and canonical key
    # (_dedupe_results_by_decision_id), plus the handler's dateless
    # court|docket key that folds the BGE dual-ID formats
    # ('bge_125 III 231' vs 'bge_BGE_125_III_231').
    _seen_ids: set[str] = set()
    _seen_keys: set[str] = set()
    _seen_dockets: set[str] = set()
    _deduped: list = []
    for _entry in scored:
        _row = _entry[3]
        _did = _row["decision_id"]
        if _did in _seen_ids:
            continue
        _court = _row_get(_row, "court") or ""
        _docket = _row_get(_row, "docket_number") or ""
        _ckey = _make_canonical_key(_court, _docket,
                                    _row_get(_row, "decision_date"))
        # Empty-docket keys (court||date) collide across unrelated decisions;
        # the id check alone governs them. Predicate copied verbatim from
        # _dedupe_results_by_decision_id so the two paths cannot diverge.
        if _ckey and "||" not in _ckey and _ckey in _seen_keys:
            continue
        # Handler key, copied verbatim from the search_decisions renderer.
        _dn = re.sub(r"[^A-Z0-9]", "", _docket.upper())
        if _court == "bge":
            _dn = re.sub(r"^(?:CH)?(?:BGE|ATF|DTF)", "", _dn)
        _dkey = f"{_court}|{_dn}"
        if _dn and _dkey in _seen_dockets:
            continue
        _seen_ids.add(_did)
        if _ckey and "||" not in _ckey:
            _seen_keys.add(_ckey)
        if _dn:
            _seen_dockets.add(_dkey)
        _deduped.append(_entry)
    scored = _deduped
    result_slice = scored[offset:offset + limit]
    result_ids = [row["decision_id"] for _, _, _, row in result_slice]
    statutes_by_id = _batch_fetch_statutes(result_ids, limit_per=8)

    results: list[dict] = []
    for final_score, _bm25, _idx, row in result_slice:
        full_text = _row_get(row, "full_text_raw")
        best_snippet = _select_best_passage_snippet(
            full_text,
            rank_terms=rank_terms,
            phrase=cleaned_phrase,
            raw_query=raw_query,
            fallback=row["snippet"],
        )
        did = row["decision_id"]
        court = row["court"] or ""

        # Graph signals
        graph = graph_signals.get(did, {})
        incoming = int(graph.get("incoming_citations", 0))
        in_pool = int(graph.get("in_pool_citations", 0))

        # Statute references from graph
        statutes = statutes_by_id.get(did, [])

        # Court metadata
        court_level = _get_court_level(court)
        is_federal = court_level.startswith("federal")
        threshold = LEADING_CASE_THRESHOLD_FEDERAL if is_federal else LEADING_CASE_THRESHOLD_CANTONAL

        result = {
            "decision_id": did,
            "court": court,
            "court_name": _get_court_display_name(court),
            "court_level": court_level,
            "canton": row["canton"],
            "chamber": row["chamber"],
            "docket_number": row["docket_number"],
            "decision_date": row["decision_date"],
            "language": row["language"],
            "title": row["title"],
            "regeste": _truncate(
                _pick_regeste(row, next(iter(query_languages), "de")),
                MAX_SNIPPET_LEN,
            ),
            "snippet": best_snippet,
            "source_url": row["source_url"],
            "pdf_url": row["pdf_url"],
            "relevance_score": round(final_score, 4),
        }
        # Enrichment fields (only included when non-empty)
        if statutes:
            result["statutes"] = statutes
        legal_area = _derive_legal_area(statutes, court)
        if legal_area:
            result["legal_area"] = legal_area
        if incoming > 0:
            result["citation_count"] = incoming
        if in_pool > 0:
            result["cited_by_results"] = in_pool
        if incoming >= threshold:
            result["is_leading_case"] = True
        results.append(result)
    return results


def _analyze_query(
    fts_query: str,
    is_docket_query: bool,
    *,
    original_query: str | None = None,
    force_natural_language: bool = False,
) -> tuple[list, list, dict]:
    """Run the two independent query-analysis Haiku calls CONCURRENTLY: query
    expansion (inside _build_query_strategies) and the structured parse. Both are
    ~2s round-trips on the same query, so overlapping them saves ~2s — with
    identical results to the former sequential path (quality-neutral, not MRR-
    affecting). Parse is skipped for docket queries, as before."""
    _box: dict = {}

    def _run_parse():
        try:
            # Skip the structured (Haiku) parse for docket lookups AND for pure
            # quoted phrases: for a phrase, the parse's doctrine/synonym terms get
            # injected as broad OR strategies downstream, which would reintroduce
            # the exact non-phrase false positives the phrase MATCH is meant to
            # avoid (#42). Keep the phrase exact end to end.
            skip = is_docket_query or _is_pure_phrase_query(fts_query)
            _box["parse"] = {} if skip else _parse_query_structured(fts_query)
            # An empty dict can now mean three different things; say which,
            # because a parse FAILURE was indistinguishable from a query
            # that never warranted a parse, so the failure rate was
            # unknowable (audit 2026-08-19). "empty" = the model ran and
            # found no legal structure.
            _box["parse_outcome"] = ("skipped" if skip
                                     else "ok" if _box["parse"] else "empty")
        except Exception:
            _box["parse"] = {}
            _box["parse_outcome"] = "failed"

    _t = threading.Thread(target=_run_parse, daemon=True)
    _t.start()
    strategies, llm_terms = _build_query_strategies(
        fts_query,
        original_query=original_query,
        force_natural_language=force_natural_language,
    )
    _t.join(timeout=LLM_EXPANSION_TIMEOUT + 3.0)
    # Thread still alive after the join timeout = the parse is hanging;
    # for the caller that is a failure, not an empty result.
    if "parse_outcome" not in _box:
        _box["parse_outcome"] = "timeout"
    return strategies, llm_terms, _box.get("parse", {}), _box["parse_outcome"]


def _build_query_strategies(
    raw_query: str,
    *,
    original_query: str | None = None,
    force_natural_language: bool = False,
) -> tuple[list[dict], list[str]]:
    """
    Build parser-safe FTS query strategies.

    For explicit FTS syntax, preserve raw query first.
    For natural language, prefer tokenized OR query first for robustness.

    `raw_query` is the SANITIZED text (executed against FTS5); explicit-syntax
    detection uses `original_query` when supplied, because sanitisation itself
    injects operator look-alikes ('Art. 335 OR' → 'Art 335 "OR"').
    `force_natural_language` pins the NL strategy set — used for auto-condensed
    document queries, which are NL by construction.

    Returns (strategies, llm_terms) where llm_terms are the raw LLM expansion
    terms (for use in vector search augmentation).
    """
    raw = raw_query.strip()
    # #42: a pure quoted phrase must stay an exact phrase MATCH. The OR/expansion
    # strategies below would decompose "Treu und Glauben" into a term-alternation
    # (matching "Glauben" alone → ~92% false positives). Run ONLY the phrase MATCH
    # and its field-focused boosts, all of which keep the phrase intact; no LLM
    # expansion. FTS5 phrase MATCH already enforces token adjacency, so this is
    # exact without a post-filter (which would break `NOT "phrase"` and, on the
    # bounded candidate pool, drop verbatim matches ranked below the cap).
    if _is_pure_phrase_query(raw):
        # Only the phrase MATCH over the full index. bm25 column weights already
        # rank regeste/title hits above body-only hits, so no field-focus (which
        # AND-combines tokens and would lose the phrase's adjacency) is needed.
        return ([{"name": "raw", "query": raw, "weight": SCORING_CONFIG["sw_raw"]}], [])
    if force_natural_language:
        has_explicit_syntax = False
    else:
        has_explicit_syntax = _has_explicit_fts_syntax(
            original_query if original_query is not None else raw)
    nl_and = _build_nl_and_query(raw)
    nl_or = _build_nl_or_query(raw, include_expansions=False)
    nl_or_expanded = _build_nl_or_query(raw, include_expansions=True)
    anchor_focus = _build_anchor_pair_strategies(raw)
    regeste_focus = _build_field_focus_query(raw, field="regeste")
    title_focus = _build_field_focus_query(raw, field="title")
    detected_languages = _detect_query_languages(raw)
    language_focus = _build_language_focus_strategies(
        raw,
        detected_languages=detected_languages,
        has_explicit_syntax=has_explicit_syntax,
    )
    cleaned = _clean_for_phrase(raw)
    quoted = f'"{cleaned}"' if cleaned else ""

    if has_explicit_syntax:
        # The raw strategy must carry the user's OPERATORS, not the sanitised
        # text: _sanitize_fts5 quotes even operand-flanked OR (right for
        # natural language — the Obligationenrecht — wrong once the user
        # wrote boolean syntax), so 'Mietzins OR Pachtzins' executed as three
        # required tokens and returned FEWER hits than either operand (52 vs
        # 2000/568, caught 2026-08-23 while verifying the /search/
        # capabilities panel). _explicit_laws_match is the corpus-agnostic
        # raw→safe-explicit transform built for exactly this (#60); fall back
        # to the sanitised form when it yields nothing.
        explicit_raw = _explicit_laws_match(
            original_query if original_query is not None else raw) or raw
        candidates = [
            {"name": "raw", "query": explicit_raw, "weight": SCORING_CONFIG["sw_raw"]},
            {"name": "quoted", "query": quoted, "weight": SCORING_CONFIG["sw_quoted_explicit"]},
            {"name": "regeste_focus", "query": regeste_focus, "weight": SCORING_CONFIG["sw_regeste_focus_explicit"]},
            {"name": "title_focus", "query": title_focus, "weight": SCORING_CONFIG["sw_title_focus_explicit"]},
            *anchor_focus,
            *language_focus,
            {"name": "nl_and", "query": nl_and, "weight": SCORING_CONFIG["sw_nl_and_explicit"]},
            {"name": "nl_or", "query": nl_or, "weight": SCORING_CONFIG["sw_nl_or_explicit"]},
        ]
    else:
        candidates = [
            *anchor_focus,
            {"name": "nl_and", "query": nl_and, "weight": SCORING_CONFIG["sw_nl_and"]},
            {"name": "regeste_focus", "query": regeste_focus, "weight": SCORING_CONFIG["sw_regeste_focus"]},
            {"name": "title_focus", "query": title_focus, "weight": SCORING_CONFIG["sw_title_focus"]},
            *language_focus,
            {"name": "quoted", "query": quoted, "weight": SCORING_CONFIG["sw_quoted"]},
            {"name": "nl_or", "query": nl_or, "weight": SCORING_CONFIG["sw_nl_or"]},
            {"name": "nl_or_expanded", "query": nl_or_expanded, "weight": SCORING_CONFIG["sw_nl_or_expanded"]},
        ]
        if _should_try_raw_fallback(raw):
            candidates.append({"name": "raw_fallback", "query": raw, "weight": 0.65})
        # Statute-citing NL queries ('Art. 261 OR Veräusserung …') ran as
        # explicit syntax before the sanitize-then-detect fix — misclassified,
        # but the raw strategy that ordering runs FIRST was carrying real
        # ranking signal (all query tokens ANDed, statute tokens included).
        # Keep that signal as a superset: full NL set above (vector rescue,
        # expansions) PLUS the raw strategy at explicit weight. RRF fusion
        # blends both. Not force_natural_language: condensed documents are
        # too long for a useful implicit-AND raw MATCH.
        elif (
            not force_natural_language
            and original_query is not None
            and QUERY_STATUTE_PATTERN.search(original_query)
            and not any(c["name"] == "raw" for c in candidates)
        ):
            candidates.insert(
                0, {"name": "raw", "query": raw, "weight": SCORING_CONFIG["sw_raw"]})

    # LLM expansion: fetch additional terms (runs in thread via asyncio.to_thread)
    llm_terms = _expand_query_with_llm(raw)
    if llm_terms:
        llm_or_parts: list[str] = []
        for term in llm_terms:
            words = term.strip().split()
            if len(words) == 1:
                norm = _normalize_token_for_fts(term)
                if norm:
                    llm_or_parts.append(norm)
            else:
                # Multi-word: normalize each word, join as quoted phrase
                normed = [
                    _normalize_token_for_fts(w)
                    for w in words if _normalize_token_for_fts(w)
                ]
                if len(normed) >= 2:
                    llm_or_parts.append(f'"{" ".join(normed)}"')
                elif normed:
                    llm_or_parts.append(normed[0])
        if llm_or_parts:
            llm_or_query = " OR ".join(llm_or_parts)
            candidates.append({"name": "llm_expanded", "query": llm_or_query, "weight": 0.9})

    # Dedupe while preserving order
    seen: set[str] = set()
    strategies: list[dict] = []
    for candidate in candidates:
        q = (candidate.get("query") or "").strip()
        if q and q not in seen:
            strategies.append({
                "name": candidate.get("name", "query"),
                "query": q,
                "weight": float(candidate.get("weight", 1.0)),
            })
            seen.add(q)
    return strategies, llm_terms


# GitHub #88. "OR" is both the FTS5 disjunction operator and the standard Swiss
# abbreviation for the Obligationenrecht, so the collision is unavoidable in
# ordinary use rather than a corner case. QUERY_STATUTE_PATTERN masks only the
# fully written form ("Art. 41 OR"); practitioners also write "OR 60" and
# "Verjährung OR 60", where OR sits directly against a bare article number.
# Reported case: search_laws("Verjährung OR 60") evaluated a disjunction and
# returned five articles numbered 60 from unrelated acts, none from SR 220.
_ARTICLE_SHAPED = re.compile(
    r"\d{1,3}(?:bis|ter|quater|quinquies|sexies|septies|octies|novies|decies|[a-z])?",
    re.IGNORECASE,
)


def _mask_or_as_statute(text: str) -> str:
    """Mask an "OR" that reads as the Obligationenrecht, not as an operator.

    Masks only when exactly ONE side is article-shaped. Requiring the asymmetry
    is what keeps a genuine numeric disjunction working: "2020 OR 2021" has a
    number on both sides and stays an operator, while "Verjährung OR 60" has one
    and is a statute reference. Uppercase-only, mirroring the operator test.
    """
    def _repl(m: "re.Match") -> str:
        left, right = m.group("l"), m.group("r")
        if bool(_ARTICLE_SHAPED.fullmatch(left)) == bool(
                _ARTICLE_SHAPED.fullmatch(right)):
            return m.group(0)
        return f"{left} __STATUTE__ {right}"

    return re.sub(r"(?P<l>\S+)\s+OR\s+(?P<r>\S+)", _repl, text)


def _has_explicit_fts_syntax(query: str) -> bool:
    """Detect advanced query syntax where raw execution should be prioritized.

    MUST be called on the ORIGINAL user query, never on _sanitize_fts5 output:
    the sanitizer strips the dot from 'Art.' and quotes bare 'OR' as '"OR"',
    which (a) defeats the statute mask below and (b) trips the quote-count
    branch — so every query citing '… OR' was misclassified as operator syntax,
    which disabled the vector/semantic rescue (integration evaluation audit 2026-07).
    """
    # Mask statute references so "Art. 41 OR" (Obligationenrecht) doesn't
    # trigger FTS-operator detection for "OR".
    masked = QUERY_STATUTE_PATTERN.sub("__STATUTE__", query)
    # …and the abbreviated forms the pattern above cannot see (#88).
    masked = _mask_or_as_statute(masked)
    # OR counts as an operator only with operands on BOTH sides (mirrors the
    # sanitizer's rule for AND/NOT/NEAR): 'Miete OR Pacht' is syntax, a bare
    # trailing 'Obligationenrecht OR' is the statute abbreviation. AND/NOT/NEAR
    # keep the loose word-boundary test — they have no legal-homonym problem.
    if re.search(r"\b(AND|NOT|NEAR)\b", masked, re.IGNORECASE):
        return True
    if re.search(r"(?<![\w\"])\S+\s+OR\s+\S+", masked):
        return True
    if "*" in query:
        return True
    if re.search(rf"\b(?:{'|'.join(sorted(FTS_COLUMNS))})\s*:", query, re.IGNORECASE):
        return True
    # Balanced quoted phrase usually indicates intentional syntax.
    if query.count('"') >= 2 and query.count('"') % 2 == 0:
        return True
    return False


def _query_has_numeric_terms(query: str) -> bool:
    tokens = re.findall(r"[0-9A-Za-zÀ-ÖØ-öø-ÿ_]+", query or "")
    return any(tok.isdigit() for tok in tokens)


def _clean_for_phrase(query: str) -> str:
    """Normalize punctuation/quotes for safe phrase fallback."""
    terms = _extract_query_terms(
        query,
        limit=MAX_NL_TOKENS,
        include_variants=False,
        include_expansions=False,
    )
    return " ".join(terms)


def _build_nl_or_query(query: str, *, include_expansions: bool) -> str:
    """Tokenize natural-language input into a robust OR-based FTS query."""
    terms = _extract_query_terms(
        query,
        limit=MAX_NL_TOKENS,
        include_variants=True,
        include_expansions=include_expansions,
    )
    return " OR ".join(terms)


def _build_nl_and_query(query: str) -> str:
    """Tokenize natural-language input into a stricter AND query."""
    keep = _extract_query_terms(
        query,
        limit=NL_AND_TERM_LIMIT,
        include_variants=False,
        include_expansions=False,
    )

    if len(keep) < 2:
        return ""
    return " AND ".join(keep)


def _build_anchor_pair_strategies(query: str) -> list[dict]:
    terms = _extract_query_terms(
        query,
        limit=MAX_NL_TOKENS,
        include_variants=False,
        include_expansions=False,
    )
    if len(terms) < 2:
        return []

    pairs = _pick_anchor_pairs(terms)
    if not pairs:
        return []

    out: list[dict] = []
    for idx, (left, right) in enumerate(pairs, start=1):
        out.append({
            "name": f"anchor_pair_{idx}",
            "query": f"{left} AND {right}",
            "weight": 1.2 if idx == 1 else 1.0,
        })
        if len(left) >= 4 and len(right) >= 4:
            out.append({
                "name": f"anchor_phrase_{idx}",
                "query": f'"{left} {right}"',
                "weight": 0.85,
            })
    return out


def _pick_anchor_pairs(terms: list[str]) -> list[tuple[str, str]]:
    term_set = set(terms)
    out: list[tuple[str, str]] = []

    for left, right in LEGAL_ANCHOR_PAIRS:
        if left in term_set and right in term_set:
            out.append((left, right))
            if len(out) >= 2:
                return out

    return out[:2]


def _build_field_focus_query(query: str, *, field: str) -> str:
    terms = _extract_query_terms(
        query,
        limit=6,
        include_variants=False,
        include_expansions=False,
    )
    safe_terms = [
        t for t in terms
        if t and re.fullmatch(r"[a-z0-9_]+", t) and not t.isdigit()
    ]
    if len(safe_terms) < 2:
        return ""
    core = safe_terms[:2]
    return " AND ".join(f"{field}:{_fts_prefix_term(term)}" for term in core)


def _build_language_focus_strategies(
    query: str,
    *,
    detected_languages: list[str],
    has_explicit_syntax: bool,
) -> list[dict]:
    out: list[dict] = []
    if not detected_languages:
        return out

    for lang in detected_languages[:2]:
        and_query = _build_language_focus_query(query, language=lang, mode="and")
        or_query = _build_language_focus_query(query, language=lang, mode="or")
        if and_query:
            out.append({"name": f"lang_{lang}_and", "query": and_query, "weight": 1.1})
        if or_query and not has_explicit_syntax:
            out.append({"name": f"lang_{lang}_or", "query": or_query, "weight": 0.8})
    return out


def _build_language_focus_query(query: str, *, language: str, mode: str) -> str:
    if mode == "and":
        base = _build_nl_and_query(query)
    else:
        base = _build_nl_or_query(query, include_expansions=False)
    if not base:
        return ""
    return f"language:{language} AND ({base})"


def _fts_prefix_term(term: str) -> str:
    # Prefix search improves recall for German compounds (e.g., asyl* -> Asylgesuch).
    if len(term) >= 4 and not term.endswith("*"):
        return f"{term}*"
    return term


def _detect_query_languages(query: str) -> list[str]:
    tokens = re.findall(r"[0-9A-Za-zÀ-ÖØ-öø-ÿ_]+", (query or "").lower())
    normalized = [_normalize_token_for_fts(t) for t in tokens]
    normalized = [t for t in normalized if t]
    if not normalized:
        return []

    scores: dict[str, int] = {lang: 0 for lang in LANGUAGE_HINT_TERMS}
    for tok in normalized:
        for lang, hints in LANGUAGE_HINT_TERMS.items():
            if tok in hints:
                scores[lang] += 2
    for tok in normalized:
        if tok in NL_STOPWORDS:
            continue
        if tok.endswith("tion") or tok.endswith("mente"):
            scores["fr"] += 1
            scores["it"] += 1
        if tok.endswith("ung") or tok.endswith("keit"):
            scores["de"] += 1

    ranked = sorted(scores.items(), key=lambda x: x[1], reverse=True)
    if not ranked or ranked[0][1] <= 0:
        return []

    top_score = ranked[0][1]
    out: list[str] = []
    for lang, score in ranked:
        if score <= 0:
            break
        if score >= max(1, top_score - 2):
            out.append(lang)
        if len(out) >= 2:
            break
    return out


def _extract_rank_terms(query: str) -> list[str]:
    """Extract deduplicated content-bearing terms for second-pass reranking."""
    tokens = re.findall(r"[0-9A-Za-zÀ-ÖØ-öø-ÿ_]+", query.lower())
    terms: list[str] = []
    seen: set[str] = set()
    for tok in tokens:
        if tok in NL_STOPWORDS:
            continue
        norm_tok = _normalize_token_for_match(tok)
        if not norm_tok:
            continue
        if norm_tok in FTS_COLUMNS:
            continue
        if norm_tok in {"and", "or", "not", "near"}:
            continue
        if not norm_tok.isdigit() and len(norm_tok) < 3:
            continue
        if norm_tok in seen:
            continue
        terms.append(norm_tok)
        seen.add(norm_tok)
        if len(terms) >= RERANK_TERM_LIMIT:
            break
    return terms


def _expand_rank_terms_for_match(terms: list[str]) -> list[str]:
    out: list[str] = []
    seen: set[str] = set(terms)
    for term in terms:
        for expansion in _get_query_expansions(term):
            normalized = _normalize_token_for_match(expansion)
            if not normalized:
                continue
            if normalized in seen:
                continue
            if not normalized.isdigit() and len(normalized) < 3:
                continue
            out.append(normalized)
            seen.add(normalized)
            if len(out) >= RERANK_TERM_LIMIT:
                return out
    return out


def _term_coverage(terms: list[str], text: str) -> float:
    """Fraction of query terms appearing in text."""
    if not terms:
        return 0.0
    hits = sum(1 for t in terms if t in text)
    return hits / len(terms)


def _target_candidate_pool(*, limit: int, offset: int = 0, is_docket: bool, has_explicit_syntax: bool) -> int:
    effective = offset + limit
    pool = max(MIN_CANDIDATE_POOL, effective * TARGET_POOL_MULTIPLIER)
    if has_explicit_syntax:
        pool = max(pool, effective * 2)
    if is_docket:
        pool = max(pool, DOCKET_MIN_CANDIDATE_POOL)
    return min(pool, MAX_RERANK_CANDIDATES)


def _should_try_raw_fallback(query: str) -> bool:
    # Raw queries with punctuation frequently trigger parser errors.
    return bool(re.fullmatch(r"[0-9A-Za-zÀ-ÖØ-öø-ÿ_\s]+", query))


def _query_has_expandable_terms(query: str) -> bool:
    terms = _extract_query_terms(
        query,
        limit=MAX_NL_TOKENS,
        include_variants=False,
        include_expansions=False,
    )
    return any(term in LEGAL_QUERY_EXPANSIONS for term in terms)


def _citation_ref_spans(query: str) -> list[tuple[int, int]]:
    """Character spans of statute / BGE / docket references in the query."""
    spans: list[tuple[int, int]] = []
    for pat in (QUERY_STATUTE_PATTERN, QUERY_BGE_PATTERN, *QUERY_DOCKET_PATTERNS):
        for mt in pat.finditer(query):
            spans.append(mt.span())
    return spans


def _rank_query_tokens(
    tokens: list[str],
    original_query: str,
) -> list[float]:
    """Informativeness score per token, aligned with `tokens`.

    No corpus IDF is available offline (an fts5vocab-based document-frequency
    lookup is the future refinement); this is a static proxy:

      +8  inside a statute / BGE / docket reference span — never dropped
      +4  contains a digit ('336' in 'Art. 336 OR' is genuinely selective)
      +3  known to the expansion tables (curated legal vocabulary)
      +2  decomposable German legal compound
      +2  appears capitalized mid-text in the original (German noun signal;
          sentence-initial noise accepted, hence the modest weight)
      +min(0.5·len, 7)  length
      +1 per repeat beyond the first, capped at +2 (letter topic words repeat)
      −0.01·first-position  stable tie-break toward earlier tokens
    """
    ref_spans = _citation_ref_spans(original_query)
    lower = original_query.lower()
    counts = collections.Counter(tokens)
    # capitalized-in-original: find each token's occurrences case-insensitively
    # and check whether any non-sentence-initial occurrence is capitalized.
    scores: list[float] = []
    seen_first: dict[str, int] = {}
    for pos, tok in enumerate(tokens):
        if tok not in seen_first:
            seen_first[tok] = pos
        s = 0.0
        idx = lower.find(tok)
        if idx >= 0 and any(a <= idx < b for a, b in ref_spans):
            s += 8.0
        if any(ch.isdigit() for ch in tok):
            s += 4.0
        if tok in LEGAL_QUERY_EXPANSIONS or _get_query_expansions(tok):
            s += 3.0
        if len(_decompose_compound(tok)) > 0:
            s += 2.0
        if idx > 0 and idx < len(original_query) and original_query[idx].isupper():
            s += 2.0
        s += min(0.5 * len(tok), 7.0)
        s += min(counts[tok] - 1, 2)
        s -= 0.01 * seen_first[tok]
        scores.append(s)
    return scores


def _condense_query(query: str) -> tuple[str, dict | None]:
    """Distill a pasted document into a searchable query.

    Citation references (statute / BGE / docket) are re-emitted VERBATIM
    first — they keep docket detection and the statute-graph rerank signals
    alive. The remainder is ranked by _rank_query_tokens with letter
    boilerplate stripped, top QUERY_CONDENSE_TERMS kept, first-occurrence
    order. The output is plain natural language (no operators), so callers
    pair it with force_natural_language=True.

    Returns (condensed_query, info) where info carries refs/terms/
    original_chars for disclosure, or (query, None) when condensation
    is impossible (pathological input).
    """
    original = query or ""
    refs: list[str] = []
    ref_spans: list[tuple[int, int]] = []
    for pat in (QUERY_STATUTE_PATTERN, QUERY_BGE_PATTERN, *QUERY_DOCKET_PATTERNS):
        for mt in pat.finditer(original):
            frag = " ".join(mt.group(0).split())
            if frag not in refs and len(refs) < 4:
                refs.append(frag)
                ref_spans.append(mt.span())

    # Tokenize the remainder (ref spans excluded so 'Art'/'336'/'OR' don't
    # re-enter as loose terms).
    remainder_chars = []
    last = 0
    for a, b in sorted(ref_spans):
        remainder_chars.append(original[last:a])
        last = b
    remainder_chars.append(original[last:])
    remainder = " ".join(remainder_chars)

    toks: list[str] = []
    for tok in re.findall(r"[0-9A-Za-zÀ-ÖØ-öø-ÿ_]+", remainder):
        low = tok.lower()
        if low in NL_STOPWORDS or low in LETTER_BOILERPLATE_STOPWORDS:
            continue
        if low in {"and", "or", "not", "near"}:
            continue  # operator homonyms must not survive into the query
        if not low.isdigit() and len(low) < 3:
            continue
        toks.append(tok)

    terms: list[str] = []
    if toks:
        lows = [t.lower() for t in toks]
        scores = _rank_query_tokens(lows, original)
        first_pos: dict[str, int] = {}
        for i, t in enumerate(lows):
            first_pos.setdefault(t, i)
        chosen: set[str] = set()
        for i in sorted(range(len(lows)), key=lambda i: -scores[i]):
            chosen.add(lows[i])
            if len(chosen) >= QUERY_CONDENSE_TERMS:
                break
        terms = sorted(chosen, key=lambda t: first_pos[t])

    if not refs and not terms:
        # Fallback: first 16 non-stopword tokens; if even that fails, a
        # bounded prefix — never the whole document.
        fallback = toks[:16]
        if fallback:
            terms = [t.lower() for t in fallback]
        else:
            return original[:200], {
                "refs": [], "terms": [], "original_chars": len(original)}

    condensed = " ".join(refs + terms)
    return condensed, {
        "refs": refs, "terms": terms, "original_chars": len(original)}


def _extract_query_terms(
    query: str,
    *,
    limit: int,
    include_variants: bool,
    include_expansions: bool,
) -> list[str]:
    """Extract deduplicated FTS-safe terms from a natural-language query.

    Selection is informativeness-ranked when the query carries more base
    tokens than `limit` — previously the cut was strictly positional, so a
    pasted letter's salutation consumed the budget and the legal content at
    later legal terms were never searched during integration evaluation.
    When the base tokens fit the limit, the original loop runs unchanged and
    the output is byte-identical.
    """
    # First pass: base tokens surviving the existing filters, in order.
    base: list[str] = []
    for tok in re.findall(r"[0-9A-Za-zÀ-ÖØ-öø-ÿ_]+", query.lower()):
        if tok in NL_STOPWORDS:
            continue
        normalized = _normalize_token_for_fts(tok)
        if not normalized:
            continue
        if not normalized.isdigit() and len(normalized) < 3:
            continue
        base.append(normalized)

    if len(base) > limit:
        # Rank, keep the top-`limit` UNIQUE tokens by score, then re-emit in
        # first-occurrence order so phrase coherence survives for
        # _clean_for_phrase / anchor-pair adjacency. Selection must happen in
        # SCORE order — cutting a positional list defeats the ranking.
        scores = _rank_query_tokens(base, query)
        first_pos: dict[str, int] = {}
        for i, t in enumerate(base):
            first_pos.setdefault(t, i)
        sel_seen: set[str] = set()
        for i in sorted(range(len(base)), key=lambda i: -scores[i]):
            t = base[i]
            if t in sel_seen:
                continue
            sel_seen.add(t)
            if len(sel_seen) >= limit:
                break
        token_stream = sorted(sel_seen, key=lambda t: first_pos[t])
    else:
        token_stream = None  # signal: run the original loop verbatim

    keep: list[str] = []
    seen: set[str] = set()
    stream = token_stream if token_stream is not None else [
        t for t in (
            _normalize_token_for_fts(tok)
            for tok in re.findall(r"[0-9A-Za-zÀ-ÖØ-öø-ÿ_]+", query.lower())
            if tok not in NL_STOPWORDS
        )
        if t and (t.isdigit() or len(t) >= 3)
    ]
    for normalized in stream:
        variants = [normalized]
        if include_variants:
            alt = _collapse_umlaut_variants(normalized)
            if alt and alt != normalized:
                variants.append(alt)
        if include_expansions:
            for expansion in _get_query_expansions(normalized):
                if expansion and expansion not in variants:
                    variants.append(expansion)
        if include_variants:
            for part in _decompose_compound(normalized):
                if part not in variants:
                    variants.append(part)
        for term in variants:
            if term in seen:
                continue
            keep.append(term)
            seen.add(term)
            if len(keep) >= limit:
                return keep
    return keep


# Common German legal compound word suffixes/prefixes for decomposition
_COMPOUND_SUFFIXES = [
    "verordnung", "gesetz", "recht", "pflicht", "schutz", "haftung",
    "versicherung", "bewilligung", "verfahren", "verhaltnis", "vertrag",
    "anspruch", "verletzung", "bestimmung", "regelung", "voraussetzung",
    "massnahme", "entscheid", "beschluss", "urteil", "klage",
    "forderung", "leistung", "zahlung", "beitrag", "grenzwert",
]

_COMPOUND_PREFIXES = [
    "arbeits", "miet", "straf", "verwaltungs", "sozial", "bundes",
    "kantons", "gemeinde", "verkehrs", "bau", "steuer", "erb",
    "familien", "handels", "schuld", "sach", "grund", "eigen",
    "ober", "unter", "vor", "nach", "aus", "ein",
]


def _decompose_compound(term: str) -> list[str]:
    """Split a German compound word into sub-words for broader FTS matching.

    E.g., "larmschutzverordnung" → ["larmschutz", "verordnung"]
          "arbeitnehmerschutz" → ["arbeitnehmer", "schutz"]

    Only decomposes words ≥ 10 chars to avoid false splits on short words.
    Returns empty list if no valid decomposition found.
    """
    if len(term) < 10:
        return []

    parts = []
    # Try suffix-based decomposition (most reliable)
    for suffix in _COMPOUND_SUFFIXES:
        if term.endswith(suffix) and len(term) > len(suffix) + 3:
            prefix = term[:-len(suffix)]
            if len(prefix) >= 3:
                parts = [prefix, suffix]
                break

    if not parts:
        # Try prefix-based decomposition
        for prefix in _COMPOUND_PREFIXES:
            if term.startswith(prefix) and len(term) > len(prefix) + 3:
                remainder = term[len(prefix):]
                if len(remainder) >= 4:
                    parts = [prefix, remainder]
                    break

    # Filter: both parts must be ≥ 3 chars
    return [p for p in parts if len(p) >= 3] if len(parts) >= 2 else []


def _get_query_expansions(term: str) -> list[str]:
    expansions = LEGAL_QUERY_EXPANSIONS.get(term, ())
    if not expansions:
        # FTS NFKD normalizes ü→u, ö→o, ä→a, but expansion keys use ue/oe/ae.
        # Use prebuilt reverse lookup to match FTS-normalized terms to expansion keys.
        expansions = _FTS_NORMALIZED_EXPANSIONS.get(term, ())
    out: list[str] = []
    for exp in expansions[:MAX_EXPANSIONS_PER_TERM]:
        normalized = _normalize_token_for_fts(exp)
        if normalized and normalized != term:
            out.append(normalized)
    return out


_FTS_NORMALIZED_EXPANSIONS: dict[str, tuple[str, ...]] = {}  # populated after _normalize_token_for_fts definition


def _normalize_token_for_fts(token: str) -> str:
    token = token.strip().lower()
    if not token:
        return ""
    token = (
        token
        .replace("ß", "ss")
        .replace("æ", "ae")
        .replace("œ", "oe")
    )
    token = unicodedata.normalize("NFKD", token)
    token = "".join(ch for ch in token if not unicodedata.combining(ch))
    token = re.sub(r"[^0-9a-z_]+", "", token)
    return token


def _normalize_token_for_match(token: str) -> str:
    token = _normalize_token_for_fts(token)
    return _collapse_umlaut_variants(token)


def _collapse_umlaut_variants(token: str) -> str:
    return token.replace("ae", "a").replace("oe", "o").replace("ue", "u")


# Prebuilt reverse lookup: FTS-normalized key → expansion values.
# Handles two mismatches:
# 1. Keys with Unicode (proprietà → proprieta via NFKD)
# 2. Keys with digraphs (kuendigung → kundigung via umlaut collapse)
# When a user types "Kündigung", FTS produces "kundigung", but the
# expansion key is "kuendigung" — this lookup bridges that gap.
for _key, _vals in LEGAL_QUERY_EXPANSIONS.items():
    _collapsed = _collapse_umlaut_variants(_key)
    if _collapsed != _key and _collapsed not in LEGAL_QUERY_EXPANSIONS:
        _FTS_NORMALIZED_EXPANSIONS[_collapsed] = _vals
    _normed = _normalize_token_for_fts(_key)
    if _normed != _key and _normed not in LEGAL_QUERY_EXPANSIONS:
        _FTS_NORMALIZED_EXPANSIONS.setdefault(_normed, _vals)


def _normalize_text_for_match(text: str | None) -> str:
    if not text:
        return ""
    normalized_tokens: list[str] = []
    for tok in re.findall(r"[0-9A-Za-zÀ-ÖØ-öø-ÿ_]+", text.lower()):
        norm = _normalize_token_for_match(tok)
        if norm:
            normalized_tokens.append(norm)
    return " ".join(normalized_tokens)


def _normalize_docket(value: str) -> str:
    """Normalize docket-like strings for exact/partial matching."""
    return re.sub(r"[^0-9a-z]+", "", (value or "").lower())


def _collapse_spaced_docket(query: str) -> str | None:
    """Try collapsing space-separated tokens into a docket-like string.

    Handles queries like '6B 1234 2025' → '6B_1234/2025' or '7W 15 25' → '7W_15/2025'.
    Returns the collapsed form if it matches a known docket pattern, else None.
    """
    parts = query.strip().split()
    if not (2 <= len(parts) <= 4):
        return None
    if not all(re.match(r"^[A-Z0-9]{1,6}$", p, re.IGNORECASE) for p in parts):
        return None
    # First part should contain at least one letter
    if not re.search(r"[A-Za-z]", parts[0]):
        return None

    variants = []
    for sep1 in ("_", ".", "-"):
        for sep2 in ("/", "_", "."):
            if len(parts) == 2:
                variants.append(f"{parts[0]}{sep1}{parts[1]}")
            elif len(parts) == 3:
                variants.append(f"{parts[0]}{sep1}{parts[1]}{sep2}{parts[2]}")
            elif len(parts) == 4:
                variants.append(f"{parts[0]}{sep1}{parts[1]}{sep2}{parts[2]}{sep1}{parts[3]}")

    # Also try expanding 2-digit year to 4-digit
    last = parts[-1]
    if len(last) == 2 and last.isdigit():
        expanded = parts[:-1] + ["20" + last]
        for sep1 in ("_", ".", "-"):
            for sep2 in ("/", "_", "."):
                if len(expanded) == 3:
                    variants.append(f"{expanded[0]}{sep1}{expanded[1]}{sep2}{expanded[2]}")
                elif len(expanded) == 4:
                    variants.append(f"{expanded[0]}{sep1}{expanded[1]}{sep2}{expanded[2]}{sep1}{expanded[3]}")

    for variant in variants:
        for pattern in QUERY_DOCKET_PATTERNS:
            if pattern.fullmatch(variant):
                return variant
    return None


def _looks_like_docket_query(query: str) -> bool:
    """Heuristic: identify docket-number style queries."""
    q = query.strip()
    if not q:
        return False

    nonspace = re.sub(r"\s+", "", q)
    if not nonspace:
        return False

    if QUERY_BGE_PATTERN.fullmatch(q):
        return True
    if QUERY_BVGE_PATTERN.fullmatch(q):
        return True
    for pattern in QUERY_DOCKET_PATTERNS:
        if pattern.fullmatch(q):
            return True

    # Accept only if a docket-like fragment dominates the whole query.
    for pattern in QUERY_DOCKET_PATTERNS:
        for match in pattern.finditer(q):
            fragment = re.sub(r"\s+", "", match.group(0))
            if len(fragment) / len(nonspace) >= 0.7:
                return True

    if re.fullmatch(r"[0-9]{1,4}\s+[A-Z]{1,4}\s+[0-9]{1,4}", q):
        return True
    # Try collapsing spaces: "6B 1234 2025" → "6B_1234/2025"
    if _collapse_spaced_docket(q):
        return True
    return False


def _to_float(value) -> float:
    try:
        return float(value)
    except Exception:
        return 1e9


def _date_sort_key(value: str) -> int:
    text = (value or "").strip()
    if not text:
        return 0
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", text)
    if not m:
        return 0
    try:
        return int(f"{m.group(1)}{m.group(2)}{m.group(3)}")
    except Exception:
        return 0


def _row_get(row: sqlite3.Row | dict, key: str, default=None):
    try:
        return row[key]
    except Exception:
        return default


def _apply_cross_encoder_boosts(
    scored: list[tuple[float, float, int, sqlite3.Row]],
    query: str,
    deadline: float | None = None,
) -> list[tuple[float, float, int, sqlite3.Row]]:
    if _past_deadline(deadline):
        return scored
    if not CROSS_ENCODER_ENABLED or not scored:
        return scored

    encoder = _get_cross_encoder()
    if encoder is None:
        return scored

    top_n = min(CROSS_ENCODER_TOP_N, len(scored))
    if top_n <= 0:
        return scored

    pre_sorted = sorted(scored, key=lambda x: (-x[0], x[1], x[2]))
    rerank_subset = pre_sorted[:top_n]
    pairs = [(query, _build_rerank_document(row)) for _s, _b, _i, row in rerank_subset]
    if not pairs:
        return scored

    try:
        raw_scores = encoder.predict(pairs)
    except Exception as e:
        logger.debug("Cross-encoder prediction failed: %s", e)
        return scored

    normalized = _normalize_score_list(raw_scores)
    ce_by_id = {
        row["decision_id"]: score
        for score, (_s, _b, _i, row) in zip(normalized, rerank_subset)
    }

    # Research trace. Unlike the Haiku path this function traced NOTHING
    # until 2026-08-19 — the scores were computed and dropped, so
    # CE-vs-Haiku agreement (two independent relevance judges over the
    # same candidates) was unmeasurable. Ids and scores only; query_len
    # rather than text because this record adds no query content of its
    # own. Raw scores, not the normalised ones: normalisation flattens a
    # low-confidence board into the same 0..1 span as a confident one,
    # which is exactly the difference a quality analysis needs to see.
    _log_search_trace({
        "type": "cross_encoder",
        "query_len": len(query or ""),
        "model": CROSS_ENCODER_MODEL,
        "scores_by_id": {
            row["decision_id"]: round(float(raw), 4)
            for raw, (_s, _b, _i, row) in zip(raw_scores, rerank_subset)
        },
        "timestamp": datetime.now(timezone.utc).isoformat(),
    })

    boosted: list[tuple[float, float, int, sqlite3.Row]] = []
    for score, bm25, idx, row in scored:
        ce_score = ce_by_id.get(row["decision_id"], 0.0)
        boosted.append((score + CROSS_ENCODER_WEIGHT * ce_score, bm25, idx, row))
    return boosted


def _get_cross_encoder():
    global _CROSS_ENCODER, _CROSS_ENCODER_FAILED
    if not CROSS_ENCODER_ENABLED:
        return None
    if _CROSS_ENCODER is not None:
        return _CROSS_ENCODER
    if _CROSS_ENCODER_FAILED:
        return None
    try:
        from sentence_transformers import CrossEncoder
    except Exception as e:
        logger.debug("sentence-transformers unavailable for cross-encoder reranking: %s", e)
        _CROSS_ENCODER_FAILED = True
        return None

    try:
        if CROSS_ENCODER_MAX_LENGTH:
            _CROSS_ENCODER = CrossEncoder(CROSS_ENCODER_MODEL, max_length=int(CROSS_ENCODER_MAX_LENGTH))
        else:
            _CROSS_ENCODER = CrossEncoder(CROSS_ENCODER_MODEL)
        return _CROSS_ENCODER
    except Exception as e:
        logger.debug("Cross-encoder model load failed (%s): %s", CROSS_ENCODER_MODEL, e)
        _CROSS_ENCODER_FAILED = True
        return None


def _normalize_score_list(scores) -> list[float]:
    values = [float(s) for s in scores]
    if not values:
        return []
    lo = min(values)
    hi = max(values)
    if hi <= lo:
        return [0.5 for _ in values]
    span = hi - lo
    return [(v - lo) / span for v in values]


LLM_RERANK_PROMPT = (
    "You are a Swiss legal search relevance judge for a multilingual corpus "
    "(German, French, Italian). Given a search query and a list of court "
    "decision candidates whose Regesten may be in any of the three languages, "
    "rank them by RELEVANCE TO THE QUERY regardless of decision language.\n"
    "\n"
    "Critical multilingual rules:\n"
    "- A French decision may be the most relevant answer to a German query, "
    "and vice versa. Cross-language equivalence is the norm in Swiss law.\n"
    "- Map terms across languages: Mietrecht ≡ droit du bail ≡ diritto della "
    "locazione; Tierhalterhaftung ≡ responsabilité du détenteur d'animaux ≡ "
    "responsabilità del detentore di animali; etc.\n"
    "- Do NOT downrank a decision because its Regeste is in a different "
    "language from the query. The legal substance is what matters.\n"
    "\n"
    "Consider: (1) legal doctrine match (across languages), (2) applicable "
    "statute provisions (same SR-number across languages: OR=CO, ZGB=CC, "
    "StGB=CP), (3) factual pattern similarity, (4) court authority level "
    "(BGer/BGE > BVGer/BStGer > kantonal).\n"
    "\n"
    "Return ONLY a JSON array of decision_id strings in order from most to "
    "least relevant. Include ALL candidates in the array. "
    "Example: [\"bge_BGE_131_III_115\",\"bge_BGE_110_II_136\"]\n"
    "Output ONLY the JSON array, nothing else."
)


# Version stamps for the label streams. Labels without provenance decay
# into noise: six months of rerank judgments spanning three silent
# prompt tweaks are three datasets, not one, and nothing recorded which
# was which. Hashes, not dates — two deploys with the same prompt ARE
# the same judge.
_RERANK_PROMPT_V = hashlib.sha256(LLM_RERANK_PROMPT.encode()).hexdigest()[:8]
_SCORING_V = hashlib.sha256(
    json.dumps(SCORING_CONFIG, sort_keys=True).encode()).hexdigest()[:8]


def _apply_llm_rerank(
    scored: list[tuple[float, float, int, sqlite3.Row]],
    query: str,
    *,
    is_docket_query: bool = False,
    deadline: float | None = None,
) -> list[tuple[float, float, int, sqlite3.Row]]:
    """Rerank top candidates using Haiku for legal relevance judgment.

    Gating rules:
    - Skip if past the search soft-deadline (degrade to fast results)
    - Skip if disabled or no API key
    - Skip for docket queries (already exact match)
    - Skip if top result dominates (score >= gate * second)
    """
    if _past_deadline(deadline):
        return scored
    if not LLM_RERANK_ENABLED or not ANTHROPIC_API_KEY or not scored:
        return scored
    if is_docket_query:
        return scored

    # Sort to find top candidates
    pre_sorted = sorted(scored, key=lambda x: (-x[0], x[1], x[2]))

    # Confidence gate: skip if top result clearly dominates
    if len(pre_sorted) >= 2:
        top_score = pre_sorted[0][0]
        second_score = pre_sorted[1][0]
        if second_score > 0 and top_score >= LLM_RERANK_CONFIDENCE_GATE * second_score:
            _metrics["haiku_rerank_skipped"] += 1
            return scored

    _metrics["haiku_rerank_fired"] += 1

    top_n = min(LLM_RERANK_TOP_N, len(pre_sorted))
    if top_n < 2:
        return scored

    rerank_subset = pre_sorted[:top_n]

    # Build candidate descriptions for Haiku
    candidates_text = []
    for _s, _b, _i, row in rerank_subset:
        did = row["decision_id"]
        docket = row["docket_number"] or ""
        regeste = (row["regeste"] or "")[:300]
        candidates_text.append(f"- {did} ({docket}): {regeste}")

    user_msg = (
        f"Query: {_llm_input_excerpt(query)}\n\nCandidates:\n" + "\n".join(candidates_text)
    )

    try:
        import httpx
    except ImportError:
        return scored

    try:
        with httpx.Client(timeout=LLM_RERANK_TIMEOUT + 1.0) as client:
            resp = client.post(
                "https://api.anthropic.com/v1/messages",
                headers={
                    "x-api-key": ANTHROPIC_API_KEY,
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                },
                json={
                    "model": "claude-haiku-4-5-20251001",
                    "max_tokens": 400,
                    "system": LLM_RERANK_PROMPT,
                    "messages": [{"role": "user", "content": user_msg}],
                },
            )
            resp.raise_for_status()
            _resp_json = resp.json()
            _llm_usage_log(model="claude-haiku-4-5-20251001",
                            feature="search_rerank", response_json=_resp_json)
            text = _resp_json["content"][0]["text"].strip()

            # Parse JSON array of decision_ids
            if text.startswith("```"):
                text = text.split("\n", 1)[-1].rsplit("```", 1)[0].strip()
            import json as _json
            ranked_ids = _json.loads(text)
            if not isinstance(ranked_ids, list):
                logger.debug("LLM rerank: unexpected response type %s", type(ranked_ids))
                return scored

    except Exception as e:
        logger.debug("LLM rerank failed: %s", e)
        return scored

    # Apply position-based boost: rank 1 gets full weight, rank N gets ~0
    rank_by_id: dict[str, int] = {}
    for rank, did in enumerate(ranked_ids):
        if isinstance(did, str) and did not in rank_by_id:
            rank_by_id[did] = rank

    # Record pre-rerank top result for impact tracking
    pre_top = pre_sorted[0][3]["decision_id"] if pre_sorted else None

    boosted: list[tuple[float, float, int, sqlite3.Row]] = []
    for score, bm25, idx, row in scored:
        did = row["decision_id"]
        rank = rank_by_id.get(did)
        if rank is not None:
            # Linear decay: rank 0 → weight, rank N-1 → 0
            boost = LLM_RERANK_WEIGHT * max(0.0, 1.0 - rank / max(top_n, 1))
            boosted.append((score + boost, bm25, idx, row))
        else:
            boosted.append((score, bm25, idx, row))

    # Track whether Haiku changed the top result
    post_sorted = sorted(boosted, key=lambda x: (-x[0], x[1], x[2]))
    post_top = post_sorted[0][3]["decision_id"] if post_sorted else None
    if pre_top and post_top and pre_top != post_top:
        _metrics["haiku_rerank_changed_top"] += 1

    # Research trace. This is a labelled-ranking record, not just an
    # impact counter: we are already paying Haiku to order these
    # candidates over a real query, and until 2026-08-19 the ordering
    # was thrown away — only pre/post_top survived, so the label stream
    # could neither train a reranker nor even measure agreement.
    #
    # `candidate_ids` is the retrieval order shown to the model,
    # `llm_order` the order it returned. Decision ids and the query the
    # existing record already carried — no new user data, same 30-day
    # trace retention as before.
    _log_search_trace({
        "type": "rerank",
        "query": query[:200],
        "pre_top": pre_top,
        "post_top": post_top,
        "changed": pre_top != post_top,
        "candidates": top_n,
        "candidate_ids": [r["decision_id"] for _s, _b, _i, r in rerank_subset],
        "llm_order": [d for d in ranked_ids if isinstance(d, str)][:top_n],
        "judge": {"model": "claude-haiku-4-5-20251001",
                  "prompt_v": _RERANK_PROMPT_V},
        "timestamp": datetime.now(timezone.utc).isoformat(),
    })

    return boosted


def _build_rerank_document(row: sqlite3.Row | dict) -> str:
    title = _row_get(row, "title") or ""
    regeste = _row_get(row, "regeste") or ""
    snippet = _row_get(row, "snippet") or ""
    full_text = (_row_get(row, "full_text_raw") or "").strip()
    if len(full_text) > FULL_TEXT_RERANK_CHARS:
        full_text = full_text[:FULL_TEXT_RERANK_CHARS]
    parts = [title, regeste, snippet, full_text]
    return " ".join(p for p in parts if p).strip()


def _select_best_passage_snippet(
    full_text: str | None,
    *,
    rank_terms: list[str],
    phrase: str,
    raw_query: str = "",
    fallback: str | None,
) -> str | None:
    if not full_text:
        return fallback

    passages = _split_passages(full_text)
    if not passages:
        return fallback

    best_text = None
    best_score = -1.0
    for passage in passages:
        if not passage:
            continue
        normalized = _normalize_text_for_match(passage)
        if not normalized:
            continue
        term_hits = sum(1 for t in rank_terms if t in normalized)
        phrase_hit = 1 if phrase and phrase in normalized else 0
        density = term_hits / max(1, min(12, len(normalized.split())))
        score = (2.4 * phrase_hit) + term_hits + (4.0 * density)
        if score > best_score:
            best_score = score
            best_text = passage

    if best_text and best_score > 0:
        compact = re.sub(r"\s+", " ", best_text).strip()
        truncated = _truncate(compact, MAX_SNIPPET_LEN)
        return _highlight_terms(truncated, rank_terms, phrase, raw_query)
    return fallback


# Terms too common in Swiss legal text to be worth highlighting.
# These appear in virtually every decision and create visual noise.
_HIGHLIGHT_STOPWORDS = {
    # Court names
    "bge", "bger", "bvger", "bstger", "bpatger",
    "bundesgericht", "tribunal", "obergericht", "gericht",
    # Structural terms (appear in every decision)
    "art", "abs", "lit", "ziff", "bgb", "erw", "vol",
    "urteil", "beschluss", "verfügung", "entscheid", "sachverhalt",
    "arrêt", "décision", "jugement", "sentenza", "fait",
    # Common procedural
    "beschwerde", "berufung", "rekurs", "klage", "recours",
    "antrag", "begründung", "erwägung", "dispositiv",
    # Roman numerals (BGE volume dividers, court divisions)
    "i", "ii", "iii", "iv", "v", "vi", "vii", "viii", "ix", "x",
    "xi", "xii", "xiii", "xiv", "xv",
}


def _is_trivial_highlight(term: str) -> bool:
    """Return True if a term is too common/trivial to highlight."""
    t = term.lower().strip("*")
    if t in _HIGHLIGHT_STOPWORDS:
        return True
    # Bare years (1900-2099) are trivial — they appear in every date
    if re.fullmatch(r"(?:19|20)\d{2}", t):
        return True
    # Pure numbers (docket fragments, page numbers) under 5 digits
    if t.isdigit() and len(t) < 5:
        return True
    return False


def _highlight_terms(
    text: str | None,
    rank_terms: list[str],
    phrase: str,
    raw_query: str = "",
) -> str | None:
    """Wrap matched search terms in <mark> tags for frontend highlighting.

    Tries full raw query phrase first, then individual terms for leftovers.
    Skips trivial terms (BGE, years, etc.) that add visual noise.
    """
    if not text:
        return text

    # Build ordered list: raw query phrase (longest) first, then individual terms
    candidates: list[str] = []

    # Try the full raw query as a phrase (strip FTS operators, but preserve
    # statute abbreviation "OR" = Obligationenrecht in "Art. N OR" patterns)
    if raw_query:
        # Mask statute refs so "OR" in "Art. 41 OR" isn't stripped
        _masked_for_strip = QUERY_STATUTE_PATTERN.sub(
            lambda m: m.group(0).replace("OR", "\x00OR\x00").replace("or", "\x00or\x00"),
            raw_query,
        )
        clean_raw = re.sub(r"\b(AND|OR|NOT)\b", " ", _masked_for_strip, flags=re.IGNORECASE)
        clean_raw = clean_raw.replace("\x00", "")
        clean_raw = clean_raw.strip(' "')
        clean_raw = re.sub(r"\s+", " ", clean_raw).strip()
        if clean_raw and len(clean_raw.split()) > 1:
            candidates.append(clean_raw)

    # Then individual rank_terms, skipping trivial ones
    for t in rank_terms:
        if t not in candidates and not _is_trivial_highlight(t):
            candidates.append(t)

    for term in candidates:
        # Allow flexible whitespace/punctuation between words for multi-word phrases
        if len(term.split()) > 1:
            words = term.split()
            pattern = r"\b" + r"[\s,;:.·/\-]+".join(re.escape(w) for w in words) + r"\b"
        else:
            pattern = rf"\b{re.escape(term)}\b"
        # Apply highlighting only to text outside existing <mark> tags
        text = _apply_highlight_outside_marks(text, pattern)
    return text


def _apply_highlight_outside_marks(text: str, pattern: str) -> str:
    """Apply a highlight pattern only to text segments not already inside <mark>."""
    parts = re.split(r"(<mark>.*?</mark>)", text, flags=re.IGNORECASE)
    for i, part in enumerate(parts):
        if part.startswith("<mark>"):
            continue  # already highlighted
        parts[i] = re.sub(
            rf"({pattern})", r"<mark>\1</mark>", part, flags=re.IGNORECASE
        )
    return "".join(parts)


def _split_passages(full_text: str) -> list[str]:
    text = (full_text or "").strip()
    if not text:
        return []

    paragraphs = [p.strip() for p in re.split(r"\n\s*\n+", text) if p.strip()]
    if len(paragraphs) >= 2:
        return paragraphs[:40]

    sentences = [s.strip() for s in re.split(r"(?<=[.!?])\s+", text) if s.strip()]
    if len(sentences) <= PASSAGE_SENTENCE_WINDOW:
        return [text]

    out: list[str] = []
    for i in range(0, len(sentences), max(1, PASSAGE_SENTENCE_WINDOW // 2)):
        window = " ".join(sentences[i:i + PASSAGE_SENTENCE_WINDOW]).strip()
        if window:
            out.append(window)
        if len(out) >= 40:
            break
    return out


_CANONICAL_ID_PREFIX_RE = re.compile(
    r"^(?:bge|bger|bvger|bstger|bpatger|mkg|hudoc|bge_egmr|bge_historical|"
    r"ecthr_chamber|ecthr_committee|ecthr_grand_chamber|"
    r"finma|finma_versicherungsrecht|weko|edoeb|ubi|elcom|postcom|comcom|"
    r"emark|ta_sst|ch_bundesrat|"
    r"zh|be|lu|ur|sz|ow|nw|gl|zg|fr|so|bs|bl|sh|ar|ai|sg|gr|ag|tg|ti|vd|vs|ne|ge|ju)"
    r"_",
    re.IGNORECASE,
)


def get_decision_by_id(decision_id: str) -> dict | None:
    """Fetch a single decision with full text.

    Lookup ladder:
      1. Exact decision_id match (indexed) — O(1).
      2. Exact docket_number match (indexed) — O(1).
      3. Partial docket_number match (LIKE %x%) — full-table scan,
         only useful for raw docket queries the user typed by hand.
         SKIPPED when the input looks like a canonical decision_id
         (e.g. starts with "bger_" / "bge_BGE_…") because such IDs
         either hit step 1 or are fabricated; the LIKE scan costs
         ~2 s on the live 1.05M-row table and produces nothing
         meaningful for these inputs.
    """
    decision_id = (decision_id or "").strip()  # trim so a padded id/docket resolves (#44)
    conn = get_db()
    row = conn.execute(
        "SELECT * FROM decisions WHERE decision_id = ?",
        (decision_id,),
    ).fetchone()

    if not row:
        # BGE/short-reference exact resolution BEFORE any docket fallback, so
        # '131 III 12' resolves to its exact canonical id and never prefix-matches
        # '131 III 121' (bug C-1).
        for cid in _bge_ref_candidates(decision_id):
            row = conn.execute(
                "SELECT * FROM decisions WHERE decision_id = ?", (cid,)
            ).fetchone()
            if row:
                break

    if not row:
        # Try searching by docket number — prefer newest decision
        row = conn.execute(
            "SELECT * FROM decisions WHERE docket_number = ? "
            "ORDER BY decision_date DESC LIMIT 1",
            (decision_id,),
        ).fetchone()

    if not row:
        # Robustness (#44): resolve a DECORATED form of the tool's own printed
        # citation ("BGer 6B 1518/2021 vom 31. Januar 2022", stray whitespace)
        # by extracting the single docket and retrying the exact lookup.
        _ext = _extract_single_docket(decision_id)
        if _ext and _ext != decision_id:
            row = conn.execute(
                "SELECT * FROM decisions WHERE docket_number = ? "
                "ORDER BY decision_date DESC LIMIT 1", (_ext,),
            ).fetchone()

    _via_alias = False
    if not row:
        # Bare ECtHR application number -> the judgment carrying it.
        _appno_ids = _lookup_ecthr_appno(conn, decision_id)
        if len(_appno_ids) == 1:
            row = conn.execute(
                "SELECT * FROM decisions WHERE decision_id = ?", (_appno_ids[0],)
            ).fetchone()

    if not row:
        # Joined-docket alias (#41): resolve a secondary docket of a
        # consolidated decision to its lead. Unique aliases only.
        _alias_ids = _lookup_docket_alias(conn, decision_id)
        if len(_alias_ids) == 1:
            row = conn.execute(
                "SELECT * FROM decisions WHERE decision_id = ?", (_alias_ids[0],)
            ).fetchone()
            _via_alias = bool(row)

    if not row:
        # Typed identifiers (decision_ref): the docket grammar names the court
        # and the minted id; PK lookups only, before the LIKE scan.
        _ref_hit = _lookup_ref_candidates(conn, decision_id) or _lookup_appno_in_prose(conn, decision_id)
        if _ref_hit:
            row = conn.execute(
                "SELECT * FROM decisions WHERE decision_id = ?", (_ref_hit,)
            ).fetchone()

    if (not row and not _CANONICAL_ID_PREFIX_RE.match(decision_id or "")
            and _input_is_docket_like(decision_id)):
        # Partial match — only for hand-typed dockets, and NEVER a longer docket
        # that merely contains the input as a numeric prefix (131 III 12 -> 121).
        # Gated by _input_is_docket_like so bare words/chars/symbols don't
        # false-match decision IDs or titles (#44). Wildcards escaped so '%'/'_'
        # in the input can't inject LIKE semantics.
        for cand in conn.execute(
            "SELECT * FROM decisions WHERE docket_number LIKE ? ESCAPE '\\' "
            "ORDER BY decision_date DESC LIMIT 8",
            (f"%{_like_escape(decision_id)}%",),
        ).fetchall():
            if not _docket_is_prefix_of_longer(decision_id, cand["docket_number"]):
                row = cand
                break

    _joined = _joined_dockets_for(conn, row["decision_id"]) if row else []
    conn.close()

    if not row:
        return None

    result = dict(row)
    # Remove json_data blob from response (redundant)
    result.pop("json_data", None)
    # The caller typed something other than the stored id (a docket, a
    # citation string, a percent-encoded or differently-separated id): say
    # what was resolved so a client can tell normalisation from a mismatch.
    if result.get("decision_id") != decision_id:
        result["resolved_from"] = decision_id

    # Joined dockets (#41): every secondary docket of a consolidated proceeding
    # filed under this lead decision, so a caller holding one of them can
    # recognise the record instead of reading the lead docket as a mismatch.
    if _joined:
        result["joined_dockets"] = _joined
    # Duplicate representations: canonical_decision_id + is_canonical from the
    # representation manifest (absent when it is not loaded; never changes
    # decision_id — the requested row is served either way).
    _attach_canonical_ids([result])

    # Joined-docket resolution (#41): the caller looked up a secondary docket of
    # a consolidated proceeding; surface that the returned decision is the lead,
    # so downstream consumers don't treat the docket mismatch as an error.
    if _via_alias:
        result["resolved_via"] = "joined_docket_alias"
        result["queried_docket"] = decision_id
        result["canonical_docket"] = result.get("docket_number")

    # Canonical-identity enrichment (C-2): a text-verified decision date overrides
    # a synthetic YYYY-01-01 placeholder; publication_date and ECLI are added; a
    # date_is_estimated flag lets consumers tell a real date from a placeholder.
    # Never overrides a real (source_metadata) date — the sidecar holds no entry
    # for those. Degrades gracefully when the sidecar is absent.
    ci = _canonical_for(result.get("decision_id"))
    if ci:
        if ci.get("decision_date") and ci.get("decision_date_provenance") == "extracted_from_text":
            result["decision_date"] = ci["decision_date"]
        if ci.get("decision_date_provenance"):
            result["date_provenance"] = ci["decision_date_provenance"]
        if ci.get("publication_date"):
            result["publication_date"] = ci["publication_date"]
            result["publication_date_provenance"] = ci.get("publication_date_provenance")
        if ci.get("canonical_key"):
            result["canonical_key"] = ci["canonical_key"]  # internal logical-decision key
    _dd = result.get("decision_date") or ""
    _prov = result.get("date_provenance")
    result["date_is_estimated"] = bool(
        (not _dd or _dd.endswith("-01-01")) and _prov != "extracted_from_text"
    )
    # cli:ch — the Swiss-native caselaw identifier (Switzerland is not an ECLI
    # member; cli:ch is the appropriate identifier). Minted on the fly from the row.
    if _mint_cli_ch is not None:
        cid = _mint_cli_ch(result)
        if cid:
            result["cli_ch"] = cid
        # A BGE is a published excerpt of an underlying full decision; surface that
        # decision's docket-based cli:ch as the navigation cross-link (the linkage
        # the old docket-encoded identifier provided). Caption docket from the head.
        if (result.get("court") or "").lower() == "bge" and _dft is not None:
            try:
                cap = _dft.extract_urteilskopf(result.get("full_text")).get("docket") \
                    or _dft.extract_docket(result.get("full_text"))
                if cap:
                    dcid = _mint_cli_ch({"decision_id": "bger_" + cap,
                                         "court": "bger", "docket_number": cap})
                    if dcid:
                        result["underlying_docket"] = cap
                        result["cli_ch_full_decision"] = dcid
            except Exception:
                pass

    # BGE-bound flag: DB stores 0/1/NULL; present it as a real bool (or None
    # when unknown). The column exists only after a post-schema-change rebuild,
    # so guard on presence — pre-rebuild responses simply omit it.
    if result.get("marked_for_publication") is not None:
        result["marked_for_publication"] = bool(result["marked_for_publication"])

    # Enrich with the same metadata that search_decisions provides,
    # so callers who fetch a decision by ID get the same fields as
    # those who find it via search.
    court = result.get("court") or ""
    did = result.get("decision_id") or ""
    result["court_name"] = _get_court_display_name(court)
    result["court_level"] = _get_court_level(court)

    statutes_map = _batch_fetch_statutes([did], limit_per=8)
    statutes = statutes_map.get(did, [])
    if statutes:
        result["statutes"] = statutes
        legal_area = _derive_legal_area(statutes, court)
        if legal_area:
            result["legal_area"] = legal_area

    incoming, outgoing = _count_citations(did)
    if incoming > 0:
        result["citation_count"] = incoming
        threshold = (
            LEADING_CASE_THRESHOLD_FEDERAL
            if _get_court_level(court).startswith("federal")
            else LEADING_CASE_THRESHOLD_CANTONAL
        )
        if incoming >= threshold:
            result["is_leading_case"] = True

    return result


def find_citations(
    *,
    decision_id: str,
    direction: str = "both",
    min_confidence: float = 0.3,
    limit: int = 50,
    offset: int = 0,
) -> dict:
    """Find outgoing and/or incoming citations for a decision."""
    limit = max(1, min(limit, 200))
    offset = max(0, offset)
    min_confidence = max(0.0, min(min_confidence, 1.0))

    # Resolve user-supplied ID to actual stored ID (handles format differences)
    _typed = (decision_id or "").strip()
    decision_id = _resolve_decision_id(decision_id)

    result: dict = {
        "decision_id": decision_id, "direction": direction,
        "limit": limit, "offset": offset,
    }
    if decision_id != _typed:
        result["resolved_from"] = _typed
    elif _typed:
        # Nothing resolved. When the typed text has a shape the coverage notes
        # explain (pre-2000 BGer, pre-2007 EVG, or one that is ambiguous with a
        # cantonal number) AND the id is not stored, say so instead of returning
        # an empty graph. The shape check is pure and runs first, so the common
        # path (a stored canonical id) never pays for the extra PK probe.
        _reason = decision_ref.unavailable_reason(_typed)
        if _reason and not _decision_exists(decision_id):
            result.update(_reason)
            result["error"] = f"Decision not found: {_typed} — {_reason['reason']}"
            return result

    check_conn = _get_graph_conn()
    if check_conn is None:
        result["error"] = "Reference graph not available."
        return result
    check_conn.close()

    # Exact totals (confidence-filtered) so the caller can tell a capped page from
    # a complete one, and paginate the rest via offset (issue #49). Neither
    # direction is silently truncated without a signal.
    incoming_total, outgoing_total = _count_citations_filtered(
        decision_id, min_confidence=min_confidence,
    )

    if direction in ("both", "outgoing"):
        rows = _find_outgoing_citations(
            decision_id, min_confidence=min_confidence, limit=limit, offset=offset,
        )
        result["outgoing"] = rows
        result["outgoing_total"] = outgoing_total
        result["outgoing_returned"] = len(rows)
        result["outgoing_has_more"] = (offset + len(rows)) < outgoing_total

    if direction in ("both", "incoming"):
        rows = _find_incoming_citations(
            decision_id, min_confidence=min_confidence, limit=limit, offset=offset,
        )
        result["incoming"] = rows
        result["incoming_total"] = incoming_total
        result["incoming_returned"] = len(rows)
        result["incoming_has_more"] = (offset + len(rows)) < incoming_total

    if result.get("outgoing_has_more") or result.get("incoming_has_more"):
        result["next_offset"] = offset + limit

    return result


def _statute_ref_from_free_text(query: str) -> tuple[str, str, str | None] | None:
    """(law_code, article, residual_query) when the free text names exactly
    one statute article — "Art. 29 BV rechtliches Gehör" -> ("BV", "29",
    "rechtliches Gehör"), "art. 8 CEDH" -> ("CEDH", "8", None).

    Callers of find_leading_cases write the provision into `query` far
    more often than into law_code/article, and the FTS filter then ANDs
    "29" and "BV" onto the citation ranking. Two different provisions in
    one query ("Art. 41 OR vs Art. 55 OR") are left alone: there is no
    single statute path for them.

    The law token must be a law code the corpus knows (_known_law_codes:
    the statutes mirror and docs/data/law_codes.json). QUERY_STATUTE_PATTERN
    is case-insensitive, so "Art. 29 der BV" would otherwise yield the
    function word "DER" as the law and route the call onto the statute
    path with a law that does not exist — a hard empty where the FTS path
    answers. An unknown token leaves the query alone, i.e. the old path.
    """
    pairs: list[tuple[str, str]] = []
    for m in QUERY_STATUTE_PATTERN.finditer(query or ""):
        law_raw = (m.group("law") or "").strip()
        law = law_raw.upper()
        art = re.sub(r"\s+", "", (m.group("article") or "").lower())
        if not law or not art or law in QUERY_STATUTE_INVALID_LAWS:
            continue
        if not _looks_like_law_code(law_raw) or law not in _known_law_codes():
            # Not a law the corpus knows: no statute path exists for it,
            # so the whole query stays a free-text query.
            return None
        if (law, art) not in pairs:
            pairs.append((law, art))
    if len(pairs) != 1:
        return None
    law, art = pairs[0]
    residual = QUERY_STATUTE_PATTERN.sub(" ", query)
    residual = re.sub(r"\s+", " ", residual).strip(" ,;:.-–—/()")
    return law, art, (residual or None)


def _looks_like_law_code(law_raw: str) -> bool:
    """The shape test the citation extractor applies
    (search_stack/reference_extraction.py): a law abbreviation carries at
    least one capital, and a title-case word longer than three letters
    ("Oder", "Della", "Ihrer") is a word, not a code. "Cst", "Abs" pass
    and are left to the blocklist / known-code check."""
    n_upper = sum(1 for c in law_raw if c.isupper())
    if n_upper == 0:
        return False
    if n_upper == 1 and len(law_raw) > 3:
        return False
    return True


_LAW_CODES_JSON_PATH = Path(__file__).resolve().parent / "docs" / "data" / "law_codes.json"
_known_law_codes_cache: frozenset[str] | None = None


def _known_law_codes() -> frozenset[str]:
    """Upper-cased law abbreviations the corpus can answer a statute lookup
    for: the static abbreviation maps, the federal aliases in
    docs/data/law_codes.json (abbr_de/fr/it of every act in the Fedlex
    mirror) and the `laws` table of statutes.db when it is deployed. A
    trailing dot is dropped ("Cst." -> "CST") because QUERY_STATUTE_PATTERN
    never captures one. Loaded once per worker; a missing file or database
    just leaves its share out, so the set is conservative, never wrong.
    """
    global _known_law_codes_cache
    if _known_law_codes_cache is not None:
        return _known_law_codes_cache
    codes: set[str] = set()

    def _add(v) -> None:
        s = str(v or "").strip().upper().rstrip(".")
        if len(s) >= 2:
            codes.add(s)

    for table in (_OK_ABBR_TO_SR, _SR_NUMBER_MAP, _MATERIALIEN_SR_MAP):
        for k in table:
            _add(k)
    try:
        with open(_LAW_CODES_JSON_PATH, encoding="utf-8") as fh:
            data = json.load(fh)
        for k in (data.get("alias_to_sr") or {}):
            _add(k)
        for law in (data.get("federal") or []):
            for key in ("abbr_de", "abbr_fr", "abbr_it"):
                _add(law.get(key))
            for a in (law.get("aliases") or []):
                _add(a)
    except (OSError, ValueError) as e:
        logger.debug("law_codes.json not loaded for the known-code set: %s", e)
    conn = _get_statutes_conn()
    if conn is not None:
        try:
            for r in conn.execute("SELECT abbr_de, abbr_fr, abbr_it FROM laws"):
                for v in r:
                    _add(v)
        except sqlite3.Error as e:
            logger.debug("statutes.db laws not loaded for the known-code set: %s", e)
        finally:
            conn.close()
    _known_law_codes_cache = frozenset(codes)
    return _known_law_codes_cache


def _rerank_candidates_by_query_or(
    candidates: list[tuple[str, int]], query: str,
) -> list[tuple[str, int]]:
    """Order statute-ranked candidates by BM25 of the ranked-OR form of
    `query`; candidates matching none of the terms keep their statute
    order behind the matches. On any FTS failure the statute order stands.

    The MATCH is keyed by rowid (decisions_fts is external-content on
    decisions, so the rowids coincide) and restricted to the first
    _OR_RERANK_MAX_CANDIDATES candidates: `decision_id` is UNINDEXED in
    the FTS table, so `decision_id IN (...)` was a filter over every row
    the OR matched — on common terms, most of the table — whereas
    `rowid IN (...)` is one doclist seek per candidate. The materialised
    CTE keeps FTS5 from running its own sorter per rowid; the ORDER BY is
    over at most that many rows.
    """
    or_q = _fts5_or_query(query)
    if not or_q or not candidates:
        return candidates
    head = candidates[:_OR_RERANK_MAX_CANDIDATES]
    tail = candidates[_OR_RERANK_MAX_CANDIDATES:]
    ids = [c[0] for c in head]
    by_id = dict(head)
    fts_conn = None
    try:
        fts_conn = get_db()
        placeholders = ",".join("?" for _ in ids)
        rowid_of = {
            r["decision_id"]: r["rowid"] for r in fts_conn.execute(
                f"SELECT rowid, decision_id FROM decisions WHERE decision_id IN ({placeholders})",
                ids,
            ).fetchall()
        }
        if not rowid_of:
            return candidates
        id_of_rowid = {v: k for k, v in rowid_of.items()}
        rid_placeholders = ",".join("?" for _ in rowid_of)
        rows = fts_conn.execute(
            f"""
            WITH hits AS MATERIALIZED (
                SELECT rowid AS rid, rank AS r FROM decisions_fts
                WHERE decisions_fts MATCH ? AND rowid IN ({rid_placeholders})
            )
            SELECT rid FROM hits ORDER BY r
            """,
            (or_q, *rowid_of.values()),
        ).fetchall()
        rows = [{"decision_id": id_of_rowid[r["rid"]]} for r in rows
                if r["rid"] in id_of_rowid]
    except sqlite3.Error as e:
        logger.debug("OR re-rank of leading-case candidates failed: %s", e)
        return candidates
    finally:
        if fts_conn is not None:
            fts_conn.close()
    matched: list[tuple[str, int]] = []
    seen: set[str] = set()
    for r in rows:
        did = r["decision_id"]
        if did in by_id and did not in seen:
            seen.add(did)
            matched.append((did, by_id[did]))
    # Head: matches by BM25, then the unmatched in statute order; tail
    # (beyond the re-rank ceiling) keeps its statute order behind both.
    return matched + [c for c in head if c[0] not in seen] + tail


def _find_leading_cases(
    *,
    query: str | None = None,
    law_code: str | None = None,
    article: str | None = None,
    court: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
    limit: int = 20,
) -> dict:
    """Find the most-cited decisions for a topic or statute."""
    limit = max(1, min(limit, 100))
    # Reject an unrecognized date instead of silently dropping the filter (#45).
    _derr = _date_arg_error(date_from, date_to)
    if _derr:
        return {"error": _derr}
    date_from = _parse_date_param(date_from)
    date_to = _parse_date_param(date_to)
    original_query = query  # preserve for response metadata
    # A statute reference written into the free text ("Art. 29 BV", "art. 8
    # CEDH") is the statute filter the caller meant, not two topic words
    # ("29" AND "BV") to AND onto the citation ranking. Lift it into
    # law_code/article when the caller did not pass them; the rest of the
    # text stays the topic query.
    statute_from_query = False
    if query and not (law_code and article):
        _parsed = _statute_ref_from_free_text(query)
        if _parsed:
            law_code, article, query = _parsed
            statute_from_query = True
    # Set when the strict (AND) form answered nothing and the page shown is
    # the relaxed one — always flagged, never silent.
    filters_relaxed = False

    # Determine path: statute (graph DB) or global/court-filtered
    conn = _get_graph_conn()
    if conn is None:
        return {"error": "Reference graph not available."}

    try:
        candidates: list[tuple[str, int]] = []  # (decision_id, ranking_count)
        global_by_id: dict[str, int] = {}       # decision_id -> global citation count

        if law_code and article:
            # Statute path: candidates are decisions applying this provision, ranked
            # by TOPICAL authority — citations FROM other decisions that also apply
            # the provision — not by global citation count. Ranking by global count
            # surfaced procedural megacases that cite the provision once (audit
            # 2026-06-28: BGE 126 I 97, right-to-be-heard, 6,535 global cites). The
            # global count is kept for context. Graph DB uses uppercase law codes.
            law_code = law_code.upper()
            overfetch = limit * 3 if query else limit
            _statute_sub = (
                "SELECT ds.decision_id FROM decision_statutes ds "
                "JOIN statutes s ON s.statute_id = ds.statute_id "
                "WHERE s.law_code = ? AND s.article = ?")
            rows = conn.execute(
                f"""
                SELECT ct.target_decision_id AS decision_id,
                       COUNT(*) AS global_count,
                       SUM(CASE WHEN ct.source_decision_id IN ({_statute_sub})
                                THEN 1 ELSE 0 END) AS topic_count
                FROM citation_targets ct
                JOIN decisions d ON d.decision_id = ct.target_decision_id
                WHERE ct.target_decision_id IN ({_statute_sub})
                """
                + (" AND d.court = ?" if court else "")
                + (" AND d.decision_date >= ?" if date_from else "")
                + (" AND d.decision_date <= ?" if date_to else "")
                + """
                GROUP BY ct.target_decision_id
                ORDER BY topic_count DESC, global_count DESC
                LIMIT ?
                """,
                tuple(
                    v
                    for v in (
                        law_code, article,          # source subquery (topic_count)
                        law_code, article,          # target subquery (candidate set)
                        court if court else None,
                        date_from if date_from else None,
                        date_to if date_to else None,
                        overfetch,
                    )
                    if v is not None
                ),
            ).fetchall()
            candidates = [(r["decision_id"], int(r["topic_count"])) for r in rows]
            global_by_id = {r["decision_id"]: int(r["global_count"]) for r in rows}
        elif query:
            # Query-only: FTS-first approach — find matching decisions, then rank by citations
            conn.close()
            conn = None  # signal we closed it
            try:
                fts_conn = get_db()
                # Critical invariant #3: use the canonical sanitizer, not an
                # ad-hoc regex (which misses hyphens, apostrophes, quotes, OR).
                safe_q = _sanitize_fts5(query)
                if not safe_q:
                    return {"results": [], "total": 0}
                fts_sql = """
                    SELECT d.decision_id FROM decisions_fts f
                    JOIN decisions d ON d.decision_id = f.decision_id
                    WHERE decisions_fts MATCH ?
                """
                fts_params: list = [safe_q]
                if court:
                    fts_sql += " AND d.court = ?"
                    fts_params.append(court)
                if date_from:
                    fts_sql += " AND d.decision_date >= ?"
                    fts_params.append(date_from)
                if date_to:
                    fts_sql += " AND d.decision_date <= ?"
                    fts_params.append(date_to)
                fts_rows = fts_conn.execute(fts_sql + " LIMIT 5000",
                                            tuple(fts_params)).fetchall()
                fts_ids = [r["decision_id"] for r in fts_rows]
                if not fts_ids:
                    # Strict AND matched nothing: the ranked-OR form, BM25
                    # ordered and bounded, gives the nearest neighbours.
                    # Explicit court/date filters stay — they are the
                    # caller's constraints, not the relaxation's.
                    # Stop words are already out of the OR form; a query of
                    # only stop words yields "" and never reaches the table.
                    # The scan is capped: BM25 scores the first
                    # _OR_RELAX_SCAN_CAP rows that match (filters applied
                    # inside the cap, joined by rowid) and ranks within
                    # them, so a common term cannot force a scored pass
                    # over the whole table the way a bare ORDER BY rank does.
                    _or_q = _fts5_or_query(query)
                    if _or_q and _or_q != safe_q:
                        relaxed_sql = """
                            WITH hits AS MATERIALIZED (
                                SELECT f.rowid AS rid, f.rank AS r
                                FROM decisions_fts f
                                JOIN decisions d ON d.rowid = f.rowid
                                WHERE decisions_fts MATCH ?
                        """
                        if court:
                            relaxed_sql += " AND d.court = ?"
                        if date_from:
                            relaxed_sql += " AND d.decision_date >= ?"
                        if date_to:
                            relaxed_sql += " AND d.decision_date <= ?"
                        relaxed_sql += f"""
                                LIMIT {int(_OR_RELAX_SCAN_CAP)}
                            )
                            SELECT d.decision_id FROM hits
                            JOIN decisions d ON d.rowid = hits.rid
                            ORDER BY hits.r LIMIT 2000
                        """
                        fts_rows = fts_conn.execute(
                            relaxed_sql, (_or_q, *fts_params[1:]),
                        ).fetchall()
                        fts_ids = [r["decision_id"] for r in fts_rows]
                        filters_relaxed = bool(fts_ids)
                fts_conn.close()
            except sqlite3.Error as e:
                logger.debug("FTS lookup for leading cases failed: %s", e)
                return {"error": f"FTS query failed: {e}"}

            if not fts_ids:
                return {"results": [], "total": 0}

            # Look up citation counts from graph for FTS matches
            graph2 = _get_graph_conn()
            if graph2 is not None:
                try:
                    placeholders = ",".join("?" for _ in fts_ids)
                    rows = graph2.execute(
                        f"""
                        SELECT target_decision_id AS decision_id, COUNT(*) AS cite_count
                        FROM citation_targets
                        WHERE target_decision_id IN ({placeholders})
                        GROUP BY target_decision_id
                        ORDER BY cite_count DESC
                        LIMIT ?
                        """,
                        (*fts_ids, limit),
                    ).fetchall()
                    candidates = [(r["decision_id"], int(r["cite_count"])) for r in rows]
                except sqlite3.Error as e:
                    logger.debug("Graph citation lookup failed: %s", e)
                finally:
                    graph2.close()
            # Skip the post-hoc FTS filter since we already started from FTS
            query = None  # prevent double-filtering below
        else:
            # Global most-cited (no query, no statute)
            sql = """
                SELECT ct.target_decision_id AS decision_id, COUNT(*) AS cite_count
                FROM citation_targets ct
            """
            params: list = []
            conditions = []
            if court or date_from or date_to:
                sql += " JOIN decisions d ON d.decision_id = ct.target_decision_id"
                if court:
                    conditions.append("d.court = ?")
                    params.append(court)
                if date_from:
                    conditions.append("d.decision_date >= ?")
                    params.append(date_from)
                if date_to:
                    conditions.append("d.decision_date <= ?")
                    params.append(date_to)
            if conditions:
                sql += " WHERE " + " AND ".join(conditions)
            sql += " GROUP BY ct.target_decision_id ORDER BY cite_count DESC LIMIT ?"
            params.append(limit)
            rows = conn.execute(sql, tuple(params)).fetchall()
            candidates = [(r["decision_id"], int(r["cite_count"])) for r in rows]
    except sqlite3.Error as e:
        logger.debug("Leading cases graph query failed: %s", e)
        return {"error": f"Graph query failed: {e}"}
    finally:
        if conn is not None:
            conn.close()

    if not candidates:
        return {"results": [], "total": 0}

    # If query provided, filter via FTS5. CRITICAL: never silently fall through
    # to UNFILTERED statute-ranked candidates — that would present the most-cited
    # cases as topical matches (silently-wrong in a citation-authority tool).
    query_filter_applied = None
    statute_ranked = list(candidates)
    if query:
        candidate_ids = [c[0] for c in candidates]
        safe_q = _sanitize_fts5(query)  # invariant #3 — was raw query
        if not safe_q:
            query_filter_applied = False
        else:
            fts_conn = None
            try:
                fts_conn = get_db()
                placeholders = ",".join("?" for _ in candidate_ids)
                matched = fts_conn.execute(
                    f"""
                    SELECT decision_id FROM decisions_fts
                    WHERE decisions_fts MATCH ? AND decision_id IN ({placeholders})
                    """,
                    (safe_q, *candidate_ids),
                ).fetchall()
                matched_ids = {r["decision_id"] for r in matched}
                candidates = [(did, cnt) for did, cnt in candidates if did in matched_ids]
                query_filter_applied = True
            except sqlite3.Error as e:
                logger.warning(
                    "FTS topical filter for leading cases failed; returning "
                    "statute-ranked candidates UNFILTERED (flagged to caller): %s", e)
                query_filter_applied = False
            finally:
                if fts_conn is not None:
                    fts_conn.close()
        if query_filter_applied and not candidates and statute_ranked:
            # The topic filter excluded every decision applying the
            # provision (31% of MCP calls, 30 days to 2026-09-08). Fall
            # back to the statute-ranked set, ordered by how well each
            # candidate matches ANY of the query terms, and say so: the
            # page is nearest neighbours on the provision, not on-point
            # matches for the whole query.
            candidates = _rerank_candidates_by_query_or(statute_ranked, query)
            filters_relaxed = True

    # Truncate to limit
    candidates = candidates[:limit]

    if not candidates:
        return {"results": [], "total": 0}

    # Enrich with metadata from FTS5 decisions table.
    # Build rows_by_id with all ID variants as keys so graph-format IDs
    # (e.g. "bge_126 I 97") resolve to the FTS5 row ("bge_BGE_126_I_97").
    candidate_ids = [c[0] for c in candidates]
    rows = _fetch_decision_rows_by_ids(candidate_ids)
    rows_by_id: dict = {}
    for r in rows:
        rows_by_id[r["decision_id"]] = r
        for v in _decision_id_variants(r["decision_id"]):
            rows_by_id.setdefault(v, r)

    results = []
    for did, cite_count in candidates:
        row = rows_by_id.get(did, {})
        url = _canonical_decision_url(did)
        docket = row.get("docket_number", did)
        glob = global_by_id.get(did)
        entry = {
            "decision_id": did,
            "docket_number": docket,
            "decision_date": row.get("decision_date", ""),
            "court": row.get("court", ""),
            # citation_count stays the GLOBAL count (overall stature); in the
            # statute path topic_citation_count is the topical ranking basis.
            "citation_count": glob if glob is not None else cite_count,
            "regeste": (row.get("regeste") or "")[:300],
            "source_url": row.get("source_url", ""),
            "canonical_url": url,
            "markdown_link": _md_link(docket, url),
        }
        if glob is not None:
            entry["topic_citation_count"] = cite_count
        results.append(entry)

    out = {
        "results": results,
        "total": len(results),
        "law_code": law_code,
        "article": article,
        "query": original_query,
    }
    # If a topical query was requested but could not be applied, say so loudly —
    # the results are ranked by citation authority only, NOT filtered by topic.
    if query and not query_filter_applied:
        out["query_filter_applied"] = False
        out["_warning"] = (
            "Topical query could not be applied to the statute candidates; "
            "results are ranked by citation authority only, not filtered by the query."
        )
    if statute_from_query:
        out["statute_parsed_from_query"] = True
        # The text left after the provision was lifted out — the topic the
        # caller actually asked about, None for a bare "Art. 8 BV". The
        # dispatcher pinpoints Erwägungen against this, not the whole query.
        out["topic_query"] = query
    if filters_relaxed:
        out["filters_relaxed"] = True
        _shown = (original_query or "").strip()
        if law_code and article:
            out["note"] = (
                f"No decision applying Art. {article} {law_code} matched every "
                f"term of \"{_shown}\"; listed instead are the leading cases on "
                "the provision, ordered by how many of the query terms each "
                "contains (filters_relaxed). Treat them as nearest neighbours, "
                "not as authority on the whole query."
            )
        else:
            out["note"] = (
                f"No decision matched every term of \"{_shown}\"; listed instead "
                "are the most-cited decisions matching any of the terms "
                "(filters_relaxed, ranked OR). Treat them as nearest neighbours, "
                "not as authority on the whole query."
            )
    return out


def _leading_cases_pinpoint_claim(arguments: dict, result) -> str:
    """The text the find_leading_cases dispatcher pinpoints Erwägungen
    against. When the provision was lifted out of the free text
    (`statute_parsed_from_query`), the claim is the residual topic
    (`topic_query`): a bare "Art. 8 BV" has no topic to pinpoint and made
    this path ~18 s, so it returns "" and the pinpoint is skipped, exactly
    as an explicit statute-only lookup is."""
    if isinstance(result, dict) and result.get("statute_parsed_from_query"):
        return str(result.get("topic_query") or "").strip()
    return str(arguments.get("query") or "").strip()


def analyze_legal_trend(
    *,
    query: str | None = None,
    law_code: str | None = None,
    article: str | None = None,
    court: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
) -> dict:
    """Year-by-year decision counts for a statute or topic."""
    if not query and not law_code:
        return {"error": "At least one of 'query' or 'law_code' is required."}

    # Reject an unrecognized date instead of silently dropping the filter (#45).
    _derr = _date_arg_error(date_from, date_to)
    if _derr:
        return {"error": _derr}
    date_from = _parse_date_param(date_from)
    date_to = _parse_date_param(date_to)

    year_counts: dict[int, int] = {}

    # Statute path: use graph DB
    if law_code and article:
        conn = _get_graph_conn()
        if conn is None:
            return {"error": "Reference graph not available."}
        try:
            sql = """
                SELECT CAST(SUBSTR(d.decision_date, 1, 4) AS INTEGER) AS year,
                       COUNT(DISTINCT ds.decision_id) AS cnt
                FROM decision_statutes ds
                JOIN statutes s ON s.statute_id = ds.statute_id
                JOIN decisions d ON d.decision_id = ds.decision_id
                WHERE s.law_code = ? AND s.article = ?
                  AND d.decision_date IS NOT NULL
                  AND CAST(SUBSTR(d.decision_date, 1, 4) AS INTEGER) > 1800
                  AND CAST(SUBSTR(d.decision_date, 1, 4) AS INTEGER) < 2100
            """
            params: list = [law_code, article]
            if court:
                sql += " AND d.court = ?"
                params.append(court)
            if date_from:
                sql += " AND d.decision_date >= ?"
                params.append(date_from)
            if date_to:
                sql += " AND d.decision_date <= ?"
                params.append(date_to)
            sql += " GROUP BY year ORDER BY year"
            rows = conn.execute(sql, tuple(params)).fetchall()
            for r in rows:
                year_counts[int(r["year"])] = int(r["cnt"])
        except sqlite3.Error as e:
            logger.debug("Trend statute query failed: %s", e)
            return {"error": f"Statute trend query failed: {e}"}
        finally:
            conn.close()

    # FTS path: text query
    if query:
        try:
            fts_conn = get_db()
            sql = """
                SELECT CAST(SUBSTR(d.decision_date, 1, 4) AS INTEGER) AS year,
                       COUNT(*) AS cnt
                FROM decisions_fts f
                JOIN decisions d ON d.decision_id = f.decision_id
                WHERE decisions_fts MATCH ?
                  AND d.decision_date IS NOT NULL
                  AND CAST(SUBSTR(d.decision_date, 1, 4) AS INTEGER) > 1800
                  AND CAST(SUBSTR(d.decision_date, 1, 4) AS INTEGER) < 2100
            """
            # Invariant #3: user-facing FTS input must pass _sanitize_fts5 (a raw
            # query here threw sqlite OperationalError on bare operators like
            # trailing "Art." / unbalanced quotes, and let adversarial OR/NEAR
            # expressions drive broad scans). Codex review P0.4.
            params2: list = [_sanitize_fts5(query)]
            if court:
                sql += " AND d.court = ?"
                params2.append(court)
            if date_from:
                sql += " AND d.decision_date >= ?"
                params2.append(date_from)
            if date_to:
                sql += " AND d.decision_date <= ?"
                params2.append(date_to)
            sql += " GROUP BY year ORDER BY year"
            rows = fts_conn.execute(sql, tuple(params2)).fetchall()
            fts_conn.close()
            # Merge with statute counts (additive if both paths used)
            for r in rows:
                y = int(r["year"])
                if law_code and article:
                    # Both paths: take max (intersection would undercount)
                    year_counts[y] = max(year_counts.get(y, 0), int(r["cnt"]))
                else:
                    year_counts[y] = int(r["cnt"])
        except sqlite3.Error as e:
            logger.debug("Trend FTS query failed: %s", e)
            if not year_counts:
                return {"error": f"FTS trend query failed: {e}"}

    total = sum(year_counts.values())
    years_sorted = sorted(year_counts.items())

    return {
        "years": [{"year": y, "count": c} for y, c in years_sorted],
        "total": total,
        "law_code": law_code,
        "article": article,
        "query": query,
    }


def draft_mock_decision(
    *,
    facts: str,
    question: str | None = None,
    preferred_language: str | None = None,
    deciding_court: str | None = None,
    statute_references: list[dict] | None = None,
    fedlex_urls: list[str] | None = None,
    clarifications: list[dict] | None = None,
    limit: int = 8,
) -> dict:
    """
    Build a structured mock-decision outline from facts using:
    - local Swiss caselaw retrieval
    - statute references (explicit + extracted from facts/question)
    - optional statute text enrichment from Fedlex
    """
    facts_text = (facts or "").strip()
    if not facts_text:
        raise ValueError("facts must not be empty")

    preferred_lang = ((preferred_language or "").strip().lower() or None)
    if preferred_lang and preferred_lang not in {"de", "fr", "it", "rm", "en"}:
        raise ValueError("preferred_language must be one of de, fr, it, rm, en")

    limit = max(3, min(int(limit or 8), MAX_FACT_DECISION_LIMIT))
    question_text = (question or "").strip()
    query_text = facts_text if not question_text else f"{facts_text}\n{question_text}"

    statute_requests = _collect_statute_requests(
        query_text=query_text,
        explicit_statutes=statute_references or [],
    )
    case_law = _retrieve_case_law_for_facts(
        query_text=query_text,
        statute_requests=statute_requests,
        preferred_language=preferred_lang,
        limit=limit,
    )
    statute_materials = _resolve_statute_materials(
        statute_requests=statute_requests,
        fedlex_urls=fedlex_urls or [],
        preferred_language=preferred_lang or "de",
    )

    facts_summary = _summarize_facts_text(facts_text)
    key_issues = _derive_key_issues(
        facts_text=facts_text,
        question_text=question_text,
        statute_requests=statute_requests,
        case_law=case_law,
    )
    clarification_questions = _build_clarification_questions(
        facts_text=facts_text,
        question_text=question_text,
        statute_requests=statute_requests,
    )
    clarification_answers = _normalize_clarification_answers(clarifications or [])
    high_priority_ids = [
        q["id"] for q in clarification_questions
        if q.get("priority") == "high"
    ]
    unanswered_high_priority = [
        qid for qid in high_priority_ids
        if not (clarification_answers.get(qid) or "").strip()
    ]
    can_conclude = len(unanswered_high_priority) == 0

    reasoning_steps = _build_reasoning_steps(
        statute_materials=statute_materials,
        case_law=case_law,
        can_conclude=can_conclude,
    )
    outcome_note = (
        _build_outcome_note(case_law=case_law, statute_materials=statute_materials)
        if can_conclude
        else (
            "No conclusion yet. Please answer the high-priority clarification "
            "questions first."
        )
    )

    return {
        "disclaimer": (
            "Research-only mock outline, not legal advice. "
            "Validate against current law and full judgments."
        ),
        "facts_summary": facts_summary,
        "question": question_text or None,
        "deciding_court": deciding_court or "unknown",
        "preferred_language": preferred_lang or "auto",
        "key_issues": key_issues,
        "clarification_gate": {
            "status": "ready_for_conclusion" if can_conclude else "needs_clarification",
            "required_high_priority": high_priority_ids,
            "unanswered_high_priority": unanswered_high_priority,
        },
        "clarifying_questions": clarification_questions,
        "clarification_answers": [
            {"id": qid, "answer": answer}
            for qid, answer in clarification_answers.items()
            if (answer or "").strip()
        ],
        "applicable_statutes": statute_materials,
        "relevant_case_law": case_law,
        "mock_decision": {
            "conclusion_ready": can_conclude,
            "outcome_note": outcome_note,
            "reasoning_steps": reasoning_steps,
            "essential_elements": [
                "Sachverhalt / faits pertinents / fatti rilevanti",
                "Zulässigkeit / recevabilité / ammissibilità",
                "Anwendbare Normen",
                "Subsumtion nach zentralen Tatbestandsmerkmalen",
                "Ergebnis / dispositif",
            ],
        },
    }


def _collect_statute_requests(
    *,
    query_text: str,
    explicit_statutes: list[dict],
) -> list[dict]:
    items: list[dict] = []
    seen: set[str] = set()

    def _add(law_code: str, article: str, paragraph: str | None):
        law = _normalize_statute_law_code(law_code)
        art = (article or "").strip().lower()
        para = (paragraph or "").strip().lower() or None
        if not law or not art:
            return
        key = f"{law}|{art}|{para or ''}"
        if key in seen:
            return
        seen.add(key)
        items.append({
            "law_code": law,
            "article": art,
            "paragraph": para,
            "ref": f"Art. {art}{(' Abs. ' + para) if para else ''} {law}",
        })

    for st in explicit_statutes or []:
        _add(
            str(st.get("law_code") or st.get("law") or ""),
            str(st.get("article") or ""),
            st.get("paragraph"),
        )

    for ref in _extract_query_statute_refs(query_text):
        article, paragraph, law = _parse_statute_ref(ref)
        if article and law:
            _add(law, article, paragraph)

    return items


def _normalize_statute_law_code(value: str) -> str:
    raw = (value or "").strip().upper()
    if not raw:
        return ""
    return re.sub(r"[^A-Z0-9/]+", "", raw)


# Extended stopwords for facts distillation (DE/FR/IT common words unlikely to
# improve legal concept matching in FTS5).
_FACTS_STOPWORDS = NL_STOPWORDS | {
    # German
    "ist", "war", "hat", "wurde", "wird", "sind", "waren", "haben", "hatte",
    "sei", "dass", "sich", "auch", "noch", "nach", "bei", "aus", "mehr",
    "wie", "aber", "wenn", "nur", "es", "er", "sie", "wir", "kann", "dieser",
    "diese", "dieses", "diesem", "diesen", "gegen", "bis", "vom", "seit",
    "seiner", "seine", "seinen", "seinem", "ihrer", "ihre", "ihrem", "ihren",
    "sowie", "bereits", "dabei", "jedoch", "dazu", "daher", "dann", "damit",
    "hier", "dort", "nun", "so", "ob", "da", "vor", "ab", "alle", "allem",
    "allen", "aller", "alles", "andere", "anderen", "anderer", "anderes",
    "wo", "welche", "welcher", "welches", "werden", "worden", "deren",
    "dessen", "gemaess", "gemass", "bzw", "etc", "vgl", "bzw",
    # French
    "est", "sont", "ont", "ete", "par", "pas", "qui", "que", "il", "elle",
    "ils", "elles", "nous", "vous", "son", "ses", "leur", "leurs", "ce",
    "cette", "ces", "mais", "plus", "entre", "aussi", "tres", "bien",
    "fait", "etre", "avoir", "peut", "tout", "tous", "toute", "toutes",
    # Italian
    "che", "non", "sono", "era", "stato", "hanno", "aveva", "come", "anche",
    "piu", "suo", "sua", "suoi", "sue", "questo", "questa", "questi",
    "queste", "dal", "dei", "degli", "alle",
    # Numbers / generic
    "chf", "fr", "eur", "nr", "abs",
}


def _extract_legal_query_from_facts(
    text: str,
    statute_requests: list[dict],
) -> str:
    """Distill a facts narrative into a focused legal query for FTS5.

    Instead of sending the entire narrative (which matches on incidental words
    like city names or party descriptions), this extracts:
    1. Statute references (Art. X Law)
    2. Tokens that appear in LEGAL_QUERY_EXPANSIONS (known legal concepts)
    3. Capitalized German legal nouns (> 5 chars, likely Fachbegriffe)
    Limits output to ~12 most distinctive terms.
    """
    # Collect statute ref strings
    ref_terms: list[str] = []
    for st in statute_requests[:6]:
        ref_terms.append(f'Art. {st["article"]} {st["law_code"]}')

    # Tokenize and normalize
    raw_tokens = re.findall(r"[A-Za-zÀ-ÖØ-öø-ÿß]+", text)
    normalized_tokens: list[str] = []
    seen_norm: set[str] = set()
    for raw in raw_tokens:
        norm = _normalize_token_for_fts(raw)
        if not norm or len(norm) < 3 or norm in _FACTS_STOPWORDS:
            continue
        if norm in seen_norm:
            continue

        # Priority 1: known legal concept in expansion dictionary
        is_legal_concept = norm in LEGAL_QUERY_EXPANSIONS
        # Priority 2: capitalized German noun > 5 chars (likely legal term)
        is_legal_noun = (
            not is_legal_concept
            and raw[0].isupper()
            and len(raw) > 5
            and norm not in {"zurich", "bern", "basel", "luzern", "geneve",
                             "lausanne", "schweiz", "suisse", "svizzera",
                             "kanton", "gemeinde", "bezirk", "herr", "frau",
                             "arbeitnehmer", "arbeitgeber", "klaeger",
                             "beklagter", "beschwerdefuhrer",
                             "beschwerdefuhrerin", "gesuchsteller",
                             "gesuchstellerin"}
        )
        if is_legal_concept or is_legal_noun:
            seen_norm.add(norm)
            # Use original form for FTS matching (FTS5 is case-insensitive)
            normalized_tokens.append((0 if is_legal_concept else 1, raw))

    # Sort: legal concepts first, then legal nouns
    normalized_tokens.sort(key=lambda x: x[0])
    concept_terms = [tok for _priority, tok in normalized_tokens[:12]]

    # Combine: statute refs first, then concept terms
    parts = ref_terms + concept_terms
    if not parts:
        # Fallback: return original text (truncated) if no terms extracted
        return text[:500]

    return " ".join(parts)


def _retrieve_case_law_for_facts(
    *,
    query_text: str,
    statute_requests: list[dict],
    preferred_language: str | None,
    limit: int,
) -> list[dict]:
    pool_limit = min(MAX_LIMIT, max(limit * 3, 18))
    scored: dict[str, dict] = {}

    def _add(rows: list[dict], *, source: str, extra_score: float = 0.0):
        for rank, row in enumerate(rows, start=1):
            decision_id = row.get("decision_id")
            if not decision_id:
                continue
            base = float(row.get("relevance_score") or 0.0)
            rank_bonus = max(0.0, 1.0 - (rank - 1) * 0.04)
            lang_bonus = 0.35 if preferred_language and row.get("language") == preferred_language else 0.0
            score = base + rank_bonus + extra_score + lang_bonus
            current = scored.get(decision_id)
            if current is None or score > float(current["match_score"]):
                scored[decision_id] = {
                    "decision_id": decision_id,
                    "court": row.get("court"),
                    "decision_date": row.get("decision_date"),
                    "docket_number": row.get("docket_number"),
                    "language": row.get("language"),
                    "title": _truncate(row.get("title"), 240),
                    "regeste": _truncate(row.get("regeste"), 320),
                    "snippet": _truncate(row.get("snippet"), 360),
                    "source_url": row.get("source_url"),
                    "source_match": source,
                    "match_score": round(score, 4),
                }

    focused_query = _extract_legal_query_from_facts(query_text, statute_requests)
    base_rows, _ = search_fts5(query=focused_query, limit=pool_limit)
    _add(base_rows, source="facts_query", extra_score=0.4)

    # Broader fallback with raw text at lower weight (only if focused query differs)
    if focused_query != query_text:
        fallback_rows, _ = search_fts5(query=query_text, limit=max(8, pool_limit // 2))
        _add(fallback_rows, source="facts_broad", extra_score=0.15)

    for st in statute_requests[:5]:
        q = f"Art. {st['article']} {st['law_code']}"
        if st.get("paragraph"):
            q = f"Art. {st['article']} Abs. {st['paragraph']} {st['law_code']}"
        rows, _ = search_fts5(query=q, limit=min(25, pool_limit))
        _add(rows, source=f"statute_query:{st['law_code']}:{st['article']}", extra_score=0.55)

    graph_rows = _search_graph_decisions_for_statutes(statute_requests=statute_requests, limit=pool_limit)
    _add(graph_rows, source="statute_graph", extra_score=0.75)

    ranked = sorted(
        scored.values(),
        key=lambda r: (
            -float(r["match_score"]),
            str(r.get("decision_date") or ""),
            str(r.get("decision_id") or ""),
        ),
        reverse=False,
    )
    ranked.sort(key=lambda r: float(r["match_score"]), reverse=True)
    return ranked[:limit]


def _search_graph_decisions_for_statutes(*, statute_requests: list[dict], limit: int) -> list[dict]:
    if not statute_requests:
        return []

    mentions: dict[str, int] = {}
    graph_conn = _get_graph_conn()
    if graph_conn is None:
        return []
    try:
        for st in statute_requests[:8]:
            law = st["law_code"]
            article = st["article"]
            paragraph = st.get("paragraph")
            if paragraph:
                rows = graph_conn.execute(
                    """
                    SELECT ds.decision_id, SUM(ds.mention_count) AS n
                    FROM decision_statutes ds
                    JOIN statutes s ON s.statute_id = ds.statute_id
                    WHERE s.law_code = ? AND s.article = ? AND IFNULL(s.paragraph, '') = ?
                    GROUP BY ds.decision_id
                    ORDER BY n DESC
                    LIMIT ?
                    """,
                    (law, article, paragraph, max(20, limit)),
                ).fetchall()
            else:
                rows = graph_conn.execute(
                    """
                    SELECT ds.decision_id, SUM(ds.mention_count) AS n
                    FROM decision_statutes ds
                    JOIN statutes s ON s.statute_id = ds.statute_id
                    WHERE s.law_code = ? AND s.article = ?
                    GROUP BY ds.decision_id
                    ORDER BY n DESC
                    LIMIT ?
                    """,
                    (law, article, max(20, limit)),
                ).fetchall()
            for row in rows:
                did = row["decision_id"]
                mentions[did] = mentions.get(did, 0) + int(row["n"] or 0)
    except sqlite3.Error as e:
        logger.debug("Graph statute lookup failed: %s", e)
        return []
    finally:
        graph_conn.close()

    ranked_ids = [
        did for did, _n in sorted(mentions.items(), key=lambda x: x[1], reverse=True)[:limit]
    ]
    if not ranked_ids:
        return []
    rows = _fetch_decision_rows_by_ids(ranked_ids)
    rows_by_id = {r["decision_id"]: r for r in rows}
    out: list[dict] = []
    for did in ranked_ids:
        row = rows_by_id.get(did)
        if not row:
            continue
        mention_count = mentions.get(did, 0)
        out.append({
            "decision_id": row["decision_id"],
            "court": row["court"],
            "decision_date": row["decision_date"],
            "docket_number": row["docket_number"],
            "language": row["language"],
            "title": row.get("title"),
            "regeste": row.get("regeste"),
            "snippet": row.get("regeste"),
            "source_url": row.get("source_url"),
            "relevance_score": 0.25 + min(2.0, mention_count * 0.1),
        })
    return out


def _fetch_decision_rows_by_ids(decision_ids: list[str]) -> list[dict]:
    ids = [d for d in dict.fromkeys(decision_ids) if d]
    if not ids:
        return []
    # Expand each ID to all format variants so graph-format IDs (e.g. "bge_126 I 97")
    # also match FTS5-format IDs (e.g. "bge_BGE_126_I_97").
    expanded = list(dict.fromkeys(v for did in ids for v in _decision_id_variants(did)))
    conn = get_db()
    try:
        placeholders = ",".join("?" for _ in expanded)
        rows = conn.execute(
            f"""
            SELECT decision_id, court, decision_date, docket_number, language,
                   title, regeste, source_url
            FROM decisions
            WHERE decision_id IN ({placeholders})
            """,
            tuple(expanded),
        ).fetchall()
        return [dict(r) for r in rows]
    finally:
        conn.close()


def _resolve_statute_materials(
    *,
    statute_requests: list[dict],
    fedlex_urls: list[str],
    preferred_language: str,
) -> list[dict]:
    if not statute_requests:
        return []

    cache = _load_fedlex_cache()
    out: list[dict] = []
    dirty_cache = False
    for st in statute_requests[:8]:
        resolved = _resolve_fedlex_statute_article(
            law_code=st["law_code"],
            article=st["article"],
            paragraph=st.get("paragraph"),
            preferred_language=preferred_language,
            fedlex_urls=fedlex_urls,
            cache=cache,
        )
        out.append(resolved)
        if resolved.get("_cache_dirty"):
            dirty_cache = True

    if dirty_cache:
        _save_fedlex_cache(cache)
    for row in out:
        row.pop("_cache_dirty", None)
    return out


def _resolve_fedlex_statute_article(
    *,
    law_code: str,
    article: str,
    paragraph: str | None,
    preferred_language: str,
    fedlex_urls: list[str],
    cache: dict,
) -> dict:
    result = {
        "law_code": law_code,
        "article": article,
        "paragraph": paragraph,
        "ref": f"Art. {article}{(' Abs. ' + paragraph) if paragraph else ''} {law_code}",
        "fedlex_url": None,
        "text_excerpt": None,
        "status": "not_fetched",
        "_cache_dirty": False,
    }
    candidates = _fedlex_candidate_urls(
        law_code=law_code,
        preferred_language=preferred_language,
        explicit_urls=fedlex_urls,
    )
    if not candidates:
        result["status"] = "no_candidate_url"
        return result

    for url in candidates:
        cache_key = f"{url}|{law_code}|{article}|{paragraph or ''}|{preferred_language}"
        cached = cache.get(cache_key)
        if isinstance(cached, dict) and cached.get("text_excerpt"):
            result["fedlex_url"] = cached.get("fedlex_url") or url
            result["text_excerpt"] = cached["text_excerpt"]
            result["status"] = "cache_hit"
            return result

        fetched = _fetch_fedlex_article_text(
            url=url,
            article=article,
            paragraph=paragraph,
        )
        if fetched:
            result["fedlex_url"] = fetched.get("fedlex_url") or url
            result["text_excerpt"] = fetched.get("text_excerpt")
            result["status"] = "fetched"
            cache[cache_key] = {
                "fedlex_url": result["fedlex_url"],
                "text_excerpt": result["text_excerpt"],
                "fetched_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            }
            result["_cache_dirty"] = True
            return result

    result["status"] = "fetch_failed"
    if candidates:
        result["fedlex_url"] = candidates[0]
    return result


def _fedlex_candidate_urls(
    *,
    law_code: str,
    preferred_language: str,
    explicit_urls: list[str],
) -> list[str]:
    lang = (preferred_language or "de").lower()
    out: list[str] = []
    seen: set[str] = set()

    # SSRF guard: fedlex_urls is a public, user-supplied field on the mock-
    # decision request, and each candidate is fetched with requests.get() (which
    # follows redirects). Without this check a caller could point it at
    # http://127.0.0.1:8770 / RFC1918 / cloud-metadata and read internal
    # responses back. Only https URLs on the Fedlex host are ever fetchable; the
    # field is semantically Fedlex-only, so this does not restrict legitimate
    # use. Applies to the internally-built base URLs too (they are fedlex hosts).
    _ALLOWED_FEDLEX_HOSTS = {"www.fedlex.admin.ch", "fedlex.admin.ch"}

    def _add(url: str):
        u = (url or "").strip()
        if not u or u in seen:
            return
        try:
            parsed = urllib.parse.urlparse(u)
        except Exception:
            return
        if parsed.scheme != "https":
            return
        if (parsed.hostname or "").lower() not in _ALLOWED_FEDLEX_HOSTS:
            return
        seen.add(u)
        out.append(u)

    for url in explicit_urls:
        _add(url)
        _add(f"{url.rstrip('/')}/{lang}")

    base = FEDLEX_LAW_CODE_BASE_URLS.get(_normalize_statute_law_code(law_code))
    if base:
        _add(base)
        _add(f"{base.rstrip('/')}/{lang}")

    return out[:8]


def _fetch_fedlex_article_text(*, url: str, article: str, paragraph: str | None) -> dict | None:
    try:
        import requests
    except Exception:
        return None

    headers = {"User-Agent": FEDLEX_USER_AGENT}
    try:
        resp = requests.get(url, headers=headers, timeout=FEDLEX_TIMEOUT_SECONDS)
        if resp.status_code >= 400 or not resp.text:
            return None
    except Exception:
        return None

    excerpt = _extract_article_excerpt_from_html(
        html=resp.text,
        article=article,
        paragraph=paragraph,
    )
    if not excerpt:
        return None
    return {
        "fedlex_url": resp.url or url,
        "text_excerpt": excerpt,
    }


def _extract_article_excerpt_from_html(*, html: str, article: str, paragraph: str | None) -> str | None:
    compact = re.sub(r"(?is)<(script|style).*?>.*?</\\1>", " ", html or "")
    compact = re.sub(r"(?s)<[^>]+>", " ", compact)
    compact = html_lib.unescape(compact)
    compact = re.sub(r"\s+", " ", compact).strip()
    if not compact:
        return None

    art = re.escape((article or "").strip())
    if not art:
        return None

    block_pattern = re.compile(
        rf"(Art\.?\s*{art}[a-zA-Z]?\b.*?)(?=Art\.?\s*\d+[a-zA-Z]?\b|$)",
        flags=re.IGNORECASE | re.DOTALL,
    )
    match = block_pattern.search(compact)
    if not match:
        return None

    excerpt = match.group(1).strip()
    if paragraph:
        para_text = str(paragraph).strip().lower()
        if para_text and f"abs. {para_text}" not in excerpt.lower():
            # Keep the article block anyway; Fedlex formatting differs by language.
            pass

    return _truncate(excerpt, 1200)


def _load_fedlex_cache() -> dict:
    if not FEDLEX_CACHE_PATH.exists():
        return {}
    try:
        payload = json.loads(FEDLEX_CACHE_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return payload if isinstance(payload, dict) else {}


def _save_fedlex_cache(cache: dict):
    try:
        FEDLEX_CACHE_PATH.parent.mkdir(parents=True, exist_ok=True)
        FEDLEX_CACHE_PATH.write_text(
            json.dumps(cache, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
    except Exception as e:
        logger.debug("Failed to persist Fedlex cache: %s", e)


def _summarize_facts_text(text: str) -> str:
    parts = [p.strip() for p in re.split(r"(?:\n+|(?<=[.!?])\s+)", text or "") if p.strip()]
    if not parts:
        return ""
    return " ".join(parts[:3])


def _derive_key_issues(
    *,
    facts_text: str,
    question_text: str,
    statute_requests: list[dict],
    case_law: list[dict],
) -> list[str]:
    issues: list[str] = []
    rank_terms = _extract_rank_terms(f"{facts_text} {question_text}")
    if statute_requests:
        refs = ", ".join(st["ref"] for st in statute_requests[:4])
        issues.append(f"Auslegung und Anwendung von {refs}.")
    if any(t in ASYL_QUERY_TERMS for t in rank_terms):
        issues.append("Materiell- und verfahrensrechtliche Anforderungen im Asyl-/Wegweisungskontext.")
    if case_law:
        courts = sorted({str(c.get("court") or "") for c in case_law[:6] if c.get("court")})
        if courts:
            issues.append(f"Einordnung in die publizierte Rechtsprechung ({', '.join(courts)}).")
    if not issues:
        issues.append("Subsumtion der Tatsachen unter die wahrscheinlich einschlägigen Normen.")
    return issues[:5]


def _build_clarification_questions(
    *,
    facts_text: str,
    question_text: str,
    statute_requests: list[dict],
) -> list[dict]:
    text = (facts_text + " " + question_text).lower()
    out: list[dict] = []

    def _add(question_id: str, prompt: str, why: str, priority: str = "high"):
        out.append({
            "id": question_id,
            "question": prompt,
            "why_it_matters": why,
            "priority": priority,
        })

    if not re.search(r"\b(20\d{2}|19\d{2})\b", text):
        _add(
            "timeline_dates",
            "What are the key dates (administrative decision, service date, appeal filing date)?",
            "Admissibility and deadline checks depend on exact timing.",
            "high",
        )

    if not re.search(
        r"\b(beschwerde|rekurs|einsprache|appeal|recours|ricorso|verfahren|proc[eé]dure)\b",
        text,
    ):
        _add(
            "procedural_posture",
            "What is the procedural posture (first instance, appeal, or extraordinary remedy)?",
            "Applicable standards and review scope differ by stage.",
            "high",
        )

    if not re.search(
        r"\b(beantragt|antrag|relief|conclusion|conclusions|demande|fordert|wants|seek)\b",
        text,
    ):
        _add(
            "requested_relief",
            "What exact relief is requested (annulment, remand, stay, damages, etc.)?",
            "The dispositive part must match the requested remedy.",
            "high",
        )

    if not re.search(r"\b(sem|kanton|tribunal|gericht|beh[oö]rde|autorit[eé])\b", text):
        _add(
            "issuing_authority",
            "Which authority/court issued the contested decision?",
            "Jurisdiction and legal basis depend on the issuing authority.",
            "medium",
        )

    rank_terms = set(_extract_rank_terms(text))
    if rank_terms.intersection(ASYL_QUERY_TERMS):
        if not re.search(
            r"\b(herkunft|nationalit[aä]t|ethnie|religion|origin|nationality|provenance)\b",
            text,
        ):
            _add(
                "asylum_profile",
                "What is the claimant's origin/profile relevant for asylum risk assessment?",
                "Risk assessment requires country/profile-specific facts.",
                "high",
            )
        if not re.search(
            r"\b(verfolg|gef[aä]hrd|risk|risque|danger|torture|persecution)\b",
            text,
        ):
            _add(
                "asylum_risk",
                "What concrete persecution or return risks are alleged and evidenced?",
                "Material asylum analysis turns on individualized risk.",
                "high",
            )

    if statute_requests and not re.search(
        r"\b(beweis|evidence|preuve|prova|akten|document|unterlagen)\b",
        text,
    ):
        _add(
            "evidence_status",
            "Which key evidence is available or disputed?",
            "Subsumption under statutes depends on proven facts.",
            "medium",
        )

    return out[:8]


def _normalize_clarification_answers(clarifications: list[dict]) -> dict[str, str]:
    out: dict[str, str] = {}
    for item in clarifications or []:
        if not isinstance(item, dict):
            continue
        qid = str(item.get("id") or "").strip()
        answer = str(item.get("answer") or "").strip()
        if qid and answer:
            out[qid] = answer
    return out


def _build_reasoning_steps(
    *,
    statute_materials: list[dict],
    case_law: list[dict],
    can_conclude: bool,
) -> list[str]:
    steps = [
        "Sachverhalt strukturieren und streitige Kerntatsachen festhalten.",
        "Zulässigkeit/Vorfragen prüfen (Zuständigkeit, Fristen, Beschwerdelegitimation).",
    ]
    if statute_materials:
        refs = ", ".join(st["ref"] for st in statute_materials[:4])
        steps.append(f"Normative Prüfung entlang der Normen: {refs}.")
    if case_law:
        top = ", ".join(
            f"{c.get('docket_number') or c.get('decision_id')}"
            for c in case_law[:3]
        )
        steps.append(f"Abgleich mit Leitlinien aus den ähnlichsten Entscheiden ({top}).")
    if can_conclude:
        steps.append("Ergebnis mit Begründungstiefe und offenem Risikoabschnitt formulieren.")
    else:
        steps.append(
            "Vorläufige Einordnung ohne Schlussfolgerung; zuerst offene Klärungsfragen beantworten."
        )
    return steps


def _build_outcome_note(*, case_law: list[dict], statute_materials: list[dict]) -> str:
    if not case_law:
        return "Zu wenige vergleichbare Entscheide für eine belastbare Tendenz."
    if statute_materials and any(st.get("text_excerpt") for st in statute_materials):
        return "Tendenz auf Basis ähnlicher Entscheide und verfügbarer Normtexte; Ergebnis bleibt fallabhängig."
    return "Tendenz nur auf Basis caselaw-Ähnlichkeit; Normtexte konnten nicht vollständig geladen werden."


def _dedup_bge_citations(items: list[dict], id_key: str) -> list[dict]:
    """Deduplicate BGE citation entries that appear with two ID formats."""
    seen: set[str] = set()
    out: list[dict] = []
    for c in items:
        did = c.get(id_key) or ""
        court = c.get("court") or ""
        dn = re.sub(r"[^A-Z0-9]", "", (c.get("docket_number") or did).upper())
        if court == "bge":
            dn = re.sub(r"^(?:CH)?(?:BGE|ATF|DTF)", "", dn)
        key = f"{court}|{dn}"
        if key not in seen:
            seen.add(key)
            out.append(c)
    return out


def _norm_cite_ref(s: str | None) -> str:
    """Normalize a citation ref (docket or BGE) for self-reference comparison:
    strip a BGE/ATF/DTF prefix, reduce to uppercase alphanumerics."""
    u = re.sub(r"[^A-Z0-9]", "", (s or "").upper())
    return re.sub(r"^(?:CH)?(?:BGE|ATF|DTF)", "", u)


def _filter_self_citations(raw_cited, result: dict):
    """Drop self-references from a decision's cited_decisions list (audit M-2):
    a BGE excerpt regex-harvests its OWN caption docket (e.g. 9C_113/2025 for BGE
    152 II 1) and BGE number into its own citation list. Returns a cleaned
    list[str], or None if nothing meaningful remains."""
    if not raw_cited:
        return None
    try:
        refs = json.loads(raw_cited) if isinstance(raw_cited, str) else raw_cited
    except Exception:
        return raw_cited if isinstance(raw_cited, list) else None
    if not isinstance(refs, list):
        return None
    selves = {_norm_cite_ref(result.get("docket_number")), _norm_cite_ref(result.get("decision_id"))}
    if _dft is not None:
        try:
            cap = _dft.extract_docket(result.get("full_text"))
            if cap:
                selves.add(_norm_cite_ref(cap))
        except Exception:
            pass
    selves.discard("")
    out = [r for r in refs if _norm_cite_ref(r) not in selves]
    return out or None


def _override_citation_dates(items, id_key):
    """find_citations dates come from the citation graph's OWN decisions copy,
    which carries the pre-correction synthetic dates (audit v5: the date re-index
    reached search + record view but not reference_graph.db). Override each item's
    decision_date with the corrected FTS decisions.db value. Graceful: on any
    failure the original (graph) date is kept."""
    ids = [c.get(id_key) for c in (items or []) if c.get(id_key)]
    if not ids:
        return items
    try:
        conn = get_db()
        ph = ",".join("?" * len(ids))
        dm = {r[0]: r[1] for r in conn.execute(
            f"SELECT decision_id, decision_date FROM decisions WHERE decision_id IN ({ph})",
            ids)}
    except Exception:
        return items
    for c in items:
        cid = c.get(id_key)
        if cid and dm.get(cid):
            c["decision_date"] = dm[cid]
    return items


def _format_citations_response(result: dict) -> str:
    """Format find_citations result into markdown.
    Every cited/citing decision is rendered as a Markdown link so the
    end-user (in ChatGPT/Claude/Copilot) can click through to verify."""
    if result.get("error"):
        return result["error"]

    did = result["decision_id"]
    self_url = _canonical_decision_url(did)
    text = f"# Citations for {_md_link(did, self_url)}\n\n"

    # KNOWN LIMITATION (#49): BGE dual-ID-format dedup (_dedup_bge_citations)
    # runs per response, AFTER SQL offset/limit paging. So a decision cited under
    # two BGE ID formats could, near a page boundary, appear on two adjacent
    # pages. Low severity (dual-ID BGE citations only, only when paginating).
    # A full fix means de-duping before paging (fetch-all-then-slice), which
    # sacrifices LIMIT/OFFSET efficiency on decisions with thousands of cites.
    offset = result.get("offset", 0)

    def _range_hdr(returned: int, total, has_more: bool) -> str:
        if total is None:
            return f"{returned}"
        if returned == 0:
            # No rows on this page \u2014 e.g. offset past the end. Avoid a nonsensical
            # "201-200 of 163" range (Codex review). Only call it "beyond end" when
            # the caller actually paged forward (offset>0); offset 0 with total 0 is
            # just an empty first page, not a bad offset.
            beyond = offset > 0 and offset >= total
            return f"0 of {total}" + (f" (offset {offset} beyond end)" if beyond else "")
        base = f"{returned} of {total}"
        if offset:
            base = f"{offset + 1}-{offset + returned} of {total}"
        if has_more:
            base += f", truncated \u2014 next_offset={result.get('next_offset')}"
        return base

    outgoing = result.get("outgoing")
    if outgoing is not None:
        raw_n = result.get("outgoing_returned", len(outgoing))
        outgoing = _dedup_bge_citations(outgoing, "target_decision_id")
        outgoing = _override_citation_dates(outgoing, "target_decision_id")
        hdr = _range_hdr(raw_n, result.get("outgoing_total"),
                         result.get("outgoing_has_more", False))
        text += f"## Outgoing ({hdr} \u2014 what this decision cites)\n"
        if not outgoing:
            text += "No outgoing citations found.\n"
        for i, c in enumerate(outgoing, 1):
            target_did = c.get("target_decision_id")
            if target_did:
                docket = c.get("docket_number") or target_did
                date = c.get("decision_date") or ""
                court = c.get("court") or ""
                conf = c.get("confidence_score")
                mentions = c.get("mention_count") or 1
                conf_str = f" conf={conf:.2f}" if conf is not None else ""
                link = _md_link(docket, _canonical_decision_url(target_did))
                text += f"{i}. {link} ({date}) [{court}]{conf_str} mentions={mentions}\n"
            else:
                ref = c.get("target_ref", "?")
                ttype = c.get("target_type", "")
                mentions = c.get("mention_count") or 1
                text += f"{i}. {ref} (unresolved, type={ttype}) mentions={mentions}\n"
        text += "\n"

    incoming = result.get("incoming")
    if incoming is not None:
        raw_n = result.get("incoming_returned", len(incoming))
        incoming = _dedup_bge_citations(incoming, "source_decision_id")
        incoming = _override_citation_dates(incoming, "source_decision_id")
        hdr = _range_hdr(raw_n, result.get("incoming_total"),
                         result.get("incoming_has_more", False))
        text += f"## Incoming ({hdr} \u2014 what cites this decision)\n"
        if not incoming:
            text += "No incoming citations found.\n"
        for i, c in enumerate(incoming, 1):
            src_did = c.get("source_decision_id", "?")
            docket = c.get("docket_number") or src_did
            date = c.get("decision_date") or ""
            court = c.get("court") or ""
            conf = c.get("confidence_score")
            mentions = c.get("mention_count") or 1
            conf_str = f" conf={conf:.2f}" if conf is not None else ""
            link = _md_link(docket, _canonical_decision_url(src_did))
            text += f"{i}. {link} ({date}) [{court}]{conf_str} mentions={mentions}\n"

    return text


def _format_appeal_chain_response(result: dict) -> str:
    """Format find_appeal_chain result into markdown."""
    if result.get("error"):
        return result["error"]

    chain = result.get("chain", [])
    did = result.get("decision_id", "?")
    court = result.get("court", "?")
    docket = _normalize_federal_docket(
        _clean_docket(result.get("docket_number")), court) or did
    date = result.get("decision_date", "?")

    self_link = _md_link(docket, _canonical_decision_url(did))
    if not chain:
        return (
            f"# Appeal chain for {self_link}\n\n"
            f"{self_link} ({date}) [{court}]\n\n"
            f"No prior or subsequent instances found in the database.\n"
            f"This may mean the decision is not an appeal, or the lower/upper court "
            f"decisions are not in the dataset."
        )

    text = f"# Appeal chain for {self_link}\n\n"
    text += f"**Query decision:** {self_link} ({date}) [{court}]\n\n"

    prior = [c for c in chain if c.get("relation") == "prior_instance"]
    subsequent = [c for c in chain if c.get("relation") == "subsequent_instance"]

    if prior:
        text += f"## Prior instances ({len(prior)})\n"
        text += "Decisions that were appealed (lower courts):\n\n"
        for c in prior:
            conf = c.get("confidence", 0)
            link = _md_link(c["docket_number"], _canonical_decision_url(c["decision_id"]))
            text += f"- {link} ({c.get('decision_date', '?')}) [{c['court']}] conf={conf:.2f}\n"
        text += "\n"

    if subsequent:
        text += f"## Subsequent instances ({len(subsequent)})\n"
        text += "Decisions that appealed this one (higher courts):\n\n"
        for c in subsequent:
            conf = c.get("confidence", 0)
            link = _md_link(c["docket_number"], _canonical_decision_url(c["decision_id"]))
            text += f"- {link} ({c.get('decision_date', '?')}) [{c['court']}] conf={conf:.2f}\n"
        text += "\n"

    # Visual chain — each step is its own clickable link.
    prior_sorted = sorted(prior, key=lambda x: x.get("decision_date") or "")
    subsequent_sorted = sorted(subsequent, key=lambda x: x.get("decision_date") or "")
    def _step(c):
        return f"{_md_link(c['docket_number'], _canonical_decision_url(c['decision_id']))} [{c['court']}]"
    chain_labels = (
        [_step(c) for c in prior_sorted]
        + [f"{self_link} [{court}]"]
        + [_step(c) for c in subsequent_sorted]
    )

    text += "## Instanzenzug\n"
    text += " → ".join(chain_labels) + "\n"

    return text


def _format_leading_cases_response(result: dict) -> str:
    """Format find_leading_cases result into markdown."""
    if result.get("error"):
        return result["error"]

    items = result.get("results", [])
    total = result.get("total", 0)
    law_code = result.get("law_code")
    article = result.get("article")
    query = result.get("query")

    header_parts = []
    if law_code and article:
        header_parts.append(f"Art. {article} {law_code}")
    if query:
        header_parts.append(f'"{query}"')
    header = " + ".join(header_parts) if header_parts else "all"

    topical = bool(items) and any("topic_citation_count" in r for r in items)
    if topical:
        text = (f"# Leading Cases on {header} "
                f"(top {total}, ranked by citations from decisions applying this provision)\n\n")
    else:
        text = f"# Leading Cases ({header}, top {total} most-cited)\n\n"
    if result.get("filters_relaxed") and result.get("note"):
        text += f"_Note: {result['note']}_\n\n"
    if not items:
        text += "No results found.\n"
        return text

    for i, r in enumerate(items, 1):
        link = _md_link(r['docket_number'], _canonical_decision_url(r['decision_id']))
        tc = r.get("topic_citation_count")
        if tc is not None:
            # statute path: ranked by topical citations (the list IS sorted by this);
            # the global count is shown for context, not the ranking key.
            cite_str = (f"**{tc} citations from {header} cases** "
                        f"({r['citation_count']} total)")
        else:
            cite_str = f"**{r['citation_count']} citations**"
        text += (
            f"**{i}.** {link} ({r['decision_date']}) [{r['court']}] \u2014 {cite_str}\n"
        )
        if r.get("regeste"):
            text += f"   Regeste: {_auto_link_citations(r['regeste'])}\n"
        pp = r.get("pinpoint")
        if pp:
            pp_link = _md_link(f"E. {pp['e_number']}", pp.get("url") or "")
            sentence = (pp.get("matched_sentence") or "").strip()
            if len(sentence) > 220:
                sentence = sentence[:217].rstrip() + "…"
            text += f"   📍 {pp_link} ({pp['confidence']}): {sentence}\n"
        text += "\n"

    return text


def _format_trend_response(result: dict) -> str:
    """Format analyze_legal_trend result into markdown."""
    if result.get("error"):
        return result["error"]

    years = result.get("years", [])
    total = result.get("total", 0)
    law_code = result.get("law_code")
    article = result.get("article")
    query = result.get("query")

    header_parts = []
    if law_code and article:
        header_parts.append(f"Art. {article} {law_code}")
    if query:
        header_parts.append(f'"{query}"')
    header = " + ".join(header_parts) if header_parts else "all"

    text = "# Legal Trend Analysis\n"
    text += f"**Filter:** {header}\n"
    text += f"**Total:** {total:,} decisions\n\n"

    if not years:
        text += "No data found.\n"
        return text

    max_count = max(y["count"] for y in years)
    bar_max = 40  # max bar width in chars

    text += f"{'Year':<6} {'Count':>7}  Bar\n"
    text += "-" * 60 + "\n"
    for y in years:
        bar_len = round(y["count"] / max_count * bar_max) if max_count > 0 else 0
        bar = "\u2588" * bar_len
        text += f"{y['year']:<6} {y['count']:>7,}  {bar}\n"

    return text


def _format_mock_decision_report(report: dict) -> str:
    text = "# Mock Decision Outline\n"
    text += f"**Disclaimer:** {report.get('disclaimer')}\n\n"
    text += f"**Deciding court (hypothetical):** {report.get('deciding_court')}\n"
    text += f"**Language:** {report.get('preferred_language')}\n\n"
    text += "## Facts Summary\n"
    text += (report.get("facts_summary") or "-") + "\n\n"
    if report.get("question"):
        text += "## Question\n"
        text += report["question"] + "\n\n"

    text += "## Key Issues\n"
    for issue in report.get("key_issues", []):
        text += f"- {issue}\n"
    text += "\n"

    gate = report.get("clarification_gate") or {}
    text += "## Clarification Gate\n"
    text += f"- Status: {gate.get('status')}\n"
    unanswered = gate.get("unanswered_high_priority") or []
    if unanswered:
        text += f"- Unanswered high-priority IDs: {', '.join(unanswered)}\n"
    else:
        text += "- All high-priority clarification questions answered.\n"
    text += "\n"

    text += "## Clarifying Questions\n"
    questions = report.get("clarifying_questions") or []
    if not questions:
        text += "- No additional clarification questions identified.\n\n"
    else:
        for q in questions:
            text += f"- [{q.get('priority')}] {q.get('id')}: {q.get('question')}\n"
            if q.get("why_it_matters"):
                text += f"  Why: {q.get('why_it_matters')}\n"
        text += "\n"

    answers = report.get("clarification_answers") or []
    if answers:
        text += "## Clarification Answers Provided\n"
        for ans in answers:
            text += f"- {ans.get('id')}: {ans.get('answer')}\n"
        text += "\n"

    text += "## Applicable Statutes (Fedlex)\n"
    statutes = report.get("applicable_statutes") or []
    if not statutes:
        text += "- No statute references detected.\n\n"
    else:
        for st in statutes:
            text += f"- **{st.get('ref')}** ({st.get('status')})\n"
            if st.get("fedlex_url"):
                text += f"  Source: {st['fedlex_url']}\n"
            if st.get("text_excerpt"):
                text += f"  Excerpt: {st['text_excerpt']}\n"
        text += "\n"

    text += "## Most Relevant Case Law\n"
    cases = report.get("relevant_case_law") or []
    if not cases:
        text += "- No sufficiently similar decisions found.\n\n"
    else:
        for i, row in enumerate(cases, start=1):
            text += (
                f"{i}. **{row.get('docket_number') or row.get('decision_id')}** "
                f"({row.get('decision_date')}, {row.get('court')}, {row.get('language')})\n"
            )
            if row.get("title"):
                text += f"   Title: {row['title']}\n"
            if row.get("regeste"):
                text += f"   Regeste: {row['regeste']}\n"
            if row.get("snippet"):
                text += f"   Snippet: {row['snippet']}\n"
            if row.get("source_url"):
                text += f"   URL: {row['source_url']}\n"
            text += f"   Match: {row.get('source_match')} | Score: {row.get('match_score')}\n\n"

    mock = report.get("mock_decision") or {}
    text += "## Mock Decision Elements\n"
    text += f"- Outcome note: {mock.get('outcome_note')}\n"
    for step in mock.get("reasoning_steps", []):
        text += f"- {step}\n"
    text += "\n"
    text += "## Essential Structure\n"
    for elem in mock.get("essential_elements", []):
        text += f"- {elem}\n"
    return text


def get_statistics(
    court: str | None = None,
    canton: str | None = None,
    year: int | None = None,
) -> dict:
    """Get aggregate statistics."""
    key = ("get_statistics", court, canton, year)
    cached = _cache_get(key)
    if cached is not None:
        return cached

    conn = get_db()

    filters = []
    params: list = []
    if court:
        filters.append("court = ?")
        params.append(court.lower())
    if canton:
        filters.append("canton = ?")
        params.append(canton.upper())
    if year:
        filters.append("decision_date LIKE ?")
        params.append(f"{year}-%")

    where = ("WHERE " + " AND ".join(filters)) if filters else ""

    total = conn.execute(
        f"SELECT COUNT(*) FROM decisions {where}", params
    ).fetchone()[0]

    by_court = conn.execute(
        f"SELECT court, COUNT(*) as n FROM decisions {where} GROUP BY court ORDER BY n DESC",
        params,
    ).fetchall()

    by_language = conn.execute(
        f"SELECT language, COUNT(*) as n FROM decisions {where} GROUP BY language ORDER BY n DESC",
        params,
    ).fetchall()

    by_year = conn.execute(
        f"SELECT substr(decision_date, 1, 4) as year, COUNT(*) as n "
        f"FROM decisions {where} GROUP BY year ORDER BY year DESC LIMIT 20",
        params,
    ).fetchall()

    conn.close()

    return _cache_set(key, {
        "total": total,
        "by_court": {r["court"]: r["n"] for r in by_court},
        "by_language": {r["language"]: r["n"] for r in by_language},
        "by_year": {r["year"]: r["n"] for r in by_year},
    })


def list_courts() -> list[dict]:
    """List all available courts with decision counts."""
    key = ("list_courts",)
    cached = _cache_get(key)
    if cached is not None:
        return cached

    conn = get_db()
    rows = conn.execute("""
        SELECT
            court,
            canton,
            COUNT(*) as decision_count,
            MIN(decision_date) as earliest,
            MAX(decision_date) as latest,
            COUNT(DISTINCT language) as languages
        FROM decisions
        GROUP BY court, canton
        ORDER BY decision_count DESC
    """).fetchall()
    conn.close()
    today = datetime.now().date().isoformat()
    out = []
    for r in rows:
        d = dict(r)
        # L-2: flag near-empty collections — a null result there proves nothing.
        d["sparse"] = (d.get("decision_count") or 0) < 15
        # L-4: `latest` is an unvalidated max(date); flag when it is in the future
        # (the M-1 cantonal date-parse bug surfaces here as a headline figure).
        lat = d.get("latest") or ""
        if lat and lat > today:
            d["latest_unvalidated"] = True
        out.append(d)
    return _cache_set(key, out)


def _list_recent(
    conn: sqlite3.Connection,
    court: str | None,
    canton: str | None,
    language: str | None,
    date_from: str | None,
    date_to: str | None,
    chamber: str | None = None,
    decision_type: str | None = None,
    limit: int = DEFAULT_LIMIT,
    offset: int = 0,
    sort: str | None = None,
    marked_for_publication: bool | None = None,
) -> tuple[list[dict], int]:
    """List recent decisions without FTS query (just filters).
    Returns (results, total_count) with exact count."""
    filters = []
    params: list = []

    if court:
        filters.append("court = ?")
        params.append(court.lower())
    if canton:
        filters.append("canton = ?")
        params.append(canton.upper())
    if language:
        filters.append("language = ?")
        params.append(language.lower())
    if date_from:
        filters.append("decision_date >= ?")
        params.append(date_from)
    if date_to:
        filters.append("decision_date <= ?")
        params.append(date_to)
    if chamber:
        filters.append("chamber LIKE ?")
        params.append(f"%{chamber}%")
    if decision_type:
        filters.append("decision_type LIKE ?")
        params.append(f"%{decision_type}%")
    if marked_for_publication and _sqlite_has_column(conn, "decisions", "marked_for_publication"):
        filters.append("marked_for_publication = 1")

    where = ("WHERE " + " AND ".join(filters)) if filters else ""

    total_count = conn.execute(
        f"SELECT COUNT(*) FROM decisions {where}", params,
    ).fetchone()[0]

    order_dir = "ASC" if sort == "date_asc" else "DESC"
    rows = conn.execute(
        f"""SELECT decision_id, court, canton, chamber, docket_number,
            decision_date, language, title, regeste, source_url, pdf_url
        FROM decisions {where}
        ORDER BY decision_date {order_dir}
        LIMIT ? OFFSET ?""",
        params + [limit, offset],
    ).fetchall()

    return [dict(r) for r in rows], total_count


def _truncate(text: str | None, max_len: int) -> str | None:
    if not text:
        return None
    if len(text) <= max_len:
        return text
    return text[:max_len] + "..."


# ── Multilingual regeste extraction ──────────────────────────

# BGE regestes are stored as a single concatenated field with language
# blocks separated by "Regeste\n" (DE/FR) and "Regesto\n" (IT) headers.
# Example: "Regeste\n Mobbing; ...\nRegeste\n Résiliation abusive; ...\nRegesto\n ..."
_REGESTE_SPLIT_RE = re.compile(
    r"\n(?=Regeste(?:\s*[a-z])?\s*\n)"  # FR/DE: "Regeste\n" or "Regeste a\n"
    r"|\n(?=Regesto\s*\n)",             # IT: "Regesto\n"
    re.I,
)
_REGESTE_LANG_HINTS = {
    "de": ("Regeste",),
    "fr": ("Regeste",),  # FR also uses "Regeste" header — detected by content
    "it": ("Regesto",),
}
_FR_CONTENT_MARKERS = (
    "résiliation", "recours", "droit", "tribunal", "loi", "art.",
    "fédéral", "cantonal", "arrêt", "contrat", "responsabilité",
)
_IT_CONTENT_MARKERS = (
    "ricorso", "diritto", "tribunale", "legge", "contratto",
    "federale", "cantonale", "sentenza", "responsabilità",
)


def _extract_regeste_for_language(
    regeste: str | None, language: str
) -> str | None:
    """Extract the language-specific block from a multilingual BGE regeste.

    Returns the block matching ``language``, or the original text if only
    one block exists or if the requested language cannot be identified.
    """
    if not regeste:
        return regeste
    language = (language or "de").lower()

    # Split into blocks
    blocks = _REGESTE_SPLIT_RE.split(regeste)
    if len(blocks) <= 1:
        return regeste  # not multilingual

    # For DE: always the first block (BGE regeste order is DE → FR → IT)
    if language == "de":
        return blocks[0].strip()

    # For FR: find the block that starts with "Regeste" AND has French content
    if language == "fr":
        for block in blocks[1:]:
            lower = block[:500].lower()
            if any(m in lower for m in _FR_CONTENT_MARKERS):
                return block.strip()
        # Fallback: second block is typically FR
        if len(blocks) >= 2:
            return blocks[1].strip()

    # For IT: find the block that starts with "Regesto" or has Italian content
    if language == "it":
        for block in blocks:
            lower = block[:500].lower()
            if "regesto" in lower[:30] or any(m in lower for m in _IT_CONTENT_MARKERS):
                return block.strip()
        # Fallback: third block is typically IT
        if len(blocks) >= 3:
            return blocks[2].strip()

    return regeste  # fallback: return full text


def _pick_regeste(row, language: str) -> str | None:
    """Pick the best regeste for the given language.

    Priority:
      1. ``abstract_{lang}`` column (per-language, populated from JSONL).
         Available after the first full rebuild with the extended schema.
      2. ``_extract_regeste_for_language(regeste, lang)`` — splits a
         concatenated multilingual regeste on language-block markers.
      3. The raw ``regeste`` field unchanged (last resort).
    """
    lang = (language or "de").lower()[:2]
    col = f"abstract_{lang}"
    try:
        val = row[col]
        if val:
            return val
    except (KeyError, IndexError):
        pass
    return _extract_regeste_for_language(row["regeste"], lang)


# ── Data management ───────────────────────────────────────────

REQUIRED_SPACE_GB = 65

_REQUIRED_PARQUET_COLUMNS = {"decision_id", "court", "canton", "full_text"}

# ── Update state (shared between background thread and tool handlers) ──

_update_state: dict = {
    "status": "idle",       # idle | running | done | failed
    "phase": "",            # download | import | optimize
    "message": "",          # latest human-readable status line
    "step": 0,
    "total": 0,
    "started_at": 0.0,
    "result": "",           # final summary or error message
}
_update_thread: threading.Thread | None = None


def _check_disk_space() -> str:
    """Check free disk space. Returns human-readable message or raises."""
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    usage = shutil.disk_usage(DATA_DIR)
    free_gb = usage.free / (1024 ** 3)
    if free_gb < REQUIRED_SPACE_GB:
        raise RuntimeError(
            f"Insufficient disk space: {free_gb:.1f} GB free, "
            f"but ~{REQUIRED_SPACE_GB} GB required. "
            f"Free up space or set SWISS_CASELAW_DIR to a larger volume."
        )
    return f"Disk space OK: {free_gb:.1f} GB free"


class _StateReporter:
    """Updates the shared _update_state dict from the worker thread."""

    def report(self, progress: float, total: float, message: str) -> None:
        logger.info(message)
        _update_state["step"] = int(progress)
        _update_state["total"] = int(total)
        _update_state["message"] = message


class _NullReporter:
    """Fallback reporter that only logs (for non-MCP callers)."""

    def report(self, progress: float, total: float, message: str) -> None:
        logger.info(message)


def _download_parquet_files(reporter) -> int:
    """Download parquet files one-by-one with per-file progress.

    Returns the number of files downloaded.
    """
    from huggingface_hub import hf_hub_download, list_repo_files

    DATA_DIR.mkdir(parents=True, exist_ok=True)
    PARQUET_DIR.mkdir(parents=True, exist_ok=True)

    # Clean old parquet files before download to prevent schema mixing
    old_files = list(PARQUET_DIR.rglob("*.parquet"))
    if old_files:
        reporter.report(0, 1, f"Removing {len(old_files)} old parquet files...")
        for f in old_files:
            f.unlink()

    # Enumerate remote files
    all_files = list_repo_files(HF_REPO, repo_type="dataset")
    parquet_files = sorted(f for f in all_files if f.startswith("data/") and f.endswith(".parquet"))
    total = len(parquet_files)

    if total == 0:
        raise RuntimeError(f"No parquet files found in {HF_REPO}/data/")

    for i, remote_path in enumerate(parquet_files, 1):
        name = Path(remote_path).stem
        reporter.report(i, total, f"Downloading {name} ({i}/{total})")
        hf_hub_download(
            repo_id=HF_REPO,
            repo_type="dataset",
            filename=remote_path,
            local_dir=str(PARQUET_DIR),
        )

    reporter.report(total, total, f"Download complete: {total} files")
    return total


def _build_db_from_parquet(reporter=None) -> dict:
    """Build SQLite FTS5 database from downloaded Parquet files.

    Returns dict with keys: imported, duplicates, skipped_files.
    """
    import pyarrow.parquet as pq

    if reporter is None:
        reporter = _NullReporter()

    # Build into a temp file, then atomically rename on success
    tmp_path = DB_PATH.with_suffix(".tmp")
    if tmp_path.exists():
        tmp_path.unlink()

    conn = sqlite3.connect(str(tmp_path))
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")

    # Use canonical schema from db_schema.py
    conn.executescript(SCHEMA_SQL)

    # Import all Parquet files
    imported = 0
    duplicates = 0
    skipped_files = []
    parquet_files = sorted(PARQUET_DIR.rglob("*.parquet"))
    total_files = len(parquet_files)
    reporter.report(0, total_files, f"Found {total_files} Parquet files to import")

    for file_idx, pf in enumerate(parquet_files, 1):
        file_imported = 0
        try:
            schema = pq.read_schema(pf)
            file_columns = set(schema.names)
            missing = _REQUIRED_PARQUET_COLUMNS - file_columns
            if missing:
                logger.warning(
                    f"Skipping {pf.name}: missing required columns {missing} "
                    f"(has: {sorted(file_columns)[:8]}...)"
                )
                skipped_files.append(pf.name)
                continue

            table = pq.read_table(pf)
            for batch in table.to_batches():
                for row in batch.to_pylist():
                    try:
                        values = tuple(
                            json.dumps(row, default=str) if col == "json_data"
                            else _make_canonical_key(
                                row.get("court", ""), row.get("docket_number", ""),
                                row.get("decision_date"),
                            ) if col == "canonical_key"
                            else row.get(col)
                            for col in INSERT_COLUMNS
                        )
                        cursor = conn.execute(INSERT_OR_IGNORE_SQL, values)
                        if cursor.rowcount > 0:
                            imported += 1
                            file_imported += 1
                        else:
                            duplicates += 1
                    except Exception as e:
                        logger.debug(f"Skip {row.get('decision_id', '?')}: {e}")
            conn.commit()
            reporter.report(
                file_idx, total_files,
                f"Imported {pf.stem}: {file_imported:,} decisions "
                f"({file_idx}/{total_files} files, {imported:,} total)",
            )
        except Exception as e:
            logger.warning(f"Failed to read {pf}: {e}")
            skipped_files.append(pf.name)

    # Optimize
    reporter.report(total_files, total_files, "Optimizing FTS5 index (this takes a while)...")
    conn.execute("INSERT INTO decisions_fts(decisions_fts) VALUES('optimize')")
    conn.execute("PRAGMA optimize")
    conn.commit()
    conn.close()

    # Atomic replace: os.replace is atomic on POSIX (no gap where DB is missing)
    os.replace(str(tmp_path), str(DB_PATH))

    logger.info(
        f"Built database: {imported} imported, {duplicates} duplicates, "
        f"{len(skipped_files)} skipped files → {DB_PATH}"
    )
    if skipped_files:
        logger.warning(f"Skipped files: {skipped_files}")

    return {"imported": imported, "duplicates": duplicates, "skipped_files": skipped_files}


def _update_with_progress(reporter) -> str:
    """Full update: download + build + sanity check. Runs in a worker thread."""
    t0 = time.monotonic()

    # 1. Disk space
    _update_state["phase"] = "disk_check"
    reporter.report(0, 1, "Checking disk space...")
    msg = _check_disk_space()
    reporter.report(0, 1, msg)

    # 2. Download
    _update_state["phase"] = "download"
    _download_parquet_files(reporter)

    # 3. Build DB
    _update_state["phase"] = "import"
    reporter.report(0, 1, "Building SQLite FTS5 database...")
    result = _build_db_from_parquet(reporter)

    # 4. Sanity check — raise so background wrapper sets status="failed"
    MIN_EXPECTED_DECISIONS = 500_000
    if result["imported"] < MIN_EXPECTED_DECISIONS:
        raise RuntimeError(
            f"Database build FAILED sanity check: only {result['imported']} decisions "
            f"imported (minimum {MIN_EXPECTED_DECISIONS}). "
            f"Skipped files: {result['skipped_files']}, duplicates: {result['duplicates']}. "
            f"The database at {DB_PATH} may be corrupt — investigate before using."
        )

    # 5. Summary
    elapsed = time.monotonic() - t0
    minutes, seconds = divmod(int(elapsed), 60)
    _cache_clear()

    stats = get_db_stats()
    reporter.report(1, 1, "Database ready!")
    return (
        f"Database updated successfully in {minutes}m {seconds:02d}s.\n"
        f"Total: {stats.get('total_decisions', '?'):,} decisions\n"
        f"Courts: {len(stats.get('courts', {}))} courts\n"
        f"Date range: {stats.get('earliest_date', '?')} to {stats.get('latest_date', '?')}\n"
        f"Database: {stats.get('db_path', '?')} ({stats.get('db_size_mb', '?')} MB)\n"
        f"Import: {result['imported']:,} inserted, {result['duplicates']:,} duplicates, "
        f"{len(result['skipped_files'])} files skipped"
    )


def _run_update_background() -> None:
    """Target for the background thread. Updates _update_state on completion."""
    reporter = _StateReporter()
    try:
        summary = _update_with_progress(reporter)
        _update_state["status"] = "done"
        _update_state["result"] = summary
    except Exception as e:
        logger.error(f"Background update failed: {e}", exc_info=True)
        _update_state["status"] = "failed"
        _update_state["result"] = f"Update failed: {e}"


def update_from_huggingface() -> str:
    """Download latest data from HuggingFace and rebuild the database.

    Thin wrapper for non-MCP callers (publish.py, CLI). Uses NullReporter.
    """
    try:
        return _update_with_progress(_NullReporter())
    except ImportError:
        return "Error: huggingface_hub not installed. Run: pip install huggingface_hub"
    except Exception as e:
        return f"Update failed: {e}"


