def _handle_generate_exam_question(
    *, topic: str, exclude_ids: list[str] | None = None
) -> dict:
    """Handler for generate_exam_question tool.

    Returns a real BGE fact pattern as a Fallbearbeitung exercise.
    The analysis is included but Claude should reveal it only after
    the student submits their answer.
    """
    if not topic or not topic.strip():
        return {"error": "Provide a legal topic, area, or statute reference."}

    exclude = set(exclude_ids or [])

    # Build candidate pool from find_leading_cases (graph path) with FTS fallback
    lc_result = _find_leading_cases(query=topic.strip(), limit=30)
    candidates = lc_result.get("results", [])

    # Fallback: if graph returned no candidates (or errored), use plain FTS search
    if not candidates:
        candidates = _find_leading_cases_by_fts_fallback(query=topic.strip(), limit=30)

    # Also check curriculum for topic-matching cases with difficulty scores
    try:
        curriculum_cases = _get_curriculum_cases_for_topic(topic)
        curriculum_map = {c["decision_id"]: c for c in curriculum_cases}
    except Exception:
        curriculum_map = {}

    # Filter and pick: need full_text >= 1000 chars and regeste >= 50 chars
    selected = None
    for case in candidates:
        did = case.get("decision_id", "")
        if did in exclude:
            continue
        decision = get_decision_by_id(did)
        if not decision:
            continue
        full_text = decision.get("full_text") or ""
        regeste = decision.get("regeste") or ""
        if len(full_text) < 1000 or len(regeste) < 50:
            continue
        selected = (case, decision)
        break

    if selected is None:
        return {"error": f"No suitable case found for topic '{topic}'. Try a broader topic."}

    case_meta, decision = selected
    decision_id = decision.get("decision_id", "")
    full_text = decision.get("full_text") or ""
    regeste = decision.get("regeste") or ""

    # Extract fact pattern from Sachverhalt section
    fact_pattern = _extract_section(
        full_text,
        start_patterns=[r"^Sachverhalt\s*:", r"^A\.\s*[-–]", r"^Faits\s*:"],
        end_patterns=[r"^Erwägungen\s*:?$", r"^Considérant\s*", r"^Das Bundesgericht"],
        fallback_chars=600,
    )
    if not fact_pattern:
        fact_pattern = full_text[:600].strip()

    # Difficulty: prefer curriculum difficulty, else default 3; clamp to 1-5
    raw_difficulty = curriculum_map.get(decision_id, {}).get("difficulty", 3)
    difficulty = max(1, min(5, int(raw_difficulty)))

    # Statutes for hidden analysis
    statutes = _get_decision_statutes(decision_id, limit=3)
    statute_labels = [
        f"{s['law_code']} {s['article']}" for s in statutes if s.get("law_code")
    ]

    # Legal test and outcome from regeste
    regeste_parts = [p.strip() for p in regeste.split(".") if p.strip()]
    legal_test = regeste_parts[0][:150] if regeste_parts else regeste[:150]
    correct_outcome = regeste_parts[-1][:150] if len(regeste_parts) > 1 else ""

    hint = "Prüfen Sie, welches Rechtsgebiet auf den Sachverhalt anwendbar ist."

    return {
        "fact_pattern": fact_pattern,
        "difficulty": difficulty,
        "hint": hint,
        "source_decision_id": decision_id,
        "analysis": {
            "applicable_statutes": statute_labels,
            "leading_case": decision.get("docket_number", decision_id),
            "legal_test": legal_test,
            "correct_outcome": correct_outcome,
        },
    }


def _get_curriculum_cases_for_topic(topic: str) -> list[dict]:
    """Return curriculum cases matching topic (area_id or keyword search)."""
    from study.curriculum_engine import load_curriculum
    areas = load_curriculum()
    results_list = []
    topic_lower = topic.lower()
    for area in areas:
        # Match by area_id or display name
        area_name = getattr(area, "area_de", None) or getattr(area, "name", "") or ""
        if topic_lower in area.area_id.lower() or topic_lower in area_name.lower():
            for mod in area.modules:
                for case in mod.cases:
                    results_list.append({
                        "decision_id": case.decision_id,
                        "difficulty": getattr(case, "difficulty", 3),
                        "area_id": area.area_id,
                    })
    return results_list


# ── Statute tools ──────────────────────────────────────────────


# A cantonal law is identified by canton PLUS number, never by abbreviation
# alone: StG is the tax act in ZH, BE and AG and the federal stamp-duty act
# as well, BauG is the building act in BE and AG. Everything below therefore
# stays scoped to one canton and reports the canton with every candidate.
_QUALIFIED_NAME = re.compile(r"^\s*([A-Za-z]{2})\s*/\s*(\S.*)$")


def split_qualified_law_name(name: str) -> tuple[str | None, str]:
    """'ZH/StG' -> ('ZH', 'StG'); 'StG' -> (None, 'StG').

    Cantonal statutes are named with their canton because the
    abbreviation alone is ambiguous — StG is the tax act in ZH, BE and AG.
    Federal law is the unprefixed default, which is how practitioners
    write it, so an unprefixed name means the federal collection.

    'EG SchKG' is not split: only a two-letter head before a slash is a
    canton.
    """
    m = _QUALIFIED_NAME.match(name or "")
    if not m:
        return None, (name or "").strip()
    return m.group(1).upper(), m.group(2).strip()


def _cantonal_sr_from_name(conn, canton: str, name: str,
                           language: str) -> str | None:
    """SR number for any name a cantonal law answers to.

    Abbreviation, short title or full title — ZH/StG and
    ZH/Steuergesetz both reach Zurich's tax act. Only ~40% of cantonal
    laws have an abbreviation at all, so the title is what makes the
    other 60% reachable rather than a gap.

    A name the canton published outranks one derived from the title, so
    a guess can never shadow the canton's own answer.
    """
    if conn is None or not name:
        return None
    # casefold(), not lower() and not COLLATE NOCASE: sources write
    # FINMAG, FinmaG and finmag for the same act, and SQLite's NOCASE
    # folds a-z only — "Bürgerrechtsgesetz" would never match itself.
    n = name.strip().casefold()
    try:
        row = conn.execute(
            """SELECT sr_number FROM law_names
                WHERE canton = ? AND language = ? AND name_folded = ?
                ORDER BY CASE name_type WHEN 'abbreviation' THEN 0
                                        WHEN 'short_title'  THEN 1
                                        ELSE 2 END,
                         CASE source WHEN 'lexwork_api' THEN 0 ELSE 1 END
                LIMIT 1""",
            (canton, language, n),
        ).fetchone()
        return row["sr_number"] if row else None
    except sqlite3.Error:
        # The table only exists once the corpus has been rebuilt with it;
        # an older mirror must keep serving, not start failing.
        return None


def _cantonal_candidates(canton: str, abbreviation: str,
                         language: str, limit: int = 5) -> list:
    """The closest laws in THIS canton, so a miss is still an answer.

    Delegates to search_laws rather than querying the mirror directly.
    That is not indirection for its own sake: a hand-rolled title/FTS
    query returns noise on this corpus (StG in ZH gives the
    Finanzausgleichsverordnung), while the tuned search path puts
    Zurich's Steuergesetz and Planungs- und Baugesetz in the top three.

    Deliberately NOT a resolver. An earlier attempt read the abbreviation
    out of the law's own text on the theory that a law declares its short
    form as "(StG)" — but Swiss drafting writes the same bracketed form
    on first CITATION, so it resolved StG to whichever act happened to
    cite the tax law. Against production data 6 of 12 lookups "resolved"
    and nearly all were the wrong act. Offering candidates the caller
    chooses between is honest; asserting one of them is not.
    """
    if not abbreviation:
        return []
    try:
        res = search_laws(query=abbreviation, canton=canton,
                          jurisdiction="cantonal", language=language,
                          limit=limit)
    except Exception:                                   # pragma: no cover
        return []
    out = []
    for r in (res or {}).get("results", [])[:limit]:
        sr = r.get("sr_number") or r.get("systematic_number")
        if not sr:
            continue
        out.append({
            "canton": canton,
            "sr_number": sr,
            "title": r.get("title"),
            # Canton-qualified: the number alone repeats across cantons and
            # against the federal collection, so it never travels bare.
            "key": f"{canton}/{sr}",
        })
    return out


def _get_law_cantonal(
    sr_number: str | None,
    abbreviation: str | None,
    article: str | None,
    language: str,
    canton: str,
) -> dict:
    """Look up a specific law or article from cantonal_laws.db."""
    # The cantonal_laws.db mirror is now only needed to resolve a textual
    # abbreviation -> sr_number; with LexFind-first serving (issue #27) the law
    # text itself comes live from LexFind, so open the mirror lazily.
    conn = None

    try:
        canton_u = canton.upper()
        # Resolve by abbreviation OR sr_number.
        if not sr_number and abbreviation:
            # A digit-form abbreviation IS the SR/LS number (the common REST
            # /api/laws/{n}?canton=ZH path) — use it directly, no mirror needed.
            if re.match(r"^[\d./]+$", abbreviation):
                sr_number = abbreviation
            else:
                conn = _get_cantonal_conn()
                if conn is not None:
                    # The name index first: every law is reachable by its
                    # title there, and by its abbreviation where one
                    # exists. The old title-LIKE match stays as a fallback
                    # for a mirror built before the index existed.
                    sr_number = _cantonal_sr_from_name(
                        conn, canton_u, abbreviation, language)
                if conn is not None and not sr_number:
                    row = conn.execute(
                        """SELECT sr_number FROM laws
                        WHERE canton = ? AND language = ?
                          AND (title LIKE ? OR title LIKE ?) LIMIT 1""",
                        (canton_u, language, f"%({abbreviation})%", f"{abbreviation}%"),
                    ).fetchone()
                    if row:
                        sr_number = row["sr_number"]
            if not sr_number:
                # Never a bare dead end: the law is usually in the corpus and
                # only the name we were given does not reach it. Hand back
                # real laws so the caller can pick one, rather than an
                # apology. They are search hits over the actual corpus, and
                # they are offered as candidates rather than asserted as the
                # answer — an abbreviation we cannot source is not one we may
                # guess at.
                cands = _cantonal_candidates(canton_u, abbreviation, language)
                out = {"error": (
                    f"No cantonal law found for {canton_u} with abbreviation "
                    f"'{abbreviation}'. Try search_laws or search_legislation."
                )}
                if cands:
                    out["candidates"] = cands
                    out["note"] = (
                        f"{canton_u} does not publish '{abbreviation}' as a "
                        f"title. The closest {canton_u} laws are listed under "
                        "`candidates`; re-request one by its `sr_number` with "
                        f"canton={canton_u}. Cantonal abbreviations repeat "
                        "across cantons (StG exists in ZH, BE and AG and is "
                        "also a federal act), so a cantonal law is only "
                        "identified by canton + number."
                    )
                return out

        if not sr_number:
            return {"error": "Provide sr_number, abbreviation, or use search_laws."}

        # LexFind-first for currency + completeness (issue #27): delegate to the
        # legislation path, which serves live from LexFind with the local mirror
        # as a resilience fallback. This fixes false "No law found" for laws
        # absent from the incomplete cantonal mirror (e.g. ZH 550.1 PolG, 554.5 HuG).
        leg = _get_legislation(
            systematic_number=sr_number, canton=canton_u, language=language,
        )
        if not isinstance(leg, dict) or leg.get("error"):
            return {
                "error": (
                    f"No law found for canton={canton_u} SR {sr_number} "
                    f"({language}). Use search_laws or get_legislation to discover the right law."
                )
            }

        cur = leg.get("current_version") or {}
        result = {
            "sr_number": leg.get("systematic_number") or sr_number,
            "title": leg.get("title"),
            "abbreviation": "",  # cantonal laws rarely have canonical abbreviations
            "canton": canton_u,
            "level": "cantonal",
            "language": language,
            "category": cur.get("category") or leg.get("category") or "",
            "lexfind_id": leg.get("lexfind_id"),
            "version_active_since": cur.get("active_since"),
            "source": leg.get("source", "lexfind"),
        }
        # Source link at the data layer (mirrors the federal path).
        _src = _lexfind_url(leg.get("lexfind_id"), language) or leg.get("original_url")
        if _src:
            result["source_url"] = _src
            result["source_label"] = "LexFind"

        articles_rows = leg.get("articles") or []

        if article:
            article_norm = article.strip().lstrip("§").lstrip("Art.").strip()
            matches = [
                a for a in articles_rows
                if (a["article_num"] or "") == article_norm
                or (a["article_num"] or "").lstrip("0") == article_norm.lstrip("0")
            ]
            if not matches:
                matches = [
                    a for a in articles_rows
                    if (a["article_num"] or "").startswith(article_norm)
                ]
            result["articles"] = [
                {"article_num": a["article_num"], "heading": a["heading"], "text": a["text"]}
                for a in matches
            ]
        else:
            result["article_count"] = len(articles_rows)
            result["articles"] = [
                {"article_num": a["article_num"], "heading": a["heading"]}
                for a in articles_rows
            ]
        return result
    except sqlite3.Error as e:
        logger.error("Cantonal law lookup error: %s", e)
        return {"error": f"Database error: {e}"}
    except Exception as e:
        # The hot path now runs live LexFind HTTP + response parsing; a malformed
        # response must degrade to a graceful error, not an unhandled 500.
        logger.error("Cantonal law lookup failed: %s", e)
        return {"error": f"Lookup failed: {e}"}
    finally:
        if conn is not None:
            conn.close()


_FEDLEX_SPARQL = "https://fedlex.data.admin.ch/sparqlendpoint"
_FEDLEX_LANG_URIS = {
    "de": "http://publications.europa.eu/resource/authority/language/DEU",
    "fr": "http://publications.europa.eu/resource/authority/language/FRA",
    "it": "http://publications.europa.eu/resource/authority/language/ITA",
}


# Federal SR numbers are digits and dots ('220', '235.1', '0.452'). Checked
# before an SR number reaches a SPARQL string: the value goes to a public
# third-party endpoint, so it must not carry quotes or query syntax.
_SR_NUMBER_RE = re.compile(r"^\d[\d.]{0,30}$")
_FEDLEX_ELI_PREFIX = "https://fedlex.data.admin.ch/eli/"
# jolux:inForceStatus is a URI ending in .../enforcement-status/<n>.
_FEDLEX_STATUS = {"/0": "in_force", "/3": "repealed"}


def _fedlex_sparql_select(query: str, timeout: float = 15) -> list[dict]:
    """POST a SELECT to Fedlex and return its bindings as {var: value} dicts.

    Raises on transport or JSON errors so each caller decides how to
    degrade. Every Fedlex query on the historical path goes through here;
    it is the one seam the offline tests stub.
    """
    import requests as _req
    resp = _req.post(_FEDLEX_SPARQL, data={"query": query},
                     headers={"Accept": "application/sparql-results+json"},
                     timeout=timeout)
    resp.raise_for_status()
    return [{k: v.get("value") for k, v in b.items()}
            for b in resp.json().get("results", {}).get("bindings", [])]


def _fedlex_candidate_works(sr_number: str) -> list[dict]:
    """Every jolux:ConsolidationAbstract that has ever carried ``sr_number``.

    Fedlex tags SR numbers two ways and the two sets barely overlap: acts
    published before ~2020 carry jolux:historicalLegalId, totally revised
    acts since then (the 2020 nDSG at SR 235.1, ~730 others) carry only the
    taxonomy notation. A historicalLegalId-only lookup therefore lands on
    the repealed 1992 DSG for every date, and an in-force filter on that
    lookup returns nothing at all, so both branches are UNIONed here.

    One row per work: {"work", "eif", "nlif", "status"} with ISO dates (or
    None) and status "in_force" / "repealed" / None. No date filter, no
    ORDER BY, no LIMIT: the pick happens in _pick_fedlex_work, in Python,
    so the Fedlex date quirks stay testable offline. Cached 7 days.
    """
    if not _SR_NUMBER_RE.match(sr_number or ""):
        raise ValueError(f"invalid SR number {sr_number!r}")
    cache_key = f"fedlex_works:v1:{sr_number}"
    cached = _lexfind_cache_get(cache_key)
    if cached is not None:
        return cached
    # str(?n) is load-bearing: skos:notation is a typed literal, so the
    # property-path form `classifiedByTaxonomyEntry/skos:notation "x"`
    # matches nothing. DISTINCT because the store emits one solution per
    # rdf:type triple.
    rows = _fedlex_sparql_select(
        'PREFIX jolux: <http://data.legilux.public.lu/resource/ontology/jolux#>\n'
        'PREFIX skos: <http://www.w3.org/2004/02/skos/core#>\n'
        'SELECT DISTINCT ?work ?eif ?nlif ?status WHERE {\n'
        f'  {{ ?work jolux:historicalLegalId "{sr_number}" . }}\n'
        '  UNION\n'
        '  { ?work jolux:classifiedByTaxonomyEntry ?tax .\n'
        '    ?tax skos:notation ?n .\n'
        f'    FILTER(str(?n) = "{sr_number}") }}\n'
        '  ?work a jolux:ConsolidationAbstract .\n'
        '  OPTIONAL { ?work jolux:dateEntryInForce ?eif }\n'
        '  OPTIONAL { ?work jolux:dateNoLongerInForce ?nlif }\n'
        '  OPTIONAL { ?work jolux:inForceStatus ?status }\n'
        '}'
    )
    by_work: dict[str, dict] = {}
    for row in rows:
        work = row.get("work")
        if not work:
            continue
        cand = by_work.setdefault(work, {"work": work, "eif": None, "nlif": None, "status": None})
        eif = (row.get("eif") or "")[:10] or None
        nlif = (row.get("nlif") or "")[:10] or None
        if eif and (cand["eif"] is None or eif < cand["eif"]):
            cand["eif"] = eif
        if nlif and (cand["nlif"] is None or nlif > cand["nlif"]):
            cand["nlif"] = nlif
        status = _FEDLEX_STATUS.get((row.get("status") or "")[-2:])
        # A live status wins over a repealed one if a work carries both.
        if status and cand["status"] != "in_force":
            cand["status"] = status
    result = list(by_work.values())
    # A transient zero-binding response must not pin "No Fedlex act carried
    # SR ..." for a week: cache only non-empty answers.
    if result:
        _lexfind_cache_set(cache_key, result)
    return result


def _pick_fedlex_work(candidates: list[dict], as_of: str) -> dict | None:
    """The work in force on ISO date ``as_of``, or None. Pure, no I/O.

    Window: dateEntryInForce <= as_of and dateNoLongerInForce >= as_of; an
    unbound date passes. ``>=`` on the end date is deliberate. Fedlex records
    it two ways: as an exclusive end (1992 DSG: nlif 2023-09-01, the day the
    nDSG entered into force) and, on a few works, as the last day in force
    (SR 131.233: nlif 2001-12-31, successor eif 2002-01-01). Keeping the
    changeover day inside both windows and breaking the tie by the newest
    entry-into-force date picks the successor under both conventions.

    Rank: repealed works with no end date last (979 of them on Fedlex; the
    repeal date is unknown, so they must never beat a datable live
    candidate), then a known start before an unknown one, then newest start.
    """
    if not as_of:
        return None
    in_window = [
        c for c in candidates
        if not (c.get("eif") and c["eif"] > as_of)
        and not (c.get("nlif") and c["nlif"] < as_of)
    ]
    if not in_window:
        return None
    in_window.sort(key=lambda c: (
        not (c.get("status") == "repealed" and not c.get("nlif")),
        c.get("eif") is not None,
        c.get("eif") or "",
    ), reverse=True)
    return in_window[0]


def _resolve_fedlex_work(sr_number: str, as_of: str) -> dict | None:
    """SR number + ISO date -> the Fedlex work in force on that date."""
    return _pick_fedlex_work(_fedlex_candidate_works(sr_number), as_of)


def _fedlex_snapshots(work_uri: str) -> list[dict]:
    """All dated consolidations of one work, [{"snapshot", "date"}] sorted by
    date. Cached 24h: a newly published consolidation is exactly what
    pending_changes must notice within a day.
    """
    if not str(work_uri).startswith(_FEDLEX_ELI_PREFIX):
        raise ValueError(f"unexpected Fedlex work URI {work_uri!r}")
    cache_key = f"fedlex_snaps:v1:{work_uri}"
    cached = _lexfind_cache_get(cache_key)
    if cached is not None:
        return cached
    rows = _fedlex_sparql_select(
        'PREFIX jolux: <http://data.legilux.public.lu/resource/ontology/jolux#>\n'
        'SELECT DISTINCT ?snapshot ?date WHERE {\n'
        f'  ?snapshot jolux:isMemberOf <{work_uri}> .\n'
        '  ?snapshot jolux:dateApplicability ?date .\n'
        '}'
    )
    seen: dict[tuple[str, str], dict] = {}
    for r in rows:
        if r.get("snapshot") and r.get("date"):
            key = (r["snapshot"], r["date"][:10])
            seen.setdefault(key, {"snapshot": key[0], "date": key[1]})
    snaps = sorted(seen.values(), key=lambda snap: (snap["date"], snap["snapshot"]))
    if snaps:
        _lexfind_cache_set(cache_key, snaps)
    return snaps


def _fedlex_expression_info(uri: str, language: str) -> dict:
    """Title, abbreviation and available formats of a Fedlex work or dated
    consolidation in one language.

    {"formats": {"xml": url, "pdf-a": url, "doc": url, ...}, "title", "abbr"};
    the format key is the tail of the jolux:userFormat URI. Asked of the
    edition itself, a repealed act is labelled with its own title, never
    its successor's. Cached 30 days.
    """
    if not str(uri).startswith(_FEDLEX_ELI_PREFIX):
        raise ValueError(f"unexpected Fedlex URI {uri!r}")
    lang_uri = _FEDLEX_LANG_URIS.get(language, _FEDLEX_LANG_URIS["de"])
    cache_key = f"fedlex_expr:v1:{uri}:{language}"
    cached = _lexfind_cache_get(cache_key)
    if cached is not None:
        return cached
    rows = _fedlex_sparql_select(
        'PREFIX jolux: <http://data.legilux.public.lu/resource/ontology/jolux#>\n'
        'SELECT DISTINCT ?fmt ?url ?title ?abbr WHERE {\n'
        f'  <{uri}> jolux:isRealizedBy ?expr .\n'
        f'  ?expr jolux:language <{lang_uri}> .\n'
        '  OPTIONAL { ?expr jolux:title ?title }\n'
        '  OPTIONAL { ?expr jolux:titleShort ?abbr }\n'
        '  OPTIONAL { ?expr jolux:isEmbodiedBy ?manif .\n'
        '             ?manif jolux:userFormat ?fmt .\n'
        '             ?manif jolux:isExemplifiedBy ?url }\n'
        '}'
    )
    info = {"formats": {}, "title": None, "abbr": None}
    for r in rows:
        if r.get("fmt") and r.get("url"):
            info["formats"].setdefault(r["fmt"].rstrip("/").rsplit("/", 1)[-1], r["url"])
        if r.get("title") and not info["title"]:
            info["title"] = r["title"]
        if r.get("abbr") and not info["abbr"]:
            info["abbr"] = r["abbr"]
    if info["formats"] or info["title"]:
        _lexfind_cache_set(cache_key, info)
    return info


def _fedlex_snapshot_url(snapshot_uri: str, language: str) -> str:
    """Public Fedlex page of one dated consolidation: the same host swap
    _fedlex_url applies to work URIs, plus the language segment."""
    return (str(snapshot_uri).replace("fedlex.data.admin.ch", "www.fedlex.admin.ch")
            .rstrip("/") + "/" + (language or "de"))


def _extract_pdf_text(content: bytes) -> tuple[str, int]:
    """Plain text of a PDF and its page count (pymupdf), pages joined by
    newlines. Kept separate so tests can stand in a synthetic edition."""
    import fitz  # pymupdf
    doc = fitz.open(stream=content, filetype="pdf")
    try:
        return "\n".join(page.get_text() for page in doc), len(doc)
    finally:
        doc.close()


# Whole editions can run to ~1.4 MB of text (OR); the LexFind cache prunes
# by row count, not size, so very large editions are served uncached.
_EDITION_TEXT_CACHE_MAX_CHARS = 3_000_000


def _fetch_fedlex_edition_text(sr_number: str, snapshot_date: str, language: str,
                               fmt: str, url: str) -> dict | None:
    """Whole-edition plain text of a dated consolidation Fedlex publishes
    only as PDF: {"full_text", "chars", "pages", "fmt", "url"}.

    Cached by edition (hist_edition:, 30 days), not by as_of, so every date
    that resolves to the same consolidation shares one download. Returns
    None when the download or the extraction fails.
    """
    cache_key = f"hist_edition:v1:{sr_number}:{snapshot_date}:{language}:{fmt}"
    cached = _lexfind_cache_get(cache_key)
    if cached is not None:
        return cached
    import requests as _req
    resp = _req.get(url, timeout=60)
    if resp.status_code != 200 or not resp.content.startswith(b"%PDF"):
        return None
    try:
        text, pages = _extract_pdf_text(resp.content)
    except Exception as e:
        logger.warning("Fedlex PDF parse failed for SR %s edition %s: %s", sr_number, snapshot_date, e)
        return None
    text = text.replace("\u00a0", " ")
    edition = {"full_text": text, "chars": len(text), "pages": pages, "fmt": fmt, "url": url}
    if len(text) <= _EDITION_TEXT_CACHE_MAX_CHARS:
        _lexfind_cache_set(cache_key, edition)
    return edition


_PDF_ARTICLE_NUM = r"\d+[a-z]?(?:bis|ter|quater|quinquies|sexies|septies|octies|novies|decies)?"
# An amended article's body header carries its footnote superscript glued to
# the number in the extracted text — "Art. 336c147" for Art. 336c, footnote
# 147 — while the table of contents lists the same article clean ("Art.
# 336c"). The glued form counts only at the end of the line: a footnote
# never sits inside a heading line, and the anchor keeps "Art. 33" from
# matching "Art. 336 …". Measured on the 2010 OR: 234 of ~1,600 body headers
# are glued; every one of them used to fall through to the TOC line.
_PDF_GLUED_FOOTNOTE = r"(\d{1,3})[ \t]*$"
_PDF_ANY_ARTICLE_MARKER = re.compile(
    rf"^[ \t]*Art\.\s*{_PDF_ARTICLE_NUM}(?:{_PDF_GLUED_FOOTNOTE}|(?![0-9a-z]))",
    re.MULTILINE,
)
# Footnote-free headers ("Art. 336c", not "Art. 336c147").
_PDF_CLEAN_ARTICLE_MARKER = re.compile(
    rf"^[ \t]*Art\.\s*({_PDF_ARTICLE_NUM})(?![0-9a-z])", re.MULTILINE)
_PDF_ORDINAL_SUFFIXES = ("bis", "ter", "quater", "quinquies", "sexies",
                         "septies", "octies", "novies", "decies")


def _pdf_article_sort_key(article: str) -> tuple[int, str]:
    """(number, suffix) in statute order: 325 < 325bis < 326, 336 < 336a."""
    m = re.match(r"(\d+)(.*)", article)
    if not m:
        return (0, article)
    suffix = m.group(2)
    if suffix in _PDF_ORDINAL_SUFFIXES:
        suffix = chr(ord("a") + _PDF_ORDINAL_SUFFIXES.index(suffix))
    return (int(m.group(1)), suffix)


def _pdf_article_spine(full_text: str) -> list[tuple[int, tuple[int, str]]]:
    """Ordered [(position, sort_key)] of the footnote-free headers that are
    certainly article numbers: those with a letter or ordinal suffix, and
    plain numbers seen at least twice (table of contents plus body). A
    plain number seen once is as likely a footnote read as digits ("Art.
    332125" is Art. 332, footnote 125) and would sit in the spine with an
    inflated value, so it is left out."""
    seen = [(c.start(), c.group(1)) for c in _PDF_CLEAN_ARTICLE_MARKER.finditer(full_text)]
    counts = collections.Counter(num for _, num in seen)
    return [(pos, _pdf_article_sort_key(num)) for pos, num in seen
            if not num.isdigit() or counts[num] > 1]


def _pdf_glued_header_fits(spine: list[tuple[int, tuple[int, str]]], article: str, pos: int) -> bool:
    """Whether the line "Art. <article><digits>" at pos reads as `article`
    with a glued footnote rather than as a longer article number ("Art.
    4817" is Art. 48 + footnote 17, but also looks like Art. 481 + 7).

    A line that is itself in the spine is a verified article number ("Art.
    333" listed in the table of contents and heading a body) and never
    reads as a shorter one. Otherwise article headers run in order, in the
    body and in the table of contents, so the reading is right when
    `article` sorts between the nearest spine headers before and after the
    line. Where the numbering restarts between them (final provisions, the
    table of contents) the article must fit one of the two runs.
    """
    import bisect
    key = _pdf_article_sort_key(article)
    i = bisect.bisect_left(spine, (pos, (0, "")))
    if i < len(spine) and spine[i][0] == pos:
        return False
    prev = spine[i - 1][1] if i > 0 else None
    nxt = spine[i][1] if i < len(spine) else None
    if prev is None or nxt is None:
        return (prev is None or key >= prev) and (nxt is None or key <= nxt)
    if prev <= nxt:
        return prev <= key <= nxt
    return key >= prev or key <= nxt


# Below this many characters of body the window holds a heading or a
# marginal note, not an article (the shortest real bodies, "Aufgehoben"
# aside, are one sentence of ~45 characters).
_PDF_EXCERPT_MIN_BODY_CHARS = 40


def _pdf_excerpt_status(excerpt: str) -> str:
    """'ok', 'heading_only' or 'empty' for a windowed PDF excerpt.

    The body is everything after the "Art. N" header line. A table-of-
    contents candidate carries the next article's marginal note ("b. durch
    den Arbeitnehmer"), a repealed article nothing at all; neither is
    statute text, and a client must be able to tell without reading it.
    Article text always closes a sentence, so a body whose lines all end
    without .;:!? (optionally a glued footnote number) is heading-only too.
    """
    body = excerpt.split("\n", 1)[1].strip() if "\n" in excerpt else ""
    if not body:
        return "empty"
    if len(body) < _PDF_EXCERPT_MIN_BODY_CHARS:
        return "heading_only"
    if not re.search(r"[.;:!?]\d{0,3}[ \t]*$", body, re.MULTILINE):
        return "heading_only"
    return "ok"


def _pdf_article_excerpt(full_text: str, article: str, max_chars: int = 8000) -> tuple[str | None, int]:
    """Best-effort window around one article in unstructured edition text.

    Every line-start "Art. N" is a candidate (Fedlex PDFs also list the
    articles in a table of contents), a glued footnote superscript allowed
    at the end of the line where it reads as this article and not a longer
    one (see _pdf_glued_header_fits). The block from each candidate to the
    next line-start "Art." marker is measured; the longest block that holds
    article text (_pdf_excerpt_status "ok") wins, else the longest block.
    Returns (excerpt, candidate_count). Measured on the 2017 OR, this kind
    of split is exact for ~63 % of articles and silently wrong for ~24 %
    (two-column layout, marginal notes bleeding in), which is why callers
    flag the result verbatim_quotation="not_guaranteed" and the server
    prompt forbids quoting it.
    """
    article = (article or "").strip()
    num = re.escape(article)
    if not num:
        return None, 0
    marker = re.compile(rf"^[ \t]*Art\.\s*{num}(?:{_PDF_GLUED_FOOTNOTE}|(?![0-9a-z]))",
                        re.MULTILINE)
    spine = None
    starts = []
    for m in marker.finditer(full_text):
        if m.group(1):
            if spine is None:
                spine = _pdf_article_spine(full_text)
            if not _pdf_glued_header_fits(spine, article, m.start()):
                continue
        starts.append(m.start())
    if not starts:
        return None, 0
    best, best_rank = "", (False, -1)
    for s in starts:
        nxt = _PDF_ANY_ARTICLE_MARKER.search(full_text, s + 1)
        block = full_text[s:nxt.start() if nxt else len(full_text)].strip()
        rank = (_pdf_excerpt_status(block) == "ok", len(block))
        if rank > best_rank:
            best, best_rank = block, rank
    return best[:max_chars], len(starts)


# Fedlex ships pre-2021 editions as PDF and, for about a fifth of them, also
# as the Bundeskanzlei Word file. The Word paragraph styles carry the article
# structure the PDF loses, so with a style-preserving converter on the host
# those editions can be served per article. Dark by default: the converter
# is not installed on the production host yet, and the split is best effort.
_HIST_DOC_ENABLED = os.environ.get("SWISS_CASELAW_HIST_DOC", "") == "1"
_DOC_CONVERTERS = ("soffice", "libreoffice", "textutil")
_doc_converter_cache: list = []


def _doc_converter() -> str | None:
    """Path of a style-preserving .doc -> HTML converter on this host, or
    None. Probed once per process and logged."""
    import shutil
    if not _doc_converter_cache:
        found = next((shutil.which(c) for c in _DOC_CONVERTERS if shutil.which(c)), None)
        _doc_converter_cache.append(found)
        logger.info("Fedlex .doc converter: %s", found or "none found")
    return _doc_converter_cache[0]


def _convert_doc_to_html(content: bytes) -> str | None:
    """Run the host converter on a .doc payload; HTML text or None."""
    import subprocess
    import tempfile
    conv = _doc_converter()
    if not conv:
        return None
    with tempfile.TemporaryDirectory(prefix="fedlex-doc-") as tmp:
        src_path = os.path.join(tmp, "edition.doc")
        with open(src_path, "wb") as fh:
            fh.write(content)
        try:
            if conv.endswith("textutil"):
                out = subprocess.run([conv, "-convert", "html", "-stdout", src_path],
                                     capture_output=True, timeout=60, check=False)
                return out.stdout.decode("utf-8", "replace") if out.returncode == 0 else None
            # LibreOffice needs a writable profile dir under ProtectSystem=strict.
            subprocess.run([conv, "--headless", f"-env:UserInstallation=file://{tmp}/lo",
                            "--convert-to", "html", "--outdir", tmp, src_path],
                           capture_output=True, timeout=60, check=False)
            html_path = os.path.join(tmp, "edition.html")
            if os.path.exists(html_path):
                with open(html_path, encoding="utf-8", errors="replace") as fh:
                    return fh.read()
        except (subprocess.TimeoutExpired, OSError) as e:
            logger.warning("Fedlex .doc conversion failed: %s", e)
    return None


_DOC_ARTICLE_MARKER = re.compile(
    r"^Art\.\s*(\d+[a-z]?(?:bis|ter|quater|quinquies|sexies|septies|octies|novies|decies|undecies|duodecies)?)$"
)


def _split_fedlex_doc_html(html_text: str) -> list[dict]:
    """Recover the articles of a Fedlex Word edition from its HTML export.

    The Bundeskanzlei template puts each "Art. N" in a paragraph style of
    its own, the marginal note (Randtitel) in a small-font style right after
    it, and the Absätze in the body style, so the split is by paragraph
    class, discovered from content rather than hard-coded: the marker class
    is the one whose paragraphs are (almost) all bare "Art. N"; the heading
    class is what usually follows a marker; the body class is what holds the
    numbered Absätze. Paragraphs in a larger font than the body (Titel /
    Abschnitt headings) end the current article. Returns [] when no marker
    class exists, i.e. the structure was not recovered. Later blocks that
    reuse a main-body number (final provisions) are dropped, first wins.
    """
    import html as _html
    from collections import Counter

    sizes: dict[str, float] = {}
    for m in re.finditer(r"\b(p\d+)\s*\{([^}]*)\}", html_text):
        g = re.search(r"font:\s*([\d.]+)px", m.group(2))
        if g:
            sizes[m.group(1)] = float(g.group(1))

    paras: list[tuple[str, str]] = []
    for cls, raw in re.findall(r'<p class="([^"]+)"[^>]*>(.*?)</p>', html_text, re.S):
        t = re.sub(r"<br\s*/?>", " ", raw)
        t = re.sub(r"<[^>]+>", "", t)
        t = _html.unescape(t).replace("\u00a0", " ").replace("\u2011", "-")
        paras.append((cls, re.sub(r"\s+", " ", t).strip()))
    if not paras:
        return []

    per_class = Counter(c for c, t in paras if t)
    marker_hits = Counter(c for c, t in paras if t and _DOC_ARTICLE_MARKER.match(t))
    marker_cls = None
    for cls, hits in marker_hits.most_common():
        if hits >= 3 and hits >= 0.95 * per_class[cls]:
            marker_cls = cls
            break
    if marker_cls is None:
        return []

    body_cls = Counter(c for c, t in paras if c != marker_cls and re.match(r"^\d+[a-z]?\s", t)).most_common(1)
    body_cls = body_cls[0][0] if body_cls else None
    if body_cls is None:
        # No numbered Absatz anywhere (short acts): the most common
        # non-marker class carries the text.
        others = Counter(c for c, t in paras if t and c != marker_cls)
        body_cls = others.most_common(1)[0][0] if others else None
    after_marker = Counter()
    for i in range(1, len(paras)):
        if paras[i - 1][0] == marker_cls and paras[i][0] not in (marker_cls, body_cls) and paras[i][1]:
            after_marker[paras[i][0]] += 1
    heading_cls = after_marker.most_common(1)[0][0] if after_marker else None
    body_size = sizes.get(body_cls) if body_cls else None

    articles: list[dict] = []
    seen: set[str] = set()
    cur: dict | None = None
    for cls, t in paras:
        if cls == marker_cls:
            m = _DOC_ARTICLE_MARKER.match(t)
            if not m:
                continue
            num = m.group(1)
            if num in seen:
                cur = None
                continue
            seen.add(num)
            cur = {"article_num": num, "heading": None, "_body": []}
            articles.append(cur)
            continue
        if cur is None or not t:
            continue
        if cls == heading_cls:
            cur["heading"] = t if cur["heading"] is None else cur["heading"] + " " + t
        elif cls == body_cls or (body_size is None and cls not in sizes):
            cur["_body"].append(t)
        elif body_size is not None and sizes.get(cls, body_size) > body_size + 1.5:
            cur = None  # structural heading: the article is over
        # other small styles (footnotes, spacers) are dropped

    out = []
    for a in articles:
        if a["_body"]:
            out.append({"article_num": a["article_num"], "heading": a["heading"],
                        "text": "\n".join(a["_body"]), "footnote": None, "section": ""})
    return out


def _fetch_fedlex_doc_articles(sr_number: str, snapshot_date: str, language: str,
                               url: str) -> list[dict] | None:
    """Per-article text of a dated consolidation from its Word file, or None
    when the download, the conversion or the split fails. Cached with the
    edition (hist_edition:, 30 days)."""
    cache_key = f"hist_edition:v1:{sr_number}:{snapshot_date}:{language}:doc"
    cached = _lexfind_cache_get(cache_key)
    if cached is not None:
        return cached
    import requests as _req
    resp = _req.get(url, timeout=60)
    if resp.status_code != 200 or not resp.content:
        return None
    html_text = _convert_doc_to_html(resp.content)
    if not html_text:
        return None
    articles = _split_fedlex_doc_html(html_text)
    if not articles:
        return None
    _lexfind_cache_set(cache_key, articles)
    return articles


def _select_historical_articles(articles: list[dict], sr_number: str,
                                requested: str) -> tuple[list[dict], dict]:
    """Pick the requested article out of a parsed edition.

    Exact number first, then the GitHub #87 ordinal alias, then a prefix
    match (what the current-law path's LIKE fallback does), main-body
    articles before transitional ones. Returns (articles, extra result
    keys) so a non-exact match is always flagged in the response.
    """
    def norm(s) -> str:
        return re.sub(r"\s+", "", str(s or "")).lower()

    req = norm(requested)
    main_first = sorted(articles, key=lambda a: bool(a.get("section")))
    exact = [a for a in main_first if norm(a["article_num"]) == req]
    if exact:
        main = [a for a in exact if not a.get("section")]
        return (main or exact), {}
    alias = _TRUNCATED_ORDINAL_ALIASES.get((sr_number, requested))
    if alias:
        hit = [a for a in main_first if norm(a["article_num"]) == norm(alias)]
        if hit:
            return hit, {"article_number_alias": {
                "requested": requested, "stored_as": alias,
                "note": f"Art. {requested} is filed as '{alias}' in this edition.",
            }}
    prefix = [a for a in main_first if norm(a["article_num"]).startswith(req)]
    if prefix:
        main = [a for a in prefix if not a.get("section")] or prefix
        return main, {"article_match": {
            "requested": requested,
            "matched": [a["article_num"] for a in main],
            "method": "prefix",
        }}
    nearest: list[str] = []
    lead = re.match(r"\d+", req)
    if lead:
        want = int(lead.group(0))

        def distance(num: str) -> int:
            m = re.match(r"\d+", num)
            return abs(int(m.group(0)) - want) if m else 10 ** 9

        nearest = sorted({a["article_num"] for a in articles if not a.get("section")},
                         key=distance)[:5]
    return [], {"note": (
        f"Art. {requested} is not in this edition. Nearest article numbers: "
        f"{', '.join(nearest) or 'none'}."
    )}


def _label_statute_stubs(articles: list[dict]) -> None:
    """Blank the body of articles whose only content is their amendment note.

    A repealed article on Fedlex is a number plus a note ("Aufgehoben durch
    ...") and no body; a few are left empty on purpose (OR Art. 6
    "Gegenstandslos.", StGB Art. 108). Rows built before 2026-09-05 carry
    that note as the body, so "the text of Art. 10 ZGB" was its footnote —
    what the LawRider edition comparison (2026-09-03) counted as a spliced
    note on every repealed article. The body becomes "" , the note stays in
    `footnote`, and `empty_body` tells the renderer to say why there is no
    text. In place; rows without a footnote are untouched, so a DB without
    the column is a no-op.
    """
    for art in articles:
        note = art.get("footnote")
        if not note:
            continue
        body = art.get("text") or ""
        if body == note or not re.search(r"\w", body):
            art["text"] = ""
            art["empty_body"] = True


def _fetch_historical_law_version(
    sr_number: str, article: str | None, language: str, as_of: str,
) -> dict | None:
    """Fetch the text of a federal law as it stood on ``as_of`` (ISO date).

    Resolves the work in force on that date (_resolve_fedlex_work), takes
    the latest dated consolidation on or before it, downloads the Akoma
    Ntoso XML and parses it with the parser the statutes.db build uses. The
    result carries the edition's own title, dates and Fedlex link, so a
    historical answer is never less attributable than a current one.

    Returns the result dict or {"error": ...} naming the specific failure:
    no act under that SR on that date, no edition on or before it, no
    machine-readable text in that language, download failure. Errors are
    never cached; editions are (a dated consolidation never changes).
    """
    # v4 (2026-09-05): repealed stubs carry an empty body + `empty_body`
    # instead of the note as body; cached v3 editions would keep serving it.
    cache_key = f"hist_law:v4:{sr_number}:{article or 'all'}:{language}:{as_of}"
    cached = _lexfind_cache_get(cache_key)
    if cached is not None:
        return cached

    try:
        import requests as _req
        import xml.etree.ElementTree as ET
        from search_stack.build_statutes_db import parse_root

        work = _resolve_fedlex_work(sr_number, as_of)
        if work is None:
            return {"error": (
                f"No Fedlex act carried SR {sr_number} on {as_of}. Either the SR "
                f"number is wrong or no act held that number on that date. Call "
                f"get_law without as_of to see the current act and when it entered "
                f"into force."
            )}
        work_uri = work["work"]
        snapshots = _fedlex_snapshots(work_uri)
        applicable = [snap for snap in snapshots if snap["date"] <= as_of]
        if not applicable:
            return {"error": (
                f"SR {sr_number} entered into force on "
                f"{work.get('eif') or 'a date Fedlex does not record'}; Fedlex has no "
                f"consolidation of it dated on or before {as_of}. Earliest available "
                f"edition: {snapshots[0]['date'] if snapshots else 'none'}."
            )}
        snapshot_uri = applicable[-1]["snapshot"]
        snapshot_date = applicable[-1]["date"]
        source_url = _fedlex_snapshot_url(snapshot_uri, language)

        # Formats live on the edition; the act's title lives on the work (the
        # edition expression carries a generic "Consolidation: 220 -
        # 2017-04-01" label or nothing). The work is the act itself, so a
        # repealed act is still labelled with its own title.
        info = _fedlex_expression_info(snapshot_uri, language)
        work_info = _fedlex_expression_info(work_uri, language)
        title = work_info.get("title") or info.get("title")
        abbr = work_info.get("abbr") or info.get("abbr")
        formats = info.get("formats") or {}
        result = {
            "sr_number": sr_number,
            "abbreviation": abbr,
            "title": title,
            "canton": "CH",
            "level": "federal",
            "language": language,
            "version": "historical",
            "as_of": as_of,
            "snapshot_date": snapshot_date,
            "work_uri": work_uri,
            "work_entry_in_force": work.get("eif"),
            "work_no_longer_in_force": work.get("nlif"),
            "work_in_force_status": work.get("status"),
            "fedlex_snapshot_uri": snapshot_uri,
            "source_url": source_url,
            "source_label": f"Fedlex (Fassung vom {snapshot_date})",
            "formats_available": sorted(formats),
        }

        xml_url = formats.get("xml")
        doc_url = formats.get("doc")
        pdf_url = formats.get("pdf-a") or formats.get("pdf")
        doc_articles = None
        if not xml_url and doc_url and _HIST_DOC_ENABLED and _doc_converter():
            doc_articles = _fetch_fedlex_doc_articles(sr_number, snapshot_date, language, doc_url)
        if xml_url:
            xml_resp = _req.get(xml_url, timeout=30)
            if xml_resp.status_code != 200:
                return {"error": (
                    f"Fedlex download failed for SR {sr_number}, edition {snapshot_date} "
                    f"(HTTP {xml_resp.status_code}). Try again later; the edition is at "
                    f"{source_url}"
                )}
            root = ET.fromstring(xml_resp.content)

            # parse_root tags articles inside transitional / final-provision
            # blocks with their section (eId 'disp_u2/art_1' vs 'art_1') so
            # Art. 1 means the main article; the raw fragment is kept only
            # for a single-article request (REST ?format=xml).
            all_articles = []
            for parsed in parse_root(root):
                entry = {
                    "article_num": parsed["article_num"],
                    "heading": parsed["heading"],
                    "text": parsed["text"],
                    "footnote": parsed.get("footnote"),
                    "section": parsed.get("section") or "",
                }
                if parsed.get("section_heading"):
                    entry["section_heading"] = parsed["section_heading"]
                if article and parsed.get("xml"):
                    entry["xml"] = parsed["xml"]
                all_articles.append(entry)
            _label_statute_stubs(all_articles)
            result.update({
                "text_source": "fedlex_xml",
                "structure": "articles",
                "verbatim_quotation": "verbatim",
            })
            if article:
                matched, extra = _select_historical_articles(all_articles, sr_number, article)
                result["articles"] = matched
                result.update(extra)
            else:
                result["articles"] = all_articles
        elif doc_articles:
            # Word edition: the paragraph styles give back the article shape,
            # validated at 72 % byte-identical bodies against XML editions of
            # the same acts. Good enough to cite with the edition date, not
            # good enough to call verbatim.
            result.update({
                "text_source": "fedlex_doc",
                "structure": "articles",
                "verbatim_quotation": "best_effort",
            })
            if article:
                matched, extra = _select_historical_articles(doc_articles, sr_number, article)
                result["articles"] = matched
                result.update(extra)
            else:
                result["articles"] = doc_articles
        elif pdf_url:
            # Pre-2021 editions (and some later ones) exist only as PDF. The
            # text is served whole-edition and flagged: a per-article split of
            # pdftotext output was measured silently wrong for one article in
            # four, so nothing here may be quoted as statute text.
            edition = _fetch_fedlex_edition_text(sr_number, snapshot_date, language,
                                                 "pdf-a" if "pdf-a" in formats else "pdf", pdf_url)
            if edition is None:
                return {"error": (
                    f"Fedlex download failed for SR {sr_number}, edition {snapshot_date} "
                    f"(PDF). Try again later; the edition is at {source_url}"
                )}
            result.update({
                "text_source": "fedlex_pdf",
                "structure": "none",
                "verbatim_quotation": "not_guaranteed",
                "edition_chars": edition["chars"],
                "edition_pages": edition["pages"],
            })
            if article:
                excerpt, candidates = _pdf_article_excerpt(edition["full_text"], article)
                if excerpt:
                    # Honesty guard: a window that holds only the header and
                    # a marginal note (the TOC line, a repealed article) is
                    # returned with text_status heading_only / empty, never
                    # as an answer. HTTP stays 200; the payload says so.
                    status = _pdf_excerpt_status(excerpt)
                    result["articles"] = [{"article_num": article, "heading": None,
                                           "text": excerpt, "excerpt": True,
                                           "text_status": status}]
                    result["excerpt_candidates"] = candidates
                    result["text_status"] = status
                    if status != "ok":
                        what = ("nothing" if status == "empty"
                                else "only a heading or marginal note")
                        result["note"] = (
                            f"UNRESOLVED: the PDF excerpt around 'Art. {article}' holds {what} "
                            f"after the header — no article text was recovered (the article "
                            f"may be repealed or left empty in this edition, or its body "
                            f"header was not recognised). Treat Art. {article} as not "
                            f"retrieved and open the edition on Fedlex: {source_url}")
                else:
                    result["articles"] = []
                    result["note"] = (f"No 'Art. {article}' marker found in the PDF text of this "
                                      f"edition; open the edition on Fedlex: {source_url}")
            else:
                result["articles"] = []
                result["article_count"] = None
                result["edition_preview"] = edition["full_text"][:1500]
                result["note"] = (f"PDF edition without article structure ({edition['chars']:,} "
                                  f"characters). Request a specific article to receive a windowed "
                                  f"excerpt, or open the edition on Fedlex.")
        else:
            present = ", ".join(sorted(formats)) or "none"
            return {"error": (
                f"Fedlex has an edition of SR {sr_number} dated {snapshot_date} (the "
                f"one applicable on {as_of}) but no machine-readable text in "
                f"'{language}' (formats present: {present}). Try language='de' or "
                f"open the edition: {source_url}"
            )}
        # hist_law: sits in _LEXFIND_CACHE_TTL_MAP at 30 days.
        _lexfind_cache_set(cache_key, result)
        return result
    except Exception as e:
        import traceback
        logger.warning("Historical law fetch failed for %s as_of %s: %s\n%s",
                       sr_number, as_of, e, traceback.format_exc())
        return None


def _fetch_pending_changes(sr_number: str) -> list[dict]:
    """Future consolidation dates of the act in force under ``sr_number``
    today: [{"date": ISO}], ascending, at most five. Cached 24h.

    The work is resolved as of today through _resolve_fedlex_work, so a
    totally revised act (whose live work carries no historicalLegalId) is
    the one checked, not its repealed predecessor.
    """
    cache_key = f"pending:v2:{sr_number}"
    cached = _lexfind_cache_get(cache_key)
    if cached is not None:
        return cached

    try:
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        work = _resolve_fedlex_work(sr_number, today)
        if work is None:
            return []
        result = [{"date": snap["date"]}
                  for snap in _fedlex_snapshots(work["work"]) if snap["date"] > today][:5]
        _lexfind_cache_set(cache_key, result)
        return result
    except Exception:
        return []


# GitHub #87. Fedlex ordinals past "novies" were truncated to their first letter
# when statutes.db was built, so StGB Art. 322decies and Art. 179decies are
# stored under "322d" and "179d" — present in the mirror, unreachable by their
# real number. search_stack/build_statutes_db.py parses them correctly now, but
# the shipped mirror predates that fix, so these two pairs are aliased here.
#
# Deliberately an exact (sr_number, article) table rather than a general
# "ordinal -> first letter" retry. OR Art. 322d is a real provision
# (Gratifikation), so a general rule would answer a query for OR Art. 322decies,
# which does not exist, with the text of a different article under the wrong
# number. Silence is better than confident wrongness here.
#
# Self-neutralising: the exact-match lookup runs first, so once statutes.db is
# rebuilt this table stops being reached and can be deleted.
_TRUNCATED_ORDINAL_ALIASES = {
    ("311.0", "179decies"): "179d",
    ("311.0", "322decies"): "322d",
}


def get_law(
    sr_number: str | None = None,
    abbreviation: str | None = None,
    article: str | None = None,
    language: str = "de",
    canton: str = "CH",
    as_of: str | None = None,
) -> dict:
    """Look up a law or specific article from the unified Swiss statute mirror.

    Federal laws (canton='CH') are served from statutes.db (Fedlex mirror).
    Cantonal laws are served from cantonal_laws.db (LexFind mirror). Both
    are local, fast, and returned in the same shape so callers can work
    uniformly across jurisdictions.

    Set ``as_of`` to a past date (ISO or DD.MM.YYYY) to retrieve the
    edition of a federal law in force on that date, fetched live from
    Fedlex. Federal laws only; the result names the edition (snapshot_date).
    """
    canton_u = (canton or "CH").upper()
    # A canton-prefixed name carries its own jurisdiction: ZH/StG is
    # Zurich's tax act whatever `canton` says, while bare StG is the
    # federal stamp-duty act. Naming them this way is what stops the two
    # being confused, so the prefix decides and an explicit canton only
    # applies to unprefixed names.
    _prefix, _bare = split_qualified_law_name(abbreviation or "")
    if _prefix:
        abbreviation, canton_u = _bare, _prefix
    if as_of and canton_u != "CH":
        # Checked before the cantonal branch: LexFind serves current text
        # only, and silently returning it for a dated request would be the
        # worst failure mode on this path.
        return {"error": (
            f"as_of is supported for federal laws only (canton='CH'); cantonal "
            f"historical versions are not available. Omit as_of for the current "
            f"text of the {canton_u} act."
        )}
    if canton_u != "CH":
        return _get_law_cantonal(sr_number, abbreviation, article, language, canton_u)

    # Historical version: on-demand fetch from Fedlex SPARQL
    if as_of:
        # The date is compared with Fedlex consolidation dates as an ISO
        # string, so anything else must be normalised or rejected here:
        # 'today' sorts above every ISO date and used to select a
        # consolidation not yet in force.
        as_of_iso = _parse_date_param(as_of)
        if not as_of_iso:
            return {"error": (
                f"Invalid as_of '{as_of}': use an ISO date YYYY-MM-DD (or DD.MM.YYYY), "
                f"e.g. '2019-06-01'. Relative words such as 'today' are not accepted; "
                f"omit as_of for the text currently in force."
            )}
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        if as_of_iso > today:
            return {"error": (
                f"as_of '{as_of_iso}' is in the future. Omit as_of for the text in "
                f"force today; consolidations not yet in force are announced in "
                f"pending_changes."
            )}
        as_of = as_of_iso
        # Resolve SR number from abbreviation
        if not sr_number and abbreviation:
            conn = _get_statutes_conn()
            if conn:
                try:
                    row = conn.execute(
                        "SELECT sr_number FROM laws WHERE UPPER(abbr_de) = ? OR UPPER(abbr_fr) = ? "
                        "OR UPPER(abbr_it) = ? LIMIT 1",
                        (abbreviation.upper(), abbreviation.upper(), abbreviation.upper()),
                    ).fetchone()
                    if row:
                        sr_number = row["sr_number"]
                finally:
                    conn.close()
        if not sr_number:
            return {"error": f"Cannot resolve SR number for '{abbreviation}'."}
        sr_number = str(sr_number).strip()
        if not _SR_NUMBER_RE.match(sr_number):
            return {"error": (
                f"Invalid sr_number '{sr_number}': federal SR numbers contain digits "
                f"and dots only (e.g. '220', '235.1', '0.452')."
            )}
        result = _fetch_historical_law_version(sr_number, article, language, as_of)
        if result:
            return result
        return {"error": f"Historical version not available for SR {sr_number} as of {as_of}."}

    conn = _get_statutes_conn()
    if conn is None:
        return {"error": "Statutes database not available. Deploy statutes.db to enable statute lookup."}

    try:
        # Resolve SR number from abbreviation if needed
        if not sr_number and abbreviation:
            abbr_upper = abbreviation.upper()
            row = conn.execute(
                """SELECT sr_number FROM laws
                   WHERE UPPER(abbr_de) = ? OR UPPER(abbr_fr) = ? OR UPPER(abbr_it) = ?
                   LIMIT 1""",
                (abbr_upper, abbr_upper, abbr_upper),
            ).fetchone()
            if row:
                sr_number = row["sr_number"]
            else:
                return {"error": f"No law found with abbreviation '{abbreviation}'."}

        if not sr_number:
            return {"error": "Provide sr_number or abbreviation."}

        # Get law metadata
        law = conn.execute(
            "SELECT * FROM laws WHERE sr_number = ?", (sr_number,)
        ).fetchone()
        if not law:
            return {"error": f"No law found with SR number '{sr_number}'."}

        result = {
            "sr_number": law["sr_number"],
            "title": law[f"title_{language}"] or law["title_de"],
            "abbreviation": law[f"abbr_{language}"] or law["abbr_de"],
            "consolidation_date": law["consolidation_date"],
            "canton": "CH",
            "level": "federal",
            "language": language,
        }
        # Source link at the data layer: one field serves the MCP text
        # formatter, the raw-dict REST route (/api/laws/...) and the Copilot
        # wire schema alike. Before this, get_law returned NO URL of any kind
        # — responses otherwise left integrators without a verifiable source.
        # Anchored to the article when one was requested.
        _src = _fedlex_url(law["sr_number"], article, language)
        if _src:
            result["source_url"] = _src
            result["source_label"] = "Fedlex"

        # Issue #22: include the verbatim Akoma Ntoso XML fragment (enumerations,
        # footnotes, sub-paragraphs) alongside the flattened text. The `xml`
        # column exists after a statutes.db rebuild; gracefully omitted on
        # older DBs so the API never errors during a staged rollout.
        _art_cols = "article_num, heading, text"
        _has_section = False
        try:
            _cols = {r[1] for r in conn.execute("PRAGMA table_info(articles)")}
            if "xml" in _cols:
                _art_cols += ", xml"
            # 2026-09 rebuild: transitional / final-provision articles carry a
            # `section` (their eId prefix) so they stop colliding with the main
            # body. Older DBs have no column; every query below degrades to the
            # old behaviour.
            if "section" in _cols:
                _has_section = True
                _art_cols += ", section, section_heading"
            # 2026-09 parser: amendment notes live in `footnote`, not in the
            # body. Serve them on the current path too (until 2026-09-05 only
            # as_of editions did), so a caller sees "Fassung gemäss ..." as a
            # note and never as article text.
            if "footnote" in _cols:
                _art_cols += ", footnote"
        except sqlite3.Error:
            pass
        _main = " AND section = ''" if _has_section else ""

        if article:
            # Fetch specific article
            articles = conn.execute(
                f"""SELECT {_art_cols} FROM articles
                   WHERE sr_number = ? AND article_num = ? AND lang = ?{_main}""",
                (sr_number, article, language),
            ).fetchall()
            if not articles:
                # Try matching with normalization (e.g., "41a" matches "41a")
                articles = conn.execute(
                    f"""SELECT {_art_cols} FROM articles
                       WHERE sr_number = ? AND lang = ?
                       AND (article_num = ? OR article_num LIKE ?){_main}""",
                    (sr_number, language, article, f"{article}%"),
                ).fetchall()
            if not articles:
                # GitHub #87: the shipped statutes.db stores a couple of Fedlex
                # ordinals under a truncated number. Retry under the stored key
                # and relabel the row to the number the caller asked for, which
                # is the one the Fedlex anchor built above already points at.
                _alias = _TRUNCATED_ORDINAL_ALIASES.get(
                    (str(sr_number), (article or "").lower())
                )
                if _alias:
                    for _lang in (language, "de", "fr", "it"):
                        _rows = conn.execute(
                            f"""SELECT {_art_cols} FROM articles
                               WHERE sr_number = ? AND article_num = ? AND lang = ?{_main}""",
                            (sr_number, _alias, _lang),
                        ).fetchall()
                        if not _rows:
                            continue
                        articles = [dict(r) | {"article_num": article}
                                    for r in _rows]
                        result["article_number_alias"] = {
                            "requested": article,
                            "stored_as": _alias,
                            "note": (
                                f"Article {article} is stored under the "
                                f"truncated number '{_alias}' in the current "
                                f"Fedlex mirror. The text below is "
                                f"Art. {article}; only the stored number was "
                                f"wrong, and it has been relabelled to match "
                                f"the request."
                            ),
                        }
                        if _lang != language:
                            result["article_language_fallback"] = {
                                "requested": language,
                                "served": _lang,
                                "note": (
                                    f"Article {article} is not available in "
                                    f"'{language}' in the current Fedlex "
                                    f"mirror; showing '{_lang}'."
                                ),
                            }
                        break
            if not articles:
                # Issue #32: the article may exist only in another language (a gap
                # in the Fedlex mirror — e.g. ZPO Art. 168 is present in fr/it but
                # not de). Fall back to any available language so the caller gets
                # the verbatim text plus a clear note, not "No articles found".
                for alt in ("de", "fr", "it"):
                    if alt == language:
                        continue
                    articles = conn.execute(
                        f"""SELECT {_art_cols} FROM articles
                           WHERE sr_number = ? AND lang = ?
                           AND (article_num = ? OR article_num LIKE ?){_main}""",
                        (sr_number, alt, article, f"{article}%"),
                    ).fetchall()
                    if articles:
                        result["article_language_fallback"] = {
                            "requested": language,
                            "served": alt,
                            "note": (
                                f"Article {article} is not available in "
                                f"'{language}' in the current Fedlex mirror; "
                                f"showing '{alt}'."
                            ),
                        }
                        break
            if _has_section:
                if articles:
                    _others = conn.execute(
                        """SELECT DISTINCT section, section_heading FROM articles
                           WHERE sr_number = ? AND lang = ? AND section != ''
                           AND article_num = ?
                           ORDER BY section""",
                        (sr_number, language, article),
                    ).fetchall()
                    if _others:
                        result["also_in_sections"] = [
                            {"section": o["section"], "section_heading": o["section_heading"]}
                            for o in _others
                        ]
                else:
                    # The number exists only in a transitional / final-provision
                    # block (ZGB SchlT, OR Schlussbestimmungen): serve it, labelled.
                    articles = conn.execute(
                        f"""SELECT {_art_cols} FROM articles
                           WHERE sr_number = ? AND lang = ? AND section != ''
                           AND article_num = ?
                           ORDER BY section""",
                        (sr_number, language, article),
                    ).fetchall()
                    if articles:
                        result["article_section_note"] = (
                            f"Art. {article} exists only in the transitional / final "
                            f"provisions of this act, not in its main body."
                        )
            _rows = [dict(a) for a in articles]
            _label_statute_stubs(_rows)
            result["articles"] = _rows

            # Enrich with Materialien (legislative history) when fetching
            # a specific article — gives the LLM the "why" alongside the "what".
            abbr = result.get("abbreviation") or abbreviation or ""
            if abbr:
                try:
                    mat = _get_materialien_for_doctrine(abbr, article)
                    if mat:
                        result["materialien"] = mat
                except Exception:
                    pass

            # Check for pending changes (future Fedlex snapshots)
            try:
                pending = _fetch_pending_changes(sr_number)
                if pending:
                    result["pending_changes"] = pending
            except Exception:
                pass
        else:
            # Return article list (no text to keep response compact)
            if _has_section:
                articles = conn.execute(
                    """SELECT article_num, heading, section, section_heading FROM articles
                       WHERE sr_number = ? AND lang = ?
                       ORDER BY (section != ''), section,
                                CAST(article_num AS INTEGER), article_num""",
                    (sr_number, language),
                ).fetchall()
                _main_rows = [a for a in articles if not a["section"]]
                result["article_count"] = len(_main_rows)
                result["transitional_count"] = len(articles) - len(_main_rows)
                result["articles"] = [
                    {"article_num": a["article_num"], "heading": a["heading"],
                     **({"section": a["section"], "section_heading": a["section_heading"]}
                        if a["section"] else {})}
                    for a in articles
                ]
            else:
                articles = conn.execute(
                    """SELECT article_num, heading FROM articles
                       WHERE sr_number = ? AND lang = ?
                       ORDER BY CAST(article_num AS INTEGER), article_num""",
                    (sr_number, language),
                ).fetchall()
                result["article_count"] = len(articles)
                result["articles"] = [
                    {"article_num": a["article_num"], "heading": a["heading"]}
                    for a in articles
                ]

        return result
    except sqlite3.Error as e:
        logger.error("Statute lookup error: %s", e)
        return {"error": f"Database error: {e}"}
    finally:
        conn.close()


# GitHub #50 / #88. A query that names one article — "Art. 60 OR",
# "art. 190 al. 2 let. e LDIP" — is a lookup, not a topic search. Before this,
# search_laws ran it as a bag of words, so the tokens "art", "60" and "or"
# ranked the articles that *mention* Art. 60 OR (Art. 39 SchKG, Art. 13 VVG,
# § 11 AI 721.301 …) while Art. 60 OR itself never appeared — a provision does
# not repeat its own number in its body, so it cannot win its own query.
#
# The abbreviation pre-match below cannot cover this: it rejects any query
# containing a space, so it only ever fires for a bare "OR".
#
# Federal only. Cantonal statutes rarely carry canonical abbreviations (see
# get_law's own docs), so "§ 11 <something>" has nothing stable to resolve
# against and keeps the FTS5 path.
_ARTICLE_REF_RE = re.compile(
    r"""^\s*
        (?:art\.?|artikel|articolo|§)\s*
        (?P<num>\d{1,3}
            (?:bis|ter|quater|quinquies|sexies|septies|octies|novies|decies
              |undecies|duodecies|terdecies|quaterdecies|quindecies)?
            [a-z]?)
        # Subdivisions (Abs./al./cpv./Ziff./lit./let.) are addressing detail;
        # the article is the retrievable unit, so they are matched and dropped.
        (?P<tail>(?:\s+(?:abs|al|cpv|ziff|ch|lit|let|lett|n)\.?\s*[0-9IVXivx]+
                    |\s+(?:lit|let|lett)\.?\s*[a-z]\b)*)
        \s+(?P<abbr>[A-Za-zÀ-ÖØ-öø-ÿ][A-Za-zÀ-ÖØ-öø-ÿ0-9\-./]{0,14})
        \s*$""",
    re.IGNORECASE | re.VERBOSE,
)


def _article_reference_lookup_federal(
    raw_query: str,
    language: str | None,
    conn: sqlite3.Connection | None = None,
) -> list[dict]:
    """Resolve an explicit "Art. N ABBR" query to that very article.

    Returns at most one synthetic result per matching law, shaped like the
    other search_laws hits, or [] when the query does not name an article or
    the abbreviation/article does not resolve. Gated on the pattern AND on
    the abbreviation existing in `laws`, so ordinary topical queries are
    untouched.

    Article-number resolution deliberately mirrors get_law: exact match, then
    the #87 truncated-ordinal alias. No LIKE-prefix fallback — that would
    answer "Art. 60" with Art. 601.
    """
    if not raw_query:
        return []
    m = _ARTICLE_REF_RE.match(raw_query.strip())
    if not m:
        return []
    article = (m.group("num") or "").lower()
    abbr_q = (m.group("abbr") or "").strip(".").lower()
    if not article or not abbr_q:
        return []

    owns_conn = conn is None
    if conn is None:
        conn = _get_statutes_conn()
    if conn is None:
        return []
    _main = " AND section = ''" if _articles_has_section(conn) else ""
    try:
        law_rows = conn.execute(
            """SELECT sr_number, abbr_de, abbr_fr, abbr_it,
                      title_de, title_fr, title_it
               FROM laws
               WHERE LOWER(abbr_de) = ? OR LOWER(abbr_fr) = ?
                  OR LOWER(abbr_it) = ?
               LIMIT 3""",
            (abbr_q, abbr_q, abbr_q),
        ).fetchall()
        if not law_rows:
            return []

        display_lang = language if language in ("de", "fr", "it") else "de"
        out: list[dict] = []
        for lr in law_rows:
            sr = str(lr["sr_number"])
            lang_order = ([language] if language in ("de", "fr", "it")
                          else []) + ["de", "fr", "it"]
            art_row = None
            stored_as = None
            for lang in dict.fromkeys(lang_order):
                rows = conn.execute(
                    f"""SELECT article_num, heading, text
                       FROM articles
                       WHERE sr_number = ? AND LOWER(article_num) = ? AND lang = ?{_main}
                       LIMIT 1""",
                    (sr, article, lang),
                ).fetchall()
                if rows:
                    art_row = rows[0]
                    break
            if art_row is None:
                alias = _TRUNCATED_ORDINAL_ALIASES.get((sr, article))
                if alias:
                    for lang in dict.fromkeys(lang_order):
                        rows = conn.execute(
                            f"""SELECT article_num, heading, text
                               FROM articles
                               WHERE sr_number = ? AND article_num = ? AND lang = ?{_main}
                               LIMIT 1""",
                            (sr, alias, lang),
                        ).fetchall()
                        if rows:
                            art_row, stored_as = rows[0], alias
                            break
            if art_row is None:
                continue

            abbr = lr[f"abbr_{display_lang}"] or lr["abbr_de"] or "?"
            title = lr[f"title_{display_lang}"] or lr["title_de"] or ""
            body = (art_row["text"] or "")[:240].replace("\n", " ").strip()
            entry = {
                "level": "federal",
                "canton": "CH",
                "sr_number": sr,
                "abbreviation": abbr,
                "title": title,
                # Label with the number the caller asked for, not the stored
                # one — same relabelling contract get_law uses for #87.
                "article_num": m.group("num"),
                "heading": art_row["heading"],
                "snippet": (f">>>Art. {m.group('num')} {abbr}<<<: {body}..."
                            if body else f">>>Art. {m.group('num')} {abbr}<<<"),
                "matched_as": "article_reference",
            }
            if stored_as:
                entry["article_number_alias"] = {
                    "requested": m.group("num"), "stored_as": stored_as,
                }
            out.append(entry)
        return out
    except sqlite3.Error as e:
        logger.error("Article-reference lookup error: %s", e)
        return []
    finally:
        if owns_conn:
            conn.close()


def _abbreviation_lookup_federal(
    raw_query: str,
    language: str,
    limit: int = 5,
    conn: sqlite3.Connection | None = None,
) -> list[dict]:
    """Match a short abbreviation against laws.{abbr_de,abbr_fr,abbr_it}.

    Returns a list of synthetic article-1 results that surface the law
    matching the abbreviation. Empty list if the query doesn't look like
    an abbreviation or no law matches.

    Runs against the raw user query (before FTS5 sanitisation), so it
    works even when the query is an FTS5 reserved word like ``OR``.

    If ``conn`` is supplied the caller owns the connection lifecycle
    (used by ``_search_laws_federal`` to avoid opening a second SQLite
    handle per request); otherwise the function opens and closes its
    own connection.
    """
    if not raw_query:
        return []
    q_clean = raw_query.strip().strip('"').lower()
    if q_clean.endswith("*"):
        q_clean = q_clean[:-1]
    # Single token, ≤ 12 chars, alpha-prefix — typical abbreviation shape.
    if (
        not q_clean
        or " " in q_clean
        or len(q_clean) > 12
        or not q_clean[0].isalpha()
    ):
        return []
    owns_conn = conn is None
    if conn is None:
        conn = _get_statutes_conn()
    if conn is None:
        return []
    try:
        abbr_rows = conn.execute(
            """SELECT sr_number, abbr_de, abbr_fr, abbr_it,
                      title_de, title_fr, title_it
               FROM laws
               WHERE LOWER(abbr_de) = ? OR LOWER(abbr_fr) = ?
                  OR LOWER(abbr_it) = ?
               LIMIT ?""",
            (q_clean, q_clean, q_clean, limit),
        ).fetchall()
        # When language is omitted (None), fall back to "de" for the display
        # columns AND fetch article 1 in any available language (no lang
        # filter on the article fetch). Without this, `abbr_None` raises
        # IndexError on the row lookups below — caught in 2026-05-16 review.
        display_lang = language if language in ("de", "fr", "it") else "de"
        out: list[dict] = []
        for ar in abbr_rows:
            abbr = ar[f"abbr_{display_lang}"] or ar["abbr_de"] or "?"
            title = ar[f"title_{display_lang}"] or ar["title_de"] or ""
            if language:
                first_arts = conn.execute(
                    """SELECT article_num, heading, text
                       FROM articles
                       WHERE sr_number = ? AND lang = ?
                       ORDER BY CAST(article_num AS INTEGER), article_num
                       LIMIT 1""",
                    (ar["sr_number"], language),
                ).fetchall()
            else:
                # language not specified: take whatever article 1 exists
                # (any of the 3 parallel languages). Prefer DE if available.
                first_arts = conn.execute(
                    """SELECT article_num, heading, text
                       FROM articles
                       WHERE sr_number = ?
                       ORDER BY (lang = 'de') DESC,
                                CAST(article_num AS INTEGER),
                                article_num
                       LIMIT 1""",
                    (ar["sr_number"],),
                ).fetchall()
            for fa in first_arts:
                body = (fa["text"] or "")[:240].replace("\n", " ").strip()
                snippet = (
                    f">>>{abbr}<<< (SR {ar['sr_number']}): {body}..."
                    if body
                    else f">>>{abbr}<<< (SR {ar['sr_number']})"
                )
                out.append({
                    "level": "federal",
                    "canton": "CH",
                    "sr_number": ar["sr_number"],
                    "abbreviation": abbr,
                    "title": title,
                    "article_num": fa["article_num"],
                    "heading": fa["heading"],
                    "snippet": snippet,
                })
        return out
    except sqlite3.Error as e:
        logger.error("Abbreviation lookup error: %s", e)
        return []
    finally:
        if owns_conn:
            conn.close()


def _run_articles_fts(conn, match_query, sr_number, language, limit):
    """One BM25-ranked articles_fts MATCH with optional sr/lang filters. Shared
    by the strict (AND) and broadened (OR) passes of search_laws (issue #31)."""
    section_cols = ", a.section, a.section_heading" if _articles_has_section(conn) else ""
    sql = [
        f"SELECT a.sr_number, a.article_num, a.heading{section_cols},",
        "       snippet(articles_fts, 3, '>>>', '<<<', '...', 40) AS snippet,",
        "       l.abbr_de, l.abbr_fr, l.abbr_it, l.title_de, l.title_fr, l.title_it",
        "FROM articles_fts f",
        "JOIN articles a ON a.id = f.rowid",
        "LEFT JOIN laws l ON a.sr_number = l.sr_number",
        "WHERE articles_fts MATCH ?",
    ]
    params: list = [match_query]
    if sr_number:
        sql.append("AND a.sr_number = ?")
        params.append(sr_number)
    if language:
        sql.append("AND a.lang = ?")
        params.append(language)
    sql.append("ORDER BY f.rank LIMIT ?")
    params.append(limit)
    return conn.execute("\n".join(sql), params).fetchall()


def _search_laws_federal(
    query: str,
    sr_number: str | None,
    language: str,
    limit: int,
    raw_query: str | None = None,
    or_query: str | None = None,
) -> list[dict]:
    """Federal-only FTS5 search against statutes.db. Returns a ranked list.

    When ``raw_query`` is supplied (the user's original input before FTS5
    sanitisation/expansion), we first try to match it as a law-level
    abbreviation (e.g. ``ERV`` → Eigenmittelverordnung, ``ZGB`` → ZGB).
    Article-1 of any matching law is surfaced ahead of FTS5 article-body
    matches, which otherwise rank articles in *other* laws that merely
    mention the abbreviation (HBEV-FINMA mentions ERV, etc.).
    """
    conn = _get_statutes_conn()
    if conn is None:
        return []
    try:
        priority: list[dict] = []
        seen_keys: set[tuple] = set()

        # Explicit article reference ("Art. 60 OR") outranks everything —
        # the caller named the provision, so it is the answer, not a
        # candidate (#50/#88). Runs before the abbreviation pre-match so a
        # query naming an article gets the article, not the law's Art. 1.
        if not sr_number and raw_query:
            for entry in _article_reference_lookup_federal(
                raw_query, language, conn=conn,
            ):
                key = (entry["sr_number"], entry["article_num"])
                if key in seen_keys:
                    continue
                seen_keys.add(key)
                priority.append(entry)

        # Abbreviation pre-match (federal-scope only). Reuse the conn we
        # already hold — opening a second handle to the immutable=1
        # statutes.db is wasteful (~0.5 ms × N RPS × 4 workers).
        if not sr_number and raw_query:
            for entry in _abbreviation_lookup_federal(
                raw_query, language, conn=conn,
            ):
                key = (entry["sr_number"], entry["article_num"])
                seen_keys.add(key)
                priority.append(entry)

        # When language is omitted (None), the per-pass helper drops the a.lang
        # filter so matches in ALL 3 languages return. Use display_lang for the
        # result row's column selection. Caught in 2026-05-16 review.
        display_lang = language if language in ("de", "fr", "it") else "de"

        def _absorb(rows):
            for r in rows:
                section = r["section"] if "section" in r.keys() else ""
                # Main-body hits keep the (sr, article) key the priority
                # entries above use; transitional hits get their own key.
                key = ((r["sr_number"], r["article_num"]) if not section
                       else (r["sr_number"], section, r["article_num"]))
                if key in seen_keys:
                    continue
                seen_keys.add(key)
                abbr = r[f"abbr_{display_lang}"] or r["abbr_de"] or "?"
                title = r[f"title_{display_lang}"] or r["title_de"] or ""
                hit = {
                    "level": "federal",
                    "canton": "CH",
                    "sr_number": r["sr_number"],
                    "abbreviation": abbr,
                    "title": title,
                    "article_num": r["article_num"],
                    "heading": r["heading"],
                    "snippet": r["snippet"],
                }
                if section:
                    hit["section"] = section
                    hit["section_heading"] = r["section_heading"]
                priority.append(hit)
                if len(priority) >= limit:
                    break

        # Issue #31: AND-first-fill. Run the strict (all-terms) query first so
        # exact hits rank on top; only if it under-fills the page broaden to the
        # OR/relevance form, appended below via the seen_keys dedup.
        _absorb(_run_articles_fts(conn, query, sr_number, language, limit))
        if or_query and or_query != query and len(priority) < limit:
            _absorb(_run_articles_fts(conn, or_query, sr_number, language, limit))
        return priority[:limit]
    except sqlite3.Error as e:
        logger.error("Federal statute search error: %s", e)
        return []
    finally:
        conn.close()


# Primary official language per canton — used to adjust the language
# filter when a user searches cantons that speak a different language.
_CANTON_PRIMARY_LANG: dict[str, str] = {
    "AG": "de", "AI": "de", "AR": "de", "BE": "de", "BL": "de",
    "BS": "de", "FR": "fr", "GE": "fr", "GL": "de", "GR": "de",
    "JU": "fr", "LU": "de", "NE": "fr", "NW": "de", "OW": "de",
    "SG": "de", "SH": "de", "SO": "de", "SZ": "de", "TG": "de",
    "TI": "it", "UR": "de", "VD": "fr", "VS": "de", "ZG": "de",
    "ZH": "de",
}


def _search_laws_cantonal(
    query: str, canton: str | None, language: str, limit: int,
    raw_query: str | None = None,
) -> list[dict]:
    """Cantonal statute search — LexFind-first (issue #27), local mirror fallback.

    LexFind is queried live so newly-consolidated laws absent from the
    incomplete local mirror (e.g. ZH PolG / HuG) are findable. Uses the RAW
    query because LexFind expects natural text, not FTS5-expanded syntax.
    """
    if canton:
        try:
            # search_in_content=True: search_laws matches article TEXT (the local
            # FTS did), so a content term like "Wegweisung" surfaces the PolG even
            # though it isn't in the title/keywords.
            leg = _search_legislation(
                query=(raw_query or query), canton=canton, language=language,
                limit=limit, search_in_content=True,
            )
        except Exception as e:
            logger.warning("Cantonal LexFind search failed, using mirror: %s", e)
            leg = None
        if isinstance(leg, dict) and leg.get("laws"):
            out: list[dict] = []
            for law in leg["laws"][:limit]:
                out.append({
                    "level": "cantonal",
                    "canton": law.get("entity") or canton.upper(),
                    "sr_number": law.get("systematic_number") or "",
                    "abbreviation": "",
                    "title": law.get("title"),
                    "article_num": None,
                    "heading": None,
                    "snippet": law.get("snippet"),
                    "lexfind_id": law.get("lexfind_id"),
                })
            return out

    # Fallback: local mirror FTS5 (offline / LexFind unavailable / federal-only).
    conn = _get_cantonal_conn()
    if conn is None:
        return []
    try:
        params: list = [query]
        where = ["articles_fts MATCH ?"]
        if canton:
            where.append("f.canton = ?")
            params.append(canton.upper())
        # When searching a specific canton, use that canton's primary
        # language instead of the query language — otherwise a German
        # query (language="de") against GE/VD/NE/JU/TI returns 0 hits
        # because all articles are stored in fr/it.
        effective_lang = language
        if canton and canton.upper() in _CANTON_PRIMARY_LANG:
            canton_lang = _CANTON_PRIMARY_LANG[canton.upper()]
            if canton_lang != language:
                effective_lang = canton_lang
        if effective_lang:
            where.append("f.language = ?")
            params.append(effective_lang)
        where_sql = " AND ".join(where)
        # Over-fetch so the per-law dedupe can still fill `limit` results.
        sql = f"""
            SELECT f.lexfind_id, f.canton, f.language, f.article_num,
                   bm25(articles_fts) AS rank,
                   snippet(articles_fts, 3, '>>>', '<<<', '...', 40) AS snippet
            FROM articles_fts f
            WHERE {where_sql}
            ORDER BY rank
            LIMIT ?
        """
        params.append(limit * 6)
        raw = conn.execute(sql, params).fetchall()
        if not raw:
            return []

        # Per-law dedupe: keep best-ranked article per (lexfind_id, language)
        seen: set = set()
        best: list[dict] = []
        for r in raw:
            key = (r["lexfind_id"], r["language"])
            if key in seen:
                continue
            seen.add(key)
            best.append(dict(r))
            if len(best) >= limit:
                break

        # Join with law metadata
        results = []
        for r in best:
            meta = conn.execute(
                """SELECT sr_number, title, canton FROM laws
                WHERE lexfind_id = ? AND language = ?""",
                (r["lexfind_id"], r["language"]),
            ).fetchone()
            if not meta:
                continue
            results.append({
                "level": "cantonal",
                "canton": meta["canton"],
                "sr_number": meta["sr_number"] or "",
                "abbreviation": "",  # cantonal lacks standard abbreviations
                "title": meta["title"],
                "article_num": r["article_num"],
                "heading": None,
                "snippet": r["snippet"],
                "lexfind_id": r["lexfind_id"],
            })
        return results
    except sqlite3.Error as e:
        logger.warning("Cantonal statute search error: %s", e)
        return []
    finally:
        conn.close()


_FTS5_OPERATOR_TOKENS = {"AND", "OR", "NOT", "NEAR"}


def _explicit_laws_match(raw_query: str) -> str:
    """FTS5 MATCH string for search_laws when the user wrote explicit syntax.

    Issue #60: the schema advertises quotes/OR/AND/* — but _expand_law_query
    re-tokenises with `re.findall(r"[\\w]+", q.lower())`, which lowercases the
    operators (FTS5 operators are uppercase-only), drops the quotes and drops
    the star. Every advertised feature was destroyed by the pipeline that
    followed the sanitiser: `X OR Y` failed closed (0 hits), `X AND junk`
    failed open (the OR-fill returned hits without `junk`), phrases matched
    unordered words, prefixes matched nothing.

    Built from the RAW query (the sanitizer quotes even operand-flanked OR to
    protect the Obligationenrecht abbreviation — right for natural-language
    queries, wrong once the user is explicitly writing boolean syntax).
    Rules, mirroring FTS5's own:
      - balanced double-quoted phrases pass through verbatim;
      - a trailing `*` on a bare token is kept (prefix search);
      - AND / OR / NOT / NEAR count as operators only in EXACT uppercase and
        only with operands on both sides — a stray leading/trailing operator
        is quoted into a literal;
      - everything else is reduced to word characters (umlauts included), so
        stray punctuation cannot produce FTS5 syntax errors. Parentheses and
        column filters are not supported and degrade to plain terms.
    """
    parts = re.findall(r'"[^"]*"|\S+', raw_query or "")
    cleaned: list[str] = []
    for p in parts:
        if len(p) >= 2 and p.startswith('"') and p.endswith('"'):
            inner = p[1:-1].replace('"', " ").strip()
            if inner:
                cleaned.append(f'"{inner}"')
            continue
        if p in _FTS5_OPERATOR_TOKENS:
            cleaned.append(p)
            continue
        star = p.endswith("*")
        body = re.sub(r"[^0-9A-Za-zÀ-ÖØ-öø-ÿ_]+", "", p)
        if body:
            cleaned.append(body + ("*" if star else ""))
    out: list[str] = []
    for i, t in enumerate(cleaned):
        if t in _FTS5_OPERATOR_TOKENS:
            has_left = i > 0 and cleaned[i - 1] not in _FTS5_OPERATOR_TOKENS
            has_right = (i + 1 < len(cleaned)
                         and cleaned[i + 1] not in _FTS5_OPERATOR_TOKENS)
            if not (has_left and has_right):
                out.append(f'"{t}"')
                continue
        out.append(t)
    return " ".join(out)


def _expand_law_query(sanitized_query: str, multi_or: bool = False) -> str:
    """Expand a sanitized query with colloquial→statute-text synonyms.

    Transforms e.g. ``"Vaterschaftsurlaub Dauer"`` into
    ``(Vaterschaftsurlaub OR urlaub OR elternteils OR vaterschaft OR geburt) Dauer``
    so that FTS5 can match articles whose text uses formal legal diction
    rather than the colloquial term the user typed.

    Uses both LAW_SEARCH_EXPANSIONS (statute-text specific) and
    LEGAL_QUERY_EXPANSIONS (cross-language synonyms from case-law search).
    Zero-latency: no LLM call, purely dictionary-driven.
    """
    tokens = re.findall(r"[0-9A-Za-zÀ-ÖØ-öø-ÿ_]+", sanitized_query.lower())
    if not tokens:
        return sanitized_query

    parts: list[str] = []
    has_or_group = False
    for tok in tokens:
        norm = _normalize_token_for_fts(tok)
        if not norm or len(norm) < 2:
            parts.append(tok)
            continue

        # Gather expansions from both dictionaries
        expansions: set[str] = set()

        # 1. LAW_SEARCH_EXPANSIONS (colloquial→statute text, primary)
        law_exps = LAW_SEARCH_EXPANSIONS.get(norm, ())
        if not law_exps:
            law_exps = _LAW_FTS_NORMALIZED_EXPANSIONS.get(norm, ())
        for exp in law_exps:
            # Multi-word expansions: split and add each word (OR semantics)
            for w in exp.split():
                w_norm = _normalize_token_for_fts(w)
                if w_norm and w_norm != norm and len(w_norm) >= 2:
                    expansions.add(w_norm)

        # 2. LEGAL_QUERY_EXPANSIONS (cross-language, secondary — allow more
        #    than the default MAX_EXPANSIONS_PER_TERM since law search needs
        #    trilingual bridges)
        legal_exps = LEGAL_QUERY_EXPANSIONS.get(norm, ())
        if not legal_exps:
            legal_exps = _FTS_NORMALIZED_EXPANSIONS.get(norm, ())
        for exp in legal_exps[:4]:
            e = _normalize_token_for_fts(exp)
            if e and e != norm:
                expansions.add(e)

        if expansions:
            # Build OR group: (original OR exp1 OR exp2 ...)
            group = " OR ".join([tok] + sorted(expansions))
            parts.append(f"({group})")
            has_or_group = True
        else:
            parts.append(tok)

    # Issue #31: callers run this twice — strict first (AND, multi_or=False),
    # then, only if that under-fills the page, broadened (OR, multi_or=True).
    # OR-joining lets an article missing one guessed term still surface, ranked
    # below the exact hits. Quoted phrases and single terms are never broadened.
    has_phrase = '"' in sanitized_query
    if multi_or and len(parts) >= 2 and not has_phrase:
        return " OR ".join(parts)
    # FTS5 does NOT support implicit AND after parenthesized OR groups:
    # "(a OR b) c" is a syntax error; "(a OR b) AND c" is required.
    joiner = " AND " if has_or_group else " "
    return joiner.join(parts)


def search_laws(
    query: str,
    sr_number: str | None = None,
    canton: str | None = None,
    language: str = "de",
    limit: int = 10,
    jurisdiction: str = "all",
) -> dict:
    """Unified federal + cantonal statute article FTS5 search.

    Args:
        query: natural-language or FTS5 query string.
        sr_number: restrict to a single federal SR number (federal-only).
        canton: two-letter canton code (cantonal-only). 'CH' → federal-only.
        language: de / fr / it.
        limit: max results (1-50).
        jurisdiction: 'all' (default) / 'federal' / 'cantonal' — override for
            callers who want explicit scoping without using sr_number/canton.
    """
    limit = min(max(1, limit), 50)
    raw_query = query

    # Determine which corpora to hit.
    # canton == "CH" is a legacy alias for federal. Explicit jurisdiction
    # overrides; otherwise jurisdiction="all" routes to both unless canton
    # narrows the scope. Parens are required: Python's `and` binds tighter
    # than `or`, so the unparen'd form silently mis-routes
    # `(jurisdiction="federal", canton="ZH")` to *neither* corpus.
    canton_u = (canton or "").upper()
    j = (jurisdiction or "all").lower()
    hit_federal = (
        canton_u == "CH"
        or j == "federal"
        or (j == "all" and not canton_u)
    )
    hit_cantonal = (
        j == "cantonal"
        or (j == "all" and not sr_number and canton_u != "CH")
    )

    # Abbreviation pre-match runs before FTS5 sanitisation so that lookups
    # for FTS5-reserved tokens like "OR" (Obligationenrecht) still surface
    # the correct law.
    federal_abbrev: list[dict] = []
    if hit_federal and not sr_number:
        federal_abbrev = _abbreviation_lookup_federal(raw_query, language)

    # Issue #60: explicit FTS5 syntax (quotes / uppercase OR-AND-NOT / prefix*)
    # must reach the index as written. Detected on the ORIGINAL query and
    # built from it — both the sanitiser (which quotes OR to protect the
    # Obligationenrecht abbreviation) and _expand_law_query (which lowercases
    # and re-tokenises) would destroy it.
    explicit_match = (_explicit_laws_match(raw_query)
                      if _has_explicit_fts_syntax(raw_query) else "")
    query = _sanitize_fts5(query)
    if not query and not explicit_match:
        if federal_abbrev:
            results = federal_abbrev[:limit]
            return {
                "query": raw_query,
                "count": len(results),
                "results": results,
                "federal_hits": len(results),
                "cantonal_hits": 0,
            }
        # Echo the user's original input, not the sanitised empty string,
        # so log lines and downstream telemetry record what was searched.
        return {"query": raw_query, "count": 0, "results": []}
    if explicit_match:
        # No expansion, no OR-fill: the user's operators decide. An AND with
        # a term the corpus lacks now honestly returns 0 instead of an
        # OR-filled page that ignores the operand (#60's fails-open case).
        query, or_query = explicit_match, None
    else:
        or_query = _expand_law_query(query, multi_or=True)  # issue #31 broadened form
        query = _expand_law_query(query)                     # strict (all-terms) form

    federal_results: list[dict] = []
    cantonal_results: list[dict] = []
    if hit_federal:
        federal_results = _search_laws_federal(
            query, sr_number, language, limit, raw_query=raw_query, or_query=or_query,
        )
    if hit_cantonal:
        cantonal_results = _search_laws_cantonal(
            query, canton_u or None, language, limit, raw_query=raw_query,
        )

    # Interleave by rank position: federal #1, cantonal #1, federal #2, ...
    merged: list[dict] = []
    fi = ci = 0
    while (fi < len(federal_results) or ci < len(cantonal_results)) and len(merged) < limit:
        if fi < len(federal_results):
            merged.append(federal_results[fi])
            fi += 1
            if len(merged) >= limit:
                break
        if ci < len(cantonal_results):
            merged.append(cantonal_results[ci])
            ci += 1

    # Count within what was actually returned. These read as a breakdown of
    # `count`, so they have to be one: reporting the pre-merge candidate
    # totals made "Art. 60 OR" answer count=5, federal_hits=5, cantonal_hits=5
    # for a payload of 3 federal + 2 cantonal. Same misleading-total family as
    # #53 / #56 / #75. Field names kept — they are in the REST schema.
    return {
        "query": query,
        "count": len(merged),
        "results": merged,
        "federal_hits": sum(1 for r in merged if r.get("level") == "federal"),
        "cantonal_hits": sum(1 for r in merged if r.get("level") == "cantonal"),
    }


# ── Cross-provider law-search highlighting (Tier A) ──────────────
# One internal highlight convention, rendered per surface so matched
# terms read well on every LLM client. Private-use sentinels cannot
# collide with statute text. Spec: docs/superpowers/specs/
# 2026-06-24-cross-provider-law-search-ux-design.md
_HL_OPEN = ""
_HL_CLOSE = ""
_SECTION_MARK_CANTONS = {"ZH", "SH", "AI", "AR", "AG", "BS", "BL"}


def _law_marker(canton: str | None) -> str:
    """'§' for cantons that number statutes by paragraph, else 'Art.'."""
    return "§" if (canton or "").upper() in _SECTION_MARK_CANTONS else "Art."


def _strip_highlight(text: str) -> str:
    """Drop highlight sentinels (for verbatim and length comparisons)."""
    return (text or "").replace(_HL_OPEN, "").replace(_HL_CLOSE, "")


def _render_highlight(text: str, surface: str = "text") -> str:
    """Render highlight sentinels for a target surface.

    text -> markdown bold (renders identically on Claude, ChatGPT, Gemini,
    Copilot; <mark> does not render on all four). html -> <mark> for the
    MCP-Apps / Apps-SDK widgets. Unbalanced sentinels (e.g. a snippet
    truncated mid-mark) are stripped so we never emit malformed markup.
    """
    if not text:
        return text or ""
    if text.count(_HL_OPEN) != text.count(_HL_CLOSE):
        return _strip_highlight(text)
    if surface == "html":
        return text.replace(_HL_OPEN, "<mark>").replace(_HL_CLOSE, "</mark>")
    return text.replace(_HL_OPEN, "**").replace(_HL_CLOSE, "**")


def _render_fts_snippet(snippet: str) -> str:
    """FTS5 '>>>...<<<' markers -> Markdown bold, for anything user-facing.

    Several tools handed the raw sentinels straight to the user, who saw
    '>>>Willensmangel<<<' where a highlight was meant (search_commentaries,
    search_materialien, search_botschaft, find_scholarship_citing_decision —
    found 2026-07-29 by reading what the tools actually return). Unbalanced
    markers are stripped rather than rendered, same rule as _render_highlight.
    """
    if not snippet:
        return snippet or ""
    return _render_highlight(
        snippet.replace(">>>", _HL_OPEN).replace("<<<", _HL_CLOSE), "text")


def _query_terms(query: str) -> list[str]:
    """Plain word tokens from a (possibly FTS-expanded) query, for the
    on-the-fly highlight fallback. Drops quotes, operators, bare numbers."""
    if not query:
        return []
    import re
    ops = {"AND", "OR", "NOT", "NEAR"}
    seen: set[str] = set()
    out: list[str] = []
    for tok in re.split(r"[\s,;:()\"]+", query):
        tok = tok.strip().strip("*")
        if len(tok) >= 2 and tok.upper() not in ops and not tok.isdigit():
            k = tok.lower()
            if k not in seen:
                seen.add(k)
                out.append(tok)
    return out


def _highlight_terms_inline(snippet: str, terms: list[str]) -> str:
    """Wrap query terms in a snippet with sentinels. Word-boundary,
    case-insensitive, idempotent (no-op if already sentinelled)."""
    if not snippet or not terms or _HL_OPEN in snippet:
        return snippet
    import re
    toks = sorted({t for t in terms if t}, key=len, reverse=True)
    if not toks:
        return snippet
    pat = re.compile(
        r"(?<!\w)(" + "|".join(re.escape(t) for t in toks) + r")(?!\w)",
        re.IGNORECASE | re.UNICODE,
    )
    return pat.sub(lambda mt: _HL_OPEN + mt.group(0) + _HL_CLOSE, snippet)


def _normalize_law_snippet(snippet: str, terms: list[str] | None = None) -> str:
    """Map any law-source highlight markers (federal '>>>...<<<',
    cantonal-local '<b>...</b>') to internal sentinels; fall back to inline
    term marking when the source provided none (e.g. LexFind plain text).
    Returns sentinelled text ready for _render_highlight."""
    if not snippet:
        return ""
    s = _truncate(snippet, MAX_SNIPPET_LEN) or ""
    s = (
        s.replace(">>>", _HL_OPEN).replace("<<<", _HL_CLOSE)
        .replace("<b>", _HL_OPEN).replace("</b>", _HL_CLOSE)
    )
    if _HL_OPEN not in s and terms:
        s = _highlight_terms_inline(s, terms)
    return s


def _build_law_reference(hit: dict) -> str:
    """Display reference assembled from VERBATIM components (marker, article
    number, abbreviation or SR number). A scannable label, NOT a quotable
    citation: direct quotes still come from get_law (R1 to R3)."""
    canton = hit.get("canton")
    marker = hit.get("marker") or _law_marker(canton)
    art = hit.get("article_num")
    abbr = hit.get("abbreviation")
    sr = hit.get("sr_number") or hit.get("systematic_number")
    parts: list[str] = []
    if art:
        parts.append(f"{marker} {art}")
    if abbr:
        parts.append(abbr)
    elif sr:
        parts.append(f"SR {sr}" if (canton in (None, "", "CH")) else f"{canton} {sr}")
    ref = " ".join(parts).strip()
    return ref or (hit.get("title") or "")[:60]


_FEDLEX_WORK_URI_MAP: dict | None = None


def _fedlex_work_uri_map() -> dict:
    """Lazy {sr_number: work_uri} map from statutes.db for federal source links."""
    global _FEDLEX_WORK_URI_MAP
    if _FEDLEX_WORK_URI_MAP is None:
        m: dict = {}
        try:
            conn = _get_statutes_conn()
            if conn is not None:
                for sr, uri in conn.execute(
                    "SELECT sr_number, work_uri FROM laws WHERE work_uri IS NOT NULL AND work_uri != ''"
                ):
                    m[str(sr)] = uri
        except Exception as e:  # pragma: no cover
            logger.debug("fedlex work_uri map load failed: %s", e)
        _FEDLEX_WORK_URI_MAP = m
    return _FEDLEX_WORK_URI_MAP


def _fedlex_url(sr_number, article_num=None, lang: str = "de") -> str | None:
    """Public Fedlex page URL for a federal law (optionally an article anchor),
    derived from the law's ELI work_uri."""
    if not sr_number:
        return None
    uri = _fedlex_work_uri_map().get(str(sr_number))
    if not uri:
        return None
    url = uri.replace("fedlex.data.admin.ch", "www.fedlex.admin.ch").rstrip("/") + "/" + (lang or "de")
    if article_num:
        anchor = "".join(ch for ch in str(article_num).lower() if ch.isalnum())
        if anchor:
            url += "#art_" + anchor
    return url


# A law scraped from a canton's own portal has no LexFind id at all, so
# the cantonal mirror mints a synthetic one above this floor (kept in step
# with search_stack.build_cantonal_laws_db._SYNTHETIC_FLOOR, which the
# tests pin). Real LexFind ids are five digits; anything at or above the
# floor is ours.
_SYNTHETIC_LAW_ID_FLOOR = 1 << 52


def _lexfind_url(lexfind_id, lang: str = "de") -> str | None:
    """LexFind detail-page URL for a cantonal law — if LexFind has one.

    Returns None for a portal-scraped law rather than a URL built from
    its synthetic id: lexfind.ch/tol/<synthetic> resolves to nothing, and
    callers use this as `_lexfind_url(...) or original_url`, so a
    plausible-looking wrong link would displace the canton's own correct
    one. Reachable whenever the local mirror answers instead of the live
    LexFind API.
    """
    if not lexfind_id:
        return None
    try:
        if int(lexfind_id) >= _SYNTHETIC_LAW_ID_FLOOR:
            return None
    except (TypeError, ValueError):
        pass
    return f"https://www.lexfind.ch/fe/{lang or 'de'}/tol/{lexfind_id}"


